// Get API keys from environment - these are loaded at runtime by Firebase
const getApiKeys = () => {
  const runtimeConfig = getRuntimeConfig();
  const stripeConfig = (runtimeConfig["stripe"] as Record<string, unknown> | undefined) || {};
  const exchangeRateConfig = (runtimeConfig["exchangerate"] as Record<string, unknown> | undefined) || {};

  const isSandboxRuntime = (() => {
    const explicit = firstNonEmptyString(process.env.STRIPE_ENV, stripeEnvParam.value())?.toLowerCase() || "";
    if (explicit == "test" || explicit == "sandbox") return true;
    if (explicit == "live" || explicit == "production" || explicit == "prod") return false;

    const baseUrl = (process.env.MOBILE_MONEY_PROVIDER_API_BASE_URL || "").toLowerCase();
    const providerUrl = (process.env.AFRIEX_PROVIDER_URL || "").toLowerCase();
    return baseUrl.includes("sandbox.") || providerUrl.includes("sandbox.");
  })();

  const stripeFromEnv = isSandboxRuntime ?
    firstNonEmptyString(process.env.STRIPE_SECRET_KEY_TEST) :
    firstNonEmptyString(process.env.STRIPE_SECRET_KEY, stripeSecretLiveParam.value());

  // Legacy `functions.config().stripe.secret_key` is often still `sk_live_...` on old projects.
  // Never use it in test/sandbox mode — that causes "token in one mode, secret in the other".
  const legacyStripeSecret = firstNonEmptyString(
    stripeConfig["secret_key"] as string | undefined,
    stripeConfig["secret"] as string | undefined,
    stripeConfig["key"] as string | undefined
  );

  const stripeSecret = stripeFromEnv || (isSandboxRuntime ? undefined : legacyStripeSecret);

  if (isSandboxRuntime && !stripeFromEnv && legacyStripeSecret) {
    functions.logger.warn(
      "STRIPE_ENV=test but STRIPE_SECRET_KEY_TEST is missing; ignoring legacy functions.config() sk_live secret."
    );
  }

  return {
    exchangeRate: (process.env.EXCHANGERATE_API_KEY ||
      exchangeRateConfig["api_key"] ||
      exchangeRateConfig["apikey"] ||
      exchangeRateConfig["key"]) as string | undefined,
    stripe: stripeSecret,
  };
};

