const getAgoraConfig = () => {
  const runtimeConfig = getRuntimeConfig();
  const agoraConfig = (runtimeConfig["agora"] as Record<string, unknown> | undefined) || {};
  const ttlSecondsRaw = Number(
    process.env.AGORA_TOKEN_TTL_SECONDS ||
      agoraConfig["token_ttl_seconds"] ||
      3600
  );
  const ttlSeconds = Number.isFinite(ttlSecondsRaw) && ttlSecondsRaw > 0 ? ttlSecondsRaw : 3600;

  return {
    appId: (process.env.AGORA_APP_ID ||
      agoraConfig["app_id"] ||
      agoraConfig["appId"]) as string | undefined,
    appCertificate: (process.env.AGORA_APP_CERTIFICATE ||
      process.env.AGORA_APP_CERT ||
      agoraConfig["app_certificate"] ||
      agoraConfig["appCertificate"] ||
      agoraConfig["certificate"]) as string | undefined,
    ttlSeconds,
  };
};

type AgoraConfig = ReturnType<typeof getAgoraConfig>;

interface AgoraRecordingStorageConfig {
  vendor?: number;
  region?: number;
  bucket?: string;
  accessKey?: string;
  secretKey?: string;
  fileNamePrefix: string[];
}

interface AgoraRecordingConfig {
  enabled: boolean;
  customerId?: string;
  customerSecret?: string;
  maxIdleTimeSeconds: number;
  resourceExpiredHours: number;
  playbackBaseUrl?: string;
  storage: AgoraRecordingStorageConfig;
}

const parseBooleanFlag = (value: unknown, fallback = false): boolean => {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value !== 0;
  if (typeof value !== "string") return fallback;
  const normalized = value.trim().toLowerCase();
  if (!normalized) return fallback;
  return ["1", "true", "yes", "y", "on"].includes(normalized);
};

const parseOptionalNumber = (value: unknown): number | undefined => {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string") {
    const parsed = Number(value.trim());
    if (Number.isFinite(parsed)) return parsed;
  }
  return undefined;
};

const parsePathSegments = (value: unknown, fallback: string[]): string[] => {
  if (Array.isArray(value)) {
    const segments = value
      .map((item) => typeof item === "string" ? item.trim() : "")
      .filter((segment) => segment.length > 0)
      .map((segment) => segment.replace(/^\/+|\/+$/g, ""));
    return segments.length > 0 ? segments : fallback;
  }
  if (typeof value === "string") {
    const segments = value
      .split("/")
      .flatMap((piece) => piece.split(","))
      .map((piece) => piece.trim())
      .filter((piece) => piece.length > 0)
      .map((segment) => segment.replace(/^\/+|\/+$/g, ""));
    return segments.length > 0 ? segments : fallback;
  }
  return fallback;
};

/** Prevent sample bucket names from being treated as a production recording target. */
const configuredLiveArchiveBucketName = (value: unknown): string | undefined => {
  const bucket = typeof value === "string" ? value.trim() : "";
  if (!bucket) return undefined;
  const normalized = bucket.toLowerCase();
  if ([
    "your-recording-bucket",
    "your-recording-bucket-name",
  ].includes(normalized)) {
    return undefined;
  }
  return bucket;
};

const getAgoraRecordingConfig = (): AgoraRecordingConfig => {
  const runtimeConfig = getRuntimeConfig();
  const agoraConfig = (runtimeConfig["agora"] as Record<string, unknown> | undefined) || {};
  const recordingConfig = (agoraConfig["recording"] as Record<string, unknown> | undefined) || {};
  const storageConfig = (recordingConfig["storage"] as Record<string, unknown> | undefined) || {};

  const maxIdleTimeSeconds = parseOptionalNumber(
    process.env.AGORA_RECORDING_MAX_IDLE_TIME_SECONDS ??
      recordingConfig["max_idle_time_seconds"]
  ) || 600;
  const resourceExpiredHours = parseOptionalNumber(
    process.env.AGORA_RECORDING_RESOURCE_EXPIRED_HOURS ??
      recordingConfig["resource_expired_hours"]
  ) || 24;

  const fileNamePrefix = parsePathSegments(
    process.env.AGORA_RECORDING_STORAGE_FILE_NAME_PREFIX ??
      storageConfig["file_name_prefix"] ??
      recordingConfig["file_name_prefix"],
    ["live_archives"]
  );

  return {
    enabled: parseBooleanFlag(
      process.env.AGORA_RECORDING_ENABLED ??
        recordingConfig["enabled"],
      false
    ),
    customerId: (
      process.env.AGORA_RECORDING_CUSTOMER_ID ||
      recordingConfig["customer_id"] ||
      recordingConfig["customerId"]
    ) as string | undefined,
    customerSecret: (
      process.env.AGORA_RECORDING_CUSTOMER_SECRET ||
      recordingConfig["customer_secret"] ||
      recordingConfig["customerSecret"]
    ) as string | undefined,
    maxIdleTimeSeconds,
    resourceExpiredHours,
    playbackBaseUrl: (
      process.env.AGORA_RECORDING_PLAYBACK_BASE_URL ||
      recordingConfig["playback_base_url"] ||
      recordingConfig["playbackBaseUrl"]
    ) as string | undefined,
    storage: {
      vendor: parseOptionalNumber(
        process.env.AGORA_RECORDING_STORAGE_VENDOR ??
          storageConfig["vendor"]
      ),
      region: parseOptionalNumber(
        process.env.AGORA_RECORDING_STORAGE_REGION ??
          storageConfig["region"]
      ),
      bucket: configuredLiveArchiveBucketName(
        process.env.AGORA_RECORDING_STORAGE_BUCKET ||
        storageConfig["bucket"]
      ),
      accessKey: (
        process.env.AGORA_RECORDING_STORAGE_ACCESS_KEY ||
        storageConfig["access_key"] ||
        storageConfig["accessKey"]
      ) as string | undefined,
      secretKey: (
        process.env.AGORA_RECORDING_STORAGE_SECRET_KEY ||
        storageConfig["secret_key"] ||
        storageConfig["secretKey"]
      ) as string | undefined,
      fileNamePrefix,
    },
  };
};

const describeAgoraRecordingConfigurationIssues = (
  recordingConfig: AgoraRecordingConfig,
  agoraConfig: AgoraConfig,
  hasStorageConfig: boolean
): string[] => {
  const issues: string[] = [];

  if (!recordingConfig.enabled) {
    issues.push("AGORA_RECORDING_ENABLED=false");
  }
  if (!recordingConfig.customerId) {
    issues.push("AGORA_RECORDING_CUSTOMER_ID");
  }
  if (!recordingConfig.customerSecret) {
    issues.push("AGORA_RECORDING_CUSTOMER_SECRET");
  }
  if (!agoraConfig.appId) {
    issues.push("AGORA_APP_ID");
  }
  if (!agoraConfig.appCertificate) {
    issues.push("AGORA_APP_CERTIFICATE");
  }
  if (!hasStorageConfig) {
    issues.push(
      "AGORA_RECORDING_STORAGE_VENDOR/REGION/BUCKET/ACCESS_KEY/SECRET_KEY"
    );
  }

  return issues;
};

const buildAgoraRecordingNotConfiguredMessage = (
  recordingConfig: AgoraRecordingConfig,
  agoraConfig: AgoraConfig,
  hasStorageConfig: boolean
): string => {
  const issues = describeAgoraRecordingConfigurationIssues(
    recordingConfig,
    agoraConfig,
    hasStorageConfig
  );
  if (issues.length === 0) {
    return "Live replay recording is not configured on the server yet.";
  }
  if (issues.length === 1 && issues[0] === "AGORA_RECORDING_ENABLED=false") {
    return "Live replay recording is currently disabled on the server.";
  }
  return `Live replay recording is not ready yet. Missing or disabled: ${issues.join(", ")}.`;
};

