const normalizeStringList = (value: unknown): string[] => {
  if (!Array.isArray(value)) return [];
  const out: string[] = [];
  for (const item of value) {
    if (typeof item === "string") {
      const trimmed = item.trim();
      if (trimmed.length > 0) out.push(trimmed);
    }
  }
  return [...new Set(out)];
};

const userHasBlocked = async (blockerUid: string, blockedUid: string): Promise<boolean> => {
  if (!blockerUid || !blockedUid) return false;
  const [primary, legacy] = await Promise.all([
    db.collection("users").doc(blockerUid).collection("blocked_users").doc(blockedUid).get(),
    db.collection("users").doc(blockerUid).collection("blockedUsers").doc(blockedUid).get(),
  ]);
  return primary.exists || legacy.exists;
};

const assertUsersAreNotBlocked = async (uidA: string, uidB: string): Promise<void> => {
  const left = String(uidA || "").trim();
  const right = String(uidB || "").trim();
  if (!left || !right || left === right) return;
  if (await userHasBlocked(left, right) || await userHasBlocked(right, left)) {
    throw new functions.https.HttpsError(
      "permission-denied",
      "This action is not available because one user has blocked the other."
    );
  }
};

const assertUserCanAccessDating = (userData: Record<string, unknown>): void => {
  if (userData.canAccessDating === false) {
    throw new functions.https.HttpsError(
      "permission-denied",
      "Dating features are not available for this account."
    );
  }
  if (userData.isMinor === true || userData.requiresParentalConsent === true) {
    throw new functions.https.HttpsError(
      "permission-denied",
      "You must be 18 or older to use Dating Loop and Blind Date."
    );
  }
  if (!userData.birthDate) {
    throw new functions.https.HttpsError(
      "permission-denied",
      "Age verification is required before using Dating features."
    );
  }
};

const assertDatingProfileExists = async (userId: string): Promise<void> => {
  const profileSnap = await db.collection("dating_profiles").doc(userId).get();
  if (!profileSnap.exists) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Create your Dating Loop profile before joining Blind Date."
    );
  }
};

const assertBlindDateMediaUrlsOwnedByUser = (userId: string, mediaUrls: string[]): void => {
  const cleanUserId = String(userId || "").trim();
  if (!cleanUserId) {
    throw new functions.https.HttpsError("invalid-argument", "Missing user ID for media validation.");
  }
  const pathPrefix = `blind_date_media/${cleanUserId}/`;
  const encodedPrefix = `blind_date_media%2F${cleanUserId}%2F`;
  for (const rawUrl of mediaUrls) {
    const url = String(rawUrl || "").trim();
    if (!url) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Each Blind Date media URL must be a non-empty string."
      );
    }
    let decodedUrl = url;
    try {
      decodedUrl = decodeURIComponent(url);
    } catch {
      decodedUrl = url;
    }
    const ownsMedia = decodedUrl.includes(pathPrefix)
      || url.includes(pathPrefix)
      || url.includes(encodedPrefix);
    if (!ownsMedia) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "All media URLs must be uploaded to your Blind Date media folder."
      );
    }
  }
};

const finalizeBlindDateRejoinActivation = (
  transaction: FirebaseFirestore.Transaction,
  userId: string,
  blindProfileData: Record<string, unknown>,
  now: admin.firestore.Timestamp,
  activationFields: Record<string, unknown> = {}
): void => {
  const blindDateProfileRef = db.collection("blindDateProfiles").doc(userId);
  const partnerId = asNonEmptyString(blindProfileData.matchedPartnerId);
  const formerPartnerId = asNonEmptyString(blindProfileData.formerMatchedPartnerId);

  if (partnerId) {
    transaction.set(blindDateProfileRef, {
      status: "active",
      ...activationFields,
      matchedPartnerId: admin.firestore.FieldValue.delete(),
      formerMatchedPartnerId: partnerId,
      matchReleasedAt: now,
      matchHoldExpiredAt: admin.firestore.FieldValue.delete(),
      updatedAt: now,
    }, {merge: true});
    transaction.set(db.collection("blindDateProfiles").doc(partnerId), {
      matchedPartnerId: admin.firestore.FieldValue.delete(),
      formerMatchedPartnerId: userId,
      partnerRejoinedAt: now,
      updatedAt: now,
    }, {merge: true});
    return;
  }

  transaction.set(blindDateProfileRef, {
    status: "active",
    ...activationFields,
    formerMatchedPartnerId: admin.firestore.FieldValue.delete(),
    matchHoldExpiredAt: admin.firestore.FieldValue.delete(),
    updatedAt: now,
  }, {merge: true});
  if (formerPartnerId) {
    transaction.set(db.collection("blindDateProfiles").doc(formerPartnerId), {
      formerMatchedPartnerId: admin.firestore.FieldValue.delete(),
      updatedAt: now,
    }, {merge: true});
  }
};

const BLIND_DATE_MATCH_HOLD_MS = 3 * 24 * 60 * 60 * 1000;

const buildDirectChatParticipantPairKey = (uidA: string, uidB: string): string =>
  [uidA, uidB].map((uid) => String(uid || "").trim()).filter(Boolean).sort().join("_");

const assertBlindDateFeatureEnabled = async (): Promise<void> => {
  const snap = await db.collection("app_config").doc("system_config").get();
  const enabled = snap.exists ? snap.get("enableBlindDate") !== false : true;
  if (!enabled) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Blind Date is temporarily disabled. Try again later."
    );
  }
};

const directChatIsBlocked = async (chat: Record<string, unknown>): Promise<boolean> => {
  const participants = normalizeStringList(chat.participants);
  const chatType = String(chat.chatType || "").trim().toLowerCase();
  if (chatType !== "direct" || participants.length !== 2) return false;
  const [firstUid, secondUid] = participants;
  return (await userHasBlocked(firstUid, secondUid)) || (await userHasBlocked(secondUid, firstUid));
};

const USER_PRIVATE_COLLECTION = "user_private";
const PAYMENT_METHOD_PRIVATE_COLLECTION = "payment_method_private";
const PRIVATE_USER_MIGRATED_FIELDS = [
  "fcmToken",
  "fcmTokenUpdatedAt",
  "apnsVoipToken",
  "apnsVoipTokenUpdatedAt",
  "apnsVoipUsesSandbox",
  "paymentCustomerId",
  "payoutAccountId",
  "stripeAccountId",
  "afriexCustomerId",
  "supportAccess",
  "isStaff",
  "staffAccessScope",
  "staffOnboardingStatus",
  "staffAssignedRole",
  "staffPreviousRole",
  "ownerBootstrappedAt",
  "grantedByOwnerId",
  "grantedAdminAt",
  "supportGrantedAt",
  "supportGrantedBy",
  "supportNote",
  "phoneVerifiedNumber",
  "phoneVerifiedDigits",
  "mobileMoneyPhoneOtpLastSentPhone",
  "mobileMoneyPhoneOtpLastSentPhoneDigits",
  "mobileMoneyPhoneOtpVerifiedPhone",
  "mobileMoneyPhoneOtpVerifiedPhoneDigits",
] as const;
const PRIVATE_PAYMENT_METHOD_MIGRATED_FIELDS = [
  "accountNumberRaw",
  "fullAccountNumber",
  "bankAccountNumber",
  "unmaskedAccountNumber",
  "providerAccountNumber",
] as const;

const trimStringValue = (value: unknown): string =>
  typeof value === "string" ? value.trim() : "";

const normalizeAfriexRateSymbols = (value: unknown, fallback: string): string | null => {
  const symbols = (trimStringValue(value) || fallback)
    .split(",")
    .map((symbol) => symbol.trim().toUpperCase())
    .filter(Boolean);
  if (symbols.length === 0 || symbols.some((symbol) => !/^[A-Z]{3}$/.test(symbol))) {
    return null;
  }
  return [...new Set(symbols)].join(",");
};

const rootUserRef = (uid: string): FirebaseFirestore.DocumentReference =>
  db.collection("users").doc(uid);

const userPrivateRef = (uid: string): FirebaseFirestore.DocumentReference =>
  db.collection(USER_PRIVATE_COLLECTION).doc(uid);

const paymentMethodPrivateRef = (
  uid: string,
  paymentMethodId: string
): FirebaseFirestore.DocumentReference =>
  db.collection(PAYMENT_METHOD_PRIVATE_COLLECTION).doc(`${uid.trim()}__${paymentMethodId.trim()}`);

const loadPrivateUserData = async (uid: string): Promise<Record<string, unknown>> => {
  const cleanUid = uid.trim();
  if (!cleanUid) return {};
  const snap = await userPrivateRef(cleanUid).get();
  return (snap.data() || {}) as Record<string, unknown>;
};

const withPrivateUserFields = async (
  uid: string,
  rootData?: Record<string, unknown>
): Promise<Record<string, unknown>> => {
  let resolvedRootData = rootData;
  if (!resolvedRootData) {
    const rootSnap = await rootUserRef(uid).get();
    resolvedRootData = (rootSnap.data() || {}) as Record<string, unknown>;
  }
  const merged = {...(resolvedRootData || {})};
  const privateData = await loadPrivateUserData(uid);
  for (const field of PRIVATE_USER_MIGRATED_FIELDS) {
    if (privateData[field] !== undefined) {
      merged[field] = privateData[field];
    }
  }
  return merged;
};

const mergePrivateUserFields = (
  rootData?: Record<string, unknown>,
  privateData?: Record<string, unknown>
): Record<string, unknown> => {
  const merged = {...(rootData || {})};
  for (const field of PRIVATE_USER_MIGRATED_FIELDS) {
    if (privateData?.[field] !== undefined) {
      merged[field] = privateData[field];
    }
  }
  return merged;
};

const buildSensitiveRootCleanupPatch = (patch: Record<string, unknown>): Record<string, unknown> => {
  const cleanup: Record<string, unknown> = {};
  for (const field of PRIVATE_USER_MIGRATED_FIELDS) {
    if (field in patch) {
      cleanup[field] = admin.firestore.FieldValue.delete();
    }
  }
  return cleanup;
};

const setPrivateUserFields = async (uid: string, patch: Record<string, unknown>): Promise<void> => {
  const cleanUid = uid.trim();
  if (!cleanUid) return;
  await userPrivateRef(cleanUid).set(patch, {merge: true});
  const cleanup = buildSensitiveRootCleanupPatch(patch);
  if (Object.keys(cleanup).length > 0) {
    await rootUserRef(cleanUid).set(cleanup, {merge: true});
  }
};

const loadPrivatePaymentMethodData = async (
  uid: string,
  paymentMethodId: string
): Promise<Record<string, unknown>> => {
  const cleanUid = uid.trim();
  const cleanPaymentMethodId = paymentMethodId.trim();
  if (!cleanUid || !cleanPaymentMethodId) return {};
  const snap = await paymentMethodPrivateRef(cleanUid, cleanPaymentMethodId).get();
  return (snap.data() || {}) as Record<string, unknown>;
};

const withPrivatePaymentMethodFields = async (
  uid: string,
  paymentMethodId: string,
  publicData?: Record<string, unknown>
): Promise<Record<string, unknown>> => {
  const merged = {...(publicData || {})};
  const privateData = await loadPrivatePaymentMethodData(uid, paymentMethodId);
  for (const field of PRIVATE_PAYMENT_METHOD_MIGRATED_FIELDS) {
    if (privateData[field] !== undefined) {
      merged[field] = privateData[field];
    }
  }
  return merged;
};

const buildPaymentMethodSensitiveCleanupPatch = (
  patch: Record<string, unknown>
): Record<string, unknown> => {
  const cleanup: Record<string, unknown> = {};
  for (const field of PRIVATE_PAYMENT_METHOD_MIGRATED_FIELDS) {
    if (field in patch) {
      cleanup[field] = admin.firestore.FieldValue.delete();
    }
  }
  return cleanup;
};

const setPrivatePaymentMethodFields = async (
  uid: string,
  paymentMethodId: string,
  patch: Record<string, unknown>
): Promise<void> => {
  const cleanUid = uid.trim();
  const cleanPaymentMethodId = paymentMethodId.trim();
  if (!cleanUid || !cleanPaymentMethodId) return;
  await paymentMethodPrivateRef(cleanUid, cleanPaymentMethodId).set(patch, {merge: true});
  const cleanup = buildPaymentMethodSensitiveCleanupPatch(patch);
  if (Object.keys(cleanup).length > 0) {
    await db.collection("users")
      .doc(cleanUid)
      .collection("payment_methods")
      .doc(cleanPaymentMethodId)
      .set(cleanup, {merge: true});
  }
};

const getUserPushRouting = async (
  uid: string,
  rootData?: Record<string, unknown>
): Promise<{fcmToken: string; apnsVoipToken: string; apnsVoipUsesSandbox: boolean}> => {
  const merged = await withPrivateUserFields(uid, rootData);
  const sandboxFlag = merged.apnsVoipUsesSandbox;
  const apnsVoipUsesSandbox = sandboxFlag === true ||
    sandboxFlag === "true" ||
    sandboxFlag === 1 ||
    sandboxFlag === "1";
  return {
    fcmToken: trimStringValue(merged.fcmToken),
    apnsVoipToken: trimStringValue(merged.apnsVoipToken),
    apnsVoipUsesSandbox,
  };
};

const isUserPresenceCallable = (
  rootData?: Record<string, unknown>
): boolean => {
  const presenceState = trimStringValue(rootData?.presenceState).toLowerCase();
  if (presenceState !== "online") {
    return false;
  }
  const lastActiveAt = rootData?.lastActiveAt as FirebaseFirestore.Timestamp | undefined;
  if (!lastActiveAt?.toMillis) {
    return false;
  }
  return Date.now() - lastActiveAt.toMillis() <= 90 * 1000;
};

const getUserPaymentCustomerId = async (
  uid: string,
  rootData?: Record<string, unknown>
): Promise<string | undefined> => {
  const merged = await withPrivateUserFields(uid, rootData);
  return trimStringValue(merged.paymentCustomerId) || undefined;
};

const getUserPayoutAccountId = async (
  uid: string,
  rootData?: Record<string, unknown>
): Promise<string | undefined> => {
  const merged = await withPrivateUserFields(uid, rootData);
  return trimStringValue(merged.payoutAccountId) || trimStringValue(merged.stripeAccountId) || undefined;
};

const getUserPrivateFlags = async (
  uid: string,
  rootData?: Record<string, unknown>
): Promise<{
  supportAccess: boolean;
  isStaff: boolean;
  staffAccessScope: string;
  staffOnboardingStatus: string;
  staffAssignedRole: string;
  staffPreviousRole: string;
  ownerBootstrappedAt: unknown;
}> => {
  const merged = await withPrivateUserFields(uid, rootData);
  return {
    supportAccess: merged.supportAccess === true,
    isStaff: merged.isStaff === true,
    staffAccessScope: trimStringValue(merged.staffAccessScope),
    staffOnboardingStatus: trimStringValue(merged.staffOnboardingStatus),
    staffAssignedRole: trimStringValue(merged.staffAssignedRole),
    staffPreviousRole: trimStringValue(merged.staffPreviousRole),
    ownerBootstrappedAt: merged.ownerBootstrappedAt,
  };
};

export const registerUserPushTokens = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const payload = (data || {}) as {
      fcmToken?: unknown;
      apnsVoipToken?: unknown;
      apnsVoipUsesSandbox?: unknown;
    };
    const patch: Record<string, unknown> = {};
    const now = admin.firestore.Timestamp.now();

    if ("fcmToken" in payload) {
      const fcmToken = trimStringValue(payload.fcmToken);
      patch.fcmToken = fcmToken || admin.firestore.FieldValue.delete();
      patch.fcmTokenUpdatedAt = now;
    }
    if ("apnsVoipToken" in payload) {
      const apnsVoipToken = trimStringValue(payload.apnsVoipToken);
      patch.apnsVoipToken = apnsVoipToken || admin.firestore.FieldValue.delete();
      patch.apnsVoipTokenUpdatedAt = now;
      if ("apnsVoipUsesSandbox" in payload) {
        patch.apnsVoipUsesSandbox = payload.apnsVoipUsesSandbox === true ||
          payload.apnsVoipUsesSandbox === "true" ||
          payload.apnsVoipUsesSandbox === 1 ||
          payload.apnsVoipUsesSandbox === "1";
      }
    }

    if (Object.keys(patch).length === 0) {
      return {success: true, noChanges: true};
    }

    patch.updatedAt = now;
    await setPrivateUserFields(context.auth.uid, patch);

    const routing = await getUserPushRouting(context.auth.uid);
    return {
      success: true,
      hasFcmToken: routing.fcmToken.length > 0,
      hasApnsVoipToken: routing.apnsVoipToken.length >= 32,
    };
  });

/** Read-only push setup check for Social Inbox (calls + messages). Does not expose token values. */
export const getSocialInboxPushDiagnostics = functions
  .runWith({secrets: [secretApnsP8], enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const uid = context.auth.uid;
    const routing = await getUserPushRouting(uid);
    const bundleId = (process.env.IOS_APP_BUNDLE_ID || "").trim();
    const apnsVoipReady = apnsVoipCredentialsReady();
    const apnsSandbox =
      process.env.APNS_USE_SANDBOX === "1" || process.env.APNS_USE_SANDBOX === "true";
    const hasFcmToken = routing.fcmToken.length > 0;
    const hasApnsVoipToken = routing.apnsVoipToken.length >= 32;
    const deviceVoipSandbox = routing.apnsVoipUsesSandbox;

    const hints: string[] = [];
    if (!hasFcmToken) {
      hints.push("Open the app while signed in and allow notifications so FCM can register.");
    }
    if (!hasApnsVoipToken) {
      hints.push("VoIP token missing — reinstall on a physical iPhone and sign in again.");
    }
    if (!apnsVoipReady) {
      hints.push("Server VoIP APNs is not fully configured (APNS_P8 secret, team, key id, bundle id).");
    }
    if (apnsSandbox && !deviceVoipSandbox) {
      hints.push("Server APNs is sandbox but this device registered a production VoIP token — lock-screen rings may fail until tokens are refreshed.");
    }
    if (!apnsSandbox && deviceVoipSandbox) {
      hints.push("This device registered a sandbox VoIP token but the server uses production APNs — use a Release/TestFlight build or set APNS_USE_SANDBOX=1 for Xcode debug.");
    }
    if (apnsSandbox) {
      hints.push("Server uses APNs sandbox — use an Xcode development build on device. Set APNS_USE_SANDBOX=0 before TestFlight/App Store.");
    } else {
      hints.push("Server uses production APNs — use TestFlight/App Store or a Release build with production push entitlements.");
    }
    if (hasFcmToken && hasApnsVoipToken && apnsVoipReady) {
      hints.push("Ready for device test: force-quit the app, then send a message or place a call from another account.");
    }

    return {
      server: {
        iosBundleId: bundleId || null,
        apnsVoipReady,
        apnsSandbox,
        customCallSound: "System Default (CallKit)",
        customMessageSound: "MessageBeep.caf",
      },
      device: {
        hasFcmToken,
        hasApnsVoipToken,
        apnsVoipUsesSandbox: deviceVoipSandbox,
      },
      hints,
    };
  });

