export const getMobileMoneySupportedCountries = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async () => {
    const providerName = getMobileMoneyProviderName();
    const providerMode = String(process.env.MOBILE_MONEY_PROVIDER_MODE || "MANUAL").toUpperCase();
    const supportedCountries = getSupportedCountriesForProvider(providerName);
    const supportedCountryConfig = providerName === "AFRIEX" ?
      getAfriexPayoutCountryConfiguration("MOBILE_MONEY") :
      {
        supportedCountries,
        defaultCountry: supportedCountries[0] || null,
        source: "FULL_MAP" as const,
      };
    const bankPayoutCountryConfig = providerName === "AFRIEX" ?
      getAfriexPayoutCountryConfiguration("BANK_ACCOUNT") :
      {
        supportedCountries: [] as string[],
        defaultCountry: null,
        source: "FULL_MAP" as const,
      };
    const swiftPayoutCountryConfig = providerName === "AFRIEX" ?
      getAfriexSwiftPayoutCountryConfiguration() :
      {
        supportedCountries: [] as string[],
        supportedCountryCodes: [] as string[],
        defaultCountry: null,
        source: "DEFAULT_DOCS" as const,
      };
    const localBankInstitutionCountries = providerName === "AFRIEX" ?
      getAfriexLocalBankInstitutionListCountries() :
      [];
    const mobileMoneyDepositCountryConfig = providerName === "AFRIEX" ?
      getAfriexMobileMoneyDepositCountryConfiguration() :
      {
        supportedCountries,
        defaultCountry: supportedCountries[0] || null,
        source: "FULL_MAP" as const,
      };
    const stripeCardCollectionCountryConfig = getStripeCardCollectionCountryConfiguration();

    return {
      success: true,
      providerName,
      providerMode,
      supportedCountries: supportedCountryConfig.supportedCountries,
      defaultCountry: supportedCountryConfig.defaultCountry,
      supportedCountrySource: supportedCountryConfig.source,
      mobileMoneyPayoutSupportedCountries: supportedCountryConfig.supportedCountries,
      mobileMoneyPayoutDefaultCountry: supportedCountryConfig.defaultCountry,
      mobileMoneyPayoutSupportedCountrySource: supportedCountryConfig.source,
      bankPayoutSupportedCountries: bankPayoutCountryConfig.supportedCountries,
      bankPayoutDefaultCountry: bankPayoutCountryConfig.defaultCountry,
      bankPayoutSupportedCountrySource: bankPayoutCountryConfig.source,
      swiftPayoutSupportedCountries: swiftPayoutCountryConfig.supportedCountries,
      swiftPayoutSupportedCountryCodes: swiftPayoutCountryConfig.supportedCountryCodes,
      swiftPayoutDefaultCountry: swiftPayoutCountryConfig.defaultCountry,
      swiftPayoutSupportedCountrySource: swiftPayoutCountryConfig.source,
      swiftPayoutRequiredFields: AFRIEX_SWIFT_PAYOUT_REQUIRED_FIELDS,
      // Local BANK_ACCOUNT institution lookup is narrower than bank/SWIFT payout coverage.
      bankInstitutionListCountries: localBankInstitutionCountries,
      bankInstitutionListDefaultCountry: localBankInstitutionCountries.includes("Nigeria") ? "Nigeria" : localBankInstitutionCountries[0] || null,
      mobileMoneyDepositSupportedCountries: mobileMoneyDepositCountryConfig.supportedCountries,
      mobileMoneyDepositDefaultCountry: mobileMoneyDepositCountryConfig.defaultCountry,
      mobileMoneyDepositSupportedCountrySource: mobileMoneyDepositCountryConfig.source,
      stripeCardCollectionCountries: stripeCardCollectionCountryConfig.supportedCountryCodes,
      stripeCardCollectionAllowAll: stripeCardCollectionCountryConfig.allowAll,
      stripeCardCollectionCountrySource: stripeCardCollectionCountryConfig.source,
      mobileMoneyDepositPausedCountries: [...getAfriexMobileMoneyDepositPausedCountries()].sort((lhs, rhs) => lhs.localeCompare(rhs)),
      rawMobileMoneyDepositPausedCountries: [...getAfriexRawMobileMoneyDepositPausedCountries()].sort((lhs, rhs) => lhs.localeCompare(rhs)),
      mobileMoneyDepositUatCountries: [...getAfriexMobileMoneyDepositUatCountries()].sort((lhs, rhs) => lhs.localeCompare(rhs)),
      pausedCountries: [...getAfriexPausedCountries()].sort((lhs, rhs) => lhs.localeCompare(rhs)),
      rawPausedCountries: [...getAfriexRawPausedCountries()].sort((lhs, rhs) => lhs.localeCompare(rhs)),
      uatCountries: [...getAfriexPayoutUatCountries()].sort((lhs, rhs) => lhs.localeCompare(rhs)),
    };
  });

export const topupAfriexSandboxBusinessWallet = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertOwnerOrAdminCallableAccess(context);

    const payload = (data || {}) as {amount?: unknown; currency?: unknown};
    const amount = Number(payload.amount);
    const currency = (trimStringValue(payload.currency) || "USD").toUpperCase();
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "amount must be a positive number."
      );
    }
    if (!/^[A-Z]{3}$/.test(currency)) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "currency must be a three-letter ISO 4217 code."
      );
    }

    const runtime = resolveAfriexRuntimeConfig();
    if (!runtime.isSandbox) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Sandbox top-up is only allowed when Afriex sandbox base URL is configured."
      );
    }

    const topup = await topupAfriexSandboxBusinessWalletRequest(runtime, {amount, currency});
    const previous = await readAfriexBusinessWalletMirrorPrevious();
    const {mirror, balanceProbe} = topup.ok ?
      await syncAfriexBusinessWalletMirrorState({
        runtime,
        syncedByUid: context.auth?.uid || null,
        topupMeta: {amount, currency, atMs: Date.now()},
        previous: previous as never,
      }) :
      {
        mirror: null,
        balanceProbe: await fetchAfriexBusinessBalance(runtime, ["USD", runtime.inScopeCurrency]),
      };

    if (mirror) {
      await persistAfriexBusinessWalletMirror(mirror as unknown as Record<string, unknown>);
    }

    if (!topup.ok) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        topup.friendlyMessage || `Sandbox top-up failed with HTTP ${topup.statusCode || "unknown"}.`
      );
    }

    return {
      topup,
      balance: balanceProbe,
      mirror,
    };
  });

