export const ensureAfriexCustomer = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    const uid = context.auth.uid;
    const rootSnap = await rootUserRef(uid).get();
    if (!rootSnap.exists) {
      throw new functions.https.HttpsError("not-found", "User account not found.");
    }
    const rootData = (rootSnap.data() || {}) as Record<string, unknown>;
    const merged = await withPrivateUserFields(uid, rootData);

    const existingCustomerId = asNonEmptyString(
      merged.afriexCustomerId,
      merged.providerCustomerId
    );
    if (existingCustomerId) {
      return {
        success: true,
        created: false,
        customerId: existingCustomerId,
        liveMode: resolveAfriexRuntimeConfig().liveMode,
      };
    }

    const fullName = resolveHostedWalletFullName(merged);
    const email = asNonEmptyString(merged.email);
    const customerProfile = resolveAfriexCustomerProfile(merged);
    const phone = customerProfile.phone;
    const countryCode = customerProfile.countryCode;
    if (!fullName || !email || !phone || !countryCode) {
      const missing: string[] = [];
      if (!fullName) missing.push("full name");
      if (!email) missing.push("email");
      if (!phone) missing.push("phone number");
      if (!countryCode) missing.push("supported country");
      throw new functions.https.HttpsError(
        "failed-precondition",
        `Complete your profile before mobile money setup (${missing.join(", ")}).`
      );
    }
    const runtime = resolveAfriexRuntimeConfig();
    const created = await createAfriexCustomerRequest(runtime, {
      fullName,
      email,
      phone,
      countryCode,
      meta: {senderId: uid},
    });
    if (!created.ok || !created.customerId) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        created.friendlyMessage || "Could not create Afriex customer."
      );
    }

    await setPrivateUserFields(uid, {
      afriexCustomerId: created.customerId,
      afriexCustomerProvisionedAtMs: Date.now(),
      afriexLiveMode: runtime.liveMode,
    });

    return {
      success: true,
      created: true,
      customerId: created.customerId,
      liveMode: runtime.liveMode,
    };
  });

export const getAfriexInstitutions = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const payload = (data || {}) as {
      channel?: unknown;
      countryCode?: unknown;
      forceRefresh?: unknown;
    };
    const runtime = resolveAfriexRuntimeConfig();
    const channel = (trimStringValue(payload.channel) || runtime.inScopeChannel).toUpperCase();
    const countryCode = (trimStringValue(payload.countryCode) || runtime.inScopeCountryCode).toUpperCase();
    const forceRefresh = payload.forceRefresh === true;

    const cacheRef = afriexInstitutionCacheRef(channel, countryCode);
    if (!forceRefresh) {
      const cacheSnap = await cacheRef.get();
      if (cacheSnap.exists) {
        const cacheData = (cacheSnap.data() || {}) as Record<string, unknown>;
        const fetchedAtMs = Number(cacheData.fetchedAtMs || 0);
        const institutions = Array.isArray(cacheData.institutions) ? cacheData.institutions : [];
        if (
          Number.isFinite(fetchedAtMs) &&
          Date.now() - fetchedAtMs < AFRIEX_INSTITUTION_CACHE_TTL_MS &&
          institutions.length > 0
        ) {
          return {
            success: true,
            channel,
            countryCode,
            cached: true,
            fetchedAtMs,
            institutions,
          };
        }
      }
    }

    const probe = await listAfriexInstitutions(runtime, {channel, countryCode});
    if (!probe.ok) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        probe.friendlyMessage || "Could not list Afriex institutions."
      );
    }

    const institutions = probe.institutions.map((entry) => ({
      institutionCode: entry.institutionCode,
      institutionName: entry.institutionName,
    }));
    const fetchedAtMs = Date.now();
    await cacheRef.set({
      provider: "afriex",
      channel,
      countryCode,
      institutions,
      fetchedAtMs,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, {merge: true});

    return {
      success: true,
      channel,
      countryCode,
      cached: false,
      fetchedAtMs,
      institutions,
    };
  });

export const resolveAfriexInstitutionCode = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const payload = (data || {}) as {
      searchTerm?: unknown;
      countryCode?: unknown;
      codeType?: unknown;
    };
    const runtime = resolveAfriexRuntimeConfig();
    const countryCode = (trimStringValue(payload.countryCode) || "US").toUpperCase();
    const codeTypeRaw = (trimStringValue(payload.codeType) || (countryCode === "US" ? "routing_number" : "swift_code"))
      .toLowerCase();
    const codeType = codeTypeRaw === "routing_number" ? "routing_number" : "swift_code";
    const searchTerm = codeType === "routing_number" ?
      trimStringValue(payload.searchTerm).replace(/[^\d]/g, "") :
      trimStringValue(payload.searchTerm).toUpperCase().replace(/[^A-Z0-9]/g, "");

    if (!searchTerm) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        codeType === "routing_number" ? "Routing number is required." : "SWIFT/BIC code is required."
      );
    }
    if (codeType === "routing_number" && countryCode !== "US") {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Routing-number lookup is only supported for US bank recipients. Use SWIFT/BIC for other countries."
      );
    }
    if (codeType === "routing_number" && (searchTerm.length < 8 || searchTerm.length > 9)) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "US routing number must be 8 to 9 digits."
      );
    }
    if (codeType === "swift_code" && ![8, 11].includes(searchTerm.length)) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "SWIFT/BIC code must be 8 or 11 characters."
      );
    }

    const probe = await resolveAfriexInstitutionCodeRequest(runtime, {
      searchTerm,
      countryCode,
      codeType,
    });
    if (!probe.ok || !probe.resolved) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        probe.friendlyMessage || "Could not resolve bank code."
      );
    }

    return {
      success: true,
      resolved: probe.resolved,
    };
  });

export const resolveAfriexAccount = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const payload = (data || {}) as {
      channel?: unknown;
      countryCode?: unknown;
      accountNumber?: unknown;
      institutionCode?: unknown;
    };
    const runtime = resolveAfriexRuntimeConfig();
    const channel = (trimStringValue(payload.channel) || runtime.inScopeChannel).toUpperCase();
    const countryCode = (trimStringValue(payload.countryCode) || runtime.inScopeCountryCode).toUpperCase();
    const accountNumber = trimStringValue(payload.accountNumber);
    const institutionCode = trimStringValue(payload.institutionCode) || undefined;
    if (!accountNumber) {
      throw new functions.https.HttpsError("invalid-argument", "accountNumber is required.");
    }
    if (channel === "BANK_ACCOUNT" && !institutionCode) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "institutionCode is required for BANK_ACCOUNT resolve."
      );
    }

    const probe = await resolveAfriexPaymentMethodAccount(runtime, {
      channel,
      countryCode,
      accountNumber,
      institutionCode,
    });
    if (!probe.ok || !probe.resolved) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        probe.friendlyMessage || "Could not resolve Afriex account holder."
      );
    }

    return {
      success: true,
      resolved: probe.resolved,
    };
  });

export const getAfriexRates = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const payload = (data || {}) as {fromSymbols?: unknown; toSymbols?: unknown};
    const runtime = resolveAfriexRuntimeConfig();
    const fromSymbols = normalizeAfriexRateSymbols(payload.fromSymbols, "USD");
    const toSymbols = normalizeAfriexRateSymbols(payload.toSymbols, runtime.inScopeCurrency);
    if (!fromSymbols || !toSymbols) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "fromSymbols and toSymbols must be comma-separated three-letter ISO 4217 codes."
      );
    }
    const probe = await fetchAfriexRates(runtime, {fromSymbols, toSymbols});
    if (!probe.ok || !probe.rates) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        probe.friendlyMessage || "Could not fetch Afriex rates."
      );
    }

    return {
      success: true,
      ...probe.rates,
      quoteTtlSeconds: 60,
    };
  });

export const getAfriexBalance = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertOwnerOrAdminCallableAccess(context);

    const payload = (data || {}) as {currencies?: unknown};
    const runtime = resolveAfriexRuntimeConfig();
    const currenciesRaw = trimStringValue(payload.currencies);
    const currencies = currenciesRaw ?
      currenciesRaw.split(",").map((entry) => entry.trim().toUpperCase()).filter(Boolean) :
      ["USD", runtime.inScopeCurrency];
    const probe = await fetchAfriexBusinessBalance(runtime, currencies);
    if (!probe.ok) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        probe.friendlyMessage || "Could not read Afriex business balance."
      );
    }

    return {
      success: true,
      isSandbox: runtime.isSandbox,
      liveMode: runtime.liveMode,
      balances: probe.balances || [],
    };
  });

/**
 * Phase 3 / PAY-MM-01 — create a WITHDRAW mobile-money payment method for UG (or override country).
 * Transaction-only: destination route for disbursement, not customer custody.
 */
export const createAfriexWithdrawPaymentMethod = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    await assertOwnerOrAdminCallableAccess(context);
    const uid = context.auth.uid;
    const payload = (data || {}) as {
      accountName?: unknown;
      accountNumber?: unknown;
      institutionCode?: unknown;
      institutionName?: unknown;
      countryCode?: unknown;
      customerId?: unknown;
    };
    const runtime = resolveAfriexRuntimeConfig();
    const countryCode = (trimStringValue(payload.countryCode) || runtime.inScopeCountryCode).toUpperCase();
    const accountName = trimStringValue(payload.accountName);
    const accountNumber = trimStringValue(payload.accountNumber);
    const institutionCode = trimStringValue(payload.institutionCode);
    const institutionName = trimStringValue(payload.institutionName) || null;
    if (!accountName || !accountNumber || !institutionCode) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "accountName, accountNumber, and institutionCode are required."
      );
    }

    const rootSnap = await rootUserRef(uid).get();
    const merged = await withPrivateUserFields(uid, (rootSnap.data() || {}) as Record<string, unknown>);
    let customerId = asNonEmptyString(payload.customerId, merged.afriexCustomerId, merged.providerCustomerId);
    if (!customerId) {
      const customerProfile = resolveAfriexCustomerProfile(merged);
      const ensured = await createAfriexCustomerRequest(runtime, {
        fullName: resolveHostedWalletFullName(merged) || accountName,
        email: asNonEmptyString(merged.email) || `${uid}@users.volunteersapp.local`,
        phone: customerProfile.phone || accountNumber,
        countryCode: customerProfile.countryCode || countryCode,
        meta: {senderId: uid},
      });
      if (!ensured.ok || !ensured.customerId) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          ensured.friendlyMessage || "Could not ensure Afriex customer."
        );
      }
      customerId = ensured.customerId;
      await setPrivateUserFields(uid, {afriexCustomerId: customerId});
    }

    const providerRuntime = getAfriexProviderRuntime();
    const paymentMethodId = await createAfriexPaymentMethod({
      providerUrl: providerRuntime.providerUrl,
      headers: providerRuntime.headers,
      timeoutMs: providerRuntime.timeoutMs,
      customerId,
      transactionType: "WITHDRAW",
      channel: "MOBILE_MONEY",
      accountName,
      accountNumber,
      countryCode,
      institutionCode,
      institutionName,
      senderId: uid,
    });

    return {
      success: true,
      customerId,
      paymentMethodId,
      channel: "MOBILE_MONEY",
      countryCode,
      type: "WITHDRAW",
    };
  });

/**
 * Phase 3 / PAY-MM-02 — create a WITHDRAW transaction to an existing Afriex destination payment method.
 * Prefer initiateTransfer for app UX; this callable is the UAT-aligned direct WITHDRAW path.
 * Owner/admin only (sandbox UAT) to avoid open business-float drain.
 */
export const createAfriexWithdrawTransaction = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    await assertOwnerOrAdminCallableAccess(context);
    if (!resolveAfriexRuntimeConfig().isSandbox) {
      // This callable exists only for the Afriex UAT workbook. Production
      // withdrawals must originate from the customer transfer pipeline so
      // recipient verification, pricing, authorization, and reconciliation
      // cannot be bypassed by a direct business-balance request.
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Direct Afriex withdrawal UAT is available in sandbox only. Use the verified Send Money flow for production transfers."
      );
    }
    const uid = context.auth.uid;
    const payload = (data || {}) as {
      destinationId?: unknown;
      customerId?: unknown;
      sourceAmount?: unknown;
      sourceCurrency?: unknown;
      destinationAmount?: unknown;
      destinationCurrency?: unknown;
      recipientName?: unknown;
      recipientPhone?: unknown;
      institutionCode?: unknown;
      countryCode?: unknown;
      forceFail?: unknown;
    };

    const destinationId = trimStringValue(payload.destinationId);
    const sourceAmount = roundMoney(Number(payload.sourceAmount || 0));
    const destinationAmount = roundMoney(Number(payload.destinationAmount || sourceAmount || 0));
    const sourceCurrency = (trimStringValue(payload.sourceCurrency) || "USD").toUpperCase();
    const destinationCurrency = (
      trimStringValue(payload.destinationCurrency) ||
      resolveAfriexRuntimeConfig().inScopeCurrency
    ).toUpperCase();
    const countryCode = (
      trimStringValue(payload.countryCode) ||
      resolveAfriexRuntimeConfig().inScopeCountryCode
    ).toUpperCase();
    if (!destinationId) {
      throw new functions.https.HttpsError("invalid-argument", "destinationId is required.");
    }
    if (!Number.isFinite(sourceAmount) || sourceAmount <= 0) {
      throw new functions.https.HttpsError("invalid-argument", "sourceAmount must be positive.");
    }

    const rootSnap = await rootUserRef(uid).get();
    const merged = await withPrivateUserFields(uid, (rootSnap.data() || {}) as Record<string, unknown>);
    const customerId = asNonEmptyString(
      payload.customerId,
      merged.afriexCustomerId,
      merged.providerCustomerId
    );
    if (!customerId) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Call ensureAfriexCustomer or createAfriexWithdrawPaymentMethod first."
      );
    }

    const payoutRef = db.collection("payout_requests").doc();
    const forceFail = payload.forceFail === true;
    // Keep meta.reference = payoutRequestId (or fail_<id>) so webhooks can bridge.
    const metaReference = forceFail ? `fail_${payoutRef.id}` : payoutRef.id;
    const afriexMetaIdempotencyKey = randomUUID();
    const now = admin.firestore.Timestamp.now();
    const recipientPhone = trimStringValue(payload.recipientPhone);
    const recipientName = trimStringValue(payload.recipientName) || "Recipient";
    const institutionCode = trimStringValue(payload.institutionCode);

    const payoutData: FirebaseFirestore.DocumentData = {
      senderId: uid,
      amount: sourceAmount,
      currency: sourceCurrency,
      walletCurrency: sourceCurrency,
      localAmount: destinationAmount,
      amountInLocalCurrency: destinationAmount,
      localCurrency: destinationCurrency,
      country: countryCode,
      type: "BENEFICIARY_TRANSFER",
      status: "PENDING_PROVIDER",
      source: AFRIEX_HOSTED_WALLET_TRANSFER_SOURCE,
      fundingSource: AFRIEX_HOSTED_WALLET_FUNDING_SOURCE,
      processor: "AFRIEX",
      settlementProvider: "AFRIEX",
      afriexPayoutRoute: "MOBILE_MONEY",
      afriexCustomerId: customerId,
      providerCustomerId: customerId,
      afriexDestinationPaymentMethodId: destinationId,
      providerDestinationPaymentMethodId: destinationId,
      recipientPhone: recipientPhone || null,
      recipientName,
      recipientNetwork: institutionCode || null,
      recipientInfo: {
        name: recipientName,
        mobileNumber: recipientPhone || null,
        accountNumber: recipientPhone || null,
        country: countryCode,
        network: institutionCode || null,
        institutionCode: institutionCode || null,
        afriexPayoutRoute: "MOBILE_MONEY",
        afriexCustomerId: customerId,
        afriexDestinationPaymentMethodId: destinationId,
      },
      metaReferenceOverride: metaReference,
      afriexMetaIdempotencyKey,
      afriexForceFailReference: forceFail,
      createdAt: now,
      processedAt: now,
      timestamp: now,
    };

    const authorizationPatch = buildMobileMoneyProviderAuthorizationPatch(
      payoutRef.id,
      payoutData,
      "createAfriexWithdrawTransaction"
    );
    await payoutRef.set({...payoutData, ...authorizationPatch}, {merge: true});

    // Claim before Afriex POST so onPendingMobileMoneyProviderRequestCreated cannot double-submit.
    const claimed = await db.runTransaction(async (transaction) => {
      const freshSnap = await transaction.get(payoutRef);
      if (!freshSnap.exists) return null;
      const freshData = freshSnap.data() || {};
      if (String(freshData.status || "").trim().toUpperCase() !== "PENDING_PROVIDER") {
        return null;
      }
      const claimNow = admin.firestore.Timestamp.now();
      transaction.set(payoutRef, {
        status: "PROCESSING_PROVIDER",
        providerStatus: "PROCESSING",
        providerProcessingStartedAt: claimNow,
        processedAt: claimNow,
        afriexSubmitClaimedBy: "createAfriexWithdrawTransaction",
      }, {merge: true});
      return {...freshData, ...payoutData};
    });
    if (!claimed) {
      // onCreate path likely claimed first — return current state instead of double-submitting.
      const racedSnap = await payoutRef.get();
      const raced = racedSnap.data() || {};
      return {
        success: true,
        payoutRequestId: payoutRef.id,
        providerTransferId: asNonEmptyString(
          raced.providerTransferId,
          raced.afriexTransactionId,
          raced.providerTransactionId
        ) || null,
        status: asNonEmptyString(raced.providerStatus, raced.status) || "PROCESSING",
        forceFail,
        message: "Payout submission was claimed by the pending-provider worker; no duplicate Afriex POST.",
        claimedByWorker: true,
      };
    }

    const providerRuntime = getAfriexProviderRuntime();
    let providerResult: MobileMoneyProviderResult;
    try {
      providerResult = await submitAfriexPayout(payoutRef, {
        ...claimed,
        afriexForceFailReference: forceFail,
        metaReferenceOverride: metaReference,
        afriexMetaIdempotencyKey,
      }, {
        payoutsUrl: providerRuntime.providerUrl,
        headers: providerRuntime.headers,
        timeoutMs: providerRuntime.timeoutMs,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Afriex withdraw submit failed.";
      await payoutRef.set({
        status: "FAILED",
        errorMessage: message,
        processedAt: admin.firestore.Timestamp.now(),
      }, {merge: true});
      throw new functions.https.HttpsError("failed-precondition", message);
    }

    await applyMobileMoneyProviderResult(payoutRef, claimed, providerResult);

    return {
      success: true,
      payoutRequestId: payoutRef.id,
      providerTransferId: providerResult.providerTransferId || null,
      status: providerResult.status,
      forceFail,
      message: forceFail ?
        "Sandbox force-fail withdraw submitted (meta.reference contains fail)." :
        "Transfer submitted successfully.",
    };
  });

export const getConversationCallAvailability = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const payload = (data || {}) as {chatId?: unknown; receiverId?: unknown};
    const chatId = trimStringValue(payload.chatId);
    const receiverId = trimStringValue(payload.receiverId);
    if (!chatId || !receiverId) {
      throw new functions.https.HttpsError("invalid-argument", "chatId and receiverId are required.");
    }

    const chatSnap = await db.collection("chats").doc(chatId).get();
    if (!chatSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Conversation not found.");
    }
    const chatData = (chatSnap.data() || {}) as Record<string, unknown>;
    const participants = normalizeStringList(chatData.participants);
    if (!participants.includes(context.auth.uid)) {
      throw new functions.https.HttpsError("permission-denied", "You do not have access to this conversation.");
    }
    if (!participants.includes(receiverId)) {
      throw new functions.https.HttpsError("failed-precondition", "Call recipient is not a participant in this conversation.");
    }

    if (await directChatIsBlocked(chatData)) {
      return {
        available: false,
        reason: "BLOCKED",
        hasFcmToken: false,
        hasApnsVoipToken: false,
      };
    }

    const exitedParticipants = new Set(normalizeStringList(chatData.exitedParticipantIds));
    if (exitedParticipants.has(receiverId)) {
      return {
        available: false,
        reason: "RECIPIENT_EXITED",
        hasFcmToken: false,
        hasApnsVoipToken: false,
      };
    }

    const activeCallSnap = await db.collection("call_sessions")
      .where("chatId", "==", chatId)
      .orderBy("createdAt", "desc")
      .limit(8)
      .get();
    const activeCall = activeCallSnap.docs.find((doc) => {
      const session = (doc.data() || {}) as Record<string, unknown>;
      const status = trimStringValue(session.status).toLowerCase();
      if (!["ringing", "accepted"].includes(status)) {
        return false;
      }
      const createdAt = session.createdAt as FirebaseFirestore.Timestamp | undefined;
      if (status === "ringing" && createdAt?.toMillis && Date.now() - createdAt.toMillis() > 5 * 60 * 1000) {
        return false;
      }
      return true;
    });
    if (activeCall) {
      return {
        available: false,
        reason: "CALL_IN_PROGRESS",
        activeCallSessionId: activeCall.id,
        hasFcmToken: false,
        hasApnsVoipToken: false,
      };
    }

    const receiverUserSnap = await db.collection("users").doc(receiverId).get();
    const receiverUserData = (receiverUserSnap.data() || {}) as Record<string, unknown>;
    const recipientIsOnline = isUserPresenceCallable(receiverUserData);

    const routing = await getUserPushRouting(receiverId, receiverUserData);
    const hasFcmToken = routing.fcmToken.length > 0;
    const hasApnsVoipToken = routing.apnsVoipToken.length >= 32;
    const canReachWhenAppClosed = hasFcmToken || hasApnsVoipToken;
    let pushReachabilityWarning: string | null = null;
    if (!canReachWhenAppClosed) {
      pushReachabilityWarning = "They may not receive this call if their app is closed.";
    } else if (!hasApnsVoipToken) {
      pushReachabilityWarning = "They may not hear a lock-screen ring if their app is closed.";
    }
    return {
      available: true,
      reason: "READY",
      recipientIsOnline,
      hasFcmToken,
      hasApnsVoipToken,
      canReachWhenAppClosed,
      pushReachabilityWarning,
    };
  });

export const getConversationMessagingAvailability = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const payload = (data || {}) as {chatId?: unknown};
    const chatId = trimStringValue(payload.chatId);
    if (!chatId) {
      throw new functions.https.HttpsError("invalid-argument", "chatId is required.");
    }

    const chatSnap = await db.collection("chats").doc(chatId).get();
    if (!chatSnap.exists) {
      return {
        available: false,
        reason: "NOT_FOUND",
      };
    }

    const chatData = (chatSnap.data() || {}) as Record<string, unknown>;
    const participants = normalizeStringList(chatData.participants);
    if (!participants.includes(context.auth.uid)) {
      return {
        available: false,
        reason: "NO_ACCESS",
      };
    }

    const chatType = String(chatData.chatType || "").trim().toLowerCase();
    const isDirect = chatType === "direct" || (chatType !== "group" && participants.length === 2);
    const exitedParticipants = new Set(normalizeStringList(chatData.exitedParticipantIds));
    if (!isDirect && exitedParticipants.has(context.auth.uid)) {
      return {
        available: false,
        reason: "SELF_EXITED",
      };
    }

    if (await directChatIsBlocked(chatData)) {
      return {
        available: false,
        reason: "BLOCKED",
      };
    }

    return {
      available: true,
      reason: "READY",
    };
  });

export const getCurrentUserPrivateFlags = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const uid = context.auth.uid;
    const rootSnap = await rootUserRef(uid).get();
    const rootData = (rootSnap.data() || {}) as Record<string, unknown>;
    const mergedUserData = await withPrivateUserFields(uid, rootData);
    const privateFlags = await getUserPrivateFlags(uid, rootData);
    return {
      success: true,
      role: trimStringValue(mergedUserData.role) || trimStringValue(mergedUserData.userRole) || null,
      supportAccess: privateFlags.supportAccess,
      isStaff: privateFlags.isStaff,
      staffAccessScope: privateFlags.staffAccessScope || null,
      staffOnboardingStatus: privateFlags.staffOnboardingStatus || null,
      staffFeeExempt: isStaffFeeExempt(
        mergedUserData,
        (context.auth.token || {}) as Record<string, unknown>
      ),
    };
  });

type LiveViewAccessMode =
  | "public"
  | "followers_only"
  | "invite_only"
  | "accepted_event_volunteers";

type LiveStageAccessMode =
  | "host_only"
  | "request_to_join"
  | "approved_volunteers"
  | "open_to_accepted_volunteers";

type LiveReplayVisibility =
  | "owner_only"
  | "shared_link"
  | "followers_only"
  | "public";

type LiveReplayAccessPurpose =
  | "playback"
  | "share";

type LiveShareAccessKind =
  | "live"
  | "replay";

const APPROVED_EVENT_APPLICATION_STATUSES = new Set([
  "approved",
  "accepted",
  "attended",
  "completed",
]);

const normalizeLiveViewAccessMode = (value: unknown): LiveViewAccessMode => {
  const normalized = String(value || "").trim().toLowerCase();
  switch (normalized) {
  case "followers_only":
  case "invite_only":
  case "accepted_event_volunteers":
    return normalized;
  default:
    return "public";
  }
};

const normalizeLiveStageAccessMode = (value: unknown): LiveStageAccessMode => {
  const normalized = String(value || "").trim().toLowerCase();
  switch (normalized) {
  case "host_only":
  case "approved_volunteers":
  case "open_to_accepted_volunteers":
    return normalized;
  default:
    return "request_to_join";
  }
};

const normalizeLiveReplayVisibility = (value: unknown): LiveReplayVisibility => {
  const normalized = String(value || "").trim().toLowerCase();
  switch (normalized) {
  case "shared_link":
  case "followers_only":
  case "public":
    return normalized;
  default:
    return "owner_only";
  }
};

const normalizeLiveReplayAccessPurpose = (value: unknown): LiveReplayAccessPurpose => {
  const normalized = String(value || "").trim().toLowerCase();
  switch (normalized) {
  case "share":
    return "share";
  default:
    return "playback";
  }
};

const normalizeLiveShareAccessKind = (value: unknown): LiveShareAccessKind => {
  const normalized = String(value || "").trim().toLowerCase();
  switch (normalized) {
  case "replay":
    return "replay";
  default:
    return "live";
  }
};

const buildLiveJoinRequestDocId = (sessionId: string, userId: string): string => {
  return `${sessionId.trim()}_${userId.trim()}`;
};

const userFollowsHost = async (hostUid: string, followerUid: string): Promise<boolean> => {
  if (!hostUid || !followerUid) return false;
  const snapshot = await db.collection("users").doc(hostUid).collection("followers").doc(followerUid).get();
  return snapshot.exists;
};

const hasAcceptedLiveJoinRequest = async (sessionId: string, userId: string): Promise<boolean> => {
  if (!sessionId || !userId) return false;
  const snapshot = await db.collection("join_requests")
    .doc(buildLiveJoinRequestDocId(sessionId, userId))
    .get();
  if (!snapshot.exists) return false;
  const status = String(snapshot.data()?.status || "").trim().toLowerCase();
  return status === "accepted";
};

const LIVE_STAGE_GUEST_TOKEN_TTL_SECONDS = 600;

/** Clients name live channels `live-<hostUid>-<timestamp>`; anything else could be another user's channel. */
const isLiveChannelOwnedByHost = (channelName: string, hostId: string): boolean => {
  if (!channelName || !hostId) return false;
  const prefix = `live-${hostId}-`;
  return channelName.startsWith(prefix) && /^\d{9,13}$/.test(channelName.slice(prefix.length));
};

const sessionHostOwnsOrganizerEventSource = async (
  session: Record<string, unknown>,
  hostId: string
): Promise<boolean> => {
  if (!hostId) return false;
  const sourceType = String(session.sourceType || "").trim().toLowerCase();
  const sourceId = String(session.sourceId || "").trim();
  // Android labels the same organizer-event link "event".
  if ((sourceType !== "organizer_event" && sourceType !== "event") || !sourceId) return false;

  const eventSnap = await db.collection("events").doc(sourceId).get();
  if (!eventSnap.exists) return false;

  const event = eventSnap.data() || {};
  const organizerId = String(event.organizerId || "").trim();
  const organizerUid = String(event.organizerUid || "").trim();
  return organizerId === hostId || organizerUid === hostId;
};

const hasApprovedLiveEventAccess = async (
  session: Record<string, unknown>,
  userId: string,
  hostId: string
): Promise<boolean> => {
  if (!userId) return false;
  const sourceId = String(session.sourceId || "").trim();
  if (!sourceId || !(await sessionHostOwnsOrganizerEventSource(session, hostId))) return false;
  const snapshot = await db.collection("events")
    .doc(sourceId)
    .collection("applications")
    .doc(userId)
    .get();
  if (!snapshot.exists) return false;
  const status = String(snapshot.data()?.status || "").trim().toLowerCase();
  return APPROVED_EVENT_APPLICATION_STATUSES.has(status);
};

const canUserWatchLiveSession = async (
  sessionId: string,
  session: Record<string, unknown>,
  userId: string,
  hostId: string
): Promise<boolean> => {
  if (!userId) return false;
  if (hostId && userId === hostId) return true;

  switch (normalizeLiveViewAccessMode(session.viewAccessMode)) {
  case "public":
    return true;
  case "followers_only":
    return userFollowsHost(hostId, userId);
  case "invite_only":
    return hasAcceptedLiveJoinRequest(sessionId, userId);
  case "accepted_event_volunteers":
    return hasApprovedLiveEventAccess(session, userId, hostId);
  }
};

const isValidLiveShareTokenForSession = (
  sessionId: string,
  session: Record<string, unknown>,
  hostId: string,
  userId: string,
  shareAccessToken?: string
): boolean => {
  const cleanToken = String(shareAccessToken || "").trim();
  if (!cleanToken) return false;
  // Event-only streams are gated on accepted-guest status, which an invite link must not bypass.
  if (normalizeLiveViewAccessMode(session.viewAccessMode) === "accepted_event_volunteers") return false;
  try {
    const claims = verifyLiveShareAccessToken(cleanToken);
    const sessionHostId = String(session.hostId || session.hostUid || "").trim();
    return claims.sid === sessionId &&
      claims.kind === "live" &&
      claims.hostId === hostId &&
      (!sessionHostId || claims.hostId === sessionHostId);
  } catch (error) {
    functions.logger.warn("Invalid live share token.", {sessionId, userId, error});
    return false;
  }
};

/**
 * Firestore rules cannot verify signed share tokens, so a validated share-link viewer gets a
 * server-written marker that the rules accept for session, chat, like and presence access.
 */
const grantLiveInvitedViewerAccess = async (sessionId: string, userId: string): Promise<void> => {
  await db.collection("live_sessions")
    .doc(sessionId)
    .collection("invited_viewers")
    .doc(userId)
    .set({
      userId,
      via: "share_link",
      grantedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, {merge: true});
};

const canUserWatchLiveSessionWithShareToken = async (
  sessionId: string,
  session: Record<string, unknown>,
  userId: string,
  hostId: string,
  shareAccessToken?: string
): Promise<boolean> => {
  if (isValidLiveShareTokenForSession(sessionId, session, hostId, userId, shareAccessToken)) {
    return true;
  }
  return canUserWatchLiveSession(sessionId, session, userId, hostId);
};

const canUserJoinLiveStage = async (
  sessionId: string,
  session: Record<string, unknown>,
  userId: string,
  hostId: string
): Promise<boolean> => {
  if (!userId) return false;
  if (hostId && userId === hostId) return true;

  switch (normalizeLiveStageAccessMode(session.stageAccessMode)) {
  case "host_only":
    return false;
  case "approved_volunteers":
  case "request_to_join":
    return hasAcceptedLiveJoinRequest(sessionId, userId);
  case "open_to_accepted_volunteers":
    return (await hasApprovedLiveEventAccess(session, userId, hostId)) ||
      (await hasAcceptedLiveJoinRequest(sessionId, userId));
  }
};

const canUserWatchLiveReplay = async (
  sessionId: string,
  session: Record<string, unknown>,
  userId: string,
  hostId: string
): Promise<boolean> => {
  if (!userId) return false;
  if (hostId && userId === hostId) return true;

  switch (normalizeLiveReplayVisibility(session.replayVisibility)) {
  case "owner_only":
    return false;
  case "shared_link":
    // Non-host replay playback must come from a host-issued share/replay JWT, not open minting.
    return false;
  case "followers_only":
    return userFollowsHost(hostId, userId);
  case "public":
    return true;
  }
};

const LIVE_ARCHIVE_PRIVATE_COLLECTION = "server_archive";
const LIVE_ARCHIVE_PRIVATE_DOC_ID = "runtime";

const liveArchivePrivateRef = (sessionId: string) =>
  db.collection("live_sessions").doc(sessionId).collection(LIVE_ARCHIVE_PRIVATE_COLLECTION).doc(LIVE_ARCHIVE_PRIVATE_DOC_ID);

/** Stores replay CDN/object URL server-side only; strips any legacy parent copy. */
const persistLiveArchivePlaybackUrl = async (
  sessionId: string,
  archivePlaybackUrl: string | undefined
): Promise<void> => {
  const sessionRef = db.collection("live_sessions").doc(sessionId);
  const privateRef = liveArchivePrivateRef(sessionId);
  const cleanUrl = String(archivePlaybackUrl || "").trim();

  if (cleanUrl) {
    await privateRef.set({
      archivePlaybackUrl: cleanUrl,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, {merge: true});
  } else {
    await privateRef.delete().catch(() => undefined);
  }

  await sessionRef.set({
    archivePlaybackUrl: admin.firestore.FieldValue.delete(),
  }, {merge: true});
};

/** Reads private archive URL; migrates + deletes legacy parent field when present. */
const resolveLiveArchivePlaybackUrl = async (
  sessionId: string,
  session?: Record<string, unknown>
): Promise<string> => {
  const sessionRef = db.collection("live_sessions").doc(sessionId);
  const privateSnap = await liveArchivePrivateRef(sessionId).get();
  const fromPrivate = String(privateSnap.data()?.archivePlaybackUrl || "").trim();
  if (fromPrivate) {
    return fromPrivate;
  }

  const data = session ?? ((await sessionRef.get()).data() || {}) as Record<string, unknown>;
  const fromParent = String(data.archivePlaybackUrl || "").trim();
  if (!fromParent) {
    return "";
  }

  await liveArchivePrivateRef(sessionId).set({
    archivePlaybackUrl: fromParent,
    migratedFromParentAt: admin.firestore.FieldValue.serverTimestamp(),
  }, {merge: true});
  await sessionRef.set({
    archivePlaybackUrl: admin.firestore.FieldValue.delete(),
  }, {merge: true});
  return fromParent;
};

const getLiveReplayAccessSecret = (): string | undefined => {
  const explicitSecret = String(process.env.LIVE_REPLAY_ACCESS_SECRET || "").trim();
  if (explicitSecret) return explicitSecret;
  const recordingSecret = String(process.env.AGORA_RECORDING_CUSTOMER_SECRET || "").trim();
  if (recordingSecret) {
    functions.logger.warn(
      "LIVE_REPLAY_ACCESS_SECRET is unset; falling back to AGORA_RECORDING_CUSTOMER_SECRET."
    );
    return recordingSecret;
  }
  return undefined;
};

const getLiveReplayAccessTtlSeconds = (purpose: LiveReplayAccessPurpose): number => {
  const raw = Number(
    purpose === "share" ?
      (process.env.LIVE_REPLAY_SHARE_TTL_SECONDS || 86400) :
      // HLS segment URLs carry this token for the whole watch; liveReplayMedia re-authorizes
      // every request against current visibility, so a longer lifetime doesn't extend access.
      (process.env.LIVE_REPLAY_ACCESS_TTL_SECONDS || 14400)
  );
  if (!Number.isFinite(raw) || raw <= 0) {
    return purpose === "share" ? 86400 : 14400;
  }
  return Math.max(60, Math.floor(raw));
};

const buildLiveReplayAccessBaseUrl = (): string => {
  const explicitBaseUrl = String(process.env.LIVE_REPLAY_ACCESS_BASE_URL || "")
    .trim()
    .replace(/\/+$/g, "");
  if (explicitBaseUrl) {
    return explicitBaseUrl;
  }

  const projectId = trimStringValue(process.env.GCLOUD_PROJECT) || trimStringValue(admin.app().options.projectId);
  if (projectId) {
    return `https://us-central1-${projectId}.cloudfunctions.net/liveReplayAccess`;
  }
  return "https://us-central1-volunteersapp-968b2.cloudfunctions.net/liveReplayAccess";
};

const buildLiveReplayAccessUrl = (signedToken: string): string => {
  const separator = buildLiveReplayAccessBaseUrl().includes("?") ? "&" : "?";
  return `${buildLiveReplayAccessBaseUrl()}${separator}token=${encodeURIComponent(signedToken)}`;
};

const buildLiveReplayMediaBaseUrl = (): string => {
  const explicitBaseUrl = String(process.env.LIVE_REPLAY_MEDIA_BASE_URL || "")
    .trim()
    .replace(/\/+$/g, "");
  if (explicitBaseUrl) {
    return explicitBaseUrl;
  }

  const projectId = trimStringValue(process.env.GCLOUD_PROJECT) || trimStringValue(admin.app().options.projectId);
  if (projectId) {
    return `https://us-central1-${projectId}.cloudfunctions.net/liveReplayMedia`;
  }
  return "https://us-central1-volunteersapp-968b2.cloudfunctions.net/liveReplayMedia";
};

const buildLiveReplayMediaUrl = (signedToken: string, objectPath: string): string => {
  const cleanPath = sanitizeLiveArchiveObjectPath(objectPath);
  const suffix = cleanPath.toLowerCase().endsWith(".mp4") ? "stream.mp4" : "playlist.m3u8";
  const url = new URL(`${buildLiveReplayMediaBaseUrl()}/${suffix}`);
  url.searchParams.set("token", signedToken);
  url.searchParams.set("file", cleanPath);
  return url.toString();
};

const assertLiveReplayMediaPathAllowed = (
  sessionId: string,
  session: Record<string, unknown>,
  objectPath: string
): string => {
  const recordingConfig = getAgoraRecordingConfig();
  const expectedPrefix = buildLiveArchiveObjectPrefix(recordingConfig, sessionId).joined;
  // Session docs were once host-writable, so a stored prefix is only trusted when it is this session's folder.
  const storedPrefix = sanitizeLiveArchiveObjectPath(String(session.archiveObjectPrefix || ""));
  const storedSegments = storedPrefix.split("/");
  const allowedPrefix = storedPrefix && storedSegments[storedSegments.length - 1] === sessionId ?
    storedPrefix :
    expectedPrefix;
  const cleanPath = sanitizeLiveArchiveObjectPath(objectPath);
  if (!cleanPath) {
    throw new Error("Replay media path is missing.");
  }
  if (allowedPrefix && cleanPath !== allowedPrefix && !cleanPath.startsWith(`${allowedPrefix}/`)) {
    throw new Error("Replay media path is not allowed.");
  }
  return cleanPath;
};

const getLiveReplayMediaContentType = (objectPath: string): string => {
  const lower = objectPath.toLowerCase();
  if (lower.endsWith(".m3u8")) return "application/vnd.apple.mpegurl";
  if (lower.endsWith(".mp4")) return "video/mp4";
  if (lower.endsWith(".ts")) return "video/mp2t";
  if (lower.endsWith(".m4s")) return "video/iso.segment";
  return "application/octet-stream";
};

/** Logs only the actionable storage failure details, never a signed replay URL or token. */
const liveReplayStorageErrorDetails = (error: unknown): {code: string | null; message: string} => {
  const record = error && typeof error === "object" ? error as Record<string, unknown> : undefined;
  const rawCode = record?.["code"];
  const code = rawCode === undefined || rawCode === null ? null : String(rawCode);
  const rawMessage = error instanceof Error ? error.message : String(record?.["message"] || "");
  return {
    code,
    message: rawMessage.trim().slice(0, 500),
  };
};

const rewriteLiveReplayHlsManifest = (
  manifestBody: string,
  manifestObjectPath: string,
  mediaToken: string
): string => {
  const manifestDir = manifestObjectPath.includes("/") ?
    manifestObjectPath.slice(0, manifestObjectPath.lastIndexOf("/")) :
    "";

  const resolveManifestPath = (rawValue: string): string => {
    const trimmed = rawValue.trim();
    return trimmed.includes("/") ?
      sanitizeLiveArchiveObjectPath(trimmed) :
      sanitizeLiveArchiveObjectPath(manifestDir ? `${manifestDir}/${trimmed}` : trimmed);
  };

  return manifestBody
    .split("\n")
    .map((line) => {
      const trimmed = line.trim();
      if (!trimmed) {
        return line;
      }

      if (trimmed.startsWith("#EXT-X-MEDIA:") && trimmed.includes("URI=\"")) {
        return line.replace(/URI="([^"]+)"/g, (_match, uriValue) => {
          const mediaPath = resolveManifestPath(String(uriValue || ""));
          return `URI="${buildLiveReplayMediaUrl(mediaToken, mediaPath)}"`;
        });
      }

      if (trimmed.startsWith("#")) {
        return line;
      }

      const segmentPath = resolveManifestPath(trimmed);
      return buildLiveReplayMediaUrl(mediaToken, segmentPath);
    })
    .join("\n");
};

/** Bearer replay links (anonymous web or share-link viewers) are only honoured while the host allows link access. */
const isLiveReplayLinkShareable = (visibility: LiveReplayVisibility): boolean =>
  visibility === "shared_link" || visibility === "public";

const isUserBlockedFromLiveSession = async (sessionId: string, userId: string): Promise<boolean> => {
  if (!sessionId || !userId) return false;
  const snap = await db.collection("live_sessions").doc(sessionId).collection("blocked_users").doc(userId).get();
  return snap.exists;
};

/**
 * Re-authorizes every replay media request against the session's current state so narrowing
 * replay visibility or blocking a viewer revokes previously issued replay tokens.
 */
const authorizeLiveReplayClaims = async (
  claims: LiveReplayAccessClaims,
  session: Record<string, unknown>,
  sessionId: string
): Promise<void> => {
  const hostId = String(session.hostId || session.hostUid || "").trim();
  if (!hostId) {
    throw new Error("You are not allowed to access this replay.");
  }
  if (claims.hostId && claims.hostId !== hostId) {
    throw new Error("You are not allowed to access this replay.");
  }
  const visibility = normalizeLiveReplayVisibility(session.replayVisibility);

  if (claims.purpose !== "playback" || !claims.uid) {
    if (!isLiveReplayLinkShareable(visibility)) {
      throw new Error("The host has turned off link access to this replay.");
    }
    return;
  }

  const requesterUid = String(claims.uid).trim();
  if (!requesterUid) {
    throw new Error("You are not allowed to access this replay.");
  }
  if (requesterUid === hostId) {
    return;
  }

  const [hostBlockedViewer, viewerBlockedHost, streamBlocked] = await Promise.all([
    userHasBlocked(hostId, requesterUid),
    userHasBlocked(requesterUid, hostId),
    isUserBlockedFromLiveSession(sessionId, requesterUid),
  ]);
  if (hostBlockedViewer || viewerBlockedHost || streamBlocked) {
    throw new Error("You are not allowed to access this replay.");
  }

  if (claims.via === "share_link") {
    if (!isLiveReplayLinkShareable(visibility)) {
      throw new Error("The host has turned off link access to this replay.");
    }
    return;
  }

  if (!(await canUserWatchLiveReplay(sessionId, session, requesterUid, hostId))) {
    throw new Error("You are not allowed to access this replay.");
  }
};

const buildLiveShareBaseUrl = (): string => {
  const explicitBaseUrl = String(process.env.LIVE_SHARE_BASE_URL || "")
    .trim()
    .replace(/\/+$/g, "");
  if (explicitBaseUrl) {
    return explicitBaseUrl;
  }
  return "https://softsolutionstech.com/live";
};

const buildLiveShareUrl = (params: {
  sessionId: string;
  hostId: string;
  signedToken: string;
}): string => {
  const url = new URL(buildLiveShareBaseUrl());
  url.searchParams.set("sessionId", params.sessionId);
  url.searchParams.set("hostId", params.hostId);
  url.searchParams.set("token", params.signedToken);
  return url.toString();
};

const isLiveSessionCurrentlyActive = (status: unknown): boolean => {
  const normalized = String(status || "").trim().toLowerCase();
  return normalized.includes("live") || normalized.includes("active") || normalized.includes("started");
};

const buildLiveAppDeepLink = (
  sessionId: string,
  hostId: string,
  shareAccessToken?: string
): string => {
  const url = new URL("volunteersapp://live");
  if (sessionId) {
    url.searchParams.set("sessionId", sessionId);
  }
  if (hostId) {
    url.searchParams.set("hostId", hostId);
  }
  const token = String(shareAccessToken || "").trim();
  if (token) {
    // Keep the host-issued invitation when a browser viewer opens either mobile app.
    url.searchParams.set("token", token);
  }
  return url.toString();
};

interface LiveReplayAccessClaims {
  sid: string;
  purpose: LiveReplayAccessPurpose;
  uid?: string;
  hostId?: string;
  replayVisibility: LiveReplayVisibility;
  via?: "share_link";
  version: number;
}

interface LiveShareAccessClaims {
  sid: string;
  kind: LiveShareAccessKind;
  hostId: string;
  version: number;
}

const signLiveReplayAccessToken = (params: {
  sessionId: string;
  purpose: LiveReplayAccessPurpose;
  requesterUid: string;
  hostId: string;
  replayVisibility: LiveReplayVisibility;
  via?: "share_link";
  ttlSecondsOverride?: number;
}): {token: string; expiresAtMs: number} => {
  const secret = getLiveReplayAccessSecret();
  if (!secret) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Replay access signing is not configured on the server."
    );
  }

  const ttlSeconds = params.ttlSecondsOverride ?? getLiveReplayAccessTtlSeconds(params.purpose);
  const issuedAtSeconds = Math.floor(Date.now() / 1000);
  const expiresAtSeconds = issuedAtSeconds + ttlSeconds;
  const token = jwt.sign(
    {
      sid: params.sessionId,
      purpose: params.purpose,
      uid: params.purpose === "playback" ? params.requesterUid : undefined,
      hostId: params.hostId,
      replayVisibility: params.replayVisibility,
      via: params.via,
      version: 1,
    } satisfies LiveReplayAccessClaims,
    secret,
    {
      algorithm: "HS256",
      issuer: "volunteersapp-live-replay",
      audience: "live-replay-access",
      subject: params.purpose === "share" ? params.hostId : params.requesterUid,
      expiresIn: ttlSeconds,
    }
  );

  return {
    token,
    expiresAtMs: expiresAtSeconds * 1000,
  };
};

const verifyLiveReplayAccessToken = (token: string): LiveReplayAccessClaims => {
  const secret = getLiveReplayAccessSecret();
  if (!secret) {
    throw new Error("Replay access signing is not configured on the server.");
  }

  const verified = jwt.verify(token, secret, {
    algorithms: ["HS256"],
    issuer: "volunteersapp-live-replay",
    audience: "live-replay-access",
  });

  if (!verified || typeof verified !== "object") {
    throw new Error("Replay access token is invalid.");
  }

  const sid = String((verified as Record<string, unknown>).sid || "").trim();
  const purpose = normalizeLiveReplayAccessPurpose((verified as Record<string, unknown>).purpose);
  const replayVisibility = normalizeLiveReplayVisibility(
    (verified as Record<string, unknown>).replayVisibility
  );
  const version = Number((verified as Record<string, unknown>).version || 0);

  if (!sid || version !== 1) {
    throw new Error("Replay access token payload is incomplete.");
  }

  const uid = trimStringValue((verified as Record<string, unknown>).uid);
  const hostId = trimStringValue((verified as Record<string, unknown>).hostId);
  const via = trimStringValue((verified as Record<string, unknown>).via) === "share_link" ? "share_link" : undefined;
  return {
    sid,
    purpose,
    uid,
    hostId,
    replayVisibility,
    via,
    version,
  };
};

const getLiveShareAccessSecret = (): string | undefined => {
  const explicitSecret = String(process.env.LIVE_SHARE_ACCESS_SECRET || "").trim();
  if (explicitSecret) return explicitSecret;
  const replaySecret = String(process.env.LIVE_REPLAY_ACCESS_SECRET || "").trim();
  if (replaySecret) return replaySecret;
  return undefined;
};

const getLiveShareAccessTtlSeconds = (kind: LiveShareAccessKind): number => {
  const raw = Number(
    kind === "replay" ?
      (process.env.LIVE_SHARE_REPLAY_TTL_SECONDS || process.env.LIVE_REPLAY_SHARE_TTL_SECONDS || 2592000) :
      (process.env.LIVE_SHARE_ACCESS_TTL_SECONDS || 7200)
  );
  if (!Number.isFinite(raw) || raw <= 0) {
    return kind === "replay" ? 2592000 : 7200;
  }
  return Math.max(300, Math.floor(raw));
};

const signLiveShareAccessToken = (params: {
  sessionId: string;
  kind: LiveShareAccessKind;
  hostId: string;
}): {token: string; expiresAtMs: number} => {
  const secret = getLiveShareAccessSecret();
  if (!secret) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Live share signing is not configured on the server."
    );
  }

  const ttlSeconds = getLiveShareAccessTtlSeconds(params.kind);
  const issuedAtSeconds = Math.floor(Date.now() / 1000);
  const expiresAtSeconds = issuedAtSeconds + ttlSeconds;
  const token = jwt.sign(
    {
      sid: params.sessionId,
      kind: params.kind,
      hostId: params.hostId,
      version: 1,
    } satisfies LiveShareAccessClaims,
    secret,
    {
      algorithm: "HS256",
      issuer: "volunteersapp-live-share",
      audience: "live-share-access",
      subject: params.hostId,
      expiresIn: ttlSeconds,
    }
  );

  return {
    token,
    expiresAtMs: expiresAtSeconds * 1000,
  };
};

const verifyLiveShareAccessToken = (token: string): LiveShareAccessClaims => {
  const {claims, expired} = verifyLiveShareAccessTokenAllowingExpiry(token);
  if (expired) {
    throw new Error("Live share access token has expired.");
  }
  return claims;
};

/**
 * Signature, issuer and audience are always enforced. Expired links are still recognised so a
 * host-shared link can keep opening a replay whose visibility allows link access.
 */
const verifyLiveShareAccessTokenAllowingExpiry = (
  token: string
): {claims: LiveShareAccessClaims; expired: boolean} => {
  const secret = getLiveShareAccessSecret();
  if (!secret) {
    throw new Error("Live share signing is not configured on the server.");
  }

  const verified = jwt.verify(token, secret, {
    algorithms: ["HS256"],
    issuer: "volunteersapp-live-share",
    audience: "live-share-access",
    ignoreExpiration: true,
  });

  if (!verified || typeof verified !== "object") {
    throw new Error("Live share access token is invalid.");
  }

  const sid = String((verified as Record<string, unknown>).sid || "").trim();
  const kind = normalizeLiveShareAccessKind((verified as Record<string, unknown>).kind);
  const hostId = String((verified as Record<string, unknown>).hostId || "").trim();
  const version = Number((verified as Record<string, unknown>).version || 0);

  if (!sid || !hostId || version !== 1) {
    throw new Error("Live share access token payload is incomplete.");
  }

  const exp = Number((verified as Record<string, unknown>).exp || 0);
  return {
    claims: {
      sid,
      kind,
      hostId,
      version,
    },
    expired: !Number.isFinite(exp) || exp <= 0 || exp * 1000 <= Date.now(),
  };
};

const buildLiveShareCorsHeaders = (res: functions.Response): void => {
  res.set("Access-Control-Allow-Origin", "*");
  res.set("Access-Control-Allow-Methods", "GET, OPTIONS");
  res.set("Access-Control-Allow-Headers", "Content-Type");
  res.set("Cache-Control", "private, no-store, no-cache, max-age=0");
};

/** Replay URLs carry a signed access token, so any web origin may fetch them (hls.js loads them with XHR). */
const applyLiveReplayCorsHeaders = (req: functions.https.Request, res: functions.Response): boolean => {
  res.set("Access-Control-Allow-Origin", "*");
  res.set("Access-Control-Allow-Methods", "GET, HEAD, OPTIONS");
  res.set("Access-Control-Allow-Headers", "Range");
  res.set("Access-Control-Expose-Headers", "Content-Length, Content-Range, Content-Type");
  res.set("Access-Control-Max-Age", "3600");
  if (String(req.method || "").toUpperCase() !== "OPTIONS") return false;
  res.status(204).end();
  return true;
};

const buildWebViewerRtcCredentials = (channelName: string): {
  appId: string;
  rtcToken: string;
  uid: number;
  expiresAtMs: number;
} => {
  const {appId, appCertificate, ttlSeconds: appTtlSeconds} = getAgoraConfig();
  if (!appId || !appCertificate) {
    throw new Error("Agora web playback is not configured on the server.");
  }
  // Browser viewers cannot renew in place (each resolve mints a new uid), so give them a full viewing window.
  const webTtlRaw = Number(process.env.LIVE_WEB_VIEWER_TTL_SECONDS || 21600);
  const ttlSeconds = Math.min(
    86400,
    Math.max(appTtlSeconds, Number.isFinite(webTtlRaw) && webTtlRaw > 0 ? Math.floor(webTtlRaw) : 21600)
  );

  const agoraUid = randomInt(100000, 2147483000);
  const token = RtcTokenBuilder.buildTokenWithUid(
    appId,
    appCertificate,
    channelName,
    agoraUid,
    RtcRole.SUBSCRIBER,
    ttlSeconds,
    ttlSeconds
  );

  return {
    appId,
    rtcToken: token,
    uid: agoraUid,
    expiresAtMs: Date.now() + ttlSeconds * 1000,
  };
};

export const createLiveReplayAccessLink = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const authUid = context.auth.uid;
    const sessionId = String(data?.sessionId || "").trim();
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const purpose = normalizeLiveReplayAccessPurpose(data?.purpose);
    const liveSnap = await db.collection("live_sessions").doc(sessionId).get();
    if (!liveSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Live replay session not found.");
    }

    const session = (liveSnap.data() || {}) as Record<string, unknown>;
    const hostId = String(session.hostId || session.hostUid || "").trim();
    const archiveStatus = String(session.archiveStatus || "").trim().toUpperCase();
    const primaryFile = String(session.archivePrimaryFile || "").trim();
    if (archiveStatus !== "READY" || !primaryFile) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Replay is not ready to watch yet."
      );
    }

    if (!hostId) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Replay host information is missing."
      );
    }

    const replayVisibility = normalizeLiveReplayVisibility(session.replayVisibility);
    let via: "share_link" | undefined;

    if (purpose === "share") {
      if (authUid !== hostId) {
        throw new functions.https.HttpsError(
          "permission-denied",
          "Only the broadcaster can create a replay share link."
        );
      }
      if (!isLiveReplayLinkShareable(replayVisibility)) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Set replay visibility to \"Anyone with the link\" or \"Public\" before sharing a replay link."
        );
      }
    } else if (authUid !== hostId) {
      const [hostBlockedViewer, viewerBlockedHost, streamBlocked, canWatchReplay] = await Promise.all([
        userHasBlocked(hostId, authUid),
        userHasBlocked(authUid, hostId),
        isUserBlockedFromLiveSession(sessionId, authUid),
        canUserWatchLiveReplay(sessionId, session, authUid, hostId),
      ]);

      if (hostBlockedViewer || viewerBlockedHost || streamBlocked) {
        throw new functions.https.HttpsError(
          "permission-denied",
          "You are not allowed to access this replay."
        );
      }

      if (!canWatchReplay) {
        const shareAccessToken = String(data?.shareAccessToken || data?.shareToken || "").trim();
        let hasValidReplayShareToken = false;
        if (shareAccessToken && isLiveReplayLinkShareable(replayVisibility)) {
          try {
            // Matches resolveLiveShareAccess: any host-signed link opens a link-shareable replay.
            const {claims} = verifyLiveShareAccessTokenAllowingExpiry(shareAccessToken);
            hasValidReplayShareToken = claims.sid === sessionId &&
              claims.hostId === hostId;
          } catch {
            hasValidReplayShareToken = false;
          }
        }
        if (!hasValidReplayShareToken) {
          throw new functions.https.HttpsError(
            "permission-denied",
            "This replay is not available for your account."
          );
        }
        via = "share_link";
      }
    }

    const signed = signLiveReplayAccessToken({
      sessionId,
      purpose,
      requesterUid: authUid,
      hostId,
      replayVisibility,
      via,
    });

    const playbackUrl = purpose === "playback" && primaryFile ?
      buildLiveReplayMediaUrl(signed.token, primaryFile) :
      undefined;

    return {
      success: true,
      purpose,
      accessUrl: buildLiveReplayAccessUrl(signed.token),
      playbackUrl,
      expiresAtMs: signed.expiresAtMs,
      replayVisibility,
    };
  });

export const createLiveShareAccessLink = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const authUid = context.auth.uid;
    const sessionId = String(data?.sessionId || "").trim();
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const kind = normalizeLiveShareAccessKind(data?.kind);
    const liveSnap = await db.collection("live_sessions").doc(sessionId).get();
    if (!liveSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Live session not found.");
    }

    const session = (liveSnap.data() || {}) as Record<string, unknown>;
    const hostId = String(session.hostId || session.hostUid || "").trim();
    if (!hostId || authUid !== hostId) {
      throw new functions.https.HttpsError(
        "permission-denied",
        "Only the broadcaster can create a browser-ready live share link."
      );
    }

    const isActive = isLiveSessionCurrentlyActive(session.status);
    const archiveStatus = String(session.archiveStatus || "").trim().toUpperCase();
    const primaryFile = String(session.archivePrimaryFile || "").trim();
    if (kind === "live" && !isActive) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "This live session has ended. Share the replay link instead."
      );
    }
    if (kind === "live" && normalizeLiveViewAccessMode(session.viewAccessMode) === "accepted_event_volunteers") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Event-only live streams are limited to accepted event guests, so invite links are not available."
      );
    }
    if (kind === "replay") {
      if (archiveStatus !== "READY" || !primaryFile) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Replay is not ready to share yet."
        );
      }
      if (!isLiveReplayLinkShareable(normalizeLiveReplayVisibility(session.replayVisibility))) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Set replay visibility to \"Anyone with the link\" or \"Public\" before sharing a replay link."
        );
      }
    }

    const signed = signLiveShareAccessToken({
      sessionId,
      kind,
      hostId,
    });

    return {
      success: true,
      kind,
      accessUrl: buildLiveShareUrl({
        sessionId,
        hostId,
        signedToken: signed.token,
      }),
      expiresAtMs: signed.expiresAtMs,
    };
  });

export const liveReplayAccess = functions.https.onRequest(async (req, res) => {
  if (applyLiveReplayCorsHeaders(req, res)) return;
  if (!["GET", "HEAD"].includes(String(req.method || "").toUpperCase())) {
    res.status(405).json({error: "Method not allowed. Use GET."});
    return;
  }

  const token = String(req.query["token"] || "").trim();
  if (!token) {
    res.status(400).json({error: "Missing replay access token."});
    return;
  }

  let claims: LiveReplayAccessClaims;
  try {
    claims = verifyLiveReplayAccessToken(token);
  } catch (error) {
    functions.logger.warn("Invalid live replay access token.", {error});
    res.status(403).json({error: "Replay access token is invalid or expired."});
    return;
  }

  try {
    const liveSnap = await db.collection("live_sessions").doc(claims.sid).get();
    if (!liveSnap.exists) {
      res.status(404).json({error: "Live replay session not found."});
      return;
    }

    const session = (liveSnap.data() || {}) as Record<string, unknown>;
    const archiveStatus = String(session.archiveStatus || "").trim().toUpperCase();
    const primaryFile = String(session.archivePrimaryFile || "").trim();
    if (archiveStatus !== "READY" || !primaryFile) {
      res.status(410).json({error: "Replay is no longer available."});
      return;
    }

    try {
      await authorizeLiveReplayClaims(claims, session, claims.sid);
    } catch (error) {
      res.status(403).json({error: error instanceof Error ? error.message : "Forbidden"});
      return;
    }

    res.set("Cache-Control", "private, no-store, no-cache, max-age=0");
    res.redirect(302, buildLiveReplayMediaUrl(token, primaryFile));
  } catch (error) {
    functions.logger.error("Live replay access redirect failed.", {
      sessionId: claims.sid,
      error,
    });
    res.status(500).json({error: "Could not open replay right now."});
  }
});

export const liveReplayMedia = functions.runWith({
  timeoutSeconds: 120,
  memory: "512MB",
}).https.onRequest(async (req, res) => {
  if (applyLiveReplayCorsHeaders(req, res)) return;
  if (!["GET", "HEAD"].includes(String(req.method || "").toUpperCase())) {
    res.status(405).json({error: "Method not allowed. Use GET."});
    return;
  }

  const token = String(req.query["token"] || "").trim();
  const requestedFile = String(req.query["file"] || "").trim();
  if (!token || !requestedFile) {
    res.status(400).json({error: "Missing replay media token or file path."});
    return;
  }

  let claims: LiveReplayAccessClaims;
  try {
    claims = verifyLiveReplayAccessToken(token);
  } catch (error) {
    functions.logger.warn("Invalid live replay media token.", {error});
    res.status(403).json({error: "Replay media token is invalid or expired."});
    return;
  }

  try {
    const liveSnap = await db.collection("live_sessions").doc(claims.sid).get();
    if (!liveSnap.exists) {
      res.status(404).json({error: "Live replay session not found."});
      return;
    }

    const session = (liveSnap.data() || {}) as Record<string, unknown>;
    const archiveStatus = String(session.archiveStatus || "").trim().toUpperCase();
    if (archiveStatus !== "READY") {
      res.status(410).json({error: "Replay is no longer available."});
      return;
    }

    await authorizeLiveReplayClaims(claims, session, claims.sid);

    const objectPath = assertLiveReplayMediaPathAllowed(claims.sid, session, requestedFile);
    if (liveArchiveBucketCandidates(session).length === 0) {
      res.status(500).json({error: "Replay storage is not configured."});
      return;
    }

    const lookup = await findLiveArchiveObjectBucket(session, objectPath);
    if (!lookup.bucketName && lookup.hadError) {
      functions.logger.error("Live replay storage availability check failed.", {sessionId: claims.sid});
      res.status(503).json({
        error: "Replay storage is temporarily unavailable. Please try again shortly.",
        code: "REPLAY_STORAGE_UNAVAILABLE",
      });
      return;
    }
    const exists = !!lookup.bucketName;
    if (lookup.bucketName && lookup.bucketName !== String(session.archiveBucket || "").trim()) {
      liveSnap.ref.set({archiveBucket: lookup.bucketName}, {merge: true}).catch((error) => {
        functions.logger.warn("Could not remember live replay bucket.", {sessionId: claims.sid, error: String(error)});
      });
    }
    // Only the server-recorded primary file may demote the replay; the caller picks `file`,
    // so any other missing path must not change session state.
    const primaryObjectPath = sanitizeLiveArchiveObjectPath(String(session.archivePrimaryFile || ""));
    if (!exists && objectPath !== primaryObjectPath) {
      res.status(404).json({error: "Replay media file was not found."});
      return;
    }
    if (!exists) {
      functions.logger.warn("Live replay primary file is not in private storage yet.", {
        sessionId: claims.sid,
        objectPath,
      });
      try {
        await liveSnap.ref.update({
          archiveStatus: "PROCESSING",
          archiveReadyAt: admin.firestore.FieldValue.delete(),
          archiveError: "Replay files are still transferring to secure storage. Playback will be enabled automatically when the upload completes.",
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        });
      } catch (error) {
        functions.logger.warn("Could not return missing live replay to processing state.", {
          sessionId: claims.sid,
          error: String(error),
        });
      }
      res.status(404).json({error: "Replay media file was not found."});
      return;
    }

    const file = getStorage().bucket(lookup.bucketName as string).file(objectPath);
    const contentType = getLiveReplayMediaContentType(objectPath);
    res.set("Cache-Control", "private, no-store, no-cache, max-age=0");
    res.set("Content-Type", contentType);

    if (String(req.method || "").toUpperCase() === "HEAD") {
      res.status(200).end();
      return;
    }

    if (objectPath.toLowerCase().endsWith(".m3u8")) {
      let contents: Buffer;
      try {
        [contents] = await file.download();
      } catch (error) {
        const details = liveReplayStorageErrorDetails(error);
        functions.logger.error("Live replay playlist download failed.", {
          sessionId: claims.sid,
          storageErrorCode: details.code,
          storageErrorMessage: details.message,
        });
        res.status(503).json({
          error: "Replay storage is temporarily unavailable. Please try again shortly.",
          code: "REPLAY_STORAGE_UNAVAILABLE",
        });
        return;
      }
      const rewritten = rewriteLiveReplayHlsManifest(contents.toString("utf8"), objectPath, token);
      res.status(200).send(rewritten);
      return;
    }

    res.status(200);
    file.createReadStream()
      .on("error", (error) => {
        const details = liveReplayStorageErrorDetails(error);
        functions.logger.error("Live replay media stream failed.", {
          sessionId: claims.sid,
          objectPath,
          storageErrorCode: details.code,
          storageErrorMessage: details.message,
        });
        if (!res.headersSent) {
          res.status(503).json({
            error: "Replay storage is temporarily unavailable. Please try again shortly.",
            code: "REPLAY_STORAGE_UNAVAILABLE",
          });
        } else {
          res.end();
        }
      })
      .pipe(res);
  } catch (error) {
    const details = liveReplayStorageErrorDetails(error);
    const message = details.message || "Could not stream replay media.";
    const isAccessDenied = details.code === "401" ||
      details.code === "403" ||
      /not allowed|permission denied|forbidden/i.test(message);
    const status = isAccessDenied ? 403 : 503;
    functions.logger.error("Live replay media request failed.", {
      sessionId: claims.sid,
      storageErrorCode: details.code,
      storageErrorMessage: message,
    });
    if (!res.headersSent) {
      res.status(status).json({
        error: isAccessDenied
          ? "You are not allowed to access this replay."
          : "Replay storage is temporarily unavailable. Please try again shortly.",
        code: isAccessDenied ? "REPLAY_ACCESS_DENIED" : "REPLAY_STORAGE_UNAVAILABLE",
      });
    }
  }
});

export const resolveLiveShareAccess = functions.https.onRequest(async (req, res) => {
  buildLiveShareCorsHeaders(res);
  if (String(req.method || "").toUpperCase() === "OPTIONS") {
    res.status(204).send("");
    return;
  }
  if (String(req.method || "").toUpperCase() !== "GET") {
    res.status(405).json({error: "Method not allowed. Use GET."});
    return;
  }

  const token = String(req.query["token"] || "").trim();
  const requestedSessionId = String(req.query["sessionId"] || "").trim();
  const requestedHostId = String(req.query["hostId"] || "").trim();

  // Signed links carry host-delegated access; plain links only open what is already public.
  let claims: LiveShareAccessClaims | undefined;
  let tokenExpired = false;
  if (token) {
    try {
      const verified = verifyLiveShareAccessTokenAllowingExpiry(token);
      claims = verified.claims;
      tokenExpired = verified.expired;
    } catch (error) {
      functions.logger.warn("Invalid live share token.", {error});
      if (!requestedSessionId || !requestedHostId) {
        res.status(403).json({error: "Live share token is invalid or expired."});
        return;
      }
    }
  }

  const sessionId = claims?.sid || requestedSessionId;
  const claimedHostId = claims?.hostId || requestedHostId;
  if (!sessionId || !claimedHostId || !/^[A-Za-z0-9_-]{1,128}$/.test(sessionId)) {
    res.status(400).json({error: "Missing live share link details."});
    return;
  }
  if (claims && requestedSessionId && requestedSessionId !== claims.sid) {
    res.status(403).json({error: "Live share link does not match this session."});
    return;
  }

  try {
    const liveSnap = await db.collection("live_sessions").doc(sessionId).get();
    if (!liveSnap.exists) {
      res.status(404).json({error: "Live session not found."});
      return;
    }

    const session = (liveSnap.data() || {}) as Record<string, unknown>;
    const hostId = String(session.hostId || session.hostUid || "").trim();
    if (!hostId || hostId !== claimedHostId) {
      res.status(403).json({error: "Live share host information does not match."});
      return;
    }

    const title = String(session.title || "Live Session").trim() || "Live Session";
    const hostName = String(session.hostName || session.hostUsername || "Host").trim() || "Host";
    // The token authorizes invite-only/shared-link access. Returning it in the
    // app link prevents the browser-to-app handoff from silently losing access.
    const appUrl = buildLiveAppDeepLink(sessionId, hostId, claims ? token : undefined);
    const isActive = isLiveSessionCurrentlyActive(session.status);
    const archiveStatus = String(session.archiveStatus || "").trim().toUpperCase();
    const primaryFile = String(session.archivePrimaryFile || "").trim();
    const replayVisibility = normalizeLiveReplayVisibility(session.replayVisibility);
    const replayReady = archiveStatus === "READY" && Boolean(primaryFile);
    const replayPending = ["STARTING", "RECORDING", "PROCESSING"].includes(archiveStatus);
    const viewAccessMode = normalizeLiveViewAccessMode(session.viewAccessMode);
    const base = {sessionId, hostId, title, hostName, appUrl};

    // Any host-signed link opens a replay the host has made link-shareable; public replays open from plain links.
    // Visibility is rechecked on every media request, so link expiry is not the revocation mechanism here.
    const replayOpenToLink = claims ?
      isLiveReplayLinkShareable(replayVisibility) :
      replayVisibility === "public";

    const sendReplay = (): void => {
      const signedReplay = signLiveReplayAccessToken({
        sessionId,
        purpose: "share",
        requesterUid: hostId,
        hostId,
        replayVisibility,
        ttlSecondsOverride: 4 * 60 * 60,
      });
      res.status(200).json({
        success: true,
        state: "replay",
        ...base,
        web: {
          mode: "video",
          playbackUrl: buildLiveReplayMediaUrl(signedReplay.token, primaryFile),
          expiresAtMs: signedReplay.expiresAtMs,
        },
      });
    };

    if (claims?.kind === "replay" || !isActive) {
      if (!replayOpenToLink) {
        const isReplayLink = claims?.kind === "replay";
        res.status(isReplayLink ? 403 : 410).json({
          error: isReplayLink ?
            "The host has turned off link access to this replay." :
            "This live session has ended.",
          state: isReplayLink ? "restricted" : "ended",
          replayAvailable: false,
          ...base,
        });
        return;
      }
      if (replayReady) {
        sendReplay();
        return;
      }
      res.status(410).json({
        error: replayPending ? "The replay is still being prepared." : "Replay is not available for this broadcast.",
        state: replayPending ? "processing" : "ended",
        replayAvailable: false,
        ...base,
      });
      return;
    }

    if (viewAccessMode === "accepted_event_volunteers") {
      res.status(403).json({
        error: "Browser share links are not available for event-only live streams.",
        state: "restricted",
        ...base,
      });
      return;
    }

    const hasLiveInvite = claims?.kind === "live" && !tokenExpired;
    if (!hasLiveInvite && viewAccessMode !== "public") {
      res.status(403).json({
        error: claims ?
          "This live invite has expired. Open it in Volunteers App or ask the host for a new link." :
          "This live stream is not open to browser viewers. Open it in Volunteers App.",
        state: "restricted",
        ...base,
      });
      return;
    }

    const channelName = String(session.agoraChannelName || session.channelName || "").trim();
    if (!channelName) {
      res.status(500).json({error: "Live stream channel is missing."});
      return;
    }
    if (!isLiveChannelOwnedByHost(channelName, hostId)) {
      res.status(403).json({error: "Live stream channel does not match this session."});
      return;
    }

    // Host-minted share JWTs intentionally delegate watch access on the web without Firebase auth.
    functions.logger.info("resolveLiveShareAccess granted live web viewer.", {
      sessionId,
      hostId,
      viewAccessMode,
      viaInvite: hasLiveInvite,
    });

    const rtc = buildWebViewerRtcCredentials(channelName);
    res.status(200).json({
      success: true,
      state: "live",
      ...base,
      web: {
        mode: "agora_live_viewer",
        appId: rtc.appId,
        channelName,
        rtcToken: rtc.rtcToken,
        uid: rtc.uid,
        expiresAtMs: rtc.expiresAtMs,
      },
    });
  } catch (error) {
    functions.logger.error("Could not resolve live share access.", {
      sessionId,
      error,
    });
    res.status(500).json({error: "Could not load this live stream right now."});
  }
});

export const getAgoraRtcToken = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const sessionId = String(data?.sessionId || "").trim();
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const channelName = String(data?.channelName || "").trim();
    if (!channelName) {
      throw new functions.https.HttpsError("invalid-argument", "channelName is required.");
    }
    if (channelName.length > 64) {
      throw new functions.https.HttpsError("invalid-argument", "channelName must be 64 characters or fewer.");
    }
    const shareAccessToken = String(data?.shareAccessToken || data?.shareToken || "").trim();

    // Support both Live Sessions and Chat Calls.
    // - Live: sessionId is a live_sessions/{id} doc and only host publishes.
    // - Call: sessionId is a call_sessions/{id} doc and both sides publish (audio/video).

    const authUid = context.auth.uid;
    const requestedRoleInput = String(data?.requestedRole || "").trim().toLowerCase();
    const wantsPublisherRole = requestedRoleInput === "publisher";
    const liveSnap = await db.collection("live_sessions").doc(sessionId).get();
    const callSnap = liveSnap.exists ? null : await db.collection("call_sessions").doc(sessionId).get();

    if (!liveSnap.exists && !callSnap?.exists) {
      throw new functions.https.HttpsError("not-found", "Session not found.");
    }

    const session = (liveSnap.exists ? liveSnap.data() : callSnap?.data()) || {};
    const fallbackCallChannel = callSnap?.exists ? `call_${sessionId}` : "";
    const expectedChannel = String(
      session.agoraChannelName || session.channelName || session.agoraChannel || fallbackCallChannel
    ).trim();
    if (!expectedChannel || expectedChannel !== channelName) {
      throw new functions.https.HttpsError("permission-denied", "Channel does not match session.");
    }

    let rtcRole = RtcRole.SUBSCRIBER;
    let requestedRole = "viewer";
    let canPublish = false;

    if (liveSnap.exists) {
      const hostId = String(session.hostId || session.hostUid || "").trim();
      if (!isLiveChannelOwnedByHost(expectedChannel, hostId)) {
        throw new functions.https.HttpsError("permission-denied", "Channel does not match session.");
      }
      const statusRaw = String(session.status || "").trim().toLowerCase();
      const isLiveLike =
        statusRaw.includes("live") || statusRaw.includes("active") || statusRaw.includes("started");
      if (!isLiveLike) {
        throw new functions.https.HttpsError("failed-precondition", "This live session is not active.");
      }

      const isHost = Boolean(hostId && hostId === authUid);
      if (!isHost && hostId) {
        const [streamBlockSnap, hostBlockedViewer, viewerBlockedHost, canWatchDirectly, invitedSnap, canStage] =
          await Promise.all([
            db.collection("live_sessions").doc(sessionId).collection("blocked_users").doc(authUid).get(),
            userHasBlocked(hostId, authUid),
            userHasBlocked(authUid, hostId),
            canUserWatchLiveSessionWithShareToken(
              sessionId,
              session,
              authUid,
              hostId,
              shareAccessToken
            ),
            db.collection("live_sessions").doc(sessionId).collection("invited_viewers").doc(authUid).get(),
            canUserJoinLiveStage(sessionId, session, authUid, hostId),
          ]);
        // A viewer admitted by a share link keeps access for this broadcast even after the link expires,
        // unless the host has since narrowed the audience to accepted event guests.
        const isEventOnly = normalizeLiveViewAccessMode(session.viewAccessMode) === "accepted_event_volunteers";
        const canWatch = canWatchDirectly || (invitedSnap.exists && !isEventOnly);
        const stageMode = normalizeLiveStageAccessMode(session.stageAccessMode);
        if (streamBlockSnap.exists || hostBlockedViewer || viewerBlockedHost) {
          throw new functions.https.HttpsError("permission-denied", "You cannot join this live stream.");
        }
        if (!canWatch) {
          throw new functions.https.HttpsError("permission-denied", "You are not allowed to watch this live stream.");
        }
        if (isValidLiveShareTokenForSession(sessionId, session, hostId, authUid, shareAccessToken)) {
          await grantLiveInvitedViewerAccess(sessionId, authUid);
        }
        if (wantsPublisherRole && !canStage) {
          const deniedMessage = stageMode === "host_only" ?
            "Only the host can join the live stage." :
            stageMode === "open_to_accepted_volunteers" ?
              "Only accepted event guests can join the live stage." :
              "You need host approval before joining the live stage.";
          throw new functions.https.HttpsError("permission-denied", deniedMessage);
        }
        canPublish = wantsPublisherRole && canStage;
      } else if (isHost) {
        canPublish = true;
      }
      rtcRole = canPublish ? RtcRole.PUBLISHER : RtcRole.SUBSCRIBER;
      requestedRole = canPublish ? "publisher" : "viewer";
    } else {
      // Call sessions: only participants may request tokens, and everyone publishes.
      const callerId = String(session.callerId || "").trim();
      const receiverId = String(session.receiverId || "").trim();
      const sessionParticipantIds = normalizeStringList(session.participantIds);
      const acceptedParticipantIds = normalizeStringList(session.acceptedParticipantIds);
      const sessionIsGroup = Boolean(session.isGroup) || sessionParticipantIds.length > 1;

      const chatId = String(session.chatId || "").trim();
      if (!chatId) {
        throw new functions.https.HttpsError("failed-precondition", "Call chat reference is missing.");
      }
      const chatSnap = await db.collection("chats").doc(chatId).get();
      if (!chatSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Call chat not found.");
      }
      const chat = (chatSnap.data() || {}) as Record<string, unknown>;
      const chatParticipants = normalizeStringList(chat.participants);
      const exitedParticipants = normalizeStringList(chat.exitedParticipantIds);

      const explicitInvitees = new Set(
        [callerId, receiverId, ...sessionParticipantIds, ...acceptedParticipantIds]
          .map((value) => String(value).trim())
          .filter((value) => value.length > 0)
      );
      let isParticipant = explicitInvitees.has(authUid);
      // Direct 1:1 fallback when legacy clients stored participantIds differently.
      if (!isParticipant && !sessionIsGroup && chatParticipants.length === 2 && chatParticipants.includes(authUid)) {
        isParticipant = true;
      }
      if (!isParticipant) {
        throw new functions.https.HttpsError("permission-denied", "Only call participants can join this channel.");
      }

      if (!chatParticipants.includes(authUid) || exitedParticipants.includes(authUid)) {
        throw new functions.https.HttpsError("permission-denied", "You no longer have access to this call.");
      }
      if (await directChatIsBlocked(chat)) {
        throw new functions.https.HttpsError("permission-denied", "This chat is blocked.");
      }

      const statusRaw = String(session.status || "").trim().toLowerCase();
      if (["ended", "declined", "missed", "cancelled", "canceled"].includes(statusRaw)) {
        throw new functions.https.HttpsError("failed-precondition", "This call has ended.");
      }
      const createdAt = session.createdAt as FirebaseFirestore.Timestamp | undefined;
      const groupCallIsActive = sessionIsGroup && acceptedParticipantIds.length >= 2;
      if (
        statusRaw === "ringing" &&
        !groupCallIsActive &&
        createdAt?.toMillis &&
        Date.now() - createdAt.toMillis() > 5 * 60 * 1000
      ) {
        throw new functions.https.HttpsError("failed-precondition", "This call is no longer ringing.");
      }
      rtcRole = RtcRole.PUBLISHER;
      requestedRole = "publisher";
      canPublish = true;
    }

    const requestedUidRaw = data?.uid;
    let requestedAgoraUid = 0;
    if (typeof requestedUidRaw === "number" && Number.isFinite(requestedUidRaw) && requestedUidRaw >= 0) {
      requestedAgoraUid = Math.floor(requestedUidRaw);
    } else if (typeof requestedUidRaw === "string" && requestedUidRaw.trim().length > 0) {
      const parsedUid = Number(requestedUidRaw.trim());
      if (Number.isFinite(parsedUid) && parsedUid >= 0) {
        requestedAgoraUid = Math.floor(parsedUid);
      }
    }

    // Calls use a stable UID derived from the authenticated Firebase user. This
    // prevents a participant from requesting an RTC token that impersonates a
    // different member of the same private call.
    const stableAgoraUidForFirebaseUid = stableAgoraUidFromFirebaseUid;

    let agoraUid: number;
    if (callSnap?.exists) {
      const expectedAgoraUid = stableAgoraUidForFirebaseUid(authUid);
      if (requestedAgoraUid !== expectedAgoraUid) {
        throw new functions.https.HttpsError(
          "permission-denied",
          "RTC identity does not match the signed-in call participant."
        );
      }
      agoraUid = expectedAgoraUid;
    } else {
      // Live tokens are bound to a server-derived uid; clients must join with the returned `uid`.
      // A uid-0 (wildcard) token would let any viewer join as the host and kick them off.
      agoraUid = stableAgoraUidForFirebaseUid(authUid);
    }

    const {appId, appCertificate, ttlSeconds} = getAgoraConfig();
    functions.logger.log("Agora config presence", {
      hasAgoraAppId: !!appId,
      hasAgoraAppCertificate: !!appCertificate,
      tokenTtlSeconds: ttlSeconds,
    });
    if (!appId) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Agora App ID is not configured in Cloud Functions environment. Set AGORA_APP_ID in functions .env/runtime config and redeploy."
      );
    }

    if (!appCertificate) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Agora App Certificate is not configured in Cloud Functions environment. Set AGORA_APP_CERTIFICATE in functions .env/runtime config and redeploy."
      );
    }

    // Stage guests renew through this callable, which re-checks removal and blocks, so a short
    // lifetime caps how long a removed guest's modified client could keep publishing.
    const isLiveStageGuest = liveSnap.exists && canPublish &&
      String(session.hostId || session.hostUid || "").trim() !== authUid;
    const tokenTtlSeconds = isLiveStageGuest ?
      Math.min(ttlSeconds, LIVE_STAGE_GUEST_TOKEN_TTL_SECONDS) :
      ttlSeconds;

    const token = RtcTokenBuilder.buildTokenWithUid(
      appId,
      appCertificate,
      channelName,
      agoraUid,
      rtcRole,
      tokenTtlSeconds,
      tokenTtlSeconds
    );

    return {
      token,
      // Public identifier; required by iOS/Android RTC SDK to create the engine.
      // Certificate stays server-side only.
      appId,
      tokenRequired: true,
      expiresInSeconds: tokenTtlSeconds,
      role: requestedRole,
      requestedRole,
      canPublish,
      stageAccessGranted: canPublish,
      replayVisibility: liveSnap.exists ? normalizeLiveReplayVisibility(session.replayVisibility) : null,
      uid: agoraUid,
    };
  });

/** Called before the room attaches listeners so share-link viewers are not denied by Firestore rules. */
export const grantLiveShareViewerAccess = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const authUid = context.auth?.uid;
    if (!authUid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    const sessionId = String(data?.sessionId || "").trim();
    const shareAccessToken = String(data?.shareAccessToken || data?.shareToken || "").trim();
    if (!sessionId || !shareAccessToken) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId and shareAccessToken are required.");
    }

    const sessionSnap = await db.collection("live_sessions").doc(sessionId).get();
    if (!sessionSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Live session not found.");
    }
    const session = (sessionSnap.data() || {}) as Record<string, unknown>;
    const hostId = String(session.hostId || session.hostUid || "").trim();
    const statusRaw = String(session.status || "").trim().toLowerCase();
    const isLiveLike = statusRaw.includes("live") || statusRaw.includes("active") || statusRaw.includes("started");
    if (!isLiveLike) {
      return {granted: false, state: "ended"};
    }
    if (!hostId) {
      throw new functions.https.HttpsError("failed-precondition", "This live session has no broadcaster.");
    }
    if (hostId === authUid) {
      return {granted: true, state: "live"};
    }

    const [streamBlockSnap, hostBlockedViewer, viewerBlockedHost] = await Promise.all([
      db.collection("live_sessions").doc(sessionId).collection("blocked_users").doc(authUid).get(),
      userHasBlocked(hostId, authUid),
      userHasBlocked(authUid, hostId),
    ]);
    if (streamBlockSnap.exists || hostBlockedViewer || viewerBlockedHost) {
      throw new functions.https.HttpsError("permission-denied", "You cannot join this live stream.");
    }
    if (!isValidLiveShareTokenForSession(sessionId, session, hostId, authUid, shareAccessToken)) {
      throw new functions.https.HttpsError("permission-denied", "This invite link is invalid or has expired.");
    }

    await grantLiveInvitedViewerAccess(sessionId, authUid);
    return {granted: true, state: "live"};
  });

export const seedLegalDocuments = functions.region("us-central1").https.onRequest(async (req, res) => {
  if (req.method !== "POST") {
    res.status(405).json({error: "Method not allowed. Use POST."});
    return;
  }

  const providedSecret = String(
    req.header("x-admin-secret") ||
      req.query["secret"] ||
      ((req.body as Record<string, unknown> | undefined)?.["secret"] as string | undefined) ||
      ""
  ).trim();
  const expectedSecret = String(process.env.ADMIN_PAYOUT_REVERSAL_SECRET || "").trim();

  if (!expectedSecret || providedSecret !== expectedSecret) {
    res.status(403).json({error: "Forbidden"});
    return;
  }

  const now = admin.firestore.FieldValue.serverTimestamp();
  const docs = [
    {
      path: "app_config/terms_and_conditions",
      data: {
        title: "Terms and Conditions",
        text: defaultTermsAndConditions,
        version: "2026-03-10",
        updatedAt: now,
      },
    },
    {
      path: "app_config/privacy_policy",
      data: {
        title: "Privacy Policy",
        text: defaultPrivacyPolicy,
        version: "2026-03-10",
        updatedAt: now,
      },
    },
    // Legacy alias copies to support older collection naming in clients.
    {
      path: "appConfig/terms_and_conditions",
      data: {
        title: "Terms and Conditions",
        text: defaultTermsAndConditions,
        version: "2026-03-10",
        updatedAt: now,
      },
    },
    {
      path: "appConfig/privacy_policy",
      data: {
        title: "Privacy Policy",
        text: defaultPrivacyPolicy,
        version: "2026-03-10",
        updatedAt: now,
      },
    },
  ];

  try {
    const batch = db.batch();
    for (const doc of docs) {
      batch.set(db.doc(doc.path), doc.data, {merge: true});
    }
    await batch.commit();

    res.status(200).json({
      success: true,
      seededPaths: docs.map((doc) => doc.path),
    });
  } catch (error) {
    functions.logger.error("Failed to seed legal documents", {error});
    res.status(500).json({
      error: "Failed to seed legal documents.",
    });
  }
});

const AGENT_CASHOUT_FEE_TIERS = [
  {min: 0, max: 2, rate: 0.09},
  {min: 2, max: 5, rate: 0.05},
  {min: 5, max: 20, rate: 0.026},
  {min: 20, max: 40, rate: 0.0164},
  {min: 40, max: 200, rate: 0.013},
  {min: 200, max: 600, rate: 0.008},
  {min: 600, max: 1200, rate: 0.00475},
  {min: 1200, max: null, rate: 0.00314},
];

const DEFAULT_AGENT_CASHOUT_AGENT_SHARE = 0.7;
const DEFAULT_AGENT_CASHOUT_OWNER_SHARE = 0.3;
const AGENT_CASHOUT_AGENT_SHARE = DEFAULT_AGENT_CASHOUT_AGENT_SHARE;
const AGENT_CASHOUT_OWNER_SHARE = DEFAULT_AGENT_CASHOUT_OWNER_SHARE;
const EVENT_TICKET_OWNER_FEE_RATE = 0.05;
const TWO_WEEKS_MS = 14 * 24 * 60 * 60 * 1000;
const AGENT_PAYOUT_CODE_TTL_MS = 15 * 60 * 1000;
const AGENT_PAYOUT_CODE_GENERATION_MAX_ATTEMPTS = 25;
const AGENT_PAYOUT_CODES_COLLECTION = "agent_payout_codes";
const CARD_DEPOSIT_HOLD_MS = 7 * 24 * 60 * 60 * 1000;
const BANK_DEPOSIT_HOLD_MS = 5 * 24 * 60 * 60 * 1000;

const roundMoney = (value: number): number => Number(value.toFixed(2));
const agentPayoutCodeRef = (secretCode: string) => db.collection(AGENT_PAYOUT_CODES_COLLECTION).doc(secretCode);
const getWalletBalanceAmount = (userData: Record<string, unknown> | undefined): number =>
  Number(((userData?.wallet as Record<string, unknown> | undefined)?.balance) || 0);
const getWalletExternalDepositHoldAmount = (userData: Record<string, unknown> | undefined): number =>
  roundMoney(
    Number(((userData?.wallet as Record<string, unknown> | undefined)?.externalDepositHoldBalance) || 0)
  );
const getWalletSpendableBalance = (userData: Record<string, unknown> | undefined): number =>
  roundMoney(
    Math.max(
      0,
      getWalletBalanceAmount(userData) - getWalletExternalDepositHoldAmount(userData)
    )
  );
const getExternalDepositHoldDurationMs = (source: string, methodType: string): number => {
  const sourceUpper = source.toUpperCase();
  const methodUpper = methodType.toUpperCase();
  if (sourceUpper.includes("CARD") || methodUpper === "CARD") {
    return CARD_DEPOSIT_HOLD_MS;
  }
  if (sourceUpper.includes("BANK") || methodUpper === "BANK") {
    return BANK_DEPOSIT_HOLD_MS;
  }
  return 0;
};

/**
 * Best-effort ISO currency for a saved card/bank used as Connect external payout destination.
 * When unknown, returns null (no cross-currency fee — avoids charging without a clear basis).
 */
const resolveExternalPayoutInstrumentCurrency = (
  methodData: FirebaseFirestore.DocumentData,
  destinationType: "CARD" | "BANK"
): string | null => {
  const fromFields =
    asNonEmptyString(methodData.currency) ||
    asNonEmptyString(methodData.defaultCurrency) ||
    asNonEmptyString(methodData.default_currency) ||
    asNonEmptyString(methodData.payoutCurrency) ||
    asNonEmptyString(methodData.payout_currency);
  if (fromFields) {
    const c = fromFields.trim().toUpperCase();
    if (c.length === 3) return c;
  }
  const countryRaw = String(methodData.country || "").trim();
  const countryUpper = countryRaw.toUpperCase();
  if (destinationType === "BANK") {
    if (countryUpper === "US" || countryUpper === "USA" || countryRaw === "United States") {
      return "USD";
    }
  }
  return null;
};

/**
 * Stripe amounts use the smallest currency unit (e.g. cents for USD/EUR).
 * Zero-decimal and three-decimal ISO codes must not use `amount * 100`.
 * @see https://stripe.com/docs/currencies
 */
const STRIPE_ZERO_DECIMAL_CURRENCIES = new Set([
  "BIF", "CLP", "DJF", "GNF", "JPY", "KMF", "KRW", "MGA", "PYG", "RWF", "UGX", "VND", "VUV", "XAF", "XOF", "XPF",
]);
const STRIPE_THREE_DECIMAL_CURRENCIES = new Set(["BHD", "JOD", "KWD", "OMR", "TND"]);

const amountToStripeMinorUnits = (amount: number, currencyRaw: string): number => {
  if (!Number.isFinite(amount) || amount <= 0) {
    return 0;
  }
  const c = (currencyRaw || "usd").trim().toUpperCase();
  if (STRIPE_ZERO_DECIMAL_CURRENCIES.has(c)) {
    return Math.round(amount);
  }
  if (STRIPE_THREE_DECIMAL_CURRENCIES.has(c)) {
    return Math.round(amount * 1000);
  }
  return Math.round(amount * 100);
};

const amountFromStripeMinorUnits = (amount: number, currencyRaw: string): number => {
  if (!Number.isFinite(amount)) {
    return 0;
  }
  const c = (currencyRaw || "usd").trim().toUpperCase();
  if (STRIPE_ZERO_DECIMAL_CURRENCIES.has(c)) {
    return roundMoney(amount);
  }
  if (STRIPE_THREE_DECIMAL_CURRENCIES.has(c)) {
    return roundMoney(amount / 1000);
  }
  return roundMoney(amount / 100);
};

const resolveAgentCashOutRate = (amount: number): number => {
  if (amount < 1) return 0.09;
  for (const tier of AGENT_CASHOUT_FEE_TIERS) {
    const matchesMin = amount >= tier.min;
    const matchesMax = tier.max === null || amount < tier.max;
    if (matchesMin && matchesMax) return tier.rate;
  }
  return 0.09;
};

const calculateAgentCashOutFee = (amount: number): {rate: number; fee: number} => {
  const rate = resolveAgentCashOutRate(amount);
  return {rate, fee: roundMoney(amount * rate)};
};

type AgentCashoutShareConfig = {
  agentShareRate: number;
  ownerShareRate: number;
};

const defaultAgentCashoutShareConfig = (): AgentCashoutShareConfig => {
  const appConfig = getAppConfig();
  const parsedAgent = Number.parseFloat(appConfig.agentCashoutAgentShareRate);
  const parsedOwner = Number.parseFloat(appConfig.agentCashoutOwnerShareRate);
  const bothFinite = Number.isFinite(parsedAgent) && Number.isFinite(parsedOwner);
  const withinRange = bothFinite && parsedAgent >= 0 && parsedAgent <= 1 && parsedOwner >= 0 && parsedOwner <= 1;
  const sumsToOne = withinRange && Math.abs((parsedAgent + parsedOwner) - 1) < 0.000001;
  if (sumsToOne) {
    return {
      agentShareRate: parsedAgent,
      ownerShareRate: parsedOwner,
    };
  }
  return {
    agentShareRate: AGENT_CASHOUT_AGENT_SHARE,
    ownerShareRate: AGENT_CASHOUT_OWNER_SHARE,
  };
};

const resolveAgentCashoutShareConfigFromFeeSettings = (
  feeSettingsData?: Record<string, unknown>
): AgentCashoutShareConfig => {
  const fallback = defaultAgentCashoutShareConfig();
  if (!feeSettingsData) return fallback;

  const parsedAgent = Number(
    feeSettingsData.agentCashoutAgentShareRate ??
    feeSettingsData.agentCashoutAgentShare
  );
  const parsedOwner = Number(
    feeSettingsData.agentCashoutOwnerShareRate ??
    feeSettingsData.agentCashoutOwnerShare
  );

  const agentFinite = Number.isFinite(parsedAgent);
  const ownerFinite = Number.isFinite(parsedOwner);

  if (agentFinite && !ownerFinite && parsedAgent >= 0 && parsedAgent <= 1) {
    return {
      agentShareRate: parsedAgent,
      ownerShareRate: roundMoney(1 - parsedAgent),
    };
  }
  if (ownerFinite && !agentFinite && parsedOwner >= 0 && parsedOwner <= 1) {
    return {
      ownerShareRate: parsedOwner,
      agentShareRate: roundMoney(1 - parsedOwner),
    };
  }

  const withinRange = agentFinite && ownerFinite && parsedAgent >= 0 && parsedAgent <= 1 && parsedOwner >= 0 && parsedOwner <= 1;
  const sumsToOne = withinRange && Math.abs((parsedAgent + parsedOwner) - 1) < 0.000001;
  if (sumsToOne) {
    return {
      agentShareRate: parsedAgent,
      ownerShareRate: parsedOwner,
    };
  }
  return fallback;
};

const splitAgentCashOutFee = (
  fee: number,
  shareConfig: AgentCashoutShareConfig = defaultAgentCashoutShareConfig()
): {agentShare: number; ownerShare: number; agentShareRate: number; ownerShareRate: number} => {
  const agentShare = roundMoney(fee * shareConfig.agentShareRate);
  const ownerShare = roundMoney(fee * shareConfig.ownerShareRate);
  return {
    agentShare,
    ownerShare,
    agentShareRate: shareConfig.agentShareRate,
    ownerShareRate: shareConfig.ownerShareRate,
  };
};

const STAFF_FREE_ROLES = new Set(["owner", "admin", "associate", "support", "support_associate"]);
const STAFF_MANAGEABLE_ROLES = new Set(["admin", "associate", "support", "support_associate"]);
const ADMIN_MANAGEABLE_STAFF_ROLES = new Set(["associate", "support", "support_associate"]);

const normalizeRoleForFeePolicy = (value: unknown): string =>
  String(value || "").trim().toLowerCase();

const hasStaffFreeClaim = (authToken?: Record<string, unknown>): boolean => {
  if (!authToken) return false;
  const claimRole = normalizeRoleForFeePolicy(authToken["role"]);
  return (
    STAFF_FREE_ROLES.has(claimRole) ||
    authToken["owner"] === true ||
    authToken["admin"] === true ||
    authToken["associate"] === true
  );
};

const isStaffOnboardingActive = (value: unknown): boolean => {
  const status = String(value || "").trim().toUpperCase();
  return status === "" || status === "ACTIVE";
};

const isStaffFeeExempt = (
  userData?: Record<string, unknown>,
  authToken?: Record<string, unknown>
): boolean => {
  const role = normalizeRoleForFeePolicy(userData?.role);
  const roleEligible = STAFF_FREE_ROLES.has(role) || hasStaffFreeClaim(authToken);
  if (!roleEligible) return false;
  return isStaffOnboardingActive(userData?.staffOnboardingStatus);
};

const isProfileOperational = (value: unknown): boolean => {
  const status = String(value || "").trim().toLowerCase();
  return status === "" || status === "active";
};

const normalizeStaffAssignedRole = (value: unknown): string => {
  const role = normalizeRoleForFeePolicy(value);
  return STAFF_MANAGEABLE_ROLES.has(role) ? role : "";
};

const staffAccessScopeForRole = (role: string): string =>
  role === "admin" ? "ADMIN_CONSOLE" : "SUPPORT_CONSOLE";

const resolveStaffAssignedRoleFromUserData = (userData: Record<string, unknown> | undefined): string => {
  const explicitAssignedRole = normalizeStaffAssignedRole(userData?.staffAssignedRole);
  if (explicitAssignedRole) return explicitAssignedRole;
  const currentRole = resolveCanonicalRoleFromUserData(userData);
  return normalizeStaffAssignedRole(currentRole);
};

const resolveNonStaffRoleFromUserData = (userData: Record<string, unknown> | undefined): string => {
  const previousRole = normalizeRoleForFeePolicy(userData?.staffPreviousRole);
  if (previousRole && !STAFF_FREE_ROLES.has(previousRole)) {
    return previousRole;
  }
  const currentRole = resolveCanonicalRoleFromUserData(userData);
  if (currentRole && !STAFF_FREE_ROLES.has(currentRole)) {
    return currentRole;
  }
  return "";
};

const buildCustomClaimsForRole = (
  existingClaims: Record<string, unknown>,
  role: string
): Record<string, unknown> => ({
  ...existingClaims,
  owner: role === "owner",
  admin: role === "owner" || role === "admin",
  associate: role === "associate" || role === "support" || role === "support_associate",
  role,
});

const isAuthorizedAgentOperator = (
  userData?: Record<string, unknown>,
  authToken?: Record<string, unknown>
): boolean => {
  const role = normalizeRoleForFeePolicy(userData?.role);
  return role === "agent" || isStaffFeeExempt(userData, authToken);
};

type PlatformRevenueSource =
  | "stripeForexEarnings"
  | "stripeTransactionOwnerFees"
  | "mobileMoneyHiddenFee"
  | "remittanceTopUpRevenue"
  | "walletExternalCurrencyChangeFee"
  | "blindDateFees"
  | "agentAuthorizationFees"
  | "agentCashoutOwnerShare"
  | "eventTicketOwnerFee"
  | "marketplacePlatinumFee"
  | "garageSaleFee"
  | "otherIncome";

type PlatformRevenueProcessor =
  | "STRIPE"
  | "AFRIEX"
  | "OTHER";

type PlatformRevenueEntry = {
  source: PlatformRevenueSource;
  amount: number;
  note?: string;
  relatedUserId?: string;
  processor?: PlatformRevenueProcessor;
  provider?: string;
  settlementCategory?: string;
  processorMode?: string;
};

const platformRevenueRef = db.collection("system").doc("platform_revenue");
const afriexBusinessWalletMirrorRef = db.collection("system").doc(AFRIEX_BUSINESS_WALLET_MIRROR_DOC_ID);
const stripePlatformSettlementMirrorRef = db.collection("system").doc("stripe_platform_settlement_mirror");

const persistStripePlatformSettlementMirror = async (
  mirror: Record<string, unknown>
): Promise<void> => {
  await stripePlatformSettlementMirrorRef.set({
    ...mirror,
    endCustomerCustody: false,
    custodyMode: PLATFORM_REVENUE_CUSTODY_MODE,
    lastSyncedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  }, {merge: true});
};

const syncStripePlatformSettlementMirrorState = async (): Promise<Record<string, unknown>> => {
  try {
    const balance = await getStripe().balance.retrieve();
    const toEntries = (rows: ReadonlyArray<{amount: number; currency: string}>) => rows.map((row) => ({
      currency: String(row.currency || "USD").toUpperCase(),
      amount: amountFromStripeMinorUnits(Number(row.amount || 0), String(row.currency || "USD")),
    }));
    const mirror = {
      provider: "stripe",
      livemode: balance.livemode === true,
      available: toEntries(balance.available),
      pending: toEntries(balance.pending),
      lastSyncStatus: "ok",
      lastSyncMessage: null,
    };
    await persistStripePlatformSettlementMirror(mirror);
    return mirror;
  } catch (error) {
    const message = error instanceof Error ? error.message : "Stripe balance mirror could not be refreshed.";
    const mirror = {
      provider: "stripe",
      endCustomerCustody: false,
      custodyMode: PLATFORM_REVENUE_CUSTODY_MODE,
      available: [],
      pending: [],
      lastSyncStatus: "error",
      lastSyncMessage: message,
    };
    await persistStripePlatformSettlementMirror(mirror);
    return mirror;
  }
};

const persistAfriexBusinessWalletMirror = async (
  mirror: Record<string, unknown>
): Promise<void> => {
  await afriexBusinessWalletMirrorRef.set({
    ...mirror,
    lastSyncedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  }, {merge: true});
};

const readAfriexBusinessWalletMirrorPrevious = async (): Promise<Record<string, unknown> | null> => {
  const snap = await afriexBusinessWalletMirrorRef.get();
  return snap.exists ? ((snap.data() || {}) as Record<string, unknown>) : null;
};

const refreshAfriexBusinessWalletMirrorBestEffort = async (
  reason: string,
  syncedByUid: string | null = null
): Promise<void> => {
  try {
    const previous = await readAfriexBusinessWalletMirrorPrevious();
    const {mirror} = await syncAfriexBusinessWalletMirrorState({
      syncedByUid,
      previous: previous as never,
    });
    await persistAfriexBusinessWalletMirror({
      ...(mirror as unknown as Record<string, unknown>),
      lastRefreshReason: reason,
    });
  } catch (error) {
    functions.logger.warn("Afriex business wallet mirror refresh skipped.", {
      reason,
      error,
    });
  }
};

const inferPlatformRevenueProcessor = (
  entry: PlatformRevenueEntry
): PlatformRevenueProcessor => {
  const explicit = asNonEmptyString(entry.processor)?.toUpperCase();
  if (explicit === "STRIPE" || explicit === "AFRIEX" || explicit === "OTHER") {
    return explicit;
  }

  switch (entry.source) {
  case "stripeForexEarnings":
  case "stripeTransactionOwnerFees":
  case "blindDateFees":
  case "agentAuthorizationFees":
  case "eventTicketOwnerFee":
  case "marketplacePlatinumFee":
  case "garageSaleFee":
    return "STRIPE";
  case "mobileMoneyHiddenFee":
  case "remittanceTopUpRevenue":
  case "walletExternalCurrencyChangeFee":
  case "agentCashoutOwnerShare":
    return "AFRIEX";
  default:
    return "OTHER";
  }
};

const recordPlatformRevenue = (
  transaction: admin.firestore.Transaction,
  entry: PlatformRevenueEntry
): void => {
  // Reversals are valid negative entries, but a zero or invalid entry must never
  // inflate the reporting ledger's transaction count.
  const amount = roundMoney(Number(entry.amount));
  if (!Number.isFinite(amount) || amount === 0) {
    functions.logger.error("Skipped invalid platform revenue entry.", {
      source: entry.source,
      amount: entry.amount,
    });
    return;
  }
  const timestamp = admin.firestore.Timestamp.now();
  const processor = inferPlatformRevenueProcessor(entry);
  const provider = asNonEmptyString(entry.provider, processor) || processor;
  const revenueUpdate: Record<string, unknown> = {
    totalCollected: admin.firestore.FieldValue.increment(amount),
    // This ledger is audit/reporting only. Never represent it as money held by SoftSolutions.
    balance: 0,
    settlementBalance: 0,
    endCustomerCustody: false,
    custodyMode: PLATFORM_REVENUE_CUSTODY_MODE,
    reportingOnly: true,
    ownerCashoutEnabled: false,
    transactionCount: admin.firestore.FieldValue.increment(1),
    lastUpdate: timestamp,
    processorTotals: {
      [processor]: admin.firestore.FieldValue.increment(amount),
    },
  };
  revenueUpdate[entry.source] = admin.firestore.FieldValue.increment(amount);

  transaction.set(platformRevenueRef, revenueUpdate, {merge: true});
  const txRef = platformRevenueRef.collection("transactions").doc();
  transaction.set(txRef, {
    source: entry.source,
    amount,
    note: entry.note || null,
    relatedUserId: entry.relatedUserId || null,
    processor,
    provider,
    settlementCategory: asNonEmptyString(entry.settlementCategory) || null,
    processorMode: asNonEmptyString(entry.processorMode) || null,
    createdAt: timestamp,
  });
};

const generateAgentPayoutSecretCode = (): string =>
  String(randomInt(100000, 1000000));

const isReservedAgentCashOutRequest = (
  payoutData: FirebaseFirestore.DocumentData | Record<string, unknown>
): boolean => {
  const type = String(payoutData.type || "").trim().toUpperCase();
  const reservationStatus = String(payoutData.reservationStatus || "").trim().toUpperCase();
  return type === "AGENT_CASH_OUT" && reservationStatus === "RESERVED";
};

const releaseReservedAgentPayout = async (
  payoutRef: FirebaseFirestore.DocumentReference,
  payoutData: FirebaseFirestore.DocumentData,
  reason: string,
  finalStatus: "EXPIRED" | "FAILED" = "EXPIRED"
): Promise<boolean> => {
  const senderId = asNonEmptyString(payoutData.senderId);
  if (!senderId || !isReservedAgentCashOutRequest(payoutData)) return false;
  const usesProviderMirror = isAfriexHostedAgentCashOutSource(payoutData.source);

  const refundAmount = roundMoney(
    Number(
      payoutData.walletDebitedAmount ||
      payoutData.totalDebit ||
      payoutData.amount ||
      0
    )
  );
  if (!usesProviderMirror && (!Number.isFinite(refundAmount) || refundAmount <= 0)) return false;

  const userRef = db.collection("users").doc(senderId);
  let refunded = false;
  let releasedMirrorTransactionId: string | null = null;

  await db.runTransaction(async (transaction) => {
    const freshSnap = await transaction.get(payoutRef);
    if (!freshSnap.exists) return;

    const freshData = freshSnap.data() || payoutData;
    if (!isReservedAgentCashOutRequest(freshData)) return;
    if (freshData.refundProcessed === true) return;

    const now = admin.firestore.Timestamp.now();
    const payoutPatch: FirebaseFirestore.DocumentData = {
      status: finalStatus,
      reservationStatus: "RELEASED",
      refundReason: reason,
      processedAt: now,
    };

    if (usesProviderMirror) {
      releasedMirrorTransactionId = asNonEmptyString(freshData.providerMirrorTransactionId);
      payoutPatch.refundProcessed = false;
      payoutPatch.refundSkipped = true;
      payoutPatch.refundSkippedAt = now;
      payoutPatch.refundSkipReason = "Hosted wallet reservation released in provider mirror.";
    } else {
      const txRef = userRef.collection("transactions").doc();
      transaction.update(userRef, "wallet.balance", admin.firestore.FieldValue.increment(refundAmount));
      transaction.set(txRef, {
        title: "Agent Cash-out Reservation Reversal",
        amount: refundAmount,
        type: "CREDIT",
        status: "COMPLETED",
        timestamp: now,
        note: reason,
        source: "AGENT_CASH_OUT_REVERSAL",
        payoutRequestId: payoutRef.id,
      });
      payoutPatch.refundProcessed = true;
      payoutPatch.refundAmount = refundAmount;
      payoutPatch.refundTransactionId = txRef.id;
      payoutPatch.refundedAt = now;
    }

    transaction.set(payoutRef, payoutPatch, {merge: true});
    const secretCode = asNonEmptyString(freshData.secretCode, payoutData.secretCode);
    if (secretCode) {
      transaction.set(agentPayoutCodeRef(secretCode), {
        payoutRequestId: payoutRef.id,
        secretCode,
        status: "RELEASED",
        refundReason: reason,
        releasedAt: now,
        updatedAt: now,
      }, {merge: true});
    }
    refunded = true;
  });

  if (refunded) {
    if (usesProviderMirror && releasedMirrorTransactionId) {
      await syncProviderMirrorTransactionStatusById({
        userId: senderId,
        mirrorTransactionId: releasedMirrorTransactionId,
        nextStatus: ProviderMirrorTransactionStatus.Cancelled,
        providerMessage: reason,
        rawStatus: finalStatus,
      });
    }
    await finalizeSenderTransactionsForPayout(senderId, payoutRef, payoutData, "FAILED");
  }

  return refunded;
};

type FollowerNotificationSetting = "jokesPosts" | "liveStreams";

const shouldNotifyFollower = (settings: admin.firestore.DocumentData | undefined, field: FollowerNotificationSetting): boolean => {
  if (!settings) return true;
  const value = settings[field];
  return value === undefined ? true : Boolean(value);
};

const notifyFollowers = async (params: {
  actorId: string;
  title: string;
  body: string;
  type: string;
  referenceId: string;
  settingsField: FollowerNotificationSetting;
  extraData?: Record<string, string>;
  /** Extra people to notify (e.g. accepted event guests), deduplicated against followers. */
  additionalRecipientIds?: string[];
  /** For audiences followers can't watch (invite/event-only), notify only the additional recipients. */
  skipFollowers?: boolean;
}): Promise<void> => {
  const {actorId, title, body, type, referenceId, settingsField, extraData} = params;
  const recipientIds = new Set<string>();
  if (!params.skipFollowers) {
    const followersSnap = await db.collection("users").doc(actorId).collection("followers").get();
    followersSnap.docs.forEach((doc) => recipientIds.add(doc.id));
  }
  (params.additionalRecipientIds || []).forEach((id) => {
    const clean = String(id || "").trim();
    if (clean) recipientIds.add(clean);
  });
  recipientIds.delete(actorId);
  // Follow docs survive a block, so a blocked user could otherwise keep receiving the actor's alerts.
  const [actorBlockedSnap, actorBlockedLegacySnap] = await Promise.all([
    db.collection("users").doc(actorId).collection("blocked_users").get(),
    db.collection("users").doc(actorId).collection("blockedUsers").get(),
  ]);
  actorBlockedSnap.docs.forEach((doc) => recipientIds.delete(doc.id));
  actorBlockedLegacySnap.docs.forEach((doc) => recipientIds.delete(doc.id));
  if (recipientIds.size === 0) {
    return;
  }

  const tokens: string[] = [];
  let batch = db.batch();
  let batchWrites = 0;
  const timestamp = admin.firestore.FieldValue.serverTimestamp();

  for (const followerId of recipientIds) {
    const [settingsDoc, recipientBlockedActor] = await Promise.all([
      db.collection("users").doc(followerId).collection("settings").doc("notifications").get(),
      userHasBlocked(followerId, actorId),
    ]);
    if (recipientBlockedActor) {
      continue;
    }
    const settings = settingsDoc.data();

    if (!shouldNotifyFollower(settings, settingsField)) {
      continue;
    }

    const followerUserDoc = await db.collection("users").doc(followerId).get();
    const routing = await getUserPushRouting(
      followerId,
      (followerUserDoc.data() || {}) as Record<string, unknown>
    );
    if (routing.fcmToken) {
      tokens.push(routing.fcmToken);
    }

    const notificationRef = db.collection("users").doc(followerId).collection("notifications").doc();
    batch.set(notificationRef, {
      type,
      title,
      body,
      actorId,
      referenceId,
      read: false,
      createdAt: timestamp,
    });
    batchWrites += 1;
    if (batchWrites >= 400) {
      await batch.commit();
      batch = db.batch();
      batchWrites = 0;
    }
  }

  if (batchWrites > 0) {
    await batch.commit();
  }

  if (tokens.length > 0) {
    const data: Record<string, string> = {
      type,
      actorId,
      referenceId,
      ...(extraData || {}),
    };
    if (type === "liveStream") {
      data.sessionId = data.sessionId || referenceId;
      data.hostId = data.hostId || actorId;
    }
    for (let start = 0; start < tokens.length; start += 500) {
      await admin.messaging().sendEachForMulticast({
        tokens: tokens.slice(start, start + 500),
        notification: {title, body},
        data,
      });
    }
  }
};

const apnsVoipCredentialsReady = (): boolean => {
  const team = (process.env.APNS_VOIP_TEAM_ID || process.env.APNS_TEAM_ID || "").trim();
  const kid = (process.env.APNS_VOIP_KEY_ID || process.env.APNS_KEY_ID || "").trim();
  const p8 = (process.env.APNS_VOIP_P8 || process.env.APNS_P8 || "").trim();
  const bundle = (process.env.IOS_APP_BUNDLE_ID || "").trim();
  return !!(team && kid && p8 && bundle);
};

const signApnsVoipJwt = (): string | null => {
  const teamId = (process.env.APNS_VOIP_TEAM_ID || process.env.APNS_TEAM_ID || "").trim();
  const keyId = (process.env.APNS_VOIP_KEY_ID || process.env.APNS_KEY_ID || "").trim();
  const p8Raw = process.env.APNS_VOIP_P8 || process.env.APNS_P8 || "";
  const p8 = p8Raw.replace(/\\n/g, "\n").trim();
  if (!teamId || !keyId || !p8) return null;
  return jwt.sign(
    {iss: teamId, iat: Math.floor(Date.now() / 1000)},
    p8,
    {algorithm: "ES256", header: {alg: "ES256", kid: keyId, typ: "JWT"}}
  );
};

/** APNs HTTP/2 VoIP push (separate from FCM) so iOS can wake and report CallKit on the lock screen. */
const sendApnsVoipCallPush = async (params: {
  deviceTokenHex: string;
  data: Record<string, string>;
  collapseId?: string;
  expirationSeconds?: number;
  useSandbox?: boolean;
}): Promise<boolean> => {
  const bundleId = (process.env.IOS_APP_BUNDLE_ID || "").trim();
  const auth = signApnsVoipJwt();
  if (!bundleId || !auth) return false;

  const useSandbox = params.useSandbox ??
    (process.env.APNS_USE_SANDBOX === "1" || process.env.APNS_USE_SANDBOX === "true");
  const host = useSandbox ? "api.sandbox.push.apple.com" : "api.push.apple.com";
  const hex = params.deviceTokenHex.trim().toLowerCase().replace(/\s+/g, "");
  if (!/^[0-9a-f]+$/i.test(hex) || hex.length < 32 || hex.length % 2 === 1) {
    functions.logger.warn("APNs VoIP token hex looks invalid; skipping.");
    return false;
  }
  const path = `/3/device/${hex}`;
  const topic = `${bundleId}.voip`;

  const bodyPayload: Record<string, unknown> = {
    aps: {"content-available": 1},
    ...params.data,
  };

  return await new Promise((resolve) => {
    let settled = false;
    const finish = (ok: boolean) => {
      if (settled) return;
      settled = true;
      resolve(ok);
    };

    let client: http2.ClientHttp2Session;
    try {
      client = http2.connect(`https://${host}`);
    } catch (error) {
      functions.logger.warn("APNs VoIP http2.connect failed", {error: String(error)});
      finish(false);
      return;
    }

    client.on("error", (error) => {
      functions.logger.warn("APNs VoIP client error", {error: String(error)});
      finish(false);
      try {
        client.close();
      } catch {
        // ignore
      }
    });

    const headers: http2.OutgoingHttpHeaders = {
      ":method": "POST",
      ":path": path,
      ":scheme": "https",
      "apns-topic": topic,
      "apns-push-type": "voip",
      "apns-priority": "10",
      authorization: `bearer ${auth}`,
      "content-type": "application/json; charset=utf-8",
    };
    const ttl = Math.max(30, params.expirationSeconds ?? 90);
    headers["apns-expiration"] = String(Math.floor(Date.now() / 1000) + ttl);
    const collapseId = (params.collapseId || params.data.callId || params.data.type || "").trim();
    if (collapseId) {
      headers["apns-collapse-id"] = collapseId.slice(0, 64);
    }

    const req = client.request(headers);
    let status = 0;

    req.setTimeout(15_000, () => {
      try {
        req.close();
      } catch {
        // ignore
      }
      try {
        client.close();
      } catch {
        // ignore
      }
      finish(false);
    });

    req.on("response", (responseHeaders) => {
      status = Number(responseHeaders[":status"] || 0);
    });
    let responseBody = "";
    req.on("data", (chunk: Buffer | string) => {
      // APNs returns a compact JSON reason for non-200 responses. Keep a bounded
      // copy for diagnostics; it never contains the device token or call payload.
      responseBody = `${responseBody}${chunk.toString()}`.slice(0, 1_024);
    });
    req.on("end", () => {
      if (status === 200) {
        finish(true);
      } else {
        let reason = "";
        try {
          reason = trimStringValue(JSON.parse(responseBody || "{}").reason);
        } catch {
          reason = responseBody.trim();
        }
        functions.logger.warn("APNs VoIP push failed", {status, reason: reason || "unknown"});
        finish(false);
      }
      try {
        client.close();
      } catch {
        // ignore
      }
    });
    req.on("error", (error) => {
      functions.logger.warn("APNs VoIP request error", {error: String(error)});
      finish(false);
      try {
        client.close();
      } catch {
        // ignore
      }
    });

    try {
      req.end(JSON.stringify(bodyPayload));
    } catch (error) {
      functions.logger.warn("APNs VoIP req.end failed", {error: String(error)});
      finish(false);
      try {
        client.close();
      } catch {
        // ignore
      }
    }
  });
};

const notifyIncomingCall = async (params: {
  receiverId: string;
  callerId: string;
  chatId: string;
  callId: string;
  callerName: string;
  callType: string;
  channelName?: string;
}): Promise<void> => {
  const {receiverId, callerId, chatId, callId, callerName, callType, channelName} = params;
  const userDoc = await db.collection("users").doc(receiverId).get();
  const userData = (userDoc.data() || {}) as Record<string, unknown>;
  const routing = await getUserPushRouting(receiverId, userData);
  const voipHex = routing.apnsVoipToken;
  const cleanFcm = routing.fcmToken;
  const preferredSandbox = routing.apnsVoipUsesSandbox ||
    process.env.APNS_USE_SANDBOX === "1" ||
    process.env.APNS_USE_SANDBOX === "true";

  if (!cleanFcm && (!voipHex || voipHex.length < 32)) {
    return;
  }

  const title = callType === "video" ? "Incoming video call" : "Incoming voice call";
  const body = `${callerName || "Someone"} is calling…`;

  const dataPayload = {
    type: "incoming_call",
    receiverId,
    callerId,
    chatId,
    callId,
    callerName: callerName || "Incoming call",
    callType,
    agoraChannelName: channelName || "",
    channelName: channelName || "",
  };

  // 1) VoIP is the only reliable lock-screen CallKit ring path on iOS.
  let voipDelivered = false;
  if (voipHex.length >= 32 && apnsVoipCredentialsReady()) {
    const voipData: Record<string, string> = {};
    for (const [k, v] of Object.entries(dataPayload)) {
      voipData[k] = String(v ?? "");
    }
    voipDelivered = await sendApnsVoipCallPush({
      deviceTokenHex: voipHex,
      data: voipData,
      collapseId: `call-${callId}`,
      expirationSeconds: 90,
      useSandbox: preferredSandbox,
    });
    if (!voipDelivered) {
      voipDelivered = await sendApnsVoipCallPush({
        deviceTokenHex: voipHex,
        data: voipData,
        collapseId: `call-${callId}`,
        expirationSeconds: 90,
        useSandbox: !preferredSandbox,
      });
    }
    if (!voipDelivered) {
      functions.logger.warn("APNs VoIP push not delivered (check token, topic, sandbox flag, and .p8 env).", {
        receiverId,
        callId,
        preferredSandbox,
      });
    }
  } else if (voipHex.length >= 32 && !apnsVoipCredentialsReady()) {
    functions.logger.warn("Receiver has apnsVoipToken but APNs VoIP env is not configured; skipping VoIP push.", {
      receiverId,
      callId,
    });
  } else if (!voipHex || voipHex.length < 32) {
    functions.logger.warn("Receiver has no apnsVoipToken; lock-screen CallKit ring will rely on FCM wake.", {
      receiverId,
      callId,
    });
  }

  if (!cleanFcm) {
    return;
  }

  const clearInvalidFcmToken = async (errorText: string): Promise<void> => {
    if (!errorText.includes("registration-token-not-registered")) return;
    await setPrivateUserFields(receiverId, {
      fcmToken: admin.firestore.FieldValue.delete(),
      fcmTokenUpdatedAt: admin.firestore.Timestamp.now(),
      updatedAt: admin.firestore.Timestamp.now(),
    });
  };

  // 2) Always send a data-only FCM wake. Android notification payloads are routed to the
  // system tray while backgrounded, bypassing FirebaseMessagingService and preventing the
  // app from presenting its full-screen incoming-call UI. iOS receives the APNs background
  // payload below and continues through CallKit/PushKit.
  try {
    await admin.messaging().send({
      token: cleanFcm,
      data: dataPayload,
      android: {
        priority: "high",
        ttl: 90_000,
      },
      apns: {
        headers: {
          "apns-priority": "5",
          "apns-push-type": "background",
          "apns-expiration": String(Math.floor(Date.now() / 1000) + 90),
        },
        payload: {
          aps: {
            "content-available": 1,
          },
        },
      },
    });
  } catch (error) {
    const errorText = String(error);
    functions.logger.warn("FCM incoming-call wake push failed", {receiverId, callId, error: errorText});
    await clearInvalidFcmToken(errorText);
  }

  // 3) Visible notification only when VoIP did not deliver — last resort for force-quit apps
  // where silent wake cannot run. Prefer CallKit ring whenever the app can be woken.
  if (!voipDelivered) {
    try {
      await admin.messaging().send({
        token: cleanFcm,
        data: dataPayload,
        apns: {
          headers: {
            "apns-priority": "10",
            "apns-push-type": "alert",
            "apns-expiration": String(Math.floor(Date.now() / 1000) + 90),
          },
          payload: {
            aps: {
              alert: {
                title,
                subtitle: callerName || "Someone",
                body: "Incoming call",
              },
              sound: "default",
              category: "INCOMING_CALL",
              "thread-id": `chat-${chatId}`,
              "content-available": 1,
              "interruption-level": "time-sensitive",
            },
          },
        },
      });
    } catch (error) {
      const errorText = String(error);
      functions.logger.warn("FCM incoming-call alert fallback failed", {receiverId, callId, error: errorText});
      await clearInvalidFcmToken(errorText);
    }
  }
};

/** Stops CallKit ringing on the receiver when the caller hangs up or the session leaves `ringing`. */
const notifyCallCancelled = async (params: {
  receiverId: string;
  chatId: string;
  callId: string;
}): Promise<void> => {
  const {receiverId, chatId, callId} = params;
  const userDoc = await db.collection("users").doc(receiverId).get();
  const routing = await getUserPushRouting(
    receiverId,
    (userDoc.data() || {}) as Record<string, unknown>
  );
  const voipHex = routing.apnsVoipToken;
  const cleanFcm = routing.fcmToken;

  const dataPayload = {
    type: "call_cancelled",
    receiverId,
    chatId,
    callId,
  };

  if (voipHex.length >= 32 && apnsVoipCredentialsReady()) {
    const voipData: Record<string, string> = {};
    for (const [k, v] of Object.entries(dataPayload)) {
      voipData[k] = String(v ?? "");
    }
    const preferredSandbox = routing.apnsVoipUsesSandbox ||
      process.env.APNS_USE_SANDBOX === "1" ||
      process.env.APNS_USE_SANDBOX === "true";
    let ok = await sendApnsVoipCallPush({
      deviceTokenHex: voipHex,
      data: voipData,
      collapseId: `call-cancel-${callId}`,
      expirationSeconds: 60,
      useSandbox: preferredSandbox,
    });
    if (!ok) {
      ok = await sendApnsVoipCallPush({
        deviceTokenHex: voipHex,
        data: voipData,
        collapseId: `call-cancel-${callId}`,
        expirationSeconds: 60,
        useSandbox: !preferredSandbox,
      });
    }
    if (!ok) {
      functions.logger.log("APNs VoIP call-cancel push not delivered.");
    }
  }

  if (cleanFcm) {
    try {
      await admin.messaging().send({
        token: cleanFcm,
        data: dataPayload,
        android: {priority: "high"},
        apns: {
          headers: {
            "apns-priority": "10",
            "apns-push-type": "background",
          },
          payload: {
            aps: {
              "content-available": 1,
            },
          },
        },
      });
    } catch (error) {
      functions.logger.warn("FCM call-cancel push failed", {receiverId, callId, error: String(error)});
    }
  }
};

// =============================================================================
//  SERVICE INITIALIZATION (Stripe, etc.)
// =============================================================================
// Initialize Stripe lazily - only when needed, so config is loaded
let stripeInstance: Stripe | null = null;

const getStripe = (): Stripe => {
  if (!stripeInstance) {
    const apiKeys = getApiKeys();
    if (!apiKeys.stripe) {
      throw new Error("Payment provider secret key is not configured. Set STRIPE_SECRET_KEY or firebase functions config key stripe.secret_key.");
    }
    stripeInstance = new Stripe(apiKeys.stripe, {
      // Preview API string; Stripe's TS types lag behind dashboard-selected versions.
      apiVersion: "2026-01-28.clover" as Stripe.LatestApiVersion,
    });
  }
  return stripeInstance;
};

const stripeSecretExpectsLiveMode = (): boolean => (getApiKeys().stripe || "").startsWith("sk_live_");

// Seller commerce uses Stripe direct charges. Stripe, not SoftSolutions, carries
// the connected-account negative-balance responsibility for these accounts.
const STRIPE_CONNECT_DIRECT_CHARGE_MODE = "CONNECT_DIRECT_CHARGE";

const isStripeManagedRiskCommerceAccount = (account: Stripe.Account): boolean => {
  const accountType = ((account as unknown as {type?: string}).type || "").toLowerCase();
  const controller = (account as unknown as {
    controller?: {
      type?: string;
      losses?: {payments?: string};
      requirement_collection?: string;
      stripe_dashboard?: {type?: string};
    };
  }).controller;
  const controllerType = (controller?.type || "").toLowerCase();
  const lossesPayments = (controller?.losses?.payments || "").toLowerCase();
  const requirementCollection = (controller?.requirement_collection || "").toLowerCase();
  const dashboardType = (controller?.stripe_dashboard?.type || "").toLowerCase();

  return (
    accountType === "standard" &&
    controllerType === "application" &&
    lossesPayments === "stripe" &&
    requirementCollection === "stripe" &&
    dashboardType === "full"
  );
};

const isStripeKeyModeMismatchMessage = (message: string): boolean => {
  const normalized = message.toLowerCase();
  return (
    normalized.includes("a similar object exists in live mode") ||
    normalized.includes("a similar object exists in test mode") ||
    (normalized.includes("test mode key was used") && normalized.includes("live mode")) ||
    (normalized.includes("live mode key was used") && normalized.includes("test mode")) ||
    normalized.includes("testmode source with a livemode token") ||
    normalized.includes("livemode source with a testmode token") ||
    (normalized.includes("no such customer") && normalized.includes("similar object exists")) ||
    normalized.includes("only live keys can access")
  );
};

const STRIPE_CONNECT_RESET_PAYOUT_SETUP_MESSAGE =
  "Your Stripe payout account needs to be set up again. Open Payment Methods, tap Reset Payout Setup, then Continue Setup and link this payment method again.";

const isStripeConnectPermissionMessage = (message: string): boolean => {
  const normalized = message.toLowerCase();
  return (
    normalized.includes("required permission") ||
    normalized.includes("required permissions") ||
    normalized.includes("does not have the required permissions")
  );
};

const shouldResetStripeConnectPayoutSetup = (message: string): boolean =>
  isStripeConnectPermissionMessage(message) || isStripeKeyModeMismatchMessage(message);

const userFacingStripeConnectLinkingMessage = (rawMessage?: string): string => {
  const trimmed = String(rawMessage || "").trim();
  if (shouldResetStripeConnectPayoutSetup(trimmed)) {
    return STRIPE_CONNECT_RESET_PAYOUT_SETUP_MESSAGE;
  }
  if (!trimmed) {
    return "Could not link this method to commerce payouts yet. Open Payment Methods and finish payout setup.";
  }
  return trimmed.replace(/acct_[A-Za-z0-9]+/g, "your payout account");
};

const clearStaleStripeConnectAccountIds = async (
  userId: string,
  userData: Record<string, unknown>,
  staleAccountId: string
): Promise<void> => {
  const staleAccountUpdates: Record<string, unknown> = {
    payoutAccountId: admin.firestore.FieldValue.delete(),
  };
  if (trimStringValue(userData.stripeAccountId) === staleAccountId) {
    staleAccountUpdates.stripeAccountId = admin.firestore.FieldValue.delete();
  }
  await setPrivateUserFields(userId, staleAccountUpdates);
};

/**
 * Returns a Stripe-managed-risk seller account in the configured test/live mode.
 * Legacy Express accounts are intentionally not reused: their platform-liability
 * configuration is incompatible with direct-charge commerce.
 */
const resolveUsableStripeConnectAccountId = async (
  userId: string,
  userData: Record<string, unknown>,
  preferredAccountId?: string
): Promise<string | undefined> => {
  const accountId =
    trimStringValue(preferredAccountId) ||
    trimStringValue(userData.payoutAccountId) ||
    trimStringValue(userData.stripeAccountId) ||
    undefined;
  if (!accountId) return undefined;

  const expectedLiveMode = stripeSecretExpectsLiveMode();
  try {
    const account = await getStripe().accounts.retrieve(accountId) as Stripe.Account;
    const accountLivemode = (account as unknown as {livemode?: boolean}).livemode === true;
    if (accountLivemode !== expectedLiveMode) {
      functions.logger.warn("Clearing Stripe Connect account due to test/live mode mismatch.", {
        userId,
        accountId,
        accountLivemode,
        expectedLiveMode,
      });
      await clearStaleStripeConnectAccountIds(userId, userData, accountId);
      return undefined;
    }
    if (!isStripeManagedRiskCommerceAccount(account)) {
      functions.logger.warn("Clearing legacy Stripe Connect account that is incompatible with direct-charge commerce.", {
        userId,
        accountId,
        accountType: (account as unknown as {type?: string}).type || null,
        controller: (account as unknown as {controller?: unknown}).controller || null,
      });
      await clearStaleStripeConnectAccountIds(userId, userData, accountId);
      return undefined;
    }
    return accountId;
  } catch (error) {
    const stripeError = error as Stripe.errors.StripeError | undefined;
    const message = (stripeError?.message || "").toLowerCase();
    const shouldClear =
      isStripeKeyModeMismatchError(error) ||
      message.includes("no such account") ||
      message.includes("only live keys can access") ||
      isStripeConnectPermissionMessage(stripeError?.message || "");

    if (shouldClear) {
      functions.logger.warn("Clearing unusable Stripe Connect account id.", {
        userId,
        accountId,
        stripeMessage: stripeError?.message,
      });
      await clearStaleStripeConnectAccountIds(userId, userData, accountId);
      return undefined;
    }
    throw error;
  }
};

const isStripeKeyModeMismatchError = (error: unknown): boolean => {
  const stripeError = error as Stripe.errors.StripeError | undefined;
  return isStripeKeyModeMismatchMessage(stripeError?.message || "");
};

/** Returns a Stripe Customer id in the same mode (test/live) as the configured secret key. */
const ensureStripePaymentCustomerId = async (
  userId: string,
  userData: Record<string, unknown>,
  options?: {email?: string}
): Promise<string> => {
  const expectedLiveMode = stripeSecretExpectsLiveMode();
  const existingId = trimStringValue(userData.paymentCustomerId) || undefined;

  const createAndPersist = async (): Promise<string> => {
    const customer = await getStripe().customers.create({
      email: asNonEmptyString(options?.email, userData.email) || undefined,
      metadata: {userId},
    });
    await setPrivateUserFields(userId, {paymentCustomerId: customer.id});
    return customer.id;
  };

  if (!existingId) {
    return createAndPersist();
  }

  try {
    const customer = await getStripe().customers.retrieve(existingId) as Stripe.Customer;
    const customerLivemode = (customer as unknown as {livemode?: boolean}).livemode === true;
    if (customerLivemode !== expectedLiveMode) {
      functions.logger.warn("Replacing Stripe payment customer due to test/live mode mismatch.", {
        userId,
        existingCustomerId: existingId,
        customerLivemode,
        expectedLiveMode,
      });
      await setPrivateUserFields(userId, {paymentCustomerId: admin.firestore.FieldValue.delete()});
      return createAndPersist();
    }
    return existingId;
  } catch (error) {
    const stripeError = error as Stripe.errors.StripeError | undefined;
    const message = (stripeError?.message || "").toLowerCase();
    const shouldReplace =
      isStripeKeyModeMismatchError(error) ||
      message.includes("no such customer");

    if (shouldReplace) {
      functions.logger.warn("Replacing unusable Stripe payment customer id.", {
        userId,
        existingCustomerId: existingId,
        stripeMessage: stripeError?.message,
      });
      await setPrivateUserFields(userId, {paymentCustomerId: admin.firestore.FieldValue.delete()});
      return createAndPersist();
    }
    throw error;
  }
};

const legacyWalletCustodyDisabledMessage = (flowName: string): string =>
  `${flowName} is disabled while we migrate money movement to licensed provider rails. Stripe is only available here for real marketplace, service, and event payments. Remittance-style transfers must use a licensed provider flow such as Afriex or Dahabshiil.`;

const legacyWalletCustodyDisabledError = (flowName: string): functions.https.HttpsError =>
  new functions.https.HttpsError(
    "failed-precondition",
    legacyWalletCustodyDisabledMessage(flowName)
  );

const stripeCommercePayoutOnlyMessage =
  "Direct Stripe payout processing is disabled. Stripe payouts may only run from explicit commerce settlement records tied to a real marketplace, service, or event sale.";

const STRIPE_COMMERCE_PAYOUT_ALLOWED_SOURCES = new Set([
  "MARKETPLACE_STRIPE_PAYOUT",
  "GARAGE_SALE_STRIPE_PAYOUT",
  "EVENT_STRIPE_PAYOUT",
  "SERVICE_STRIPE_PAYOUT",
  "SPONSORED_STRIPE_PAYOUT",
]);

const STRIPE_COMMERCE_PAYOUT_ALLOWED_TYPES = new Set([
  "COMMERCE_PAYOUT",
  "EVENT_PAYOUT",
  "SERVICE_PAYOUT",
]);

const STRIPE_COMMERCE_PAYOUT_ALLOWED_CATEGORIES = new Set([
  "MARKETPLACE",
  "GARAGE_SALE",
  "EVENT",
  "SERVICE",
  "SPONSORED",
]);

const STRIPE_COMMERCE_PAYOUT_ALLOWED_MODES = new Set([
  "CONNECT_DESTINATION_CHARGE",
  "CONNECT_SEPARATE_CHARGES_AND_TRANSFERS",
  "CONNECT_SEPARATE_CHARGE_AND_TRANSFER",
  "CONNECT_PAYOUT",
]);

const isExplicitStripeCommercePayoutRequest = (
  payoutData: FirebaseFirestore.DocumentData | Record<string, unknown>
): boolean => {
  const source = String(payoutData.source || "").trim().toUpperCase();
  const type = String(payoutData.type || "").trim().toUpperCase();
  const category = String(
    payoutData.settlementCategory ||
    payoutData.commerceCategory ||
    payoutData.commerceFlow ||
    ""
  ).trim().toUpperCase();
  const processorMode = String(payoutData.processorMode || "").trim().toUpperCase();
  const processor = String(
    payoutData.processor ||
    payoutData.provider ||
    payoutData.payoutProvider ||
    ""
  ).trim().toUpperCase();
  const commerceContextId = asNonEmptyString(
    payoutData.commerceRecordId,
    payoutData.orderId,
    payoutData.purchaseRequestId,
    payoutData.eventId,
    payoutData.garageSalePaymentId,
    payoutData.serviceRequestId,
    payoutData.listingId
  );

  if (!STRIPE_COMMERCE_PAYOUT_ALLOWED_SOURCES.has(source)) return false;
  if (!STRIPE_COMMERCE_PAYOUT_ALLOWED_TYPES.has(type)) return false;
  if (!STRIPE_COMMERCE_PAYOUT_ALLOWED_CATEGORIES.has(category)) return false;
  if (!STRIPE_COMMERCE_PAYOUT_ALLOWED_MODES.has(processorMode)) return false;
  if (processor !== "STRIPE" && processor !== "STRIPE_CONNECT") return false;
  return !!commerceContextId;
};

const LEGACY_CUSTODY_PAYOUT_TERMINAL_STATUSES = new Set([
  "COMPLETED",
  "FAILED",
  "REFUNDED",
  "CANCELLED",
  "EXPIRED",
  "REVERSED",
]);

const LEGACY_CUSTODY_DEPOSIT_TERMINAL_STATUSES = new Set([
  "COMPLETED",
  "FAILED",
  "DISPUTED",
  "REFUNDED",
]);

const AFRIEX_HOSTED_WALLET_TRANSFER_SOURCE = "AFRIEX_HOSTED_WALLET_TRANSFER";
const AFRIEX_HOSTED_WALLET_FUNDING_SOURCE = "AFRIEX_HOSTED_WALLET";
const AFRIEX_HOSTED_WALLET_CASH_IN_SOURCE = "AFRIEX_HOSTED_WALLET_CASH_IN";
const AFRIEX_HOSTED_WALLET_CARD_DEPOSIT_SOURCE = "AFRIEX_HOSTED_WALLET_CARD_DEPOSIT";
const AFRIEX_HOSTED_WALLET_BANK_DEPOSIT_SOURCE = "AFRIEX_HOSTED_WALLET_BANK_DEPOSIT";
const AFRIEX_HOSTED_WALLET_CASH_OUT_SOURCE = "AFRIEX_HOSTED_WALLET_CASH_OUT";
const AFRIEX_HOSTED_AGENT_CASH_OUT_SOURCE = "AFRIEX_HOSTED_AGENT_CASH_OUT";
const AFRIEX_HOSTED_AGENT_EARNINGS_CASH_OUT_SOURCE = "AFRIEX_HOSTED_AGENT_EARNINGS_CASH_OUT";
const HOSTED_FUNDED_TRANSFER_MODE = "HOSTED_FUNDED_TRANSFER";
const AGENT_EARNINGS_PAYOUT_FUNDING_SOURCE = "AGENT_EARNINGS";
const MINIMUM_REMITTANCE_TRANSFER_AMOUNT = 1;

const assertMinimumRemittanceTransferAmount = (amount: number, currencyRaw: unknown): void => {
  const currency = normalizeIsoCurrencyForFx(currencyRaw, "USD") || "USD";
  if (!Number.isFinite(amount) || amount < MINIMUM_REMITTANCE_TRANSFER_AMOUNT) {
    throw new functions.https.HttpsError(
      "invalid-argument",
      `The minimum transfer is ${currency} ${MINIMUM_REMITTANCE_TRANSFER_AMOUNT.toFixed(2)}. This delivery route may require a higher provider minimum.`
    );
  }
};

const isAfriexHostedWalletTransferSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase() === AFRIEX_HOSTED_WALLET_TRANSFER_SOURCE;

const isAfriexHostedWalletCashInSource = (source: unknown): boolean => {
  const normalized = String(source || "").trim().toUpperCase();
  return normalized === AFRIEX_HOSTED_WALLET_CASH_IN_SOURCE ||
    normalized === AFRIEX_HOSTED_WALLET_CARD_DEPOSIT_SOURCE ||
    normalized === AFRIEX_HOSTED_WALLET_BANK_DEPOSIT_SOURCE;
};

const isAfriexHostedWalletCardDepositSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase() === AFRIEX_HOSTED_WALLET_CARD_DEPOSIT_SOURCE;

const isAfriexHostedWalletBankDepositSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase() === AFRIEX_HOSTED_WALLET_BANK_DEPOSIT_SOURCE;

const isStripeSettledAfriexHostedWalletTopUp = (
  payoutData: FirebaseFirestore.DocumentData | Record<string, unknown>
): boolean => {
  const normalizedType = String(payoutData.type || "").trim().toUpperCase();
  if (normalizedType !== "CASH_IN") return false;

  const payoutSource = asNonEmptyString(payoutData.source);
  const collectionProcessor = String(
    asNonEmptyString(payoutData.collectionProcessor, payoutData.processor) || ""
  ).trim().toUpperCase();

  return (
    (isAfriexHostedWalletCardDepositSource(payoutSource) ||
      isAfriexHostedWalletBankDepositSource(payoutSource)) &&
    collectionProcessor === "STRIPE"
  );
};

const isAfriexHostedWalletCashOutSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase() === AFRIEX_HOSTED_WALLET_CASH_OUT_SOURCE;

const isAfriexHostedAgentCashOutSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase() === AFRIEX_HOSTED_AGENT_CASH_OUT_SOURCE;

const isAfriexHostedAgentEarningsCashOutSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase() === AFRIEX_HOSTED_AGENT_EARNINGS_CASH_OUT_SOURCE;

const legacyCustodyPayoutFlowName = (
  payoutData: FirebaseFirestore.DocumentData | Record<string, unknown>
): string | null => {
  const type = String(payoutData.type || "").trim().toUpperCase();
  const source = String(payoutData.source || "").trim().toUpperCase();

  if (source === AFRIEX_HOSTED_WALLET_TRANSFER_SOURCE ||
    source === AFRIEX_HOSTED_WALLET_CASH_IN_SOURCE ||
    source === AFRIEX_HOSTED_WALLET_CARD_DEPOSIT_SOURCE ||
    source === AFRIEX_HOSTED_WALLET_BANK_DEPOSIT_SOURCE ||
    source === AFRIEX_HOSTED_WALLET_CASH_OUT_SOURCE ||
    source === AFRIEX_HOSTED_AGENT_CASH_OUT_SOURCE ||
    source === AFRIEX_HOSTED_AGENT_EARNINGS_CASH_OUT_SOURCE ||
    source === AGENT_CUSTOMER_MOBILE_COLLECTION_SOURCE) {
    return null;
  }

  if (type === AGENT_CUSTOMER_WALLET_WITHDRAWAL_TYPE) {
    return "Agent customer wallet withdrawals";
  }
  if (source === AGENT_CUSTOMER_MOBILE_COLLECTION_SOURCE) {
    return "Agent customer mobile-money collection";
  }
  if (type === "AGENT_CASH_OUT") {
    return "Agent cash-out";
  }
  if (source === AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE) {
    return "Agent customer wallet deposits";
  }
  if (source === "WALLET_TRANSFER" || source === "MOBILE_MONEY_TRANSFER" || type === "BENEFICIARY_TRANSFER") {
    return "Send Money";
  }
  if (source === "MOBILE_MONEY_CASH_OUT_CALLABLE" || type === "CASH_OUT") {
    return "Mobile money cash-out";
  }
  if (source === "MOBILE_MONEY_CASH_IN_CLIENT" || source === "MOBILE_MONEY_VERIFICATION" || type === "CASH_IN") {
    return "Wallet top-ups";
  }
  return null;
};

const isLegacyCustodyDepositRequest = (
  depositData: FirebaseFirestore.DocumentData | Record<string, unknown>
): boolean => {
  const type = String(depositData.type || "").trim().toUpperCase();
  // After the custody migration, any wallet-crediting DEPOSIT record is treated
  // as legacy custody unless it is already completed historical data.
  return type === "DEPOSIT";
};

type StripeSavedCardFundingMethod = {
  paymentMethodDocId: string;
  customerId: string;
  stripePaymentMethodId: string;
  brand: string | null;
  last4: string | null;
};

type StripeCommerceChargeResult = {
  paymentIntentId: string;
  latestChargeId: string | null;
  status: string;
  fundingPaymentMethodDocId: string;
  fundingCardBrand: string | null;
  fundingCardLast4: string | null;
  connectedAccountId: string | null;
};

const normalizedStoredPaymentMethodType = (value: unknown): string =>
  String(value || "").trim().toUpperCase();

const stripePaymentMethodOwnerCustomerId = (paymentMethod: Stripe.PaymentMethod): string | null => {
  const customer = paymentMethod.customer;
  if (typeof customer === "string") return asNonEmptyString(customer) || null;
  if (customer && typeof customer === "object") {
    return asNonEmptyString((customer as Stripe.Customer).id) || null;
  }
  return null;
};

const resolveStripeChargeCustomerForSavedPaymentMethod = async (params: {
  userId: string;
  methodId: string;
  methodData: Record<string, unknown>;
  chargePaymentMethodId: string;
  fallbackCustomerId?: string | null;
  flowName: string;
}): Promise<string> => {
  const storedCustomerId = asNonEmptyString(params.methodData.chargeCustomerId);
  const fallbackCustomerId = asNonEmptyString(params.fallbackCustomerId);
  const methodRef = db.collection("users").doc(params.userId)
    .collection("payment_methods").doc(params.methodId);

  let paymentMethod: Stripe.PaymentMethod;
  try {
    paymentMethod = await getStripe().paymentMethods.retrieve(params.chargePaymentMethodId) as Stripe.PaymentMethod;
  } catch (error) {
    const stripeError = error as Stripe.errors.StripeError | undefined;
    await methodRef.set({
      requiresRelinkForCharges: true,
      chargeSetupCheckedAt: admin.firestore.Timestamp.now(),
      lastChargeSetupError: stripeError?.message || "Stripe payment method could not be retrieved.",
    }, {merge: true});
    throw new functions.https.HttpsError(
      "failed-precondition",
      `This saved card needs to be re-linked before it can be used for ${params.flowName}.`
    );
  }

  const ownerCustomerId = stripePaymentMethodOwnerCustomerId(paymentMethod);
  if (ownerCustomerId) {
    const expectedCustomerId = storedCustomerId || fallbackCustomerId;
    if (expectedCustomerId && ownerCustomerId !== expectedCustomerId) {
      await methodRef.set({
        requiresRelinkForCharges: true,
        chargeSetupCheckedAt: admin.firestore.Timestamp.now(),
        lastChargeSetupError: "Stripe payment method belongs to a different billing customer.",
      }, {merge: true});
      throw new functions.https.HttpsError(
        "failed-precondition",
        `This saved card needs to be re-linked before it can be used for ${params.flowName}.`
      );
    }
    await methodRef.set({
      chargeCustomerId: ownerCustomerId,
      requiresRelinkForCharges: false,
      chargeSetupCheckedAt: admin.firestore.Timestamp.now(),
      lastChargeSetupError: admin.firestore.FieldValue.delete(),
    }, {merge: true});
    return ownerCustomerId;
  }

  const attachCustomerId = storedCustomerId || fallbackCustomerId;
  if (!attachCustomerId) {
    await methodRef.set({
      requiresRelinkForCharges: true,
      chargeSetupCheckedAt: admin.firestore.Timestamp.now(),
      lastChargeSetupError: "Stripe payment method is not attached to a billing customer.",
    }, {merge: true});
    throw new functions.https.HttpsError(
      "failed-precondition",
      `This saved card needs to be re-linked before it can be used for ${params.flowName}.`
    );
  }

  try {
    await getStripe().paymentMethods.attach(params.chargePaymentMethodId, {customer: attachCustomerId});
    await methodRef.set({
      chargeCustomerId: attachCustomerId,
      requiresRelinkForCharges: false,
      chargeSetupCheckedAt: admin.firestore.Timestamp.now(),
      lastChargeSetupError: admin.firestore.FieldValue.delete(),
    }, {merge: true});
    return attachCustomerId;
  } catch (error) {
    const stripeError = error as Stripe.errors.StripeError | undefined;
    await methodRef.set({
      requiresRelinkForCharges: true,
      chargeSetupCheckedAt: admin.firestore.Timestamp.now(),
      lastChargeSetupError: stripeError?.message || "Stripe payment method could not be attached.",
    }, {merge: true});
    throw new functions.https.HttpsError(
      "failed-precondition",
      `This saved card needs to be re-linked before it can be used for ${params.flowName}.`
    );
  }
};

const loadDefaultStripeSavedCardFundingMethod = async (
  userId: string,
  userData?: Record<string, unknown>
): Promise<StripeSavedCardFundingMethod> => {
  const fallbackCustomerId = await getUserPaymentCustomerId(userId, userData);

  const methodsSnap = await db.collection("users").doc(userId)
    .collection("payment_methods")
    .get();

  const eligible = methodsSnap.docs
    .map((doc) => ({id: doc.id, data: doc.data() as Record<string, unknown>}))
    .filter(({data}) => {
      const type = normalizedStoredPaymentMethodType(data.type);
      const chargePaymentMethodId = asNonEmptyString(
        data.chargePaymentMethodId,
        data.stripePaymentMethodId
      );
      return (
        type === "CARD" &&
        !!chargePaymentMethodId &&
        data.requiresRelinkForCharges !== true
      );
    })
    .sort((left, right) => {
      const leftDefault = left.data.isDefault === true ? 1 : 0;
      const rightDefault = right.data.isDefault === true ? 1 : 0;
      return rightDefault - leftDefault;
    });

  const selected = eligible[0];
  if (!selected) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Add a default saved card in Wallet > Payment Methods before paying with Stripe."
    );
  }

  const stripePaymentMethodId = asNonEmptyString(
    selected.data.chargePaymentMethodId,
    selected.data.stripePaymentMethodId
  );
  if (!stripePaymentMethodId) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Your default saved card is missing Stripe charge details. Remove and re-add the card, then try again."
    );
  }

  const customerId = await resolveStripeChargeCustomerForSavedPaymentMethod({
    userId,
    methodId: selected.id,
    methodData: selected.data,
    chargePaymentMethodId: stripePaymentMethodId,
    fallbackCustomerId,
    flowName: "this payment",
  });

  return {
    paymentMethodDocId: selected.id,
    customerId,
    stripePaymentMethodId,
    brand: asNonEmptyString(selected.data.brand) || null,
    last4: asNonEmptyString(selected.data.last4) || null,
  };
};

const ensureStripeCommerceDestinationAccountId = async (
  userId: string,
  userData: Record<string, unknown>,
  flowName: string
): Promise<string> => {
  const destinationAccountId = await getUserPayoutAccountId(userId, userData);
  if (!destinationAccountId) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      `${flowName} cannot be paid out yet because the seller has not finished Stripe merchant onboarding.`
    );
  }

  const stripeSecret = getApiKeys().stripe;
  const expectedLiveMode = (stripeSecret || "").startsWith("sk_live_");

  const clearStaleDestinationIds = async () => {
    const staleAccountUpdates: Record<string, unknown> = {
      payoutAccountId: admin.firestore.FieldValue.delete(),
    };
    if (trimStringValue(userData.stripeAccountId) === destinationAccountId) {
      staleAccountUpdates.stripeAccountId = admin.firestore.FieldValue.delete();
    }
    await setPrivateUserFields(userId, staleAccountUpdates);
  };

  try {
    const account = await getStripe().accounts.retrieve(destinationAccountId) as Stripe.Account;
    const accountLivemode = ((account as unknown as {livemode?: boolean}).livemode === true);
    const isUsableAccount =
      accountLivemode === expectedLiveMode &&
      isStripeManagedRiskCommerceAccount(account);

    if (!isUsableAccount) {
      await clearStaleDestinationIds();
      throw new functions.https.HttpsError(
        "failed-precondition",
        `${flowName} cannot be paid out yet because the seller's Stripe merchant account needs to be reconnected. Ask them to open Wallet > Payment Methods and finish Stripe setup again.`
      );
    }

    if (account.details_submitted !== true) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        `${flowName} cannot be paid out yet because the seller has not finished Stripe merchant onboarding.`
      );
    }

    if (account.charges_enabled !== true || account.payouts_enabled !== true) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        `${flowName} cannot be paid out yet because the seller's Stripe merchant account is not fully enabled. Ask them to open Wallet > Payment Methods and complete Stripe setup.`
      );
    }
  } catch (error) {
    if (error instanceof functions.https.HttpsError) {
      throw error;
    }

    const stripeError = error as Stripe.errors.StripeError | undefined;
    const rawMessage = stripeError?.message || "";
    const message = rawMessage.toLowerCase();
    const recoverableAccountError =
      message.includes("test mode") ||
      message.includes("live mode") ||
      message.includes("a similar object exists") ||
      message.includes("no such account") ||
      message.includes("required permissions") ||
      message.includes("does not have the required permissions");

    if (recoverableAccountError) {
      await clearStaleDestinationIds();
      throw new functions.https.HttpsError(
        "failed-precondition",
        `${flowName} cannot be paid out yet because the seller's Stripe merchant account needs to be reconnected. Ask them to open Wallet > Payment Methods and finish Stripe setup again.`
      );
    }

    functions.logger.error("Failed to verify Stripe commerce destination account.", {
      userId,
      destinationAccountId,
      flowName,
      stripeType: stripeError?.type,
      stripeCode: stripeError?.code,
      stripeMessage: stripeError?.message,
      stripeRequestId: stripeError?.requestId,
      error,
    });
    throw new functions.https.HttpsError(
      "internal",
      `${flowName} could not verify the recipient's Stripe earnings account right now. Please try again.`
    );
  }

  return destinationAccountId;
};

const mapStripeCommerceChargeError = (error: unknown): functions.https.HttpsError => {
  if (error instanceof functions.https.HttpsError) {
    return error;
  }
  const stripeError = error as Stripe.errors.StripeError | undefined;
  const code = stripeError?.code || "";
  const message = stripeError?.message || "";
  if (code === "authentication_required") {
    return new functions.https.HttpsError(
      "failed-precondition",
      "This saved card requires extra authentication. Use another card or re-add the card and try again."
    );
  }
  if (code === "card_declined" || code === "insufficient_funds" || code === "expired_card") {
    return new functions.https.HttpsError(
      "failed-precondition",
      message || "Stripe declined the card charge."
    );
  }
  if (message) {
    return new functions.https.HttpsError("failed-precondition", message);
  }
  return new functions.https.HttpsError("internal", "Stripe charge failed.");
};

const createStripeCardCommerceCharge = async (params: {
  payerUserId: string;
  payerUserData?: Record<string, unknown>;
  amount: number;
  currency?: string;
  description: string;
  destinationAccountId?: string;
  applicationFeeAmount?: number;
  metadata?: Record<string, string>;
  idempotencyKey: string;
}): Promise<StripeCommerceChargeResult> => {
  const fundingMethod = await loadDefaultStripeSavedCardFundingMethod(
    params.payerUserId,
    params.payerUserData
  );
  const normalizedCurrency = (params.currency || "USD").trim().toLowerCase();
  const amountMinor = amountToStripeMinorUnits(params.amount, normalizedCurrency);
  if (amountMinor <= 0) {
    throw new functions.https.HttpsError("invalid-argument", "Invalid Stripe payment amount.");
  }

  const applicationFeeMinor = params.destinationAccountId && Number(params.applicationFeeAmount || 0) > 0 ?
    amountToStripeMinorUnits(Number(params.applicationFeeAmount || 0), normalizedCurrency) :
    undefined;

  const paymentIntent = await getStripe().paymentIntents.create({
    amount: amountMinor,
    currency: normalizedCurrency,
    customer: fundingMethod.customerId,
    payment_method: fundingMethod.stripePaymentMethodId,
    confirm: true,
    off_session: true,
    description: params.description,
    metadata: {
      payerUserId: params.payerUserId,
      fundingPaymentMethodDocId: fundingMethod.paymentMethodDocId,
      fundingCardBrand: fundingMethod.brand || "",
      fundingCardLast4: fundingMethod.last4 || "",
      ...(params.metadata || {}),
    },
    receipt_email: asNonEmptyString(params.payerUserData?.email) || undefined,
    transfer_data: params.destinationAccountId ? {destination: params.destinationAccountId} : undefined,
    application_fee_amount: applicationFeeMinor,
    on_behalf_of: params.destinationAccountId || undefined,
  }, {
    idempotencyKey: params.idempotencyKey,
  });

  const status = String(paymentIntent.status || "").trim().toLowerCase();
  if (status !== "succeeded") {
    throw new functions.https.HttpsError(
      "failed-precondition",
      status === "processing" ?
        "Payment is still processing. This checkout currently requires a card that confirms immediately." :
        "Stripe could not complete the payment with the saved card."
    );
  }

  return {
    paymentIntentId: paymentIntent.id,
    latestChargeId: asStripeObjectId(paymentIntent.latest_charge) || null,
    status,
    fundingPaymentMethodDocId: fundingMethod.paymentMethodDocId,
    fundingCardBrand: fundingMethod.brand,
    fundingCardLast4: fundingMethod.last4,
    connectedAccountId: null,
  };
};

/**
 * Creates a direct charge on the seller's connected account. A platform-saved
 * PaymentMethod is cloned for that one connected-account charge, as required by
 * Stripe. The persisted attempt makes retries safe after a function restart.
 */
const createStripeCardCommerceDirectCharge = async (params: {
  payerUserId: string;
  payerUserData?: Record<string, unknown>;
  amount: number;
  currency?: string;
  description: string;
  connectedAccountId: string;
  applicationFeeAmount?: number;
  metadata?: Record<string, string>;
  idempotencyKey: string;
}): Promise<StripeCommerceChargeResult> => {
  const normalizedCurrency = (params.currency || "USD").trim().toLowerCase();
  const amountMinor = amountToStripeMinorUnits(params.amount, normalizedCurrency);
  if (amountMinor <= 0) {
    throw new functions.https.HttpsError("invalid-argument", "Invalid Stripe payment amount.");
  }

  const applicationFeeMinor = Number(params.applicationFeeAmount || 0) > 0 ?
    amountToStripeMinorUnits(Number(params.applicationFeeAmount || 0), normalizedCurrency) :
    undefined;
  if (applicationFeeMinor !== undefined && applicationFeeMinor >= amountMinor) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "The platform fee must be lower than the seller payment amount."
    );
  }

  const attemptRef = db.collection("stripe_commerce_charge_attempts").doc(params.idempotencyKey);
  let fundingMethod = await loadDefaultStripeSavedCardFundingMethod(
    params.payerUserId,
    params.payerUserData
  );
  let clonedPaymentMethodId: string | null = null;

  try {
    await attemptRef.create({
      idempotencyKey: params.idempotencyKey,
      status: "PREPARING",
      payerUserId: params.payerUserId,
      connectedAccountId: params.connectedAccountId,
      amountMinor,
      currency: normalizedCurrency,
      fundingPaymentMethodDocId: fundingMethod.paymentMethodDocId,
      fundingCardBrand: fundingMethod.brand,
      fundingCardLast4: fundingMethod.last4,
      createdAt: admin.firestore.Timestamp.now(),
      updatedAt: admin.firestore.Timestamp.now(),
    });
  } catch (error) {
    const firestoreCode = (error as {code?: unknown}).code;
    if (firestoreCode !== 6 && firestoreCode !== "already-exists") {
      throw error;
    }

    const existingAttemptSnap = await attemptRef.get();
    const existingAttempt = (existingAttemptSnap.data() || {}) as Record<string, unknown>;
    if (
      asNonEmptyString(existingAttempt.connectedAccountId) !== params.connectedAccountId ||
      Number(existingAttempt.amountMinor || 0) !== amountMinor ||
      String(existingAttempt.currency || "").toLowerCase() !== normalizedCurrency
    ) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "This checkout is already being processed with different payment details. Start a new checkout instead."
      );
    }

    const existingPaymentIntentId = asNonEmptyString(existingAttempt.paymentIntentId);
    if (existingPaymentIntentId) {
      if (String(existingAttempt.status || "").trim().toUpperCase() === "REFUNDED") {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "The previous card payment was refunded. Start a new checkout to try again."
        );
      }
      const existingIntent = await getStripe().paymentIntents.retrieve(existingPaymentIntentId, {
        stripeAccount: params.connectedAccountId,
      });
      const existingStatus = String(existingIntent.status || "").trim().toLowerCase();
      if (existingStatus !== "succeeded") {
        throw new functions.https.HttpsError(
          "failed-precondition",
          existingStatus === "processing" ?
            "Payment is still processing. Please wait before trying again." :
            "The previous card payment did not complete. Start a new checkout with your preferred card."
        );
      }
      return {
        paymentIntentId: existingIntent.id,
        latestChargeId: asStripeObjectId(existingIntent.latest_charge) || null,
        status: existingStatus,
        fundingPaymentMethodDocId: asNonEmptyString(existingAttempt.fundingPaymentMethodDocId) || fundingMethod.paymentMethodDocId,
        fundingCardBrand: asNonEmptyString(existingAttempt.fundingCardBrand) || fundingMethod.brand,
        fundingCardLast4: asNonEmptyString(existingAttempt.fundingCardLast4) || fundingMethod.last4,
        connectedAccountId: params.connectedAccountId,
      };
    }

    clonedPaymentMethodId = asNonEmptyString(existingAttempt.clonedPaymentMethodId);
    if (!clonedPaymentMethodId) {
      throw new functions.https.HttpsError(
        "aborted",
        "This checkout is already being prepared. Please wait a moment before trying again."
      );
    }
    fundingMethod = {
      paymentMethodDocId: asNonEmptyString(existingAttempt.fundingPaymentMethodDocId) || fundingMethod.paymentMethodDocId,
      customerId: fundingMethod.customerId,
      stripePaymentMethodId: fundingMethod.stripePaymentMethodId,
      brand: asNonEmptyString(existingAttempt.fundingCardBrand) || fundingMethod.brand,
      last4: asNonEmptyString(existingAttempt.fundingCardLast4) || fundingMethod.last4,
    };
  }

  if (!clonedPaymentMethodId) {
    const clonedPaymentMethod = await getStripe().paymentMethods.create({
      customer: fundingMethod.customerId,
      payment_method: fundingMethod.stripePaymentMethodId,
    }, {
      stripeAccount: params.connectedAccountId,
    });
    clonedPaymentMethodId = clonedPaymentMethod.id;
    await attemptRef.set({
      status: "READY_TO_CHARGE",
      clonedPaymentMethodId,
      updatedAt: admin.firestore.Timestamp.now(),
    }, {merge: true});
  }

  const paymentIntent = await getStripe().paymentIntents.create({
    amount: amountMinor,
    currency: normalizedCurrency,
    payment_method: clonedPaymentMethodId,
    confirm: true,
    off_session: true,
    description: params.description,
    application_fee_amount: applicationFeeMinor,
    metadata: {
      payerUserId: params.payerUserId,
      fundingPaymentMethodDocId: fundingMethod.paymentMethodDocId,
      fundingCardBrand: fundingMethod.brand || "",
      fundingCardLast4: fundingMethod.last4 || "",
      connectedAccountId: params.connectedAccountId,
      commerceChargeMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
      ...(params.metadata || {}),
    },
    receipt_email: asNonEmptyString(params.payerUserData?.email) || undefined,
  }, {
    stripeAccount: params.connectedAccountId,
    idempotencyKey: params.idempotencyKey,
  });

  const status = String(paymentIntent.status || "").trim().toLowerCase();
  await attemptRef.set({
    status: status === "succeeded" ? "SUCCEEDED" : status.toUpperCase() || "UNKNOWN",
    paymentIntentId: paymentIntent.id,
    latestChargeId: asStripeObjectId(paymentIntent.latest_charge) || null,
    updatedAt: admin.firestore.Timestamp.now(),
    completedAt: status === "succeeded" ? admin.firestore.Timestamp.now() : null,
  }, {merge: true});

  if (status !== "succeeded") {
    throw new functions.https.HttpsError(
      "failed-precondition",
      status === "processing" ?
        "Payment is still processing. This checkout currently requires a card that confirms immediately." :
        "Stripe could not complete the payment with the saved card."
    );
  }

  return {
    paymentIntentId: paymentIntent.id,
    latestChargeId: asStripeObjectId(paymentIntent.latest_charge) || null,
    status,
    fundingPaymentMethodDocId: fundingMethod.paymentMethodDocId,
    fundingCardBrand: fundingMethod.brand,
    fundingCardLast4: fundingMethod.last4,
    connectedAccountId: params.connectedAccountId,
  };
};

const refundStripeCommercePaymentIntent = async (params: {
  paymentIntentId: string;
  idempotencyKey: string;
  metadata?: Record<string, string>;
  connectedAccountId?: string | null;
  directChargeAttemptId?: string | null;
}): Promise<void> => {
  if (!params.paymentIntentId.trim()) return;
  try {
    const refund = await getStripe().refunds.create({
      payment_intent: params.paymentIntentId,
      reason: "requested_by_customer",
      metadata: params.metadata,
    }, {
      idempotencyKey: params.idempotencyKey,
      stripeAccount: params.connectedAccountId || undefined,
    });
    const directChargeAttemptId = asNonEmptyString(params.directChargeAttemptId);
    if (directChargeAttemptId) {
      await db.collection("stripe_commerce_charge_attempts").doc(directChargeAttemptId).set({
        status: "REFUNDED",
        refundId: refund.id,
        refundedAt: admin.firestore.Timestamp.now(),
        updatedAt: admin.firestore.Timestamp.now(),
      }, {merge: true});
    }
  } catch (error) {
    functions.logger.error("Stripe commerce refund failed", {
      paymentIntentId: params.paymentIntentId,
      error,
    });
  }
};

