const isMarketplaceStorageUrlForSeller = (url: unknown, sellerId: string): boolean => {
  const raw = String(url ?? "").trim();
  const cleanSellerId = String(sellerId ?? "").trim();
  if (!raw || raw.length > 2000 || !cleanSellerId) return false;
  const hostOk =
    raw.startsWith("https://firebasestorage.googleapis.com/") ||
    /^https:\/\/[^/]+\.firebasestorage\.app\//.test(raw);
  if (!hostOk) return false;
  const encoded = `marketplace_images%2F${cleanSellerId}%2F`;
  const plain = `marketplace_images/${cleanSellerId}/`;
  return raw.includes(encoded) || raw.includes(plain);
};

const marketplaceItemMediaUrlsAreValid = (
  data: Record<string, unknown>,
  sellerId: string
): boolean => {
  const imageUrls = Array.isArray(data.imageUrls) ? data.imageUrls : [];
  if (imageUrls.length === 0 || imageUrls.length > 20) return false;
  if (!imageUrls.every((url) => isMarketplaceStorageUrlForSeller(url, sellerId))) return false;
  const media = Array.isArray(data.media) ? data.media : [];
  for (const row of media) {
    const mediaUrl =
      typeof row === "object" && row !== null ?
        (row as Record<string, unknown>).url :
        undefined;
    if (!isMarketplaceStorageUrlForSeller(mediaUrl, sellerId)) return false;
  }
  return true;
};

const resolveMarketplaceSellerDisplayName = (userData: Record<string, unknown>): string => {
  const name = String(userData.name ?? userData.username ?? userData.email ?? "Seller").trim();
  return name || "Seller";
};

export const onMarketplaceItemCreated = functions.firestore
  .document("marketplace_items/{itemId}")
  .onCreate(async (snap) => {
    const data = (snap.data() || {}) as Record<string, unknown>;
    const sellerId = String(data.sellerId ?? "").trim();
    if (!sellerId) return;

    const updates: Record<string, unknown> = {};
    const userDoc = await db.collection("users").doc(sellerId).get();
    const userData = (userDoc.data() || {}) as Record<string, unknown>;
    const profileName = resolveMarketplaceSellerDisplayName(userData);
    if (String(data.sellerName ?? "").trim() !== profileName) {
      updates.sellerName = profileName;
    }

    if (!marketplaceItemMediaUrlsAreValid(data, sellerId)) {
      updates.isDeleted = true;
      updates.status = "DELETED";
      updates.deletedAt = admin.firestore.FieldValue.serverTimestamp();
      updates.deletedReason = "INVALID_MEDIA_URL";
    }

    if (Object.keys(updates).length === 0) return;
    await snap.ref.set(updates, {merge: true});
  });

export const processPurchaseRequest = functions.firestore
  .document("purchase_requests/{requestId}")
  .onCreate(async (snap, context) => {
    const requestId = context.params.requestId;
    const requestData = snap.data();
    functions.logger.log(`Processing purchase request: ${requestId}`);

    if (!requestData || !snap) {
      functions.logger.error("Purchase request data is missing.");
      return undefined;
    }

    const {buyerId, sellerId, itemId, price} = requestData;

    if (!buyerId || !sellerId || !itemId || typeof price !== "number") {
      functions.logger.error("Invalid purchase request data.", requestData);
      return snap.ref.update({
        status: "failed",
        resultMessage: "Invalid request data. Cannot be processed.",
      });
    }

    const buyerIdStr = String(buyerId || "").trim();
    const sellerIdStr = String(sellerId || "").trim();
    if (!buyerIdStr || !sellerIdStr || buyerIdStr === sellerIdStr) {
      functions.logger.error("Self-purchase or invalid marketplace buyer/seller.", requestData);
      return snap.ref.update({
        status: "failed",
        resultMessage: "You cannot purchase your own listing.",
      });
    }

    const buyerRef = db.collection("users").doc(buyerIdStr);
    const sellerRef = db.collection("users").doc(sellerIdStr);
    const itemRef = db.collection("marketplace_items").doc(itemId);
    let activeProcessor = "STRIPE";
    let activeProcessorMode = STRIPE_CONNECT_DIRECT_CHARGE_MODE;

    try {
      const requestedFundingPreference = normalizeMarketplaceCheckoutFundingPreference(
        requestData.fundingPreference
      );
      activeProcessor = "STRIPE";
      activeProcessorMode = STRIPE_CONNECT_DIRECT_CHARGE_MODE;
      await snap.ref.set({
        status: "processing",
        fundingPreference: requestedFundingPreference,
        processor: activeProcessor,
        processorMode: activeProcessorMode,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, {merge: true});

      const [buyerDoc, sellerDoc, itemDoc] = await Promise.all([
        buyerRef.get(),
        sellerRef.get(),
        itemRef.get(),
      ]);

      if (!buyerDoc.exists || !sellerDoc.exists) {
        throw new functions.https.HttpsError("not-found", "Buyer or seller account does not exist.");
      }
      if (!itemDoc.exists) {
        throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
      }

      const buyerData = await withPrivateUserFields(
        String(buyerId || "").trim(),
        (buyerDoc.data() || {}) as Record<string, unknown>
      );
      const sellerData = await withPrivateUserFields(
        String(sellerId || "").trim(),
        (sellerDoc.data() || {}) as Record<string, unknown>
      );
      const itemData = (itemDoc.data() || {}) as Record<string, unknown>;
      if (itemData.isDeleted === true) {
        throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
      }
      const itemStatus = String(itemData.status || "").trim().toUpperCase();
      const reservedBy = String(itemData.reservedBy || "").trim();
      const listedSellerId = String(itemData.sellerId || "").trim();
      const itemPrice = roundMoney(Number(itemData.price || 0));
      const itemTitle = String(itemData.title || "Marketplace Item").trim() || "Marketplace Item";

      if (!(itemPrice > 0) || itemPrice > 50000) {
        throw new functions.https.HttpsError("failed-precondition", "Invalid listing price.");
      }

      if (!listedSellerId || listedSellerId !== sellerIdStr) {
        throw new functions.https.HttpsError("failed-precondition", "Purchase seller does not match listing.");
      }

      const requestPrice = roundMoney(Number(price));
      if (requestPrice !== itemPrice) {
        functions.logger.warn("Purchase request price ignored; using listing price.", {
          requestId,
          requestPrice,
          itemPrice,
        });
      }

      const listedOpen =
        itemStatus === "AVAILABLE" || itemStatus === "ACTIVE" || itemStatus === "OPEN";
      const availableForBuyer =
        listedOpen ||
        (itemStatus === "RESERVED" && reservedBy === buyerIdStr);

      if (!availableForBuyer) {
        throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
      }

      const competingRequestsSnap = await db.collection("purchase_requests")
        .where("itemId", "==", String(itemId || "").trim())
        .limit(25)
        .get();
      for (const doc of competingRequestsSnap.docs) {
        if (doc.id === requestId) continue;
        const competingData = (doc.data() || {}) as Record<string, unknown>;
        const competingStatus = String(competingData.status || "").trim().toLowerCase();
        if (!["processing", "awaiting_payment"].includes(competingStatus)) continue;
        const competingBuyer = String(competingData.buyerId || "").trim();
        if (competingBuyer && competingBuyer !== buyerIdStr) {
          throw new functions.https.HttpsError(
            "failed-precondition",
            "Another buyer is already checking out this item."
          );
        }
      }

      const feeSnap = await db.collection("app_config").doc("fee_settings").get();
      const feeData = (feeSnap.data() || {}) as Record<string, unknown>;
      const sellerStaffFeeExempt = isStaffFeeExempt(sellerData);
      const platinumFeeRate = pickMarketplacePlatinumFeeRate(feeData);
      const platformFee = sellerStaffFeeExempt ? 0 : roundMoney(itemPrice * platinumFeeRate);
      const sellerNet = roundMoney(itemPrice - platformFee);
      const sellerAfriexPayoutPlan = await buildAfriexCommercePayoutPlanForUser(
        String(sellerId || "").trim()
      );
      const settlementDecision = await resolveMarketplaceCheckoutSettlementDecision({
        recipientUserId: String(sellerId || "").trim(),
        recipientUserData: sellerData,
        flowName: "Marketplace purchase",
        requestedFundingPreference,
      });
      if (settlementDecision.provider === "AFRIEX" && settlementDecision.executionMode === "LIVE") {
        activeProcessor = "AFRIEX";
        activeProcessorMode = AFRIEX_COMMERCE_PROCESSOR_MODE;
        const afriexRuntime = await resolveAfriexCommerceRuntime({
          buyerUserId: String(buyerId || "").trim(),
          recipientUserId: String(sellerId || "").trim(),
          recipientPayoutPlan: sellerAfriexPayoutPlan,
          grossAmount: itemPrice,
          netAmount: sellerNet,
          flowName: "Marketplace purchase",
        });
        const collectionRef = db.collection("payout_requests").doc();
        await db.runTransaction(async (transaction) => {
          const [freshRequestDoc, freshItemDoc] = await Promise.all([
            transaction.get(snap.ref),
            transaction.get(itemRef),
          ]);
          if (!freshRequestDoc.exists) {
            throw new functions.https.HttpsError("not-found", "Purchase request no longer exists.");
          }
          const freshRequestData = (freshRequestDoc.data() || {}) as Record<string, unknown>;
          const requestStatus = String(freshRequestData.status || "").trim().toLowerCase();
          if (!["pending", "processing"].includes(requestStatus)) {
            throw new functions.https.HttpsError("failed-precondition", "Purchase request is no longer pending.");
          }
          if (!freshItemDoc.exists) {
            throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
          }
          const freshItemData = (freshItemDoc.data() || {}) as Record<string, unknown>;
          const freshItemStatus = String(freshItemData.status || "").trim().toUpperCase();
          const freshReservedBy = String(freshItemData.reservedBy || "").trim();
          const stillAvailable =
            freshItemStatus === "AVAILABLE" ||
            freshItemStatus === "ACTIVE" ||
            freshItemStatus === "OPEN" ||
            (freshItemStatus === "RESERVED" && freshReservedBy === buyerIdStr);
          if (!stillAvailable) {
            throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
          }

          const timestamp = admin.firestore.Timestamp.now();
          const collectionData: FirebaseFirestore.DocumentData = {
            senderId: String(buyerId || "").trim(),
            amount: itemPrice,
            currency: "USD",
            phone: afriexRuntime.fundingMethod.phoneNumber,
            network: afriexRuntime.fundingMethod.network,
            country: afriexRuntime.fundingMethod.country,
            dialCode: afriexRuntime.fundingMethod.dialCode,
            localCurrency: afriexRuntime.fundingMethod.currency,
            paymentMethodId: afriexRuntime.fundingMethod.paymentMethodId,
            type: "CASH_IN",
            status: "PENDING",
            source: buildAfriexCommerceCollectionSource("MARKETPLACE"),
            fundingSource: "EXTERNAL_MOBILE_MONEY",
            fundingPreference: requestedFundingPreference,
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            createdAt: timestamp,
            processedAt: timestamp,
            transferIntent: {
              mode: AFRIEX_COMMERCE_TRANSFER_MODE,
              settlementCategory: "MARKETPLACE",
              commerceTitle: itemTitle,
              purchaseRequestId: requestId,
              itemId: String(itemId || "").trim(),
              grossAmount: itemPrice,
              netAmount: sellerNet,
              platformFee,
              recipientUserId: String(sellerId || "").trim(),
              recipientName: asNonEmptyString(sellerData.name, sellerData.username) || "Seller",
              recipientPaymentMethodId: afriexRuntime.recipientTarget.paymentMethodId,
              recipientInfo: afriexRuntime.recipientTarget.recipientInfo,
              recipientLocalAmount: afriexRuntime.recipientTarget.localAmount,
              recipientLocalCurrency: afriexRuntime.recipientTarget.localCurrency,
              recipientFx: afriexRuntime.recipientTarget.payoutFx,
              afriexPayoutRoute: afriexRuntime.recipientTarget.route,
              requestedCurrency: "USD",
              processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            },
          };
          transaction.set(collectionRef, collectionData, {merge: true});
          transaction.update(itemRef, {
            status: "RESERVED",
            reservedBy: buyerIdStr,
            reservedForPaymentRequestId: requestId,
            reservedVia: "AFRIEX_COMMERCE",
            reservedAt: timestamp,
          });
          transaction.update(snap.ref, {
            status: "awaiting_payment",
            fundingPreference: requestedFundingPreference,
            resultMessage: "Mobile money collection started. Approve the prompt on your phone to complete this purchase.",
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            providerRoutingStatus: "COLLECTION_PENDING",
            providerRoutingMessage: "Awaiting buyer mobile money approval.",
            afriexPayoutProvider: "AFRIEX",
            afriexPreferredPayoutRoute: afriexRuntime.recipientTarget.route,
            afriexPayoutSelectionRequired: false,
            providerCollectionRequestId: collectionRef.id,
            updatedAt: timestamp,
          });
        });
        return undefined;
      }
      if (settlementDecision.executionMode !== "LIVE" || settlementDecision.provider !== "STRIPE") {
        await snap.ref.set({
          status: "failed",
          resultMessage: settlementDecision.message || "This marketplace corridor is not ready for live checkout.",
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          ...buildLiveCommerceSettlementMetadata(settlementDecision),
        }, {merge: true});
        return undefined;
      }
      const connectedAccountId = settlementDecision.destinationAccountId;
      if (!connectedAccountId) {
        throw new functions.https.HttpsError("failed-precondition", "Marketplace purchase is missing the seller's Stripe account.");
      }

      const releaseStripeMarketplaceReservation = async () => {
        await db.runTransaction(async (transaction) => {
          const itemSnap = await transaction.get(itemRef);
          if (!itemSnap.exists) return;
          const itemData = (itemSnap.data() || {}) as Record<string, unknown>;
          const itemStatus = String(itemData.status || "").trim().toUpperCase();
          const reservedFor = String(itemData.reservedForPaymentRequestId || "").trim();
          if (itemStatus !== "RESERVED" || reservedFor !== requestId) return;
          transaction.update(itemRef, {
            status: "AVAILABLE",
            reservedBy: admin.firestore.FieldValue.delete(),
            reservedForPaymentRequestId: admin.firestore.FieldValue.delete(),
            reservedVia: admin.firestore.FieldValue.delete(),
            reservedAt: admin.firestore.FieldValue.delete(),
          });
        });
      };

      await db.runTransaction(async (transaction) => {
        const [freshRequestDoc, freshItemDoc] = await Promise.all([
          transaction.get(snap.ref),
          transaction.get(itemRef),
        ]);
        if (!freshRequestDoc.exists) {
          throw new functions.https.HttpsError("not-found", "Purchase request no longer exists.");
        }
        const freshRequestData = (freshRequestDoc.data() || {}) as Record<string, unknown>;
        const requestStatus = String(freshRequestData.status || "").trim().toLowerCase();
        if (!["pending", "processing"].includes(requestStatus)) {
          throw new functions.https.HttpsError("failed-precondition", "Purchase request is no longer pending.");
        }
        if (!freshItemDoc.exists) {
          throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
        }
        const freshItemData = (freshItemDoc.data() || {}) as Record<string, unknown>;
        const freshItemStatus = String(freshItemData.status || "").trim().toUpperCase();
        const freshReservedBy = String(freshItemData.reservedBy || "").trim();
        const stillAvailable =
          freshItemStatus === "AVAILABLE" ||
          freshItemStatus === "ACTIVE" ||
          freshItemStatus === "OPEN" ||
          (freshItemStatus === "RESERVED" && freshReservedBy === buyerIdStr);
        if (!stillAvailable) {
          throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
        }

        const reserveTimestamp = admin.firestore.Timestamp.now();
        transaction.update(itemRef, {
          status: "RESERVED",
          reservedBy: buyerIdStr,
          reservedForPaymentRequestId: requestId,
          reservedVia: "STRIPE_COMMERCE",
          reservedAt: reserveTimestamp,
        });
      });

      let chargeResult: Awaited<ReturnType<typeof createStripeCardCommerceDirectCharge>>;
      try {
        chargeResult = await createStripeCardCommerceDirectCharge({
          payerUserId: String(buyerId || "").trim(),
          payerUserData: buyerData,
          amount: itemPrice,
          currency: "USD",
          description: `Marketplace purchase: ${itemTitle}`,
          connectedAccountId,
          applicationFeeAmount: platformFee,
          metadata: {
            flow: "MARKETPLACE_PURCHASE",
            purchaseRequestId: requestId,
            itemId: String(itemId || "").trim(),
            buyerId: String(buyerId || "").trim(),
            sellerId: String(sellerId || "").trim(),
          },
          idempotencyKey: `marketplace_purchase_${requestId}`,
        });
      } catch (chargeError) {
        await releaseStripeMarketplaceReservation();
        throw chargeError;
      }
      const commercePayoutRef = sellerNet > 0 ? db.collection("payout_requests").doc() : null;

      try {
        await db.runTransaction(async (transaction) => {
          const [freshRequestDoc, freshItemDoc] = await Promise.all([
            transaction.get(snap.ref),
            transaction.get(itemRef),
          ]);
          if (!freshRequestDoc.exists) {
            throw new functions.https.HttpsError("not-found", "Purchase request no longer exists.");
          }
          const freshRequestData = (freshRequestDoc.data() || {}) as Record<string, unknown>;
          const requestStatus = String(freshRequestData.status || "").trim().toLowerCase();
          if (!["pending", "processing"].includes(requestStatus)) {
            throw new functions.https.HttpsError("failed-precondition", "Purchase request is no longer pending.");
          }

          if (!freshItemDoc.exists) {
            throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
          }
          const freshItemData = (freshItemDoc.data() || {}) as Record<string, unknown>;
          const freshItemStatus = String(freshItemData.status || "").trim().toUpperCase();
          const freshReservedBy = String(freshItemData.reservedBy || "").trim();
          const stillAvailable =
            freshItemStatus === "AVAILABLE" ||
            freshItemStatus === "ACTIVE" ||
            freshItemStatus === "OPEN" ||
            (freshItemStatus === "RESERVED" && freshReservedBy === buyerIdStr);
          if (!stillAvailable) {
            throw new functions.https.HttpsError("failed-precondition", "Item is no longer available.");
          }

          const timestamp = admin.firestore.Timestamp.now();
          transaction.update(itemRef, {
            status: "SOLD",
            soldAt: timestamp,
            soldTo: buyerId,
            soldPrice: itemPrice,
            soldVia: "STRIPE_CONNECT",
            reservedBy: admin.firestore.FieldValue.delete(),
            reservedForPaymentRequestId: admin.firestore.FieldValue.delete(),
            reservedVia: admin.firestore.FieldValue.delete(),
            reservedAt: admin.firestore.FieldValue.delete(),
          });

          if (platformFee > 0) {
            recordPlatformRevenue(transaction, {
              source: "marketplacePlatinumFee",
              amount: platformFee,
              note: `Marketplace Stripe fee for item ${itemId}`,
              relatedUserId: String(buyerId || "").trim(),
              processor: "STRIPE",
              provider: "STRIPE",
              settlementCategory: "MARKETPLACE",
              processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
            });
          }

          transaction.set(db.collection("users").doc(String(buyerId || "").trim()).collection("transactions").doc(), {
            title: `Purchase: ${itemTitle}`,
            amount: -itemPrice,
            type: "DEBIT",
            status: "COMPLETED",
            timestamp,
            note: `Charged to your saved Stripe card. Seller: ${sellerDoc.data()?.name || "seller"}.`,
            source: "MARKETPLACE_STRIPE",
            processor: "STRIPE",
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
            fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
          });

          transaction.set(db.collection("users").doc(String(sellerId || "").trim()).collection("transactions").doc(), {
            title: `Sale: ${itemTitle}`,
            amount: sellerNet,
            type: "CREDIT",
            status: "COMPLETED",
            timestamp,
            note: sellerStaffFeeExempt ?
              `Stripe direct sale from ${buyerDoc.data()?.name || "buyer"}. Staff fee exemption applied; Stripe processing fees settle in your merchant account.` :
              `Stripe direct sale from ${buyerDoc.data()?.name || "buyer"}. Platform fee: $${platformFee.toFixed(2)}. Stripe processing fees settle in your merchant account.`,
            source: "MARKETPLACE_STRIPE_SALE",
            processor: "STRIPE",
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
          });

          if (commercePayoutRef) {
            transaction.set(commercePayoutRef, buildCompletedCommercePayoutRequestRecord({
              amount: sellerNet,
              grossAmount: itemPrice,
              currency: "USD",
              recipientId: String(sellerId || "").trim(),
              recipientName: asNonEmptyString(sellerData.name, sellerData.username) || "Seller",
              senderId: String(buyerId || "").trim(),
              source: "MARKETPLACE_STRIPE_PAYOUT",
              type: "COMMERCE_PAYOUT",
              settlementCategory: "MARKETPLACE",
              commerceRecordId: String(itemId || "").trim(),
              processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
              timestamp,
              providerMessage: "Stripe direct marketplace sale completed in the seller's Stripe account.",
              stripePaymentIntentId: chargeResult.paymentIntentId,
              stripeChargeId: chargeResult.latestChargeId,
              fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
              destinationAccountId: connectedAccountId,
              stripeConnectedAccountId: chargeResult.connectedAccountId,
              platformFee,
              extraContext: {
                purchaseRequestId: requestId,
                itemId: String(itemId || "").trim(),
                itemTitle,
                buyerId: String(buyerId || "").trim(),
                sellerId: String(sellerId || "").trim(),
              },
            }));
          }

          transaction.update(snap.ref, {
            status: "completed",
            fundingPreference: requestedFundingPreference,
            resultMessage: "Purchase successful! Your card was charged through Stripe.",
            settledPrice: itemPrice,
            platformFee,
            sellerNet,
            ...buildLiveCommerceSettlementMetadata(settlementDecision),
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
            fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
            commercePayoutRequestId: commercePayoutRef?.id || null,
            completedAt: timestamp,
          });
        });
      } catch (settleError) {
        await refundStripeCommercePaymentIntent({
          paymentIntentId: chargeResult.paymentIntentId,
          connectedAccountId: chargeResult.connectedAccountId,
          directChargeAttemptId: `marketplace_purchase_${requestId}`,
          idempotencyKey: `marketplace_purchase_refund_${requestId}`,
          metadata: {
            flow: "MARKETPLACE_PURCHASE",
            purchaseRequestId: requestId,
            reason: "post_charge_commit_failed",
          },
        });
        await releaseStripeMarketplaceReservation();
        throw settleError;
      }

      functions.logger.log(`Successfully processed transaction for request: ${requestId}`);
    } catch (error) {
      const mappedError = mapStripeCommerceChargeError(error);
      functions.logger.error(`Transaction failed for request ${requestId}:`, error);
      await snap.ref.update({
        status: "failed",
        resultMessage: mappedError.message || "An unexpected error occurred. Please try again.",
        processor: activeProcessor,
        processorMode: activeProcessorMode,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
    }
    return undefined;
  });


// =============================================================================
//  2A. CALL SESSION NOTIFICATIONS (NEW)
// =============================================================================

export const onCallSessionCreated = functions
  .runWith({secrets: [secretApnsP8]})
  .firestore.document("call_sessions/{sessionId}")
  .onCreate(async (snap, context) => {
    const session = snap.data();
    if (!session) return undefined;

    const receiverId = trimStringValue(session.receiverId);
    const callerId = trimStringValue(session.callerId);
    const chatId = trimStringValue(session.chatId);
    const callType = trimStringValue(session.callType);
    const callerName = trimStringValue(session.callerName);
    const channelName = trimStringValue(session.agoraChannelName);
    const status = trimStringValue(session.status).toLowerCase();

    if (!receiverId || !callerId || !chatId || !callType) return undefined;
    if (status && status !== "ringing") return undefined;
    if (receiverId === callerId) return undefined;

    const chatSnap = await db.collection("chats").doc(chatId).get();
    if (!chatSnap.exists) return undefined;
    const chat = (chatSnap.data() || {}) as Record<string, unknown>;
    const participants = normalizeUidList(chat.participants);
    const exited = new Set(normalizeUidList(chat.exitedParticipantIds));
    if (!participants.includes(callerId) || !participants.includes(receiverId)) return undefined;
    if (exited.has(callerId) || exited.has(receiverId)) return undefined;
    if (await directChatIsBlocked(chat)) return undefined;

    const sessionParticipants = normalizeUidList(session.participantIds);
    const callees = sessionParticipants.filter((uid) => uid && uid !== callerId && !exited.has(uid));
    if (callees.length === 0) {
      callees.push(receiverId);
    }

    for (const calleeId of [...new Set(callees)]) {
      const calleeUserSnap = await db.collection("users").doc(calleeId).get();
      const calleeUserData = (calleeUserSnap.data() || {}) as Record<string, unknown>;
      const routing = await getUserPushRouting(calleeId, calleeUserData);
      if (!routing.fcmToken && !routing.apnsVoipToken) {
        functions.logger.warn("onCallSessionCreated: callee has no push routing tokens", {
          calleeId,
          callId: context.params.sessionId,
          chatId,
        });
        continue;
      }
      await notifyIncomingCall({
        receiverId: calleeId,
        callerId,
        chatId,
        callId: context.params.sessionId,
        callerName: callerName || "Incoming call",
        callType,
        channelName: channelName || "",
      });
    }

    return undefined;
  });

/**
 * Denormalize `chats/{chatId}/call_logs/{callLogId}` into each active participant's
 * `users/{uid}/call_history/{callLogId}` so clients can load Social Inbox call history with a single query.
 * Client writes to `call_history` are denied in Firestore rules; only the Admin SDK (Functions) updates this path.
 */
const normalizeUidList = (value: unknown): string[] => {
  if (!Array.isArray(value)) return [];
  const out: string[] = [];
  for (const item of value) {
    if (typeof item === "string") {
      const t = item.trim();
      if (t.length > 0) out.push(t);
    }
  }
  return [...new Set(out)];
};

const commitBatchedDeletes = async (
  userIds: string[],
  buildRef: (uid: string) => FirebaseFirestore.DocumentReference
): Promise<void> => {
  let batch = db.batch();
  let ops = 0;
  for (const uid of userIds) {
    if (!uid) continue;
    batch.delete(buildRef(uid));
    ops += 1;
    if (ops >= 450) {
      await batch.commit();
      batch = db.batch();
      ops = 0;
    }
  }
  if (ops > 0) {
    await batch.commit();
  }
};

const commitBatchedSets = async (
  entries: Array<{ref: FirebaseFirestore.DocumentReference; data: Record<string, unknown>}>,
): Promise<void> => {
  let batch = db.batch();
  let ops = 0;
  for (const {ref, data} of entries) {
    batch.set(ref, data, {merge: true});
    ops += 1;
    if (ops >= 450) {
      await batch.commit();
      batch = db.batch();
      ops = 0;
    }
  }
  if (ops > 0) {
    await batch.commit();
  }
};

/** Marks long-unanswered ringing sessions as missed so call history and cancel pushes stay accurate. */
export const expireStaleRingingCallSessions = functions.pubsub
  .schedule("every 1 minutes")
  .onRun(async () => {
    const cutoffMs = Date.now() - 90 * 1000;
    const cutoff = admin.firestore.Timestamp.fromMillis(cutoffMs);
    const snap = await db.collection("call_sessions")
      .where("status", "==", "ringing")
      .where("createdAt", "<", cutoff)
      .limit(120)
      .get();

    if (snap.empty) {
      return undefined;
    }

    let expired = 0;
    for (const doc of snap.docs) {
      const session = (doc.data() || {}) as Record<string, unknown>;
      const status = trimStringValue(session.status).toLowerCase();
      if (status !== "ringing") {
        continue;
      }
      const sessionParticipants = normalizeUidList(session.participantIds);
      const acceptedParticipants = normalizeUidList(session.acceptedParticipantIds);
      const isGroupCall = session.isGroup === true || sessionParticipants.length > 1;
      // Group calls remain `ringing` while participants join/leave. Once at least one invitee
      // joined the caller, the session is active and must not be marked missed by the 90-second
      // unanswered-call cleanup intended for direct calls.
      if (isGroupCall && acceptedParticipants.length >= 2) {
        continue;
      }
      try {
        await doc.ref.update({
          status: "missed",
          endedAt: admin.firestore.FieldValue.serverTimestamp(),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        });
        expired += 1;
      } catch (error) {
        functions.logger.warn("expireStaleRingingCallSessions update failed", {
          sessionId: doc.id,
          error: String(error),
        });
      }
    }

    if (expired > 0) {
      functions.logger.log("expireStaleRingingCallSessions", {expired});
    }
    return undefined;
  });

export const onCallSessionUpdated = functions
  .runWith({secrets: [secretApnsP8]})
  .firestore
  .document("call_sessions/{sessionId}")
  .onUpdate(async (change, context) => {
    const sessionId = String(context.params.sessionId || "").trim();
    if (!sessionId) return undefined;

    const before = (change.before.data() || {}) as Record<string, unknown>;
    const after = (change.after.data() || {}) as Record<string, unknown>;
    const chatId = typeof after.chatId === "string" ? after.chatId.trim() : "";
    if (!chatId) return undefined;

    const beforeStatus = typeof before.status === "string" ? before.status.trim().toLowerCase() : "";
    const afterStatus = typeof after.status === "string" ? after.status.trim().toLowerCase() : "";

    if (
      beforeStatus === "ringing" &&
      afterStatus !== beforeStatus &&
      ["ended", "declined", "missed"].includes(afterStatus)
    ) {
      const callerId = trimStringValue(after.callerId);
      const sessionParticipants = normalizeUidList(after.participantIds);
      const fallbackReceiver = trimStringValue(after.receiverId);
      const targets = sessionParticipants.filter((uid) => uid && uid !== callerId);
      if (targets.length === 0 && fallbackReceiver) {
        targets.push(fallbackReceiver);
      }
      for (const receiverId of [...new Set(targets)]) {
        await notifyCallCancelled({receiverId, chatId, callId: sessionId});
      }
    }

    if (!afterStatus || beforeStatus === afterStatus) return undefined;
    if (!["accepted", "ended", "declined", "missed"].includes(afterStatus)) return undefined;

    const update: Record<string, unknown> = {
      status: afterStatus,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    };

    if (afterStatus === "accepted") {
      update.answeredAt = admin.firestore.FieldValue.serverTimestamp();
    }
    if (["ended", "declined", "missed"].includes(afterStatus)) {
      update.endedAt = admin.firestore.FieldValue.serverTimestamp();
      const answeredAt = after.answeredAt as FirebaseFirestore.Timestamp | undefined;
      const endedAt = after.endedAt as FirebaseFirestore.Timestamp | undefined;
      if (answeredAt?.toMillis && endedAt?.toMillis) {
        update.durationSeconds = Math.max(
          0,
          Math.floor((endedAt.toMillis() - answeredAt.toMillis()) / 1000),
        );
      } else {
        // Missed and declined calls have no connected-call duration.
        update.durationSeconds = 0;
      }
    }

    await db.collection("chats").doc(chatId)
      .collection("call_logs").doc(sessionId)
      .set(update, {merge: true});

    return undefined;
  });

export const onChatCallLogWrite = functions.firestore
  .document("chats/{chatId}/call_logs/{callLogId}")
  .onWrite(async (change, context) => {
    const chatId = String(context.params.chatId || "").trim();
    const callLogId = String(context.params.callLogId || "").trim();
    if (!chatId || !callLogId) {
      return undefined;
    }

    const chatSnap = await db.collection("chats").doc(chatId).get();
    const chat = (chatSnap.data() || {}) as Record<string, unknown>;
    const chatParticipants = normalizeUidList(chat.participants);
    const exited = new Set(normalizeUidList(chat.exitedParticipantIds));

    if (!change.after.exists) {
      const before = (change.before.data() || {}) as Record<string, unknown>;
      const fromLog = normalizeUidList(before.participantIds);
      const callerId = trimStringValue(before.callerId);
      const toDelete = new Set<string>([...fromLog, callerId, ...chatParticipants]);
      await commitBatchedDeletes([...toDelete], (uid) =>
        db.collection("users").doc(uid).collection("call_history").doc(callLogId),
      );
      return undefined;
    }

    const data = (change.after.data() || {}) as Record<string, unknown>;
    let targets = normalizeUidList(data.participantIds);
    const callerId = trimStringValue(data.callerId);
    if (callerId) {
      // `participantIds` intentionally contains invitees only; the caller also needs history.
      targets.push(callerId);
    }
    targets = [...new Set(targets)];
    if (targets.length === 0) {
      targets = chatParticipants.filter((uid) => !exited.has(uid));
    } else {
      targets = targets.filter((uid) => chatParticipants.includes(uid) && !exited.has(uid));
    }

    if (targets.length === 0) {
      functions.logger.warn("onChatCallLogWrite: no active recipients for call log fan-out.", {chatId, callLogId});
      return undefined;
    }

    const visibility = await Promise.all(
      targets.map(async (uid) => {
        const hiddenSnap = await db.collection("users").doc(uid)
          .collection("call_history_hidden").doc(callLogId).get();
        return {uid, visible: !hiddenSnap.exists};
      }),
    );
    const visibleTargets = visibility.filter((entry) => entry.visible).map((entry) => entry.uid);
    if (visibleTargets.length === 0) {
      return undefined;
    }

    const groupNameFromChat = typeof chat.groupName === "string" ? chat.groupName.trim() : "";
    const groupNameFromLog = typeof data.groupName === "string" ? String(data.groupName).trim() : "";
    const mergedGroupName = groupNameFromLog || groupNameFromChat || null;

    const payload: Record<string, unknown> = {
      ...data,
      chatId,
      groupName: mergedGroupName,
      syncedAt: admin.firestore.FieldValue.serverTimestamp(),
    };

    if (!payload.startedAt && payload.createdAt) {
      payload.startedAt = payload.createdAt;
    }

    const writes = visibleTargets.map((uid) => ({
      ref: db.collection("users").doc(uid).collection("call_history").doc(callLogId),
      data: payload,
    }));

    await db.collection("chats").doc(chatId).set({
      lastCallType: typeof data.callType === "string" ? data.callType.trim().toLowerCase() : null,
      lastCallStatus: typeof data.status === "string" ? data.status.trim().toLowerCase() : null,
      lastCallTimestamp: payload.startedAt || admin.firestore.FieldValue.serverTimestamp(),
      lastCallInitiatorId: typeof data.callerId === "string" ? data.callerId.trim() : null,
      lastCallReceiverId: typeof data.receiverId === "string" ? data.receiverId.trim() : null,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, {merge: true});

    await commitBatchedSets(writes);
    return undefined;
  });

const truncateForPush = (value: string, max: number): string => {
  const t = value.replace(/\s+/g, " ").trim();
  if (t.length <= max) return t;
  return `${t.slice(0, Math.max(0, max - 1))}…`;
};

const notifyChatMessageRecipients = async (params: {
  chatId: string;
  messageId: string;
  senderId: string;
  senderName: string;
  preview: string;
  isGroup: boolean;
  groupName: string | null;
  recipientIds: string[];
}): Promise<void> => {
  const {chatId, messageId, senderId, senderName, preview, isGroup, groupName, recipientIds} = params;
  if (recipientIds.length === 0) return;

  const title = isGroup ?
    (groupName ? `New message in ${groupName}` : "New group message") :
    (senderName || "New message");
  const body = isGroup ? `${senderName || "Someone"}: ${preview}` : preview;

  for (const recipientId of recipientIds) {
    const doc = await db.collection("users").doc(recipientId).get();
    const routing = await getUserPushRouting(
      recipientId,
      (doc.data() || {}) as Record<string, unknown>
    );
    const token = routing.fcmToken;
    if (!token) continue;

    try {
      await admin.messaging().send({
        token,
        data: {
          type: "chat_message",
          chatId,
          messageId,
          senderId,
          receiverId: recipientId,
        },
        android: {
          priority: "high",
          notification: {
            title,
            body,
            sound: "default",
          },
        },
        apns: {
          headers: {
            "apns-priority": "10",
            "apns-push-type": "alert",
          },
          payload: {
            aps: {
              alert: {
                title,
                body,
              },
              sound: "MessageBeep.caf",
              category: "NEW_CHAT_MESSAGE",
              "thread-id": `chat-${chatId}`,
              "content-available": 1,
            },
          },
        },
      });
    } catch (error) {
      functions.logger.warn("FCM chat message push failed", {
        chatId,
        messageId,
        recipientId,
        error: String(error),
      });
    }
  }
};

/** FCM alert for new chat messages (direct + group). Excludes sender and exited participants. */
export const onChatMessageCreatedNotifyRecipients = functions.firestore
  .document("chats/{chatId}/messages/{messageId}")
  .onCreate(async (snap, context) => {
    const chatId = String(context.params.chatId || "").trim();
    const messageId = String(context.params.messageId || "").trim();
    if (!chatId || !messageId) {
      return undefined;
    }

    const msg = snap.data() as Record<string, unknown> | undefined;
    if (!msg) {
      return undefined;
    }

    const senderId = String(msg.senderId || "").trim();
    if (!senderId) {
      return undefined;
    }

    const textRaw = String(msg.messageText ?? msg.text ?? "").trim();
    const preview = truncateForPush(textRaw.length > 0 ? textRaw : "New message", 160);

    const chatSnap = await db.collection("chats").doc(chatId).get();
    const chat = (chatSnap.data() || {}) as Record<string, unknown>;
    if (await directChatIsBlocked(chat)) {
      return undefined;
    }
    const senderSnap = await db.collection("users").doc(senderId).get();
    const senderData = (senderSnap.data() || {}) as Record<string, unknown>;
    const participants = normalizeUidList(chat.participants);
    const exited = new Set(normalizeUidList(chat.exitedParticipantIds));
    const chatType = String(chat.chatType || "").trim().toLowerCase();
    const activeCount = participants.filter((p) => !exited.has(p)).length;
    const isGroup = chatType === "group" || activeCount > 2;

    const groupNameRaw = typeof chat.groupName === "string" ? chat.groupName.trim() : "";
    const groupName = groupNameRaw.length > 0 ? groupNameRaw : null;
    const senderName = String(
      senderData.name ||
      senderData.username ||
      msg.senderDisplayName ||
      "Someone"
    ).trim() || "Someone";

    await db.collection("chats").doc(chatId).set({
      lastMessageText: textRaw.length > 0 ? textRaw : "New message",
      lastMessageTimestamp: msg.timestamp || admin.firestore.FieldValue.serverTimestamp(),
      lastMessageSenderId: senderId,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, {merge: true});

    const recipients = participants.filter((uid) => uid && uid !== senderId && !exited.has(uid));
    if (recipients.length === 0) {
      return undefined;
    }

    await notifyChatMessageRecipients({
      chatId,
      messageId,
      senderId,
      senderName,
      preview,
      isGroup,
      groupName,
      recipientIds: recipients,
    });

    return undefined;
  });


// =============================================================================
//  2A. GARAGE SALE PAYMENTS (NEW)
// =============================================================================

const defaultAdListingFeeFromEnv = (): number => {
  const raw = String(
    process.env.SPONSORED_AD_LISTING_FEE_USD ||
    process.env.CONFIG_AD_POST_FEE_USD ||
    getAppConfig().adPostFeeUsdDefault ||
    "0"
  ).trim();
  const n = Number.parseFloat(raw);
  return Number.isFinite(n) && n >= 0 ? roundMoney(n) : 0;
};

const pickAdListingFeeUsd = (feeSnap: FirebaseFirestore.DocumentSnapshot): number => {
  const feeData = (feeSnap.data() || {}) as Record<string, unknown>;
  const order = ["adPostFeeUsd", "sponsoredAdFeeUsd", "sponsored_ad_fee_usd"] as const;
  for (const key of order) {
    if (feeData && Object.prototype.hasOwnProperty.call(feeData, key)) {
      const n = Number.parseFloat(String(feeData[key] ?? ""));
      return Number.isFinite(n) && n >= 0 ? roundMoney(n) : 0;
    }
  }
  return feeSnap.exists ? 0 : defaultAdListingFeeFromEnv();
};

const pickGarageSaleFeeRate = (feeData: Record<string, unknown>): number => {
  const n = Number.parseFloat(String(feeData.garageSaleFeeRate ?? "NaN"));
  if (Number.isFinite(n) && n >= 0 && n <= 1) {
    return n;
  }
  return 0.02;
};

const pickEventTicketOwnerFeeRate = (feeData: Record<string, unknown>): number => {
  const n = Number.parseFloat(String(feeData.eventTicketOwnerFeeRate ?? "NaN"));
  if (Number.isFinite(n) && n >= 0 && n <= 1) {
    return n;
  }
  return EVENT_TICKET_OWNER_FEE_RATE;
};

type GarageSaleCheckoutFundingPreference = "STRIPE_CARD" | "AFRIEX_MOBILE_MONEY";

const normalizeGarageSaleCheckoutFundingPreference = (
  value: unknown
): GarageSaleCheckoutFundingPreference => {
  const normalized = String(value || "").trim().toUpperCase();
  // Older app versions had only the card flow; never infer a different funding method.
  if (!normalized || normalized === "STRIPE_CARD") return "STRIPE_CARD";
  if (normalized === "AFRIEX_MOBILE_MONEY") {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Mobile money checkout is not available for seller or organizer payments right now. Use a card so the recipient is paid through Stripe Connect."
    );
  }
  throw new functions.https.HttpsError(
    "invalid-argument",
    "Select a supported garage sale payment method."
  );
};

const pickMarketplacePlatinumFeeRate = (feeData: Record<string, unknown>): number => {
  const n = Number.parseFloat(String(feeData.marketplacePlatinumFeeRate ?? "NaN"));
  if (Number.isFinite(n) && n >= 0 && n <= 1) {
    return n;
  }
  return 0.02;
};

const assertGarageShopIsOpen = (
  shopProfileSnap: FirebaseFirestore.DocumentSnapshot
): void => {
  const shopIsOpen = shopProfileSnap.exists ? shopProfileSnap.data()?.isOpen !== false : true;
  if (!shopIsOpen) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "This garage shop is closed right now."
    );
  }
};

export const processGarageSalePayment = functions.firestore
  .document("garage_sale_payments/{paymentId}")
  .onCreate(async (snap, context) => {
    const paymentId = context.params.paymentId;
    const paymentData = snap.data();
    functions.logger.log(`Processing garage sale payment: ${paymentId}`);

    if (!paymentData || !snap) {
      functions.logger.error("Garage sale payment data is missing.");
      return undefined;
    }

    const {buyerId, sellerId, garageSaleId, amount} = paymentData;

    if (!buyerId || !sellerId || !garageSaleId || typeof amount !== "number" || amount <= 0) {
      functions.logger.error("Invalid garage sale payment data.", paymentData);
      return snap.ref.update({
        status: "failed",
        resultMessage: "Invalid payment data. Cannot be processed.",
      });
    }

    const buyerRef = db.collection("users").doc(buyerId);
    const sellerRef = db.collection("users").doc(sellerId);
    const saleRef = db.collection("garage_sales").doc(garageSaleId);
    let activeProcessor = "STRIPE";
    let activeProcessorMode = STRIPE_CONNECT_DIRECT_CHARGE_MODE;

    try {
      const requestedFundingPreference = normalizeGarageSaleCheckoutFundingPreference(
        paymentData.fundingPreference
      );
      activeProcessor = "STRIPE";
      activeProcessorMode = STRIPE_CONNECT_DIRECT_CHARGE_MODE;
      await snap.ref.set({
        status: "processing",
        fundingPreference: requestedFundingPreference,
        processor: activeProcessor,
        processorMode: activeProcessorMode,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, {merge: true});

      const feeSnap = await db.collection("app_config").doc("fee_settings").get();
      const feeData = (feeSnap.data() || {}) as Record<string, unknown>;
      const platformFeeRate = pickGarageSaleFeeRate(feeData);

      const [buyerDoc, sellerDoc, saleDoc] = await Promise.all([
        buyerRef.get(),
        sellerRef.get(),
        saleRef.get(),
      ]);

      if (!buyerDoc.exists || !sellerDoc.exists) {
        throw new functions.https.HttpsError("not-found", "Buyer or seller account does not exist.");
      }
      if (buyerId === sellerId) {
        throw new functions.https.HttpsError("failed-precondition", "Buyer and seller cannot be the same account.");
      }
      if (!saleDoc.exists) {
        throw new functions.https.HttpsError("failed-precondition", "Garage sale not found.");
      }

      const buyerData = await withPrivateUserFields(
        String(buyerId || "").trim(),
        (buyerDoc.data() || {}) as Record<string, unknown>
      );
      const sellerData = await withPrivateUserFields(
        String(sellerId || "").trim(),
        (sellerDoc.data() || {}) as Record<string, unknown>
      );
      const saleData = (saleDoc.data() || {}) as Record<string, unknown>;
      if (saleData.isDeleted === true) {
        throw new functions.https.HttpsError("failed-precondition", "This garage sale is no longer available.");
      }

      const saleOwnerId = String(saleData.ownerId || "").trim();
      if (!saleOwnerId || saleOwnerId !== sellerId) {
        throw new functions.https.HttpsError("failed-precondition", "Seller does not own this garage sale.");
      }

      const shopProfileSnap = await db.collection("garage_shop_profiles").doc(sellerId).get();
      assertGarageShopIsOpen(shopProfileSnap);

      const saleTitle = String(saleData.title || "Garage Sale").trim() || "Garage Sale";
      const sellerStaffFeeExempt = isStaffFeeExempt(sellerData);
      const platformFee = sellerStaffFeeExempt ? 0 : roundMoney(amount * platformFeeRate);
      const sellerNet = roundMoney(amount - platformFee);
      const sellerAfriexPayoutPlan = await buildAfriexCommercePayoutPlanForUser(
        String(sellerId || "").trim()
      );
      const settlementDecision = await resolveMarketplaceCheckoutSettlementDecision({
        recipientUserId: String(sellerId || "").trim(),
        recipientUserData: sellerData,
        flowName: "Garage sale checkout",
        requestedFundingPreference,
      });
      if (settlementDecision.provider === "AFRIEX" && settlementDecision.executionMode === "LIVE") {
        activeProcessor = "AFRIEX";
        activeProcessorMode = AFRIEX_COMMERCE_PROCESSOR_MODE;
        const afriexRuntime = await resolveAfriexCommerceRuntime({
          buyerUserId: String(buyerId || "").trim(),
          recipientUserId: String(sellerId || "").trim(),
          recipientPayoutPlan: sellerAfriexPayoutPlan,
          grossAmount: roundMoney(Number(amount)),
          netAmount: sellerNet,
          flowName: "Garage sale checkout",
        });
        const collectionRef = db.collection("payout_requests").doc();
        const shopProfileRef = db.collection("garage_shop_profiles").doc(String(sellerId || "").trim());
        await db.runTransaction(async (transaction) => {
          const [freshPaymentDoc, freshSaleDoc, freshShopProfileDoc] = await Promise.all([
            transaction.get(snap.ref),
            transaction.get(saleRef),
            transaction.get(shopProfileRef),
          ]);
          if (!freshPaymentDoc.exists) {
            throw new functions.https.HttpsError("not-found", "Garage sale payment record no longer exists.");
          }
          const freshPaymentData = (freshPaymentDoc.data() || {}) as Record<string, unknown>;
          const paymentStatus = String(freshPaymentData.status || "").trim().toLowerCase();
          if (!["pending", "processing"].includes(paymentStatus)) {
            throw new functions.https.HttpsError("failed-precondition", "Garage sale payment is no longer pending.");
          }
          if (!freshSaleDoc.exists) {
            throw new functions.https.HttpsError("failed-precondition", "Garage sale not found.");
          }
          const freshSaleData = (freshSaleDoc.data() || {}) as Record<string, unknown>;
          if (freshSaleData.isDeleted === true) {
            throw new functions.https.HttpsError("failed-precondition", "This garage sale is no longer available.");
          }
          const freshOwnerId = String(freshSaleData.ownerId || "").trim();
          if (!freshOwnerId || freshOwnerId !== String(sellerId || "").trim()) {
            throw new functions.https.HttpsError("failed-precondition", "Seller does not own this garage sale.");
          }
          assertGarageShopIsOpen(freshShopProfileDoc);

          const timestamp = admin.firestore.Timestamp.now();
          const collectionData: FirebaseFirestore.DocumentData = {
            senderId: String(buyerId || "").trim(),
            amount: roundMoney(Number(amount)),
            currency: "USD",
            phone: afriexRuntime.fundingMethod.phoneNumber,
            network: afriexRuntime.fundingMethod.network,
            country: afriexRuntime.fundingMethod.country,
            dialCode: afriexRuntime.fundingMethod.dialCode,
            localCurrency: afriexRuntime.fundingMethod.currency,
            paymentMethodId: afriexRuntime.fundingMethod.paymentMethodId,
            type: "CASH_IN",
            status: "PENDING",
            source: buildAfriexCommerceCollectionSource("GARAGE_SALE"),
            fundingSource: "EXTERNAL_MOBILE_MONEY",
            fundingPreference: requestedFundingPreference,
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            createdAt: timestamp,
            processedAt: timestamp,
            transferIntent: {
              mode: AFRIEX_COMMERCE_TRANSFER_MODE,
              settlementCategory: "GARAGE_SALE",
              commerceTitle: saleTitle,
              garageSalePaymentId: paymentId,
              garageSaleId: String(garageSaleId || "").trim(),
              grossAmount: roundMoney(Number(amount)),
              netAmount: sellerNet,
              platformFee,
              recipientUserId: String(sellerId || "").trim(),
              recipientName: asNonEmptyString(sellerData.name, sellerData.username) || "Seller",
              recipientPaymentMethodId: afriexRuntime.recipientTarget.paymentMethodId,
              recipientInfo: afriexRuntime.recipientTarget.recipientInfo,
              recipientLocalAmount: afriexRuntime.recipientTarget.localAmount,
              recipientLocalCurrency: afriexRuntime.recipientTarget.localCurrency,
              recipientFx: afriexRuntime.recipientTarget.payoutFx,
              afriexPayoutRoute: afriexRuntime.recipientTarget.route,
              requestedCurrency: "USD",
              processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            },
          };
          transaction.set(collectionRef, collectionData, {merge: true});
          transaction.update(snap.ref, {
            status: "awaiting_payment",
            fundingPreference: requestedFundingPreference,
            resultMessage: "Mobile money collection started. Ask the buyer to approve the prompt on their phone.",
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            providerRoutingStatus: "COLLECTION_PENDING",
            providerRoutingMessage: "Awaiting buyer mobile money approval.",
            afriexPayoutProvider: "AFRIEX",
            afriexPreferredPayoutRoute: afriexRuntime.recipientTarget.route,
            afriexPayoutSelectionRequired: false,
            providerCollectionRequestId: collectionRef.id,
            updatedAt: timestamp,
          });
        });
        return undefined;
      }
      if (settlementDecision.executionMode !== "LIVE" || settlementDecision.provider !== "STRIPE") {
        await snap.ref.set({
          status: "failed",
          resultMessage: settlementDecision.message || "This garage sale corridor is not ready for live checkout.",
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          ...buildLiveCommerceSettlementMetadata(settlementDecision),
        }, {merge: true});
        return undefined;
      }
      const connectedAccountId = settlementDecision.destinationAccountId;
      if (!connectedAccountId) {
        throw new functions.https.HttpsError("failed-precondition", "Garage sale checkout is missing the seller's Stripe account.");
      }
      const chargeResult = await createStripeCardCommerceDirectCharge({
        payerUserId: String(buyerId || "").trim(),
        payerUserData: buyerData,
        amount: roundMoney(Number(amount)),
        currency: "USD",
        description: `Garage sale checkout: ${saleTitle}`,
        connectedAccountId,
        applicationFeeAmount: platformFee,
        metadata: {
          flow: "GARAGE_SALE_CHECKOUT",
          garageSalePaymentId: paymentId,
          garageSaleId: String(garageSaleId || "").trim(),
          buyerId: String(buyerId || "").trim(),
          sellerId: String(sellerId || "").trim(),
        },
        idempotencyKey: `garage_sale_checkout_${paymentId}`,
      });
      const commercePayoutRef = sellerNet > 0 ? db.collection("payout_requests").doc() : null;
      const shopProfileRef = db.collection("garage_shop_profiles").doc(String(sellerId || "").trim());

      try {
        await db.runTransaction(async (transaction) => {
          const [freshPaymentDoc, freshSaleDoc, freshShopProfileDoc] = await Promise.all([
            transaction.get(snap.ref),
            transaction.get(saleRef),
            transaction.get(shopProfileRef),
          ]);
          if (!freshPaymentDoc.exists) {
            throw new functions.https.HttpsError("not-found", "Garage sale payment record no longer exists.");
          }
          const freshPaymentData = (freshPaymentDoc.data() || {}) as Record<string, unknown>;
          const paymentStatus = String(freshPaymentData.status || "").trim().toLowerCase();
          if (!["pending", "processing"].includes(paymentStatus)) {
            throw new functions.https.HttpsError("failed-precondition", "Garage sale payment is no longer pending.");
          }

          if (!freshSaleDoc.exists) {
            throw new functions.https.HttpsError("failed-precondition", "Garage sale not found.");
          }
          const freshSaleData = (freshSaleDoc.data() || {}) as Record<string, unknown>;
          if (freshSaleData.isDeleted === true) {
            throw new functions.https.HttpsError("failed-precondition", "This garage sale is no longer available.");
          }
          const freshOwnerId = String(freshSaleData.ownerId || "").trim();
          if (!freshOwnerId || freshOwnerId !== String(sellerId || "").trim()) {
            throw new functions.https.HttpsError("failed-precondition", "Seller does not own this garage sale.");
          }
          assertGarageShopIsOpen(freshShopProfileDoc);

          if (platformFee > 0) {
            recordPlatformRevenue(transaction, {
              source: "garageSaleFee",
              amount: platformFee,
              note: `Garage sale Stripe fee for sale ${garageSaleId}`,
              relatedUserId: String(buyerId || "").trim(),
              processor: "STRIPE",
              provider: "STRIPE",
              settlementCategory: "GARAGE_SALE",
              processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
            });
          }

          const timestamp = admin.firestore.Timestamp.now();
          transaction.set(db.collection("users").doc(String(buyerId || "").trim()).collection("transactions").doc(), {
            title: `Garage Sale Payment: ${saleTitle}`,
            amount: -roundMoney(Number(amount)),
            type: "DEBIT",
            status: "COMPLETED",
            timestamp,
            note: `Charged to your saved Stripe card. Seller: ${sellerDoc.data()?.name || "seller"}.`,
            source: "GARAGE_SALE_STRIPE",
            processor: "STRIPE",
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
            fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
          });
          transaction.set(db.collection("users").doc(String(sellerId || "").trim()).collection("transactions").doc(), {
            title: `Garage Sale Earnings: ${saleTitle}`,
            amount: sellerNet,
            type: "CREDIT",
            status: "COMPLETED",
            timestamp,
            note: sellerStaffFeeExempt ?
              `Stripe direct sale from ${buyerDoc.data()?.name || "buyer"}. Staff fee exemption applied; Stripe processing fees settle in your merchant account.` :
              `Stripe direct sale from ${buyerDoc.data()?.name || "buyer"}. Platform fee: $${platformFee.toFixed(2)}. Stripe processing fees settle in your merchant account.`,
            source: "GARAGE_SALE_STRIPE_SALE",
            processor: "STRIPE",
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
          });

          if (commercePayoutRef) {
            transaction.set(commercePayoutRef, buildCompletedCommercePayoutRequestRecord({
              amount: sellerNet,
              grossAmount: roundMoney(Number(amount)),
              currency: "USD",
              recipientId: String(sellerId || "").trim(),
              recipientName: asNonEmptyString(sellerData.name, sellerData.username) || "Seller",
              senderId: String(buyerId || "").trim(),
              source: "GARAGE_SALE_STRIPE_PAYOUT",
              type: "COMMERCE_PAYOUT",
              settlementCategory: "GARAGE_SALE",
              commerceRecordId: String(garageSaleId || "").trim(),
              processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
              timestamp,
              providerMessage: "Stripe direct garage sale completed in the seller's Stripe account.",
              stripePaymentIntentId: chargeResult.paymentIntentId,
              stripeChargeId: chargeResult.latestChargeId,
              fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
              destinationAccountId: connectedAccountId,
              stripeConnectedAccountId: chargeResult.connectedAccountId,
              platformFee,
              extraContext: {
                garageSalePaymentId: paymentId,
                garageSaleId: String(garageSaleId || "").trim(),
                garageSaleTitle: saleTitle,
                buyerId: String(buyerId || "").trim(),
                sellerId: String(sellerId || "").trim(),
              },
            }));
          }

          transaction.update(snap.ref, {
            status: "completed",
            fundingPreference: requestedFundingPreference,
            resultMessage: "Payment successful! Your card was charged through Stripe.",
            platformFee,
            sellerNet,
            ...buildLiveCommerceSettlementMetadata(settlementDecision),
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
            fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
            commercePayoutRequestId: commercePayoutRef?.id || null,
            completedAt: timestamp,
          });
        });
      } catch (settleError) {
        await refundStripeCommercePaymentIntent({
          paymentIntentId: chargeResult.paymentIntentId,
          connectedAccountId: chargeResult.connectedAccountId,
          directChargeAttemptId: `garage_sale_checkout_${paymentId}`,
          idempotencyKey: `garage_sale_checkout_refund_${paymentId}`,
          metadata: {
            flow: "GARAGE_SALE_CHECKOUT",
            garageSalePaymentId: paymentId,
            reason: "post_charge_commit_failed",
          },
        });
        throw settleError;
      }

      functions.logger.log(`Successfully processed garage sale payment: ${paymentId}`);
    } catch (error) {
      const mappedError = mapStripeCommerceChargeError(error);
      functions.logger.error(`Garage sale payment failed for ${paymentId}:`, error);
      await snap.ref.update({
        status: "failed",
        resultMessage: mappedError.message || "An unexpected error occurred. Please try again.",
        processor: activeProcessor,
        processorMode: activeProcessorMode,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
    }
    return undefined;
  });

// Sponsored ads: Firestore rules set `advertisements` create=false — publish only via this callable (Admin write).
interface PostSponsoredAdPayload {
  title?: unknown;
  description?: unknown;
  targetUrl?: unknown;
  ownerPhone?: unknown;
  mediaUrls?: unknown;
  media?: unknown;
  sponsor?: unknown;
  ownerId?: unknown;
  fundingPreference?: unknown;
}

const clampStr = (value: unknown, maxLen: number): string => {
  const raw = String(value ?? "").trim();
  if (raw.length <= maxLen) return raw;
  return raw.slice(0, maxLen);
};

type SponsoredAdFundingPreference = "STRIPE_CARD" | "AFRIEX_MOBILE_MONEY";

const normalizeSponsoredAdFundingPreference = (
  value: unknown
): SponsoredAdFundingPreference => {
  const normalized = String(value || "").trim().toUpperCase();
  // Older apps published paid ads through verified mobile money only.
  if (!normalized || normalized === "AFRIEX_MOBILE_MONEY") return "AFRIEX_MOBILE_MONEY";
  if (normalized === "STRIPE_CARD") return "STRIPE_CARD";
  throw new functions.https.HttpsError(
    "invalid-argument",
    "Select a supported sponsored-ad payment method."
  );
};

export const postSponsoredAd = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in to publish an ad.");
    }
    const uid = context.auth.uid;
    const body = (data || {}) as PostSponsoredAdPayload;
    const requestedFundingPreference = normalizeSponsoredAdFundingPreference(
      body.fundingPreference
    );
    const ownerId = clampStr(body.ownerId, 128);
    if (ownerId !== uid) {
      throw new functions.https.HttpsError("permission-denied", "ownerId must match the signed-in user.");
    }

    const title = clampStr(body.title, 180);
    const description = clampStr(body.description, 4000);
    const targetUrl = clampStr(body.targetUrl, 2000);
    if (!title || !description || !targetUrl) {
      throw new functions.https.HttpsError("invalid-argument", "title, description, and targetUrl are required.");
    }
    if (!targetUrl.toLowerCase().startsWith("https://")) {
      throw new functions.https.HttpsError("invalid-argument", "targetUrl must start with https://.");
    }

    const mediaUrlsRaw = body.mediaUrls;
    if (!Array.isArray(mediaUrlsRaw) || mediaUrlsRaw.length === 0) {
      throw new functions.https.HttpsError("invalid-argument", "At least one media URL is required.");
    }
    const mediaUrls = mediaUrlsRaw.map((u) => clampStr(u, 2000)).filter((u) => u.length > 0);
    if (mediaUrls.length === 0) {
      throw new functions.https.HttpsError("invalid-argument", "At least one media URL is required.");
    }

    const ownerPhone = clampStr(body.ownerPhone, 64);
    const sponsor = clampStr(body.sponsor, 180) || "Volunteer App Partner";

    const mediaVal = body.media;
    const media: Array<Record<string, unknown>> = Array.isArray(mediaVal) ?
      (mediaVal as unknown[]).map((row) => (typeof row === "object" && row !== null ? row as Record<string, unknown> : {})) :
      [];

    const feeSnap = await db.collection("app_config").doc("fee_settings").get();
    const feeUsd = pickAdListingFeeUsd(feeSnap);

    const userRef = db.collection("users").doc(uid);
    const adRef = db.collection("advertisements").doc();
    const adId = adRef.id;
    const userDoc = await userRef.get();
    if (!userDoc.exists) {
      throw new functions.https.HttpsError("not-found", "User profile not found.");
    }
    const userData = await withPrivateUserFields(
      uid,
      (userDoc.data() || {}) as Record<string, unknown>
    );
    const staffExempt = isStaffFeeExempt(userData, (context.auth?.token || {}) as Record<string, unknown>);

    const requiresPayment = feeUsd > 0 && !staffExempt;
    let afriexFundingMethod: AfriexCommerceFundingMethod | null = null;
    if (requiresPayment && requestedFundingPreference === "AFRIEX_MOBILE_MONEY") {
      afriexFundingMethod = await resolveReadyAfriexCommerceFundingMethodForUser(uid);
      if (!afriexFundingMethod) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Mobile money payment for this sponsored ad requires a verified mobile money method in an available collection country."
        );
      }
    }

    let stripeChargeResult: StripeCommerceChargeResult | null = null;
    try {
      if (requiresPayment && requestedFundingPreference === "STRIPE_CARD") {
        stripeChargeResult = await createStripeCardCommerceCharge({
          payerUserId: uid,
          payerUserData: userData,
          amount: feeUsd,
          currency: "USD",
          description: `Sponsored ad listing fee: ${title}`,
          metadata: {
            flow: "SPONSORED_AD",
            adId,
            ownerId: uid,
          },
          idempotencyKey: `sponsored_ad_${adId}`,
        });
      }

      await db.runTransaction(async (transaction) => {
      const freshUserDoc = await transaction.get(userRef);
      if (!freshUserDoc.exists) {
        throw new functions.https.HttpsError("not-found", "User profile not found.");
      }
      const now = admin.firestore.Timestamp.now();

      if (feeUsd > 0 && !staffExempt && afriexFundingMethod) {
        const collectionRef = db.collection("payout_requests").doc();
        transaction.set(collectionRef, {
          senderId: uid,
          amount: feeUsd,
          currency: "USD",
          phone: afriexFundingMethod.phoneNumber,
          network: afriexFundingMethod.network,
          country: afriexFundingMethod.country,
          dialCode: afriexFundingMethod.dialCode,
          localCurrency: afriexFundingMethod.currency,
          paymentMethodId: afriexFundingMethod.paymentMethodId,
          type: "CASH_IN",
          status: "PENDING",
          source: buildAfriexCommerceCollectionSource("SPONSORED"),
          fundingSource: "EXTERNAL_MOBILE_MONEY",
          fundingPreference: requestedFundingPreference,
          processor: "AFRIEX",
          collectionProcessor: "AFRIEX",
          settlementProvider: "AFRIEX",
          processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
          createdAt: now,
          processedAt: now,
          transferIntent: {
            mode: AFRIEX_COMMERCE_TRANSFER_MODE,
            settlementCategory: "SPONSORED",
            commerceTitle: title,
            adId,
            userId: uid,
            grossAmount: feeUsd,
            platformFee: feeUsd,
            requestedCurrency: "USD",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
          },
        }, {merge: true});

        transaction.set(adRef, {
          title,
          description,
          targetUrl,
          ownerPhone,
          mediaUrls,
          media,
          sponsor,
          ownerId: uid,
          fundingPreference: requestedFundingPreference,
          timestamp: now,
          isDeleted: false,
          status: "INACTIVE",
          paymentStatus: "AWAITING_COLLECTION",
          paymentProcessor: "AFRIEX",
          paymentIntentId: null,
          stripeChargeId: null,
          collectionProcessor: "AFRIEX",
          settlementProvider: "AFRIEX",
          processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
          providerRoutingStatus: "PENDING_COLLECTION",
          providerRoutingMessage: "Mobile money collection started. Approve the prompt on your phone to publish this ad.",
          providerCollectionRequestId: collectionRef.id,
          listingFeeUsd: feeUsd,
        }, {merge: true});
      } else if (requiresPayment && stripeChargeResult) {
        const txRef = userRef.collection("transactions").doc();
        transaction.set(txRef, {
          title: `Sponsored Ad Fee: ${title}`,
          amount: -feeUsd,
          type: "DEBIT",
          status: "COMPLETED",
          timestamp: now,
          note: "Charged to your saved Stripe card. Your sponsored ad is now live.",
          source: "SPONSORED_STRIPE",
          processor: "STRIPE",
          stripePaymentIntentId: stripeChargeResult.paymentIntentId,
          stripeChargeId: stripeChargeResult.latestChargeId,
          fundingPaymentMethodId: stripeChargeResult.fundingPaymentMethodDocId,
        });
        recordPlatformRevenue(transaction, {
          source: "otherIncome",
          amount: feeUsd,
          note: `Sponsored ad listing fee via Stripe for ad ${adId}`,
          relatedUserId: uid,
          processor: "STRIPE",
          provider: "STRIPE",
          settlementCategory: "SPONSORED",
          processorMode: "STRIPE_CARD_COLLECTION",
        });
        transaction.set(adRef, {
          title,
          description,
          targetUrl,
          ownerPhone,
          mediaUrls,
          media,
          sponsor,
          ownerId: uid,
          fundingPreference: requestedFundingPreference,
          timestamp: now,
          isDeleted: false,
          status: "ACTIVE",
          paymentStatus: "PAID",
          paymentProcessor: "STRIPE",
          paymentIntentId: stripeChargeResult.paymentIntentId,
          stripeChargeId: stripeChargeResult.latestChargeId,
          collectionProcessor: "STRIPE",
          settlementProvider: "STRIPE",
          processorMode: "STRIPE_CARD_COLLECTION",
          providerRoutingStatus: "COLLECTION_COMPLETED",
          providerRoutingMessage: "Card payment approved. Sponsored ad is now live.",
          listingFeeUsd: feeUsd,
          activatedAt: now,
        }, {merge: true});
      } else {
        if (feeUsd > 0 && staffExempt) {
          const txRef = userRef.collection("transactions").doc();
          transaction.set(txRef, {
            title: "Sponsored ad listing (staff exempt)",
            amount: 0,
            type: "INFO",
            status: "COMPLETED",
            timestamp: now,
            source: "SPONSORED_AD_STAFF_EXEMPT",
            note: "Listing fee waived for staff or owner role.",
          });
        }

        transaction.set(adRef, {
          title,
          description,
          targetUrl,
          ownerPhone,
          mediaUrls,
          media,
          sponsor,
          ownerId: uid,
          fundingPreference: requestedFundingPreference,
          timestamp: now,
          isDeleted: false,
          status: "ACTIVE",
          paymentStatus: feeUsd > 0 ? "WAIVED" : "NOT_REQUIRED",
          paymentProcessor: feeUsd > 0 && staffExempt ? "STAFF_EXEMPT" : null,
          paymentIntentId: null,
          stripeChargeId: null,
          listingFeeUsd: feeUsd,
        }, {merge: true});
      }
    });

      return {
        success: true,
        adId,
        sponsoredAdFeeUsd: feeUsd,
        fundingPreference: requestedFundingPreference,
        message:
          requiresPayment && requestedFundingPreference === "AFRIEX_MOBILE_MONEY" ?
            `Mobile money collection started for the ${feeUsd.toFixed(2)} USD sponsored-ad fee. Approve the prompt on your phone and the ad will go live automatically.` :
            requiresPayment && requestedFundingPreference === "STRIPE_CARD" ?
              `Card payment approved for the ${feeUsd.toFixed(2)} USD sponsored-ad fee. Your ad is now live.` :
              feeUsd > 0 && staffExempt ?
                `Ad published. Standard listing fee ${feeUsd.toFixed(2)} USD was waived for staff.` :
                "Ad published. No listing fee is configured (set adPostFeeUsd on app_config/fee_settings, or SPONSORED_AD_LISTING_FEE_USD when no doc).",
      };
    } catch (error) {
      if (stripeChargeResult) {
        await refundStripeCommercePaymentIntent({
          paymentIntentId: stripeChargeResult.paymentIntentId,
          idempotencyKey: `sponsored_ad_refund_${adId}`,
          metadata: {
            flow: "SPONSORED_AD",
            adId,
            reason: "post_charge_commit_failed",
          },
        });
      }
      throw mapStripeCommerceChargeError(error);
    }
  });


// =============================================================================
//  2B. JOKES + LIVE NOTIFICATIONS (NEW)
// =============================================================================

export const onJokePostedNotifyFollowers = functions.firestore
  .document("users/{userId}/jokes/{jokeId}")
  .onCreate(async (snap, context) => {
    const actorId = context.params.userId as string;
    const joke = snap.data();
    if (!joke) return undefined;

    const authorName = joke.authorName || "Someone";
    const preview = typeof joke.text === "string" ? joke.text.slice(0, 80) : "New post";
    const mediaType = String(joke.mediaType || joke.sourceType || "").trim().toUpperCase();
    const liveSessionId = typeof joke.sourceLiveSessionId === "string"
      ? joke.sourceLiveSessionId.trim()
      : "";
    const isLiveLinkedPost = mediaType === "LIVE_SESSION" || mediaType === "LIVE_REPLAY";

    if (isLiveLinkedPost) {
      // Never trust client-supplied live references: only the session's own host may announce it.
      if (!liveSessionId) return undefined;
      const sessionSnap = await db.collection("live_sessions").doc(liveSessionId).get();
      const session = (sessionSnap.data() || {}) as Record<string, unknown>;
      const sessionHostId = String(session.hostId || session.hostUid || "").trim();
      if (!sessionSnap.exists || sessionHostId !== actorId) {
        functions.logger.warn("Skipping follower push for a live post that does not belong to its author.", {
          actorId,
          liveSessionId,
          jokeId: context.params.jokeId,
        });
        return undefined;
      }

      if (mediaType === "LIVE_SESSION") {
        if (!isLiveSessionCurrentlyActive(session.status)) return undefined;
        // Shares the go-live lock so followers get one "is live" push per broadcast.
        if (!(await claimLiveFollowerNotification(liveSessionId))) return undefined;
        await notifyFollowers({
          actorId,
          title: `${authorName} is live on MindLoom`,
          body: preview,
          type: "liveStream",
          referenceId: liveSessionId,
          settingsField: "liveStreams",
          extraData: {
            jokeId: context.params.jokeId,
            hostId: actorId,
            sessionId: liveSessionId,
          },
        });
        return undefined;
      }

      await notifyFollowers({
        actorId,
        title: `${authorName} shared a live replay`,
        body: preview,
        type: "jokesPost",
        referenceId: context.params.jokeId,
        settingsField: "jokesPosts",
      });
      return undefined;
    }

    await notifyFollowers({
      actorId,
      title: `${authorName} posted a new joke`,
      body: preview,
      type: "jokesPost",
      referenceId: context.params.jokeId,
      settingsField: "jokesPosts",
    });

    return undefined;
  });

/** MindLoom: keep `commentsCount` authoritative — clients must not update parent joke docs for counts. */
export const onMindLoomCommentCreated = functions.firestore
  .document("users/{userId}/jokes/{jokeId}/comments/{commentId}")
  .onCreate(async (snap, context) => {
    const ownerUid = context.params.userId as string;
    const jokeId = context.params.jokeId as string;
    const parentRef = db.collection("users").doc(ownerUid).collection("jokes").doc(jokeId);
    try {
      await parentRef.update({
        commentsCount: admin.firestore.FieldValue.increment(1),
      });
    } catch (error) {
      functions.logger.warn("MindLoom commentsCount increment failed", {ownerUid, jokeId, error});
    }
    return undefined;
  });

/**
 * One-shot pagination over MindLoom posts (users/{uid}/jokes/{postId}) to set commentsCount from each comments subcollection.
 * Callable: owner or admin only. Re-run with returned nextPageToken until done is true.
 */
export const adminBackfillMindLoomCommentsCount = functions
  .runWith({enforceAppCheck: true, timeoutSeconds: 300, memory: "512MB"})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    const callerUid = context.auth.uid;
    const ownerUserId = getAppConfig().ownerUserId;
    const callerTokenRole = String(context.auth.token?.role || "").trim().toLowerCase();
    let isPrivileged =
      context.auth.token?.owner === true ||
      context.auth.token?.admin === true ||
      callerTokenRole === "owner" ||
      callerTokenRole === "admin" ||
      (ownerUserId ? callerUid === ownerUserId : false);

    if (!isPrivileged) {
      const callerSnap = await db.collection("users").doc(callerUid).get();
      const callerData = (callerSnap.data() || {}) as Record<string, unknown>;
      const callerRole = asNonEmptyString(
        callerData.role,
        callerData.userRole,
        callerData.userType
      )?.toLowerCase();
      isPrivileged =
        callerRole === "owner" ||
        callerRole === "admin" ||
        (ownerUserId ? callerUid === ownerUserId : false);
    }

    if (!isPrivileged) {
      throw new functions.https.HttpsError("permission-denied", "Owner or admin access required.");
    }

    const payload = (data || {}) as Record<string, unknown>;
    const limitRaw = Number(payload.limit ?? 40);
    const limit = Math.min(200, Math.max(1, Math.trunc(limitRaw)));
    const pageToken = typeof payload.pageToken === "string" ? payload.pageToken.trim() : "";

    let query: FirebaseFirestore.Query = db.collectionGroup("jokes")
      .orderBy("timestamp", "desc")
      .limit(limit);

    if (pageToken) {
      const cursor = await db.doc(pageToken).get();
      if (cursor.exists) {
        query = query.startAfter(cursor);
      }
    }

    const snap = await query.get();
    if (snap.empty) {
      return {
        success: true,
        examined: 0,
        updated: 0,
        skipped: 0,
        processedDocs: 0,
        nextPageToken: null,
        done: true,
        message: "No more MindLoom posts in this page range.",
      };
    }

    let examined = 0;
    let updated = 0;
    let skipped = 0;

    for (const doc of snap.docs) {
      const parts = doc.ref.path.split("/");
      if (parts.length !== 4 || parts[0] !== "users" || parts[2] !== "jokes") {
        skipped++;
        continue;
      }
      examined++;

      const jokeRef = doc.ref;
      const countSnap = await jokeRef.collection("comments").count().get();
      const trueCount = countSnap.data().count;
      const current = Math.trunc(Number((doc.data() || {}).commentsCount ?? 0));

      if (trueCount !== current) {
        await jokeRef.update({commentsCount: trueCount});
        updated++;
      }
    }

    const lastDoc = snap.docs[snap.docs.length - 1];
    const nextPageToken = lastDoc.ref.path;
    const done = snap.size < limit;

    functions.logger.log("adminBackfillMindLoomCommentsCount batch", {
      callerUid,
      examined,
      updated,
      skipped,
      processedDocs: snap.size,
      done,
    });

    return {
      success: true,
      examined,
      updated,
      skipped,
      processedDocs: snap.size,
      nextPageToken: done ? null : nextPageToken,
      done,
      message: `Processed ${snap.size} joke doc(s); updated ${updated} where counts differed.`,
    };
  });

type AgoraRecordingStatus =
  | "NOT_CONFIGURED"
  | "STARTING"
  | "RECORDING"
  | "PROCESSING"
  | "READY"
  | "FAILED";

interface AgoraRecordingFileInfo {
  fileName: string;
  trackType?: string;
  uid?: string;
  mixedAllUser?: boolean;
  isPlayable?: boolean;
  sliceStartTime?: number;
}

interface AgoraAcquireResponse {
  resourceId?: string;
  resourceid?: string;
}

interface AgoraStartResponse {
  sid?: string;
  resourceId?: string;
  resourceid?: string;
}

interface AgoraStopResponse {
  resourceId?: string;
  sid?: string;
  serverResponse?: {
    fileListMode?: string;
    fileList?: unknown;
    uploadingStatus?: string;
  };
}

const LIVE_ARCHIVE_MODE = "individual";

const buildAgoraRecordingAuthorizationHeader = (customerId: string, customerSecret: string): string => {
  const credentials = Buffer.from(`${customerId}:${customerSecret}`).toString("base64");
  return `Basic ${credentials}`;
};

const normalizeLiveArchiveStatus = (value: unknown): AgoraRecordingStatus | undefined => {
  const normalized = String(value || "").trim().toUpperCase();
  switch (normalized) {
  case "NOT_CONFIGURED":
  case "STARTING":
  case "RECORDING":
  case "PROCESSING":
  case "READY":
  case "FAILED":
    return normalized;
  default:
    return undefined;
  }
};

const buildLiveArchiveRecorderUid = (sessionId: string): string => {
  const digest = createHash("sha256").update(`live-archive:${sessionId}`).digest();
  const numericUid = (digest.readUInt32BE(0) & 0x7fffffff) || 900000001;
  return String(numericUid);
};

const sanitizeLiveArchiveObjectPath = (value: string): string => {
  return value
    .split("/")
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0)
    .join("/");
};

const buildLiveArchiveObjectPrefix = (
  config: AgoraRecordingConfig,
  sessionId: string
): {segments: string[]; joined: string} => {
  const segments = [...config.storage.fileNamePrefix, sessionId]
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0)
    .map((segment) => segment.replace(/^\/+|\/+$/g, ""));
  return {
    segments,
    joined: segments.join("/"),
  };
};

const buildLiveArchivePlaybackUrl = (baseUrl: string | undefined, objectPath: string): string | undefined => {
  const cleanBase = String(baseUrl || "").trim().replace(/\/+$/g, "");
  const cleanPath = sanitizeLiveArchiveObjectPath(objectPath);
  if (!cleanBase || !cleanPath) return undefined;
  return encodeURI(`${cleanBase}/${cleanPath}`);
};

const getLiveArchiveStorageBucketName = (): string | undefined => {
  return configuredLiveArchiveBucketName(getAgoraRecordingConfig().storage.bucket);
};

/** Buckets that received recordings under earlier configs; replays stored there must stay playable. */
const LIVE_ARCHIVE_LEGACY_BUCKETS = String(process.env.AGORA_RECORDING_LEGACY_BUCKETS ?? "agora_recording_storage_bucket")
  .split(",")
  .map((bucket) => bucket.trim())
  .filter((bucket) => bucket.length > 0);

const liveArchiveBucketCandidates = (session: Record<string, unknown>): string[] => {
  const candidates = [
    configuredLiveArchiveBucketName(session.archiveBucket),
    getLiveArchiveStorageBucketName(),
    ...LIVE_ARCHIVE_LEGACY_BUCKETS,
  ].filter((bucket): bucket is string => !!bucket);
  return Array.from(new Set(candidates));
};

/**
 * The recording bucket can change between deploys, so each replay is looked up in the
 * bucket recorded on the session first, then the configured and legacy buckets.
 */
const findLiveArchiveObjectBucket = async (
  session: Record<string, unknown>,
  objectPath: string
): Promise<{bucketName?: string; hadError: boolean}> => {
  let hadError = false;
  for (const bucketName of liveArchiveBucketCandidates(session)) {
    try {
      const [exists] = await getStorage().bucket(bucketName).file(objectPath).exists();
      if (exists) return {bucketName, hadError};
    } catch (error) {
      hadError = true;
      const details = liveReplayStorageErrorDetails(error);
      functions.logger.warn("Could not check live replay object in bucket.", {
        bucketName,
        objectPath,
        storageErrorCode: details.code,
        storageErrorMessage: details.message,
      });
    }
  }
  return {hadError};
};

/**
 * Keep replay media private. Playback is authorized and streamed by
 * `liveReplayMedia`, so archive objects must never be exposed through a
 * directly guessable Cloud Storage URL.
 */
const restrictLiveArchiveObjectsToServerAccess = async (params: {
  bucketName: string;
  objectPaths?: string[];
  objectPrefix?: string;
}): Promise<void> => {
  const bucket = getStorage().bucket(params.bucketName);
  const paths = new Set<string>();

  for (const rawPath of params.objectPaths || []) {
    const cleanPath = sanitizeLiveArchiveObjectPath(rawPath);
    if (cleanPath) paths.add(cleanPath);
  }

  const objectPrefix = sanitizeLiveArchiveObjectPath(params.objectPrefix || "");
  if (objectPrefix) {
    try {
      const [objects] = await bucket.getFiles({prefix: `${objectPrefix}/`});
      for (const object of objects) {
        const name = String(object.name || "").trim();
        if (name) paths.add(name);
      }
      if (objects.length === 0) {
        const [fallbackObjects] = await bucket.getFiles({prefix: objectPrefix});
        for (const object of fallbackObjects) {
          const name = String(object.name || "").trim();
          if (name) paths.add(name);
        }
      }
    } catch (error) {
      functions.logger.warn("Could not list live archive objects for access restriction.", {
        bucketName: params.bucketName,
        objectPrefix,
        error,
      });
    }
  }

  if (paths.size === 0) return;

  await Promise.all(
    Array.from(paths).map(async (objectPath) => {
      try {
        await bucket.file(objectPath).makePrivate();
      } catch (error) {
        functions.logger.warn("Could not restrict live archive object to server access.", {
          bucketName: params.bucketName,
          objectPath,
          error,
        });
      }
    })
  );
};

/**
 * Agora can report a file list before its backup uploader has completed the
 * transfer to GCS. A replay is only playable after its primary file exists.
 */
const findLiveArchivePrimaryFileBucket = async (
  session: Record<string, unknown>,
  primaryFile: string
): Promise<string | undefined> => {
  const objectPath = sanitizeLiveArchiveObjectPath(primaryFile);
  if (!objectPath) return undefined;
  return (await findLiveArchiveObjectBucket(session, objectPath)).bucketName;
};

const normalizeLiveArchiveFileList = (
  rawFileList: unknown,
  objectPrefix: string
): AgoraRecordingFileInfo[] => {
  const normalizeFileName = (fileName: string): string => {
    const cleanName = sanitizeLiveArchiveObjectPath(fileName);
    if (!cleanName) return "";
    if (!objectPrefix) return cleanName;
    if (cleanName.startsWith(`${objectPrefix}/`) || cleanName === objectPrefix) {
      return cleanName;
    }
    return sanitizeLiveArchiveObjectPath(`${objectPrefix}/${cleanName}`);
  };

  const mapItem = (item: unknown): AgoraRecordingFileInfo | null => {
    if (typeof item === "string") {
      const fileName = normalizeFileName(item);
      return fileName ? {fileName} : null;
    }
    if (!item || typeof item !== "object") return null;
    const data = item as Record<string, unknown>;
    const fileName = normalizeFileName(String(data.fileName || "").trim());
    if (!fileName) return null;
    return {
      fileName,
      trackType: String(data.trackType || "").trim() || undefined,
      uid: String(data.uid || "").trim() || undefined,
      mixedAllUser: typeof data.mixedAllUser === "boolean" ? data.mixedAllUser : undefined,
      isPlayable: typeof data.isPlayable === "boolean" ? data.isPlayable : undefined,
      sliceStartTime: parseOptionalNumber(data.sliceStartTime),
    };
  };

  if (Array.isArray(rawFileList)) {
    return rawFileList.map(mapItem).filter((item): item is AgoraRecordingFileInfo => item !== null);
  }

  if (typeof rawFileList === "string") {
    const trimmed = rawFileList.trim();
    if (!trimmed) return [];
    if (trimmed.startsWith("[")) {
      try {
        const parsed = JSON.parse(trimmed) as unknown[];
        return parsed.map(mapItem).filter((item): item is AgoraRecordingFileInfo => item !== null);
      } catch {
        // Fall through and treat the raw string as a single filename.
      }
    }
    const mapped = mapItem(trimmed);
    return mapped ? [mapped] : [];
  }

  return [];
};

/**
 * Server-assigned Agora uid for a Firebase user. RTC tokens are bound to it, so the host's
 * recorded track can be identified in individual-mode recordings.
 */
const stableAgoraUidFromFirebaseUid = (uid: string): number => {
  let hash = 0;
  for (let index = 0; index < uid.length; index += 1) {
    hash = (Math.imul(hash, 31) + uid.charCodeAt(index)) | 0;
  }
  if (hash === -2147483648) return 1;
  return Math.max(Math.abs(hash), 1);
};

const pickPrimaryLiveArchiveFile = (
  files: AgoraRecordingFileInfo[],
  hostFirebaseUid?: string
): AgoraRecordingFileInfo | undefined => {
  const isPreferredPlayableFile = (file: AgoraRecordingFileInfo): boolean => {
    const lowerName = file.fileName.toLowerCase();
    return lowerName.endsWith(".m3u8") || lowerName.endsWith(".mp4");
  };

  // With stage guests, individual mode records one file per participant; the replay should be the host's.
  const hostAgoraUid = hostFirebaseUid ? String(stableAgoraUidFromFirebaseUid(hostFirebaseUid)) : "";
  const hostFile = hostAgoraUid ? files.find((file) =>
    file.uid === hostAgoraUid &&
    file.isPlayable !== false &&
    (file.trackType === undefined || file.trackType === "audio_and_video") &&
    isPreferredPlayableFile(file)
  ) : undefined;
  if (hostFile) return hostFile;

  return files.find((file) =>
    file.isPlayable === true &&
    (file.trackType === "audio_and_video" || file.mixedAllUser === true) &&
    isPreferredPlayableFile(file)
  ) ?? files.find((file) =>
    file.isPlayable === true && isPreferredPlayableFile(file)
  ) ?? files.find((file) =>
    isPreferredPlayableFile(file)
  ) ?? files[0];
};

const extractAgoraRecordingErrorMessage = (error: unknown, fallback: string): string => {
  if (axios.isAxiosError(error)) {
    const responseData = error.response?.data as Record<string, unknown> | undefined;
    const serverMessage = responseData && (
      String(responseData.message || "").trim() ||
      String(responseData.reason || "").trim() ||
      String(responseData.serverResponse || "").trim()
    );
    if (serverMessage) return serverMessage;
    if (error.code === "ECONNABORTED") return "The recording service timed out.";
    if (typeof error.message === "string" && error.message.trim()) return error.message.trim();
  }
  if (error instanceof Error && error.message.trim()) return error.message.trim();
  return fallback;
};

const callAgoraRecordingApi = async <T>(
  path: string,
  body: Record<string, unknown>,
  config: AgoraRecordingConfig,
  timeoutMs = 30000
): Promise<T> => {
  if (!config.customerId || !config.customerSecret) {
    throw new Error("Agora recording customer credentials are not configured.");
  }
  const agoraConfig = getAgoraConfig();
  if (!agoraConfig.appId) {
    throw new Error("Agora App ID is not configured for recording.");
  }

  const url = `https://api.agora.io/v1/apps/${agoraConfig.appId}/cloud_recording${path}`;
  const response = await axios.post(url, body, {
    timeout: timeoutMs,
    headers: {
      Authorization: buildAgoraRecordingAuthorizationHeader(config.customerId, config.customerSecret),
      "Content-Type": "application/json;charset=utf-8",
    },
  });
  return response.data as T;
};

const buildLiveArchiveStorageConfig = (
  config: AgoraRecordingConfig,
  sessionId: string
): {storageConfig?: Record<string, unknown>; objectPrefix: string} => {
  const objectPrefix = buildLiveArchiveObjectPrefix(config, sessionId);
  const storage = config.storage;
  if (
    storage.vendor === undefined ||
    storage.region === undefined ||
    !storage.bucket ||
    !storage.accessKey ||
    !storage.secretKey
  ) {
    return {objectPrefix: objectPrefix.joined};
  }

  return {
    objectPrefix: objectPrefix.joined,
    storageConfig: {
      vendor: storage.vendor,
      region: storage.region,
      bucket: storage.bucket,
      accessKey: storage.accessKey,
      secretKey: storage.secretKey,
      fileNamePrefix: objectPrefix.segments,
    },
  };
};

const updateLiveArchiveFields = async (
  sessionRef: FirebaseFirestore.DocumentReference,
  patch: Record<string, unknown>
): Promise<void> => {
  await sessionRef.set(patch, {merge: true});
};

const LIVE_ARCHIVE_TERMINAL_STATUSES: AgoraRecordingStatus[] = [
  "NOT_CONFIGURED",
  "FAILED",
  "READY",
];
/** The recorder leaves the channel when its token expires, so it must outlast any broadcast (Agora caps at 24h). */
const LIVE_ARCHIVE_RECORDER_TOKEN_TTL_SECONDS = 24 * 60 * 60;
const LIVE_ARCHIVE_ENDED_BEFORE_START_MESSAGE = "Live ended before replay recording finished starting on the server.";
const LIVE_ARCHIVE_PENDING_UPLOAD_MESSAGE =
  "Replay files are still being prepared. Playback will be enabled automatically when the upload completes.";
const LIVE_ARCHIVE_ENDED_SESSION_STATUSES = ["ended", "completed", "closed"];
const LIVE_ARCHIVE_STOP_METADATA_WAIT_ATTEMPTS = 25;
const LIVE_ARCHIVE_STOP_METADATA_WAIT_MS = 3000;
const LIVE_ARCHIVE_PROCESSING_TIMEOUT_MS = Math.max(
  10 * 60 * 1000,
  parseOptionalNumber(process.env.LIVE_ARCHIVE_PROCESSING_TIMEOUT_MS) ?? 45 * 60 * 1000
);

const liveArchiveProcessingStartedAtMs = (session: Record<string, unknown>): number => {
  const candidates = [
    session.archiveStoppedAt,
    session.endedAt,
    session.archiveStartedAt,
    session.updatedAt,
    session.createdAt,
  ];
  for (const value of candidates) {
    if (value && typeof (value as admin.firestore.Timestamp).toMillis === "function") {
      return (value as admin.firestore.Timestamp).toMillis();
    }
  }
  return 0;
};

const liveArchiveProcessingHasExpired = (session: Record<string, unknown>): boolean => {
  const startedAtMs = liveArchiveProcessingStartedAtMs(session);
  return startedAtMs > 0 && Date.now() - startedAtMs >= LIVE_ARCHIVE_PROCESSING_TIMEOUT_MS;
};

const liveArchiveProcessingTimedOutMessage =
  "The replay recording has not reached storage yet. It will appear automatically if it arrives in the next few days.";
/** Earlier wording still stored on timed-out sessions; kept so the recovery query matches them. */
const liveArchiveProcessingTimedOutMessages = [
  liveArchiveProcessingTimedOutMessage,
  "Replay recording did not reach secure storage in time. This broadcast cannot be replayed; start a new live stream to record another replay.",
];

/** Agora keeps retrying `backuped` uploads, so timed-out replays are re-checked for this long. */
const LIVE_ARCHIVE_LATE_UPLOAD_RECOVERY_MS = 7 * 24 * 60 * 60 * 1000;

interface LiveArchiveStopMetadata {
  archiveStatus?: AgoraRecordingStatus;
  channelName: string;
  resourceId: string;
  sid: string;
  recorderUid: string;
  objectPrefix: string;
}

const delayMs = (ms: number): Promise<void> => new Promise((resolve) => {
  setTimeout(resolve, ms);
});

const buildLiveArchiveStopMetadata = (
  data: Record<string, unknown>,
  snapshotData: Record<string, unknown>,
  recordingConfig: AgoraRecordingConfig,
  sessionId: string
): LiveArchiveStopMetadata => {
  return {
    archiveStatus: normalizeLiveArchiveStatus(data.archiveStatus),
    channelName: String(
      data.agoraChannelName ||
      data.channelName ||
      snapshotData.agoraChannelName ||
      snapshotData.channelName ||
      ""
    ).trim(),
    resourceId: String(data.archiveResourceId || "").trim(),
    sid: String(data.archiveSid || "").trim(),
    recorderUid: String(
      data.archiveRecorderUid ||
      buildLiveArchiveRecorderUid(sessionId)
    ).trim(),
    objectPrefix: String(data.archiveObjectPrefix || "").trim() ||
      buildLiveArchiveObjectPrefix(recordingConfig, sessionId).joined,
  };
};

const hasLiveArchiveRecorderMetadata = (metadata: LiveArchiveStopMetadata): boolean => {
  return Boolean(
    metadata.channelName &&
    metadata.resourceId &&
    metadata.sid &&
    metadata.recorderUid
  );
};

const waitForLiveArchiveStopMetadata = async (
  sessionRef: FirebaseFirestore.DocumentReference,
  sessionId: string,
  snapshotData: Record<string, unknown>,
  recordingConfig: AgoraRecordingConfig
): Promise<LiveArchiveStopMetadata> => {
  let latestData = {} as Record<string, unknown>;
  let metadata = buildLiveArchiveStopMetadata(latestData, snapshotData, recordingConfig, sessionId);

  for (let attempt = 0; attempt <= LIVE_ARCHIVE_STOP_METADATA_WAIT_ATTEMPTS; attempt += 1) {
    const latestSnapshot = await sessionRef.get();
    if (!latestSnapshot.exists) {
      return metadata;
    }

    latestData = (latestSnapshot.data() || {}) as Record<string, unknown>;
    metadata = buildLiveArchiveStopMetadata(latestData, snapshotData, recordingConfig, sessionId);

    if (
      hasLiveArchiveRecorderMetadata(metadata) ||
      (metadata.archiveStatus && LIVE_ARCHIVE_TERMINAL_STATUSES.includes(metadata.archiveStatus))
    ) {
      return metadata;
    }

    if (attempt < LIVE_ARCHIVE_STOP_METADATA_WAIT_ATTEMPTS) {
      await delayMs(LIVE_ARCHIVE_STOP_METADATA_WAIT_MS);
    }
  }

  return metadata;
};

const startLiveArchiveRecording = async (
  sessionId: string,
  snapshotData: Record<string, unknown>
): Promise<void> => {
  const sessionRef = db.collection("live_sessions").doc(sessionId);
  const latestSnapshot = await sessionRef.get();
  if (!latestSnapshot.exists) return;
  const latestData = (latestSnapshot.data() || {}) as Record<string, unknown>;
  const status = String(latestData.status || snapshotData.status || "").trim().toLowerCase();
  if (!["live", "active", "started"].includes(status)) return;

  const currentArchiveStatus = normalizeLiveArchiveStatus(latestData.archiveStatus);
  if (currentArchiveStatus && ["STARTING", "RECORDING", "PROCESSING", "READY"].includes(currentArchiveStatus)) {
    return;
  }

  const recordingConfig = getAgoraRecordingConfig();
  const agoraConfig = getAgoraConfig();
  const channelName = String(
    latestData.agoraChannelName ||
    latestData.channelName ||
    snapshotData.agoraChannelName ||
    snapshotData.channelName ||
    ""
  ).trim();
  if (!channelName) {
    await updateLiveArchiveFields(sessionRef, {
      archiveStatus: "FAILED",
      archiveError: "Live channel name is missing for archive recording.",
    });
    return;
  }
  const archiveHostId = String(latestData.hostId || latestData.hostUid || "").trim();
  if (!isLiveChannelOwnedByHost(channelName, archiveHostId)) {
    await updateLiveArchiveFields(sessionRef, {
      archiveStatus: "FAILED",
      archiveError: "Live channel does not belong to this host.",
    });
    return;
  }

  const storage = buildLiveArchiveStorageConfig(recordingConfig, sessionId);
  functions.logger.info("Live archive start configuration", {
    sessionId,
    recordingEnabled: recordingConfig.enabled,
    hasRecordingCustomerId: !!recordingConfig.customerId,
    hasRecordingCustomerSecret: !!recordingConfig.customerSecret,
    hasAgoraAppId: !!agoraConfig.appId,
    hasAgoraAppCertificate: !!agoraConfig.appCertificate,
    hasStorageConfig: !!storage.storageConfig,
  });
  if (
    !recordingConfig.enabled ||
    !recordingConfig.customerId ||
    !recordingConfig.customerSecret ||
    !agoraConfig.appId ||
    !agoraConfig.appCertificate ||
    !storage.storageConfig
  ) {
    const archiveError = buildAgoraRecordingNotConfiguredMessage(
      recordingConfig,
      agoraConfig,
      !!storage.storageConfig
    );
    await updateLiveArchiveFields(sessionRef, {
      archiveStatus: "NOT_CONFIGURED",
      archiveError,
    });
    functions.logger.warn("Live archive recording is not configured", {sessionId, archiveError});
    return;
  }

  const recorderUid = buildLiveArchiveRecorderUid(sessionId);
  await updateLiveArchiveFields(sessionRef, {
    archiveStatus: "STARTING",
    archiveError: admin.firestore.FieldValue.delete(),
    archiveRecorderUid: recorderUid,
    archiveObjectPrefix: storage.objectPrefix,
    archiveBucket: recordingConfig.storage.bucket,
  });

  let finalizeAfterStart: Record<string, unknown> | undefined;
  try {
    const acquireResponse = await callAgoraRecordingApi<AgoraAcquireResponse>(
      "/acquire",
      {
        cname: channelName,
        uid: recorderUid,
        clientRequest: {
          resourceExpiredHour: recordingConfig.resourceExpiredHours,
          scene: 0,
        },
      },
      recordingConfig
    );

    const resourceId = String(acquireResponse.resourceId || acquireResponse.resourceid || "").trim();
    if (!resourceId) {
      throw new Error("Agora did not return a resource ID for archive recording.");
    }

    const rtcToken = RtcTokenBuilder.buildTokenWithUid(
      agoraConfig.appId,
      agoraConfig.appCertificate,
      channelName,
      Number.parseInt(recorderUid, 10),
      RtcRole.SUBSCRIBER,
      Math.max(agoraConfig.ttlSeconds, LIVE_ARCHIVE_RECORDER_TOKEN_TTL_SECONDS),
      Math.max(agoraConfig.ttlSeconds, LIVE_ARCHIVE_RECORDER_TOKEN_TTL_SECONDS)
    );

    const startResponse = await callAgoraRecordingApi<AgoraStartResponse>(
      `/resourceid/${resourceId}/mode/${LIVE_ARCHIVE_MODE}/start`,
      {
        cname: channelName,
        uid: recorderUid,
        clientRequest: {
          token: rtcToken,
          recordingConfig: {
            maxIdleTime: recordingConfig.maxIdleTimeSeconds,
            streamTypes: 2,
            streamMode: "standard",
            channelType: 1,
            videoStreamType: 0,
            subscribeUidGroup: 0,
          },
          storageConfig: storage.storageConfig,
        },
      },
      recordingConfig,
      45000
    );

    const sid = String(startResponse.sid || "").trim();
    if (!sid) {
      throw new Error("Agora did not return a recording SID.");
    }

    // The end-of-live trigger may have run while Agora was starting; never overwrite a later state.
    const claim = await db.runTransaction(async (transaction) => {
      const current = await transaction.get(sessionRef);
      const currentData = (current.data() || {}) as Record<string, unknown>;
      if (!current.exists) return {recorded: false, ended: false, data: currentData};
      const currentArchiveStatus = normalizeLiveArchiveStatus(currentData.archiveStatus);
      const endedBeforeStart = currentArchiveStatus === "FAILED" &&
        String(currentData.archiveError || "").trim() === LIVE_ARCHIVE_ENDED_BEFORE_START_MESSAGE;
      if (currentArchiveStatus !== "STARTING" && !endedBeforeStart) {
        return {recorded: false, ended: false, data: currentData};
      }
      transaction.set(sessionRef, {
        archiveStatus: "RECORDING",
        archiveResourceId: resourceId,
        archiveSid: sid,
        archiveRecorderUid: recorderUid,
        archiveObjectPrefix: storage.objectPrefix,
        archiveStartedAt: admin.firestore.FieldValue.serverTimestamp(),
        archiveStoppedAt: admin.firestore.FieldValue.delete(),
        archiveError: admin.firestore.FieldValue.delete(),
      }, {merge: true});
      const liveStatus = String(currentData.status || "").trim().toLowerCase();
      return {
        recorded: true,
        ended: LIVE_ARCHIVE_ENDED_SESSION_STATUSES.includes(liveStatus),
        data: {
          ...currentData,
          archiveStatus: "RECORDING",
          archiveResourceId: resourceId,
          archiveSid: sid,
          archiveRecorderUid: recorderUid,
          archiveObjectPrefix: storage.objectPrefix,
        } as Record<string, unknown>,
      };
    });

    if (!claim.recorded) {
      functions.logger.warn("Live archive start was superseded; stopping the untracked recorder.", {sessionId});
      await callAgoraRecordingApi(
        `/resourceid/${resourceId}/sid/${sid}/mode/${LIVE_ARCHIVE_MODE}/stop`,
        {cname: channelName, uid: recorderUid, clientRequest: {async_stop: true}},
        recordingConfig
      ).catch((stopError) => {
        functions.logger.warn("Could not stop superseded live archive recorder.", {
          sessionId,
          message: extractAgoraRecordingErrorMessage(stopError, "Stop failed."),
        });
      });
      return;
    }
    functions.logger.info("Live archive recording started", {sessionId});
    if (claim.ended) finalizeAfterStart = claim.data;
  } catch (error) {
    const message = extractAgoraRecordingErrorMessage(
      error,
      "Could not start live replay recording."
    );
    functions.logger.error("Failed to start live archive recording", {
      sessionId,
      message,
    });
    await updateLiveArchiveFields(sessionRef, {
      archiveStatus: "FAILED",
      archiveError: message,
    });
  }

  if (finalizeAfterStart) {
    functions.logger.info("Live ended while the recorder was starting; finalizing the replay now.", {sessionId});
    await stopLiveArchiveRecording(sessionId, finalizeAfterStart);
  }
};

/**
 * A MindLoom live post is a durable reference to the session, never a stored
 * browser bearer token. Once the archive is ready, the same post becomes a
 * replay so viewers mint fresh playback access when they open it.
 */
const promoteMindLoomLivePostToReplay = async (
  sessionId: string,
  session: Record<string, unknown>
): Promise<void> => {
  const hostId = String(session.hostId || session.hostUid || "").trim();
  if (!hostId) return;

  const postsSnap = await db.collection("users")
    .doc(hostId)
    .collection("jokes")
    .where("sourceLiveSessionId", "==", sessionId)
    .limit(450)
    .get();
  if (postsSnap.empty) return;

  // The caller's snapshot can predate a slow recording stop; visibility may have changed meanwhile.
  const freshSnap = await db.collection("live_sessions").doc(sessionId).get();
  const freshSession = freshSnap.exists ? (freshSnap.data() || {}) as Record<string, unknown> : session;
  const replayVisibility = normalizeLiveReplayVisibility(freshSession.replayVisibility);
  const title = String(freshSession.title || session.title || "").trim();
  const canonicalShareUrl = `${buildLiveShareBaseUrl()}?sessionId=${encodeURIComponent(sessionId)}` +
    `&hostId=${encodeURIComponent(hostId)}`;
  const batch = db.batch();
  for (const post of postsSnap.docs) {
    const postData = post.data() || {};
    const sourceType = String(postData.sourceType || postData.mediaType || "")
      .trim()
      .toUpperCase();
    if (sourceType !== "LIVE_SESSION") continue;

    batch.set(post.ref, {
      mediaType: "LIVE_REPLAY",
      sourceType: "LIVE_REPLAY",
      sourceReplayVisibility: replayVisibility,
      ...(title ? {text: `Replay: ${title}`} : {}),
      // Replace legacy, expiring browser invitations with the canonical link.
      sourceLiveShareUrl: canonicalShareUrl,
    }, {merge: true});
  }
  await batch.commit();
};

/** Removes the app-owned archive objects without exposing storage credentials to clients. */
const deleteLiveArchiveObjects = async (
  sessionId: string,
  session: Record<string, unknown>
): Promise<void> => {
  const bucketNames = liveArchiveBucketCandidates(session);
  if (bucketNames.length === 0) return;

  const recordingConfig = getAgoraRecordingConfig();
  const expectedPrefix = buildLiveArchiveObjectPrefix(recordingConfig, sessionId).joined;
  const storedPrefix = sanitizeLiveArchiveObjectPath(String(session.archiveObjectPrefix || ""));
  const objectPrefix = storedPrefix.split("/").includes(sessionId)
    ? storedPrefix
    : expectedPrefix;
  if (!objectPrefix) return;

  for (const bucketName of bucketNames) {
    try {
      await getStorage().bucket(bucketName).deleteFiles({
        prefix: `${objectPrefix}/`,
        force: true,
      });
    } catch (error) {
      // App access is removed below even if an external storage provider is down.
      // Retain an operator-visible log so its private objects can be cleaned up.
      functions.logger.warn("Could not remove live archive objects during broadcast deletion.", {
        sessionId,
        bucketName,
        objectPrefix,
        error,
      });
    }
  }
};

const deleteMindLoomPostsForLiveSession = async (
  hostId: string,
  sessionId: string
): Promise<number> => {
  const postsSnap = await db.collection("users")
    .doc(hostId)
    .collection("jokes")
    .where("sourceLiveSessionId", "==", sessionId)
    .get();
  if (postsSnap.empty) return 0;

  // recursiveDelete also removes each post's comments subcollection, which a plain delete would orphan.
  for (const post of postsSnap.docs) {
    await db.recursiveDelete(post.ref);
  }
  return postsSnap.size;
};

/** Keeps MindLoom replay cards in sync when the host changes who can watch the replay. */
export const onLiveReplayVisibilityChangedSyncPosts = functions.firestore
  .document("live_sessions/{sessionId}")
  .onUpdate(async (change, context) => {
    const before = (change.before.data() || {}) as Record<string, unknown>;
    const after = (change.after.data() || {}) as Record<string, unknown>;
    const beforeVisibility = normalizeLiveReplayVisibility(before.replayVisibility);
    const afterVisibility = normalizeLiveReplayVisibility(after.replayVisibility);
    if (beforeVisibility === afterVisibility) return undefined;

    const hostId = String(after.hostId || after.hostUid || "").trim();
    if (!hostId) return undefined;
    const postsSnap = await db.collection("users")
      .doc(hostId)
      .collection("jokes")
      .where("sourceLiveSessionId", "==", context.params.sessionId)
      .limit(450)
      .get();
    if (postsSnap.empty) return undefined;

    const batch = db.batch();
    for (const post of postsSnap.docs) {
      batch.set(post.ref, {sourceReplayVisibility: afterVisibility}, {merge: true});
    }
    await batch.commit();
    return undefined;
  });

/**
 * Hosts delete only completed broadcasts. The server removes all private
 * subcollections, preventing a client-side delete from leaving live data behind.
 */
export const deleteLiveBroadcast = functions.runWith({
  enforceAppCheck: true,
  timeoutSeconds: 540,
  memory: "1GB",
}).https.onCall(async (data, context) => {
  const hostId = String(context.auth?.uid || "").trim();
  if (!hostId) {
    throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
  }

  const sessionId = String((data as Record<string, unknown> | undefined)?.sessionId || "").trim();
  if (!sessionId) {
    throw new functions.https.HttpsError("invalid-argument", "Live session id is required.");
  }

  const sessionRef = db.collection("live_sessions").doc(sessionId);
  const sessionSnap = await sessionRef.get();
  if (!sessionSnap.exists) {
    throw new functions.https.HttpsError("not-found", "This broadcast no longer exists.");
  }

  const session = (sessionSnap.data() || {}) as Record<string, unknown>;
  const sessionHostId = String(session.hostId || session.hostUid || "").trim();
  if (!sessionHostId || sessionHostId !== hostId) {
    throw new functions.https.HttpsError("permission-denied", "Only the broadcaster can delete this broadcast.");
  }

  const liveStatus = String(session.status || "").trim().toLowerCase();
  if (["live", "active", "started"].includes(liveStatus)) {
    throw new functions.https.HttpsError("failed-precondition", "End the live stream before deleting it.");
  }

  const archiveStatus = normalizeLiveArchiveStatus(session.archiveStatus);
  if (archiveStatus && !LIVE_ARCHIVE_TERMINAL_STATUSES.includes(archiveStatus)) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Replay processing is still in progress. Wait for it to finish before deleting the broadcast."
    );
  }

  await deleteLiveArchiveObjects(sessionId, session);
  const deletedMindLoomPostCount = await deleteMindLoomPostsForLiveSession(sessionHostId, sessionId);
  await db.recursiveDelete(sessionRef);

  functions.logger.info("Live broadcast deleted by host", {
    sessionId,
    hostId,
    archiveStatus: archiveStatus || null,
    deletedMindLoomPostCount,
  });
  return {success: true, deletedMindLoomPostCount};
});

const stopLiveArchiveRecording = async (
  sessionId: string,
  snapshotData: Record<string, unknown>
): Promise<void> => {
  const recordingConfig = getAgoraRecordingConfig();
  const sessionRef = db.collection("live_sessions").doc(sessionId);
  const latestSnapshot = await sessionRef.get();
  if (!latestSnapshot.exists) return;
  let latestData = (latestSnapshot.data() || {}) as Record<string, unknown>;
  let metadata = buildLiveArchiveStopMetadata(latestData, snapshotData, recordingConfig, sessionId);

  if (metadata.archiveStatus && LIVE_ARCHIVE_TERMINAL_STATUSES.includes(metadata.archiveStatus)) {
    functions.logger.info("Live archive already reached a terminal state", {
      sessionId,
      archiveStatus: metadata.archiveStatus,
    });
    return;
  }

  if (!hasLiveArchiveRecorderMetadata(metadata) &&
    (metadata.archiveStatus === "STARTING" || metadata.archiveStatus === undefined)) {
    metadata = await waitForLiveArchiveStopMetadata(sessionRef, sessionId, snapshotData, recordingConfig);
  }

  if (metadata.archiveStatus && LIVE_ARCHIVE_TERMINAL_STATUSES.includes(metadata.archiveStatus)) {
    functions.logger.info("Live archive reached a terminal state while waiting to stop", {
      sessionId,
      archiveStatus: metadata.archiveStatus,
    });
    return;
  }

  const {channelName, resourceId, sid, recorderUid, objectPrefix} = metadata;

  if (!channelName || !resourceId || !sid || !recorderUid || !recordingConfig.customerId || !recordingConfig.customerSecret) {
    const archiveError = metadata.archiveStatus === "STARTING" || metadata.archiveStatus === undefined ?
      LIVE_ARCHIVE_ENDED_BEFORE_START_MESSAGE :
      "Live replay recording could not be finalized because recorder metadata was missing.";
    functions.logger.warn("Live archive stop skipped because recorder metadata was incomplete.", {
      sessionId,
      archiveStatus: metadata.archiveStatus || null,
      hasChannelName: !!channelName,
      hasResourceId: !!resourceId,
      hasSid: !!sid,
      hasRecorderUid: !!recorderUid,
      hasCustomerId: !!recordingConfig.customerId,
      hasCustomerSecret: !!recordingConfig.customerSecret,
    });
    const canStopRecorder = !!recordingConfig.customerId && !!recordingConfig.customerSecret;
    const recorderStartedMeanwhile = await db.runTransaction(async (transaction) => {
      const current = await transaction.get(sessionRef);
      if (!current.exists) return false;
      const currentData = (current.data() || {}) as Record<string, unknown>;
      const currentMetadata = buildLiveArchiveStopMetadata(currentData, snapshotData, recordingConfig, sessionId);
      if (canStopRecorder && currentMetadata.archiveStatus === "RECORDING" &&
        hasLiveArchiveRecorderMetadata(currentMetadata)) {
        return true;
      }
      transaction.set(sessionRef, {
        archiveStatus: "FAILED",
        archiveStoppedAt: admin.firestore.FieldValue.serverTimestamp(),
        archiveError,
      }, {merge: true});
      return false;
    });
    if (recorderStartedMeanwhile) {
      await stopLiveArchiveRecording(sessionId, snapshotData);
    }
    return;
  }

  // The end-of-live trigger and the reconciler can both reach this point; only one may stop the recorder.
  const claimedStop = await db.runTransaction(async (transaction) => {
    const current = await transaction.get(sessionRef);
    if (!current.exists) return false;
    const currentStatus = normalizeLiveArchiveStatus((current.data() || {}).archiveStatus);
    if (currentStatus !== "RECORDING" && currentStatus !== "STARTING") return false;
    transaction.set(sessionRef, {
      archiveStatus: "PROCESSING",
      archiveStoppedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, {merge: true});
    return true;
  });
  if (!claimedStop) {
    functions.logger.info("Live archive stop is already being handled", {sessionId});
    return;
  }

  try {
    const stopResponse = await callAgoraRecordingApi<AgoraStopResponse>(
      `/resourceid/${resourceId}/sid/${sid}/mode/${LIVE_ARCHIVE_MODE}/stop`,
      {
        cname: channelName,
        uid: recorderUid,
        clientRequest: {
          async_stop: false,
        },
      },
      recordingConfig,
      180000
    );

    const serverResponse = stopResponse.serverResponse || {};
    const uploadStatus = String(serverResponse.uploadingStatus || "").trim();
    const files = normalizeLiveArchiveFileList(serverResponse.fileList, objectPrefix);
    const primaryFile = pickPrimaryLiveArchiveFile(
      files,
      String(snapshotData.hostId || snapshotData.hostUid || "").trim() || undefined
    );
    const archivePlaybackUrl = primaryFile ?
      buildLiveArchivePlaybackUrl(recordingConfig.playbackBaseUrl, primaryFile.fileName) :
      undefined;

    const primaryFileBucket = primaryFile ?
      await findLiveArchivePrimaryFileBucket(latestData, primaryFile.fileName) :
      undefined;
    const replayReady = files.length > 0 && !!primaryFile && !!primaryFileBucket;
    const replayPendingMessage = uploadStatus.toLowerCase() === "backuped" ?
      "Replay files are still transferring to secure storage. Playback will be enabled automatically when the upload completes." :
      LIVE_ARCHIVE_PENDING_UPLOAD_MESSAGE;

    await updateLiveArchiveFields(sessionRef, {
      archiveStatus: replayReady ? "READY" : "PROCESSING",
      archiveUploadStatus: uploadStatus || admin.firestore.FieldValue.delete(),
      archivePrimaryFile: primaryFile?.fileName || admin.firestore.FieldValue.delete(),
      archiveFileCount: files.length,
      ...(primaryFileBucket ? {archiveBucket: primaryFileBucket} : {}),
      archiveReadyAt: replayReady ? admin.firestore.FieldValue.serverTimestamp() : admin.firestore.FieldValue.delete(),
      archiveError: replayReady ? admin.firestore.FieldValue.delete() : replayPendingMessage,
    });
    functions.logger.info("Live archive finalization result", {
      sessionId,
      uploadStatus: uploadStatus || null,
      archiveFileCount: files.length,
      hasPrimaryFile: !!primaryFile,
      replayReady,
    });
    await persistLiveArchivePlaybackUrl(sessionId, replayReady ? archivePlaybackUrl : undefined);
    if (replayReady) {
      try {
        await promoteMindLoomLivePostToReplay(sessionId, latestData);
      } catch (error) {
        functions.logger.error("Could not promote MindLoom live post to replay", {sessionId, error});
      }
    }
    if (replayReady && primaryFileBucket) {
      await restrictLiveArchiveObjectsToServerAccess({
        bucketName: primaryFileBucket,
        objectPaths: files.map((file) => file.fileName),
        objectPrefix,
      });
    }
  } catch (error) {
    const message = extractAgoraRecordingErrorMessage(
      error,
      "Could not finalize the live replay archive."
    );
    functions.logger.error("Failed to stop live archive recording", {
      sessionId,
      message,
    });
    const agoraErrorCode = axios.isAxiosError(error) ?
      Number((error.response?.data as Record<string, unknown> | undefined)?.code) :
      Number.NaN;
    // Agora 435: nothing was recorded because no one published media.
    if (agoraErrorCode === 435) {
      await updateLiveArchiveFields(sessionRef, {
        archiveStatus: "FAILED",
        archiveError: "No video was published during this broadcast, so there is no replay.",
      });
      return;
    }
    // The recorder can stop on its own (idle timeout) and still upload; reconciliation finds the files in storage.
    await updateLiveArchiveFields(sessionRef, {
      archiveStatus: "PROCESSING",
      archiveError: LIVE_ARCHIVE_PENDING_UPLOAD_MESSAGE,
    });
  }
};

/**
 * A blocked user's RTC token stays valid until it expires, so a modified client could keep
 * watching or publishing. Agora's kicking rule removes them from the channel right away.
 */
export const onLiveViewerBlockedKickFromChannel = functions.firestore
  .document("live_sessions/{sessionId}/blocked_users/{blockedUid}")
  .onCreate(async (_snapshot, context) => {
    const sessionId = String(context.params.sessionId || "").trim();
    const blockedUid = String(context.params.blockedUid || "").trim();
    if (!sessionId || !blockedUid) return;

    const sessionSnap = await db.collection("live_sessions").doc(sessionId).get();
    if (!sessionSnap.exists) return;
    const session = (sessionSnap.data() || {}) as Record<string, unknown>;
    const status = String(session.status || "").trim().toLowerCase();
    if (!["live", "active", "started"].includes(status)) return;

    const hostId = String(session.hostId || session.hostUid || "").trim();
    const channelName = String(session.agoraChannelName || session.channelName || "").trim();
    if (blockedUid === hostId || !isLiveChannelOwnedByHost(channelName, hostId)) return;

    const recordingConfig = getAgoraRecordingConfig();
    const {appId, ttlSeconds} = getAgoraConfig();
    if (!appId || !recordingConfig.customerId || !recordingConfig.customerSecret) {
      functions.logger.warn("Agora REST credentials missing; blocked live viewer was not kicked.", {sessionId});
      return;
    }

    try {
      await axios.post(
        "https://api.agora.io/dev/v1/kicking-rule",
        {
          appid: appId,
          cname: channelName,
          uid: stableAgoraUidFromFirebaseUid(blockedUid),
          // Outlasts any token already issued; new tokens are refused by the block check.
          time: Math.min(1440, Math.max(1, Math.ceil(ttlSeconds / 60))),
          privileges: ["join_channel"],
        },
        {
          timeout: 15000,
          headers: {
            Authorization: buildAgoraRecordingAuthorizationHeader(
              recordingConfig.customerId,
              recordingConfig.customerSecret
            ),
            "Content-Type": "application/json;charset=utf-8",
          },
        }
      );
    } catch (error) {
      functions.logger.warn("Failed to kick blocked live viewer from Agora channel.", {
        sessionId,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  });

export const onLiveSessionCreatedStartArchive = functions.runWith({
  timeoutSeconds: 540,
  memory: "512MB",
}).firestore
  .document("live_sessions/{sessionId}")
  .onCreate(async (snapshot, context) => {
    const data = (snapshot.data() || {}) as Record<string, unknown>;
    await startLiveArchiveRecording(context.params.sessionId, data);
    return undefined;
  });

export const onLiveSessionEndedFinalizeArchive = functions.runWith({
  timeoutSeconds: 540,
  memory: "1GB",
}).firestore
  .document("live_sessions/{sessionId}")
  .onUpdate(async (change, context) => {
    const before = (change.before.data() || {}) as Record<string, unknown>;
    const after = (change.after.data() || {}) as Record<string, unknown>;
    const beforeStatus = String(before.status || "").trim().toLowerCase();
    const afterStatus = String(after.status || "").trim().toLowerCase();
    const wasEnded = ["ended", "completed", "closed"].includes(beforeStatus);
    const isEnded = ["ended", "completed", "closed"].includes(afterStatus);
    if (!isEnded || wasEnded) return undefined;

    await stopLiveArchiveRecording(context.params.sessionId, after);
    return undefined;
  });

/**
 * Agora retries files marked `backuped` after the stop call. Promote only
 * archives whose actual primary file has reached our private storage bucket.
 */
const LIVE_ARCHIVE_STUCK_RECORDER_GRACE_MS = 3 * 60 * 1000;
const LIVE_ARCHIVE_STUCK_START_GRACE_MS = 15 * 60 * 1000;
const liveArchiveRecoveryExpiredMessage =
  "The replay recording never reached storage, so this broadcast can't be replayed.";

/** Finds the host's replay playlist in storage when Agora's stop response never listed it. */
const discoverLiveArchivePrimaryFile = async (
  sessionId: string,
  session: Record<string, unknown>
): Promise<string | undefined> => {
  const storedPrefix = sanitizeLiveArchiveObjectPath(String(session.archiveObjectPrefix || ""));
  const objectPrefix = storedPrefix.split("/").includes(sessionId) ?
    storedPrefix :
    buildLiveArchiveObjectPrefix(getAgoraRecordingConfig(), sessionId).joined;
  if (!objectPrefix) return undefined;

  const hostId = String(session.hostId || session.hostUid || "").trim();
  const hostAgoraUid = hostId ? String(stableAgoraUidFromFirebaseUid(hostId)) : "";
  // Individual mode names files `<sid>_<cname>__uid_s_<uid>__uid_e_<av|video|audio>.m3u8`.
  const rank = (fileName: string): number => {
    const match = /__uid_s_(\d+)__uid_e_([a-z]+)\.(m3u8|mp4)$/i.exec(fileName);
    const uid = match?.[1] || "";
    const track = (match?.[2] || "").toLowerCase();
    const trackScore = track === "av" ? 2 : (track === "video" ? 1 : 0);
    return (hostAgoraUid && uid === hostAgoraUid ? 10 : 0) + trackScore;
  };

  for (const bucketName of liveArchiveBucketCandidates(session)) {
    try {
      const [objects] = await getStorage().bucket(bucketName).getFiles({prefix: `${objectPrefix}/`});
      const playable = objects
        .map((object) => String(object.name || "").trim())
        .filter((name) => /\.(m3u8|mp4)$/i.test(name))
        .sort((left, right) => rank(right) - rank(left));
      if (playable.length > 0) return playable[0];
    } catch (error) {
      functions.logger.warn("Could not list live archive objects for replay discovery.", {
        sessionId,
        bucketName,
        error: String(error),
      });
    }
  }
  return undefined;
};

/** The end-of-live trigger can time out or miss a recorder that was still starting; finish those here. */
const finalizeStuckLiveArchiveRecorders = async (): Promise<void> => {
  const stuck = await db.collection("live_sessions")
    .where("archiveStatus", "in", ["STARTING", "RECORDING"])
    .limit(40)
    .get();
  const recordingConfig = getAgoraRecordingConfig();

  for (const snapshot of stuck.docs) {
    const session = (snapshot.data() || {}) as Record<string, unknown>;
    const liveStatus = String(session.status || "").trim().toLowerCase();
    if (!LIVE_ARCHIVE_ENDED_SESSION_STATUSES.includes(liveStatus)) continue;

    const endedAtMs = readFirestoreTimestampMs(session.endedAt) || readFirestoreTimestampMs(session.updatedAt);
    const sinceEndMs = endedAtMs > 0 ? Date.now() - endedAtMs : Number.POSITIVE_INFINITY;
    const metadata = buildLiveArchiveStopMetadata(session, session, recordingConfig, snapshot.id);
    try {
      if (hasLiveArchiveRecorderMetadata(metadata)) {
        if (sinceEndMs < LIVE_ARCHIVE_STUCK_RECORDER_GRACE_MS) continue;
        functions.logger.warn("Finalizing a live replay recorder that was never stopped.", {sessionId: snapshot.id});
        await stopLiveArchiveRecording(snapshot.id, session);
      } else if (sinceEndMs >= LIVE_ARCHIVE_STUCK_START_GRACE_MS) {
        await db.runTransaction(async (transaction) => {
          const current = await transaction.get(snapshot.ref);
          if (!current.exists) return;
          const currentData = (current.data() || {}) as Record<string, unknown>;
          if (normalizeLiveArchiveStatus(currentData.archiveStatus) !== "STARTING") return;
          if (String(currentData.archiveSid || "").trim()) return;
          transaction.set(snapshot.ref, {
            archiveStatus: "FAILED",
            archiveError: LIVE_ARCHIVE_ENDED_BEFORE_START_MESSAGE,
          }, {merge: true});
        });
      }
    } catch (error) {
      functions.logger.warn("Could not finalize a stuck live replay recorder.", {
        sessionId: snapshot.id,
        error: String(error),
      });
    }
  }
};

export const reconcilePendingLiveReplayArchives = functions.runWith({
  timeoutSeconds: 540,
  memory: "512MB",
}).pubsub
  .schedule("every 5 minutes")
  .onRun(async () => {
    const recordingConfig = getAgoraRecordingConfig();

    await finalizeStuckLiveArchiveRecorders();

    const [pending, timedOut] = await Promise.all([
      db.collection("live_sessions")
        .where("archiveStatus", "==", "PROCESSING")
        .limit(40)
        .get(),
      db.collection("live_sessions")
        .where("archiveStatus", "==", "FAILED")
        .where("archiveError", "in", liveArchiveProcessingTimedOutMessages)
        .limit(100)
        .get(),
    ]);
    const recoverable: FirebaseFirestore.QueryDocumentSnapshot[] = [];
    for (const snapshot of timedOut.docs) {
      const startedAtMs = liveArchiveProcessingStartedAtMs(snapshot.data() || {});
      if (startedAtMs > 0 && Date.now() - startedAtMs < LIVE_ARCHIVE_LATE_UPLOAD_RECOVERY_MS) {
        recoverable.push(snapshot);
      } else {
        // Leaving the recovery query keeps stale rows from crowding out recent ones.
        await updateLiveArchiveFields(snapshot.ref, {archiveError: liveArchiveRecoveryExpiredMessage});
      }
    }
    let promoted = 0;
    let recovered = 0;

    for (const snapshot of [...pending.docs, ...recoverable]) {
      const session = (snapshot.data() || {}) as Record<string, unknown>;
      const isLateRecovery = String(session.archiveStatus || "").trim().toUpperCase() === "FAILED";
      let primaryFile = String(session.archivePrimaryFile || "").trim();
      if (!primaryFile) {
        primaryFile = (await discoverLiveArchivePrimaryFile(snapshot.id, session)) || "";
        if (primaryFile) {
          await updateLiveArchiveFields(snapshot.ref, {archivePrimaryFile: primaryFile});
        }
      }
      const primaryFileBucket = primaryFile ?
        await findLiveArchivePrimaryFileBucket(session, primaryFile) :
        undefined;
      if (!primaryFileBucket) {
        if (!isLateRecovery && liveArchiveProcessingHasExpired(session)) {
          await updateLiveArchiveFields(snapshot.ref, {
            archiveStatus: "FAILED",
            archiveError: liveArchiveProcessingTimedOutMessage,
          });
          functions.logger.warn("Live replay processing timed out before the archive file arrived.", {
            sessionId: snapshot.id,
            hasPrimaryFile: !!primaryFile,
            processingStartedAtMs: liveArchiveProcessingStartedAtMs(session) || null,
          });
        }
        continue;
      }

      try {
        await updateLiveArchiveFields(snapshot.ref, {
          archiveStatus: "READY",
          archiveBucket: primaryFileBucket,
          archiveReadyAt: admin.firestore.FieldValue.serverTimestamp(),
          archiveError: admin.firestore.FieldValue.delete(),
        });
        await persistLiveArchivePlaybackUrl(
          snapshot.id,
          buildLiveArchivePlaybackUrl(recordingConfig.playbackBaseUrl, primaryFile)
        );
        await promoteMindLoomLivePostToReplay(snapshot.id, session);
        await restrictLiveArchiveObjectsToServerAccess({
          bucketName: primaryFileBucket,
          objectPaths: [primaryFile],
          objectPrefix: String(session.archiveObjectPrefix || "").trim(),
        });
        promoted += 1;
        if (isLateRecovery) {
          recovered += 1;
          functions.logger.info("Timed-out live replay recovered after a late upload.", {sessionId: snapshot.id});
        }
      } catch (error) {
        functions.logger.warn("Could not reconcile pending live replay archive.", {
          sessionId: snapshot.id,
          error: String(error),
        });
      }
    }

    if (promoted > 0) {
      functions.logger.info("Pending live replay archives promoted.", {promoted, recovered});
    }
    return undefined;
  });

const LIVE_STALE_SESSION_ACTIVE_STATUSES = ["LIVE", "live", "active", "started"] as const;

const readFirestoreTimestampMs = (value: unknown): number => {
  if (value && typeof (value as admin.firestore.Timestamp).toMillis === "function") {
    return (value as admin.firestore.Timestamp).toMillis();
  }
  return 0;
};

const resolveLiveHostHeartbeatMs = async (
  sessionId: string,
  hostId: string
): Promise<number> => {
  if (!sessionId || !hostId) return 0;
  const viewerSnap = await db.collection("live_sessions")
    .doc(sessionId)
    .collection("viewers")
    .doc(hostId)
    .get();
  return readFirestoreTimestampMs(viewerSnap.data()?.lastSeenAt);
};

/** Ends abandoned live sessions so discovery and host relaunch do not stay stuck on ghost streams. */
export const reconcileStaleLiveSessions = functions.pubsub
  .schedule("every 2 minutes")
  .onRun(async () => {
    // Host heartbeat is every 25s; ~7 missed beats means the broadcaster is gone.
    const staleAfterMs = Math.max(
      120_000,
      Number(process.env.LIVE_STALE_SESSION_AFTER_MS || 3 * 60 * 1000)
    );
    const startupGraceMs = Math.max(
      60_000,
      Number(process.env.LIVE_STALE_SESSION_STARTUP_GRACE_MS || 2 * 60 * 1000)
    );
    const cutoffMs = Date.now() - staleAfterMs;
    const seenSessionIds = new Set<string>();
    let reconciled = 0;

    for (const status of LIVE_STALE_SESSION_ACTIVE_STATUSES) {
      const snap = await db.collection("live_sessions")
        .where("status", "==", status)
        .limit(60)
        .get();
      for (const doc of snap.docs) {
        if (seenSessionIds.has(doc.id)) continue;
        seenSessionIds.add(doc.id);

        const session = (doc.data() || {}) as Record<string, unknown>;
        const hostId = String(session.hostId || session.hostUid || "").trim();
        if (!hostId) continue;

        const startedMs = Math.max(
          readFirestoreTimestampMs(session.startTime),
          readFirestoreTimestampMs(session.createdAt)
        );
        if (startedMs > 0 && Date.now() - startedMs < startupGraceMs) {
          continue;
        }

        const heartbeatMs = await resolveLiveHostHeartbeatMs(doc.id, hostId);
        const updatedMs = readFirestoreTimestampMs(session.updatedAt);
        const lastActivityMs = Math.max(heartbeatMs, updatedMs);
        if (lastActivityMs > 0 && lastActivityMs >= cutoffMs) {
          continue;
        }
        if (lastActivityMs === 0 && startedMs > 0 && Date.now() - startedMs < staleAfterMs) {
          continue;
        }

        try {
          await doc.ref.update({
            status: "ENDED",
            endedAt: admin.firestore.FieldValue.serverTimestamp(),
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          });
          reconciled += 1;
        } catch (error) {
          functions.logger.warn("reconcileStaleLiveSessions update failed", {
            sessionId: doc.id,
            hostId,
            error: String(error),
          });
        }
      }
    }

    if (reconciled > 0) {
      functions.logger.log("reconcileStaleLiveSessions", {reconciled, staleAfterMs});
    }
    return undefined;
  });

/**
 * Two triggers (this onWrite and the recovery onUpdate) observe the same go-live transition;
 * a create-only lock guarantees followers get exactly one "is live now" push per session.
 */
const claimLiveFollowerNotification = async (sessionId: string): Promise<boolean> => {
  try {
    await db.collection("live_sessions")
      .doc(sessionId)
      .collection("server_archive")
      .doc("follower_notification")
      .create({claimedAt: admin.firestore.FieldValue.serverTimestamp()});
    return true;
  } catch (error) {
    const code = (error as {code?: unknown})?.code;
    if (code === 6 || code === "already-exists") return false;
    throw error;
  }
};

// The notification lock is claimed before fan-out and the trigger isn't retried, so a
// timeout on a large follower list would silently drop the remaining pushes.
export const onLiveSessionStartedNotifyFollowers = functions.runWith({timeoutSeconds: 540, memory: "512MB"})
  .firestore
  .document("live_sessions/{sessionId}")
  .onWrite(async (change) => {
    const after = change.after.exists ? change.after.data() : undefined;
    if (!after) return undefined;

    const before = change.before.exists ? (change.before.data() || {}) : {};
    const beforeStatus = String((before as Record<string, unknown>).status || "").trim().toLowerCase();
    const afterStatus = String(after.status || "").trim().toLowerCase();
    const isAfterLive = ["live", "active", "started"].includes(afterStatus);
    const wasAlreadyLive = ["live", "active", "started"].includes(beforeStatus);

    if (!isAfterLive || wasAlreadyLive) return undefined;

    const actorId = typeof after.hostId === "string" ? after.hostId.trim() : "";
    if (!actorId) return undefined;

    const session = after as Record<string, unknown>;
    const viewAccessMode = normalizeLiveViewAccessMode(session.viewAccessMode);
    const isOwnedEventStream = await sessionHostOwnsOrganizerEventSource(session, actorId);
    const eventGuestIds = isOwnedEventStream ?
      await fetchApprovedEventGuestIds(String(session.sourceId || "").trim()) :
      [];
    // Followers can only open public/followers streams; invite and event-only rooms would just deny them.
    const followersCanWatch = viewAccessMode === "public" || viewAccessMode === "followers_only";
    const notifyFollowersEnabled = after.notifyFollowers !== false && followersCanWatch;
    if (!notifyFollowersEnabled && eventGuestIds.length === 0) return undefined;
    if (!(await claimLiveFollowerNotification(change.after.id))) return undefined;

    const title = typeof after.title === "string" && after.title.trim().length > 0
      ? after.title.trim()
      : "Live now";
    const hostName = typeof after.hostName === "string" && after.hostName.trim().length > 0
      ? after.hostName.trim()
      : "Someone";

    await notifyFollowers({
      actorId,
      title: isOwnedEventStream ? `${hostName} started the event live stream` : `${hostName} is live now`,
      body: title,
      type: "liveStream",
      referenceId: change.after.id,
      settingsField: "liveStreams",
      additionalRecipientIds: eventGuestIds,
      skipFollowers: !notifyFollowersEnabled,
    });

    return undefined;
  });

/**
 * Accepted guests of an organizer event. Watch access is checked at events/{id}/applications/{uid},
 * so the document id is the guest uid that can actually open the stream.
 */
const fetchApprovedEventGuestIds = async (eventId: string): Promise<string[]> => {
  if (!eventId) return [];
  const snapshot = await db.collection("events").doc(eventId).collection("applications").limit(1000).get();
  return snapshot.docs
    .filter((doc) => APPROVED_EVENT_APPLICATION_STATUSES.has(String(doc.data()?.status || "").trim().toLowerCase()))
    .map((doc) => doc.id);
};


