const AGENT_CUSTOMER_WALLET_WITHDRAWAL_TYPE = "AGENT_CUSTOMER_WALLET_WITHDRAWAL";
const AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE = "AGENT_CUSTOMER_PORTAL";
const AGENT_CUSTOMER_MOBILE_COLLECTION_SOURCE = "AGENT_CUSTOMER_PORTAL_MM_COLLECTION";
const AGENT_CUSTOMER_WALLET_WITHDRAWAL_OTP_TTL_MS = 10 * 60 * 1000;
const AGENT_CUSTOMER_WALLET_WITHDRAWAL_RESERVATION_TTL_MS = 15 * 60 * 1000;
const AGENT_CUSTOMER_WALLET_WITHDRAWAL_MAX_OTP_ATTEMPTS = 5;
const AGENT_CUSTOMER_WALLET_WITHDRAWAL_PENDING_STATES = new Set([
  "PHONE_CAPTURED",
  "CUSTOMER_VERIFIED",
  "OTP_SENT",
  "OTP_VERIFIED",
  "CUSTOMER_APPROVED",
  "FUNDS_RESERVED",
  "CASH_HANDOVER_PENDING",
]);
const AGENT_CUSTOMER_MOBILE_COLLECTION_ACTIVE_STATUSES = new Set([
  "PENDING",
  "PENDING_PROVIDER",
  "PROCESSING_PROVIDER",
  "COMPLETED",
]);

const maskAgentCustomerName = (value: unknown): string => {
  const raw = String(value || "").trim();
  if (!raw) return "Customer";
  const parts = raw.split(/\s+/).filter((part) => part.length > 0);
  if (parts.length === 0) return "Customer";
  return parts.map((part) => {
    if (part.length <= 2) return `${part[0] || "*"}*`;
    return `${part.slice(0, 2)}***`;
  }).join(" ");
};

const getUserDisplayName = (userData: Record<string, unknown> | undefined): string =>
  asNonEmptyString(
    userData?.name,
    userData?.displayName,
    userData?.username,
    userData?.email
  ) || "Customer";

const assertAgentCustomerPortalOperator = async (
  context: functions.https.CallableContext
): Promise<{uid: string; userData: Record<string, unknown>}> => {
  assertTransactionOnlyCashServicesDisabled();
  if (!context.auth?.uid) {
    throw new functions.https.HttpsError("unauthenticated", "You must be logged in to perform this action.");
  }

  const uid = context.auth.uid;
  const userSnap = await db.collection("users").doc(uid).get();
  if (!userSnap.exists) {
    throw new functions.https.HttpsError("not-found", "Agent account not found.");
  }

  const mergedUserData = await withPrivateUserFields(uid, (userSnap.data() || {}) as Record<string, unknown>);
  if (!isAuthorizedAgentOperator(mergedUserData, (context.auth?.token || {}) as Record<string, unknown>)) {
    throw new functions.https.HttpsError("permission-denied", "You must be an authorized agent or staff operator.");
  }

  return {uid, userData: mergedUserData};
};

const loadWalletCustomerCandidatesByPhone = async (
  phoneE164: string,
  phoneDigits: string
): Promise<Array<{uid: string; userData: Record<string, unknown>}>> => {
  const normalizedPhone = phoneE164.trim();
  const normalizedDigits = normalizeDigits(phoneDigits);
  if (!normalizedPhone || normalizedDigits.length < 8) {
    return [];
  }

  const userQueries = [
    db.collection("users").where("phoneNumber", "==", normalizedPhone).limit(5).get(),
    db.collection("users").where("phone", "==", normalizedPhone).limit(5).get(),
    db.collection("users").where("mobileNumber", "==", normalizedPhone).limit(5).get(),
  ];
  const privateQueries = [
    db.collection(USER_PRIVATE_COLLECTION).where("phoneVerifiedDigits", "==", normalizedDigits).limit(5).get(),
    db.collection(USER_PRIVATE_COLLECTION).where("mobileMoneyPhoneOtpVerifiedPhoneDigits", "==", normalizedDigits).limit(5).get(),
  ];

  const [userQuerySnaps, privateQuerySnaps] = await Promise.all([
    Promise.all(userQueries),
    Promise.all(privateQueries),
  ]);

  const candidateIds = new Set<string>();
  for (const snap of userQuerySnaps) {
    for (const doc of snap.docs) {
      candidateIds.add(doc.id);
    }
  }
  for (const snap of privateQuerySnaps) {
    for (const doc of snap.docs) {
      candidateIds.add(doc.id);
    }
  }

  if (candidateIds.size === 0) {
    return [];
  }

  const candidates: Array<{uid: string; userData: Record<string, unknown>}> = [];
  for (const uid of candidateIds) {
    const userSnap = await db.collection("users").doc(uid).get();
    if (!userSnap.exists) continue;
    const merged = await withPrivateUserFields(uid, (userSnap.data() || {}) as Record<string, unknown>);
    const storedPhoneE164 = normalizeStoredAccountPhoneE164(merged);
    const storedDigits = normalizeDigits(
      asNonEmptyString(
        merged.phoneVerifiedDigits,
        merged.mobileMoneyPhoneOtpVerifiedPhoneDigits,
        merged.phoneNumber,
        merged.phone,
        merged.mobileNumber,
        storedPhoneE164
      ) || ""
    );
    const storedPhoneMatches = normalizeDigits(storedPhoneE164) === normalizedDigits;
    const verifiedDigitsMatch = storedDigits === normalizedDigits;
    if (!storedPhoneMatches && !verifiedDigitsMatch) {
      continue;
    }
    candidates.push({uid, userData: merged});
  }

  return candidates;
};

const resolveAgentCustomerPhoneMatchSummary = async (
  phoneE164: string,
  phoneDigits: string
): Promise<{
  customerType: AgentCustomerType;
  customerUserId: string | null;
  maskedName: string;
  riskFlags: string[];
  userData?: Record<string, unknown>;
}> => {
  const candidates = await loadWalletCustomerCandidatesByPhone(phoneE164, phoneDigits);
  if (candidates.length === 0) {
    return {
      customerType: "WALK_IN_CUSTOMER",
      customerUserId: null,
      maskedName: "Walk-in Customer",
      riskFlags: [],
    };
  }

  if (candidates.length > 1) {
    return {
      customerType: "REVIEW_REQUIRED",
      customerUserId: null,
      maskedName: "Multiple Matches",
      riskFlags: ["MULTIPLE_WALLET_CUSTOMERS_MATCHED_PHONE"],
    };
  }

  const customer = candidates[0];
  return {
    customerType: "WALLET_CUSTOMER",
    customerUserId: customer.uid,
    maskedName: maskAgentCustomerName(getUserDisplayName(customer.userData)),
    riskFlags: [],
    userData: customer.userData,
  };
};

const buildAgentCustomerLookupResponse = async (args: {
  country?: unknown;
  network?: unknown;
  phoneNumber?: unknown;
}): Promise<Record<string, unknown>> => {
  const country = asNonEmptyString(args.country) || "";
  const network = asNonEmptyString(args.network) || "";
  const phoneE164 = normalizeMobileMoneyPhoneE164(args.phoneNumber);
  const phoneDigits = normalizeDigits(phoneE164);
  if (phoneDigits.length < 8 || phoneDigits.length > 15) {
    throw new functions.https.HttpsError(
      "invalid-argument",
      "Provide a valid customer phone number in international format."
    );
  }

  const mobileMoneyCurrency = resolveMobileMoneyCurrency({country, network});
  const canonicalCountry = canonicalMobileMoneyCountry(country);
  const providerMode = String(process.env.MOBILE_MONEY_PROVIDER_MODE || "MANUAL").toUpperCase();
  const providerSupportsCollectionCountry =
    providerMode !== "HTTP_API" ||
    isMobileMoneyDepositCountrySupportedByProvider(getMobileMoneyProviderName(), canonicalCountry);
  const mobileMoneyCollectionEnabled = !!mobileMoneyCurrency && providerSupportsCollectionCountry;
  const mobileMoneyAllowedModes: AgentCustomerLookupMode[] = mobileMoneyCollectionEnabled ?
    ["MM_COLLECTION"] :
    [];
  const customerMatch = await resolveAgentCustomerPhoneMatchSummary(phoneE164, phoneDigits);

  if (customerMatch.customerType === "WALK_IN_CUSTOMER") {
    return {
      success: true,
      customerType: customerMatch.customerType,
      customerUserId: null,
      maskedName: customerMatch.maskedName,
      maskedPhoneNumber: maskPhoneNumberForOtp(phoneE164),
      walletCurrency: "USD",
      maxWithdrawableAmount: 0,
      withdrawalEnabled: false,
      authMode: "MANUAL_SUPPORT_REVIEW",
      allowedModes: mobileMoneyAllowedModes,
      riskFlags: customerMatch.riskFlags,
    };
  }

  if (customerMatch.customerType === "REVIEW_REQUIRED") {
    return {
      success: true,
      customerType: customerMatch.customerType,
      customerUserId: null,
      maskedName: customerMatch.maskedName,
      maskedPhoneNumber: maskPhoneNumberForOtp(phoneE164),
      walletCurrency: "USD",
      maxWithdrawableAmount: 0,
      withdrawalEnabled: false,
      authMode: "MANUAL_SUPPORT_REVIEW",
      allowedModes: mobileMoneyAllowedModes,
      riskFlags: customerMatch.riskFlags,
    };
  }

  const customer = {
    uid: customerMatch.customerUserId || "",
    userData: customerMatch.userData || {},
  };
  const customerUsesHostedWallet = userUsesProviderHostedWallet(customer.userData);
  const hostedWallet = customerUsesHostedWallet ?
    await loadProviderWalletMirrorRecord(customer.uid, customer.userData) :
    null;
  const wallet = (customer.userData.wallet || {}) as Record<string, unknown>;
  const walletCurrency = customerUsesHostedWallet ?
    (hostedWallet?.currency || normalizeIsoCurrencyForFx(wallet.currency, "USD") || "USD") :
    (normalizeIsoCurrencyForFx(wallet.currency, "USD") || "USD");
  const spendableBalance = customerUsesHostedWallet ?
    0 :
    getWalletSpendableBalance(customer.userData);
  const riskFlags: string[] = [];
  const allowedModes: AgentCustomerLookupMode[] = [];
  if (customerUsesHostedWallet) {
    riskFlags.push("HOSTED_WALLET_SERVICE_REQUIRES_PROVIDER_FLOW");
  }
  if (!isProfileOperational(customer.userData.profileStatus)) {
    riskFlags.push("CUSTOMER_PROFILE_NOT_ACTIVE");
  }
  if (mobileMoneyCollectionEnabled) {
    allowedModes.push("MM_COLLECTION");
  } else {
    riskFlags.push("PROVIDER_COLLECTION_NOT_ENABLED_FOR_CORRIDOR");
  }

  return {
    success: true,
    customerType: customerMatch.customerType,
    customerUserId: customer.uid,
    maskedName: customerMatch.maskedName,
    maskedPhoneNumber: maskPhoneNumberForOtp(phoneE164),
    walletCurrency,
    maxWithdrawableAmount: 0,
    withdrawalEnabled: allowedModes.includes("WALLET_WITHDRAWAL"),
    authMode: "PHONE_OTP",
    allowedModes,
    riskFlags,
  };
};

const resolveAgentWalletCustomerByPhone = async (args: {
  phoneNumber?: unknown;
  expectedCustomerUserId?: string | null;
}): Promise<{uid: string; userData: Record<string, unknown>; phoneE164: string; phoneDigits: string}> => {
  const phoneE164 = normalizeMobileMoneyPhoneE164(args.phoneNumber);
  const phoneDigits = normalizeDigits(phoneE164);
  if (phoneDigits.length < 8 || phoneDigits.length > 15) {
    throw new functions.https.HttpsError(
      "invalid-argument",
      "Provide a valid customer phone number in international format."
    );
  }

  const candidates = await loadWalletCustomerCandidatesByPhone(phoneE164, phoneDigits);
  if (candidates.length === 0) {
    throw new functions.https.HttpsError("not-found", "No wallet customer matched this phone number.");
  }

  const expectedCustomerUserId = asNonEmptyString(args.expectedCustomerUserId);
  if (expectedCustomerUserId) {
    const matched = candidates.find((candidate) => candidate.uid === expectedCustomerUserId);
    if (!matched) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Customer lookup no longer matches this phone number. Refresh the lookup and try again."
      );
    }
    return {
      uid: matched.uid,
      userData: matched.userData,
      phoneE164,
      phoneDigits,
    };
  }

  if (candidates.length > 1) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Multiple wallet customers matched this phone number. Manual review is required."
    );
  }

  return {
    uid: candidates[0].uid,
    userData: candidates[0].userData,
    phoneE164,
    phoneDigits,
  };
};

const assertNoActiveAgentCustomerPortalSession = async (args: {
  agentId: string;
  phoneE164: string;
}): Promise<void> => {
  const [walletWithdrawalSnap, mobileCollectionSnap] = await Promise.all([
    db.collection("payout_requests")
      .where("customerPhoneE164", "==", args.phoneE164)
      .limit(50)
      .get(),
    db.collection("payout_requests")
      .where("phone", "==", args.phoneE164)
      .limit(50)
      .get(),
  ]);

  const byId = new Map<string, FirebaseFirestore.QueryDocumentSnapshot>();
  for (const doc of walletWithdrawalSnap.docs) {
    byId.set(doc.id, doc);
  }
  for (const doc of mobileCollectionSnap.docs) {
    byId.set(doc.id, doc);
  }

  for (const doc of byId.values()) {
    const sessionData = doc.data() || {};
    if (asNonEmptyString(sessionData.agentId, sessionData.senderId) !== args.agentId) {
      continue;
    }

    const type = String(sessionData.type || "").trim().toUpperCase();
    const source = asNonEmptyString(sessionData.source) || "";
    const status = String(sessionData.status || "").trim().toUpperCase();
    const flowStage = String(sessionData.flowStage || "").trim().toUpperCase();

    const isActiveWalletWithdrawal =
      type === AGENT_CUSTOMER_WALLET_WITHDRAWAL_TYPE &&
      AGENT_CUSTOMER_WALLET_WITHDRAWAL_PENDING_STATES.has(flowStage);
    const isActiveMobileCollection =
      source === AGENT_CUSTOMER_MOBILE_COLLECTION_SOURCE &&
      AGENT_CUSTOMER_MOBILE_COLLECTION_ACTIVE_STATUSES.has(status) &&
      !sessionData.cashConfirmedAt;

    if (!isActiveWalletWithdrawal && !isActiveMobileCollection) {
      continue;
    }

    const conflictMode = isActiveWalletWithdrawal ? "customer cash session" : "mobile-money collection";
    throw new functions.https.HttpsError(
      "failed-precondition",
      `Another ${conflictMode} session is already in progress for this phone number. Complete or cancel it before starting a new one.`
    );
  }
};

const loadAgentCustomerWalletSession = async (
  sessionId: string,
  agentId: string
): Promise<{
  ref: FirebaseFirestore.DocumentReference;
  data: FirebaseFirestore.DocumentData;
}> => {
  const sessionRef = db.collection("payout_requests").doc(sessionId);
  const sessionSnap = await sessionRef.get();
  if (!sessionSnap.exists) {
    throw new functions.https.HttpsError("not-found", "Withdrawal session not found.");
  }
  const sessionData = sessionSnap.data() || {};
  if (String(sessionData.type || "").trim().toUpperCase() !== AGENT_CUSTOMER_WALLET_WITHDRAWAL_TYPE) {
    throw new functions.https.HttpsError("failed-precondition", "Session is not a wallet-withdrawal portal request.");
  }
  if (asNonEmptyString(sessionData.agentId) !== agentId) {
    throw new functions.https.HttpsError("permission-denied", "This session belongs to a different operator.");
  }
  return {ref: sessionRef, data: sessionData};
};

const buildAgentCustomerWalletSessionResponse = (
  sessionId: string,
  sessionData: FirebaseFirestore.DocumentData
): Record<string, unknown> => ({
  success: true,
  sessionId,
  payoutRequestId: sessionId,
  id: sessionId,
  status: asNonEmptyString(sessionData.status) || "PENDING",
  flowStage: asNonEmptyString(sessionData.flowStage) || "PHONE_CAPTURED",
  authMode: asNonEmptyString(sessionData.authMode) || "PHONE_OTP",
  agentId: asNonEmptyString(sessionData.agentId) || "",
  customerUserId: asNonEmptyString(sessionData.customerUserId) || "",
  maskedName: asNonEmptyString(sessionData.customerMaskedName, sessionData.maskedName) || "Customer",
  maskedPhoneNumber: asNonEmptyString(sessionData.customerMaskedPhone, sessionData.maskedPhoneNumber) || "Hidden",
  amount: roundMoney(Number(sessionData.amount || sessionData.walletDebitAmount || 0)),
  walletDebitedAmount: roundMoney(Number(sessionData.walletDebitedAmount || sessionData.amount || 0)),
  currency: normalizeIsoCurrencyForFx(sessionData.currency, "USD") || "USD",
  walletCurrency: normalizeIsoCurrencyForFx(sessionData.currency, "USD") || "USD",
  localAmount: Number(sessionData.localAmount || 0) > 0 ? roundMoney(Number(sessionData.localAmount || 0)) : null,
  localCurrency: normalizeIsoCurrencyForFx(sessionData.localCurrency) || null,
  providerReference: asNonEmptyString(sessionData.providerReference) || null,
  otpExpiresAtMs: toMillisTimestamp(sessionData.otpExpiresAt) || Number(sessionData.otpExpiresAtMs || 0) || null,
  otpExpiresAt: sessionData.otpExpiresAt || null,
  cashHandoverExpiresAtMs: toMillisTimestamp(sessionData.cashHandoverExpiresAt) || Number(sessionData.cashHandoverExpiresAtMs || 0) || null,
  cashHandoverExpiresAt: sessionData.cashHandoverExpiresAt || null,
  failureReason: asNonEmptyString(sessionData.failureReason) || null,
  riskFlags: normalizeStringList(sessionData.riskFlags),
});

const loadAgentCustomerMobileMoneyCollectionSession = async (
  sessionId: string,
  agentId: string
): Promise<{
  ref: FirebaseFirestore.DocumentReference;
  data: FirebaseFirestore.DocumentData;
}> => {
  const sessionRef = db.collection("payout_requests").doc(sessionId);
  const sessionSnap = await sessionRef.get();
  if (!sessionSnap.exists) {
    throw new functions.https.HttpsError("not-found", "Mobile-money collection session not found.");
  }
  const sessionData = sessionSnap.data() || {};
  if (String(sessionData.type || "").trim().toUpperCase() !== "CASH_IN" ||
    asNonEmptyString(sessionData.source) !== AGENT_CUSTOMER_MOBILE_COLLECTION_SOURCE) {
    throw new functions.https.HttpsError("failed-precondition", "Session is not an agent mobile-money collection request.");
  }
  if (asNonEmptyString(sessionData.agentId, sessionData.senderId) !== agentId) {
    throw new functions.https.HttpsError("permission-denied", "This session belongs to a different operator.");
  }
  return {ref: sessionRef, data: sessionData};
};

const deriveAgentCustomerMobileMoneyCollectionStage = (
  sessionData: FirebaseFirestore.DocumentData
): string => {
  const status = String(sessionData.status || "").trim().toUpperCase();
  if (status === "REVERSED") return "REVERSED";
  if (status === "FAILED") return "FAILED";
  if (status === "CANCELLED") return "CANCELLED";
  if (sessionData.cashConfirmedAt) return "COMPLETED";
  if (status === "COMPLETED") return "COLLECTION_COMPLETED";
  return "COLLECTION_PENDING";
};

const buildAgentCustomerMobileMoneyCollectionSessionResponse = (
  sessionId: string,
  sessionData: FirebaseFirestore.DocumentData
): Record<string, unknown> => ({
  success: true,
  sessionId,
  payoutRequestId: sessionId,
  id: sessionId,
  status: asNonEmptyString(sessionData.status) || "PENDING",
  flowStage: deriveAgentCustomerMobileMoneyCollectionStage(sessionData),
  agentId: asNonEmptyString(sessionData.agentId, sessionData.senderId) || "",
  customerUserId: asNonEmptyString(sessionData.customerUserId) || null,
  customerType: asNonEmptyString(sessionData.customerType) || "WALK_IN_CUSTOMER",
  maskedName: asNonEmptyString(sessionData.customerMaskedName, sessionData.maskedName) || "Customer",
  maskedPhoneNumber: asNonEmptyString(sessionData.customerMaskedPhone, sessionData.maskedPhoneNumber) || "Hidden",
  amount: roundMoney(Number(sessionData.amount || sessionData.walletCreditedAmount || 0)),
  walletCreditedAmount: roundMoney(Number(sessionData.walletCreditedAmount || sessionData.amount || 0)),
  currency: normalizeIsoCurrencyForFx(sessionData.walletCurrency, sessionData.currency) || "USD",
  walletCurrency: normalizeIsoCurrencyForFx(sessionData.walletCurrency, sessionData.currency) || "USD",
  localAmount: Number(sessionData.localAmount || 0) > 0 ? roundMoney(Number(sessionData.localAmount || 0)) : null,
  localCurrency: normalizeIsoCurrencyForFx(sessionData.localCurrency) || null,
  providerReference: asNonEmptyString(sessionData.providerTransferId, sessionData.providerReference) || null,
  providerStatus: asNonEmptyString(sessionData.providerStatus) || null,
  providerMessage: asNonEmptyString(sessionData.providerMessage, sessionData.errorMessage) || null,
  cashConfirmedAtMs: toMillisTimestamp(sessionData.cashConfirmedAt) || Number(sessionData.cashConfirmedAtMs || 0) || null,
  cashConfirmedAt: sessionData.cashConfirmedAt || null,
  failureReason: asNonEmptyString(sessionData.failureReason, sessionData.errorMessage, sessionData.providerMessage) || null,
  riskFlags: normalizeStringList(sessionData.riskFlags),
});

const reverseAgentCustomerWalletWithdrawalReservation = async (args: {
  sessionRef: FirebaseFirestore.DocumentReference;
  sessionData: FirebaseFirestore.DocumentData;
  finalStatus: "CANCELLED" | "REVERSED" | "FAILED";
  finalStage: "CANCELLED" | "REVERSED" | "FAILED";
  reason: string;
}): Promise<FirebaseFirestore.DocumentData> => {
  const customerUserId = asNonEmptyString(args.sessionData.customerUserId);
  const walletDebitedAmount = roundMoney(Number(
    args.sessionData.walletDebitedAmount ||
    args.sessionData.amount ||
    0
  ));

  await db.runTransaction(async (transaction) => {
    const freshSnap = await transaction.get(args.sessionRef);
    if (!freshSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Withdrawal session not found.");
    }

    const freshData = freshSnap.data() || args.sessionData;
    const currentStage = String(freshData.flowStage || "").trim().toUpperCase();
    const currentStatus = String(freshData.status || "").trim().toUpperCase();
    if (["COMPLETED", "FAILED", "CANCELLED", "EXPIRED", "REVERSED"].includes(currentStage) ||
      ["COMPLETED", "FAILED", "CANCELLED", "EXPIRED", "REVERSED"].includes(currentStatus)) {
      return;
    }

    const now = admin.firestore.Timestamp.now();
    const sessionPatch: FirebaseFirestore.DocumentData = {
      status: args.finalStatus,
      flowStage: args.finalStage,
      failureReason: args.reason,
      updatedAt: now,
      processedAt: now,
      cashHandoverExpiresAt: admin.firestore.FieldValue.delete(),
      cashHandoverExpiresAtMs: admin.firestore.FieldValue.delete(),
      fundsReservationExpiresAt: admin.firestore.FieldValue.delete(),
      fundsReservationExpiresAtMs: admin.firestore.FieldValue.delete(),
    };
    if (args.finalStatus === "CANCELLED") {
      sessionPatch.cancelledAt = now;
    } else if (args.finalStatus === "REVERSED") {
      sessionPatch.reversedAt = now;
    } else {
      sessionPatch.failedAt = now;
    }

    const customerId = asNonEmptyString(freshData.customerUserId, customerUserId);
    const amount = roundMoney(Number(freshData.walletDebitedAmount || walletDebitedAmount || 0));
    const senderTransactionIds = Array.isArray(freshData.senderTransactionIds) ?
      freshData.senderTransactionIds.filter((value: unknown): value is string => typeof value === "string" && value.trim().length > 0) :
      [];
    const shouldRefund = (
      currentStage === "FUNDS_RESERVED" ||
      currentStage === "CASH_HANDOVER_PENDING" ||
      currentStage === "CUSTOMER_APPROVED"
    ) && !!customerId && amount > 0;

    if (shouldRefund) {
      const customerRef = db.collection("users").doc(customerId);
      const customerSnap = await transaction.get(customerRef);
      if (!customerSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Customer account not found for refund.");
      }

      const refundTxRef = customerRef.collection("transactions").doc();
      transaction.update(customerRef, "wallet.balance", admin.firestore.FieldValue.increment(amount));
      transaction.set(refundTxRef, {
        title: "Agent Wallet Withdrawal Reversal",
        amount,
        type: "CREDIT",
        status: "COMPLETED",
        timestamp: now,
        note: args.reason,
        source: AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE,
        payoutRequestId: args.sessionRef.id,
      });

      if (senderTransactionIds.length > 0) {
        sessionPatch.refundProcessed = true;
        sessionPatch.refundAmount = amount;
        sessionPatch.refundReason = args.reason;
        sessionPatch.refundedAt = now;
        sessionPatch.refundTransactionId = refundTxRef.id;
      }
    }

    transaction.set(args.sessionRef, sessionPatch, {merge: true});
  });

  if (customerUserId) {
    await finalizeSenderTransactionsForPayout(
      customerUserId,
      args.sessionRef,
      args.sessionData,
      "FAILED"
    );
  }

  const refreshed = await args.sessionRef.get();
  return refreshed.data() || args.sessionData;
};

const expireAgentCustomerWalletWithdrawalIfNeeded = async (
  sessionRef: FirebaseFirestore.DocumentReference,
  sessionData: FirebaseFirestore.DocumentData
): Promise<FirebaseFirestore.DocumentData> => {
  const flowStage = String(sessionData.flowStage || "").trim().toUpperCase();
  const status = String(sessionData.status || "").trim().toUpperCase();
  if (["COMPLETED", "FAILED", "CANCELLED", "EXPIRED", "REVERSED"].includes(flowStage) ||
    ["COMPLETED", "FAILED", "CANCELLED", "EXPIRED", "REVERSED"].includes(status)) {
    return sessionData;
  }

  const nowMs = Date.now();
  const otpExpiresAtMs = toMillisTimestamp(sessionData.otpExpiresAt) || Number(sessionData.otpExpiresAtMs || 0);
  if (
    ["OTP_SENT", "OTP_VERIFIED"].includes(flowStage) &&
    Number.isFinite(otpExpiresAtMs) &&
    otpExpiresAtMs > 0 &&
    otpExpiresAtMs <= nowMs
  ) {
    const now = admin.firestore.Timestamp.now();
    await sessionRef.set({
      status: "EXPIRED",
      flowStage: "EXPIRED",
      failureReason: "Customer phone verification expired.",
      expiredAt: now,
      updatedAt: now,
      processedAt: now,
    }, {merge: true});
    const refreshed = await sessionRef.get();
    return refreshed.data() || sessionData;
  }

  const reservationExpiresAtMs =
    toMillisTimestamp(sessionData.cashHandoverExpiresAt) ||
    Number(sessionData.cashHandoverExpiresAtMs || 0) ||
    toMillisTimestamp(sessionData.fundsReservationExpiresAt) ||
    Number(sessionData.fundsReservationExpiresAtMs || 0);
  if (
    ["CUSTOMER_APPROVED", "FUNDS_RESERVED", "CASH_HANDOVER_PENDING"].includes(flowStage) &&
    Number.isFinite(reservationExpiresAtMs) &&
    reservationExpiresAtMs > 0 &&
    reservationExpiresAtMs <= nowMs
  ) {
    return reverseAgentCustomerWalletWithdrawalReservation({
      sessionRef,
      sessionData,
      finalStatus: "REVERSED",
      finalStage: "REVERSED",
      reason: "Cash handover confirmation expired before completion.",
    });
  }

  return sessionData;
};

const AGENT_PAYOUT_ATTEMPT_WINDOW_MS = 5 * 60 * 1000;
const AGENT_PAYOUT_MAX_ATTEMPTS_PER_WINDOW = 10;

export const createAgentPayoutCode = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    assertTransactionOnlyCashServicesDisabled();
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in to perform this action.");
    }

    const senderId = context.auth.uid;
    const payload = (data || {}) as CreateAgentPayoutCodeRequest;
    const amount = roundMoney(Number(payload.amount || 0));
    const currency = asNonEmptyString(payload.currency)?.toUpperCase() || "USD";
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new functions.https.HttpsError("invalid-argument", "Amount must be a positive number.");
    }

    const userRef = db.collection("users").doc(senderId);
    const payoutRef = db.collection("payout_requests").doc();
    const expiresAtMs = Date.now() + AGENT_PAYOUT_CODE_TTL_MS;
    const expiresAt = admin.firestore.Timestamp.fromMillis(expiresAtMs);

    let responseMessage = "Agent cash-out code created.";
    let reservedFee = 0;
    let reservedFeeRate = 0;
    let reservedTotalDebit = amount;
    let generatedSecretCode = "";

    for (let attempt = 0; attempt < AGENT_PAYOUT_CODE_GENERATION_MAX_ATTEMPTS; attempt++) {
      const candidateCode = generateAgentPayoutSecretCode();
      const codeRef = agentPayoutCodeRef(candidateCode);
      try {
        await db.runTransaction(async (transaction) => {
          const [userSnap, codeSnap] = await Promise.all([
            transaction.get(userRef),
            transaction.get(codeRef),
          ]);
          if (!userSnap.exists) {
            throw new functions.https.HttpsError("not-found", "User account not found.");
          }
          if (codeSnap.exists) {
            throw new Error("AGENT_PAYOUT_CODE_COLLISION");
          }

          const userData = (userSnap.data() || {}) as Record<string, unknown>;
          const feeSettingsRef = db.collection("app_config").doc("fee_settings");
          const feeSettingsSnap = await transaction.get(feeSettingsRef);
          const feeSettingsData = (feeSettingsSnap.data() || {}) as Record<string, unknown>;
          const shareConfig = resolveAgentCashoutShareConfigFromFeeSettings(feeSettingsData);
          const feeInfo = isStaffFeeExempt(
            userData,
            context.auth?.token as Record<string, unknown> | undefined
          ) ? {rate: 0, fee: 0} : calculateAgentCashOutFee(amount);
          const totalDebit = roundMoney(amount + feeInfo.fee);
          const {agentShare, ownerShare, agentShareRate, ownerShareRate} = splitAgentCashOutFee(
            feeInfo.fee,
            shareConfig
          );
          const now = admin.firestore.Timestamp.now();
          const senderTxRef = userRef.collection("transactions").doc();
          reservedFee = feeInfo.fee;
          reservedFeeRate = feeInfo.rate;
          reservedTotalDebit = totalDebit;
          generatedSecretCode = candidateCode;

          let providerMirrorTransactionId: string | null = null;
          if (userUsesProviderHostedWallet(userData)) {
            const walletSnap = await transaction.get(providerWalletRef(senderId));
            const wallet = parseProviderWalletMirrorRecord(
              senderId,
              walletSnap.exists ? (walletSnap.data() || {}) as Record<string, unknown> : undefined,
              userData
            );
            const spendableBalance = getProviderWalletSpendableCents(wallet);
            const totalDebitCents = amountToCents(totalDebit);
            if (spendableBalance < totalDebitCents) {
              throw new functions.https.HttpsError("failed-precondition", "Insufficient hosted wallet balance.");
            }
            const providerMirror = createPendingProviderMirrorTransactionInTransaction({
              transaction,
              userId: senderId,
              wallet,
              type: ProviderMirrorTransactionType.Withdrawal,
              amountCents: totalDebitCents,
              currency: wallet.currency,
              lane: WalletProductLane.ProviderHostedWallet,
              localReference: payoutRef.id,
              idempotencyKey: payoutRef.id,
              providerCustomerId: wallet.providerCustomerId || null,
              providerMessage: "Agent cash-out code reserved.",
            });
            providerMirrorTransactionId = providerMirror.txRef.id;
          } else {
            throw legacyWalletCustodyDisabledError("Agent cash-out");
          }

          transaction.set(senderTxRef, {
            title: "Agent Cash-out (Pending)",
            amount: -totalDebit,
            fee: feeInfo.fee,
            type: "DEBIT",
            status: "PENDING",
            timestamp: now,
            note: "Agent cash-out code reserved against the mirrored provider balance. Redeem within 15 minutes.",
            source: "WALLET_AGENT",
            provider: "AFRIEX",
            payoutRequestId: payoutRef.id,
          });

          transaction.set(codeRef, {
            payoutRequestId: payoutRef.id,
            senderId,
            secretCode: candidateCode,
            status: "RESERVED",
            expiresAt,
            expiresAtMs,
            createdAt: now,
            updatedAt: now,
          });
          transaction.set(payoutRef, {
            senderId,
            amount,
            currency,
            secretCode: candidateCode,
            status: "PENDING",
            type: "AGENT_CASH_OUT",
            reservationStatus: "RESERVED",
            walletDebitedAmount: totalDebit,
            fee: feeInfo.fee,
            feeRate: feeInfo.rate,
            agentShare,
            ownerShare,
            agentShareRate,
            ownerShareRate,
            source: AFRIEX_HOSTED_AGENT_CASH_OUT_SOURCE,
            fundingSource: AFRIEX_HOSTED_WALLET_FUNDING_SOURCE,
            processor: "AFRIEX",
            providerMirrorTransactionId,
            senderTransactionIds: [senderTxRef.id],
            expiresAt,
            expiresAtMs,
            createdAt: now,
            updatedAt: now,
          }, {merge: true});

          responseMessage = `Agent cash-out code created. ${totalDebit.toFixed(2)} ${currency} is reserved for 15 minutes while the code stays active.`;
        });
        break;
      } catch (error) {
        if (error instanceof Error && error.message === "AGENT_PAYOUT_CODE_COLLISION") {
          continue;
        }
        throw error;
      }
    }

    if (!generatedSecretCode) {
      throw new functions.https.HttpsError(
        "resource-exhausted",
        "Could not allocate a unique cash-out code. Please try again."
      );
    }

    return {
      success: true,
      payoutRequestId: payoutRef.id,
      secretCode: generatedSecretCode,
      expiresAtMs,
      fee: reservedFee,
      feeRate: reservedFeeRate,
      totalDebit: reservedTotalDebit,
      message: responseMessage,
    };
  });

export const processAgentCashIn = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    assertTransactionOnlyCashServicesDisabled();
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in to perform this action.");
    }

    const agentId = context.auth.uid;
    const payload = (data || {}) as AgentCashInRequest;
    const recipientId = asNonEmptyString(payload.recipientId, payload.targetUserId);
    const amount = roundMoney(Number(payload.amount || 0));
    const currency = asNonEmptyString(payload.currency)?.toUpperCase() || "USD";

    if (!recipientId) {
      throw new functions.https.HttpsError("invalid-argument", "recipientId is required.");
    }
    if (recipientId === agentId) {
      throw new functions.https.HttpsError("invalid-argument", "Agents cannot cash in to their own wallet.");
    }
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new functions.https.HttpsError("invalid-argument", "Amount must be a positive number.");
    }

    const agentRef = db.collection("users").doc(agentId);
    const agentSnap = await agentRef.get();
    if (!agentSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Agent account not found.");
    }
    const agentData = (agentSnap.data() || {}) as Record<string, unknown>;
    if (!isAuthorizedAgentOperator(agentData, (context.auth?.token || {}) as Record<string, unknown>)) {
      throw new functions.https.HttpsError("permission-denied", "You must be an authorized agent or staff operator.");
    }
    if (!userUsesProviderHostedWallet(agentData)) {
      throw legacyWalletCustodyDisabledError("Agent cash-in");
    }

    let hostedWallet = await loadProviderWalletMirrorRecord(agentId, agentData);
    if (!hostedWallet.providerCustomerId) {
      hostedWallet = await provisionAfriexHostedWalletMirror({
        uid: agentId,
        rootData: agentData,
        requestedCurrency: hostedWallet.currency,
      });
    }

    const walletCurrency = normalizeProviderWalletCurrency(
      currency,
      hostedWallet.currency,
      "USD"
    );
    if (walletCurrency !== hostedWallet.currency) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        `Agent cash-in must use your Afriex wallet currency (${hostedWallet.currency}).`
      );
    }

    const routeInfo = await resolveAfriexHostedWalletAppUserRecipientRoute({
      recipientUserId: recipientId,
    });
    const payoutFx = await buildMobileMoneyPayoutFxQuote({
      amount,
      sourceCurrency: hostedWallet.currency,
      localCurrency: routeInfo.recipientCurrency,
      senderData: agentData,
      authToken: (context.auth?.token || {}) as Record<string, unknown>,
      direction: "AGENT_CASH_IN",
      destinationCountry: routeInfo.recipientCountry,
      destinationRoute: routeInfo.payoutRoute,
    });

    const payoutRequestRef = db.collection("payout_requests").doc();
    const amountCents = amountToCents(amount);
    const idempotencyKey = `agent_cash_in_${payoutRequestRef.id}`;
    const recipientLabel = `${routeInfo.recipientName} via ${routeInfo.payoutRoute === "BANK_ACCOUNT" ? "bank deposit" : "mobile money"}`;

    await db.runTransaction(async (transaction) => {
      const [freshAgentSnap, walletSnap] = await Promise.all([
        transaction.get(agentRef),
        transaction.get(providerWalletRef(agentId)),
      ]);
      if (!freshAgentSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Agent account not found.");
      }

      const freshAgentData = (freshAgentSnap.data() || {}) as Record<string, unknown>;
      if (!isAuthorizedAgentOperator(freshAgentData, (context.auth?.token || {}) as Record<string, unknown>)) {
        throw new functions.https.HttpsError("permission-denied", "You must be an authorized agent or staff operator.");
      }
      if (!userUsesProviderHostedWallet(freshAgentData)) {
        throw legacyWalletCustodyDisabledError("Agent cash-in");
      }

      const freshWallet = parseProviderWalletMirrorRecord(
        agentId,
        walletSnap.exists ? (walletSnap.data() || {}) as Record<string, unknown> : undefined,
        freshAgentData
      );
      if (freshWallet.provider !== WalletRuntimeProvider.Afriex || !freshWallet.providerCustomerId) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Afriex hosted wallet setup is incomplete for this agent."
        );
      }
      if (normalizeProviderWalletCurrency(freshWallet.currency) !== walletCurrency) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          `Agent cash-in must use your Afriex wallet currency (${freshWallet.currency}).`
        );
      }
      if (getProviderWalletSpendableCents(freshWallet) < amountCents) {
        throw new functions.https.HttpsError("failed-precondition", "Insufficient hosted wallet balance.");
      }

      const providerMirror = createPendingProviderMirrorTransactionInTransaction({
        transaction,
        userId: agentId,
        wallet: freshWallet,
        type: ProviderMirrorTransactionType.Transfer,
        amountCents,
        currency: walletCurrency,
        lane: WalletProductLane.Remittance,
        localReference: payoutRequestRef.id,
        idempotencyKey,
        providerCustomerId: freshWallet.providerCustomerId,
        providerMessage: "Awaiting Afriex agent cash-in settlement.",
      });
      const senderTxRef = agentRef.collection("transactions").doc();

      const payoutRequestData: FirebaseFirestore.DocumentData = {
        senderId: agentId,
        recipientUserId: routeInfo.recipientUserId || null,
        recipientPaymentMethodId: routeInfo.recipientPaymentMethodId || null,
        recipientInfo: routeInfo.recipientInfo,
        recipientName: routeInfo.recipientName,
        recipientNetwork: routeInfo.recipientNetwork || null,
        recipientPhone: routeInfo.recipientPhone || null,
        recipientCountry: routeInfo.recipientCountry,
        amount,
        amountInLocalCurrency: payoutFx.localAmount,
        localAmount: payoutFx.localAmount,
        localCurrency: payoutFx.localCurrency,
        currency: walletCurrency,
        walletCurrency,
        fx: payoutFx.fx,
        status: "PENDING_PROVIDER",
        type: "BENEFICIARY_TRANSFER",
        source: AFRIEX_HOSTED_WALLET_TRANSFER_SOURCE,
        fundingSource: AFRIEX_HOSTED_WALLET_FUNDING_SOURCE,
        afriexPayoutRoute: routeInfo.payoutRoute,
        providerMirrorTransactionId: providerMirror.txRef.id,
        senderTransactionIds: [senderTxRef.id],
        createdAt: admin.firestore.Timestamp.now(),
        processedAt: admin.firestore.Timestamp.now(),
        note: `Agent cash-in for ${routeInfo.recipientName}.`,
      };

      const authorizationPatch = buildMobileMoneyProviderAuthorizationPatch(
        payoutRequestRef.id,
        payoutRequestData,
        "processAgentCashIn"
      );
      transaction.set(payoutRequestRef, {
        ...payoutRequestData,
        ...authorizationPatch,
      });

      transaction.set(senderTxRef, {
        title: "Agent Cash-In (Pending)",
        amount: -amount,
        type: "DEBIT",
        status: "PENDING",
        timestamp: admin.firestore.Timestamp.now(),
        note: `Agent deposit to ${recipientLabel}.`,
        source: AFRIEX_HOSTED_WALLET_TRANSFER_SOURCE,
        payoutRequestId: payoutRequestRef.id,
        recipientId,
        recipientUserId: recipientId,
        recipientName: routeInfo.recipientName,
      });
    });

    return {
      success: true,
      message: routeInfo.payoutRoute === "BANK_ACCOUNT" ?
        `Agent deposit queued for ${routeInfo.recipientName}. Bank settlement is now processing.` :
        `Agent deposit queued for ${routeInfo.recipientName}. Mobile money payout is now processing.`,
      payoutRequestId: payoutRequestRef.id,
    };
  });

export const agentLookupCustomerByPhone = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerPhoneLookupRequest;
    return buildAgentCustomerLookupResponse(payload);
  });

export const agentStartCustomerWithdrawal = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    throw legacyWalletCustodyDisabledError("Agent customer wallet withdrawals");
    const {uid: agentId, userData: agentData} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerWalletWithdrawalRequest;
    const amount = roundMoney(Number(payload.amount || 0));
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new functions.https.HttpsError("invalid-argument", "Amount must be a positive number.");
    }

    const country = asNonEmptyString(payload.country) || "";
    const network = asNonEmptyString(payload.network) || "";
    const customer = await resolveAgentWalletCustomerByPhone({
      phoneNumber: payload.phoneNumber,
      expectedCustomerUserId: asNonEmptyString(payload.customerUserId),
    });
    await assertNoActiveAgentCustomerPortalSession({
      agentId,
      phoneE164: customer.phoneE164,
    });
    if (!isProfileOperational(customer.userData.profileStatus)) {
      throw new functions.https.HttpsError("failed-precondition", "Customer profile is not active for wallet withdrawal.");
    }
    assertLegacyInternalWalletAllowed(agentData, "Agent customer wallet withdrawal");
    assertLegacyInternalWalletAllowed(customer.userData, "Customer wallet withdrawal via agent");

    const walletCurrency = normalizeIsoCurrencyForFx(
      ((customer.userData.wallet || {}) as Record<string, unknown>).currency,
      "USD"
    ) || "USD";
    const requestedCurrency = normalizeIsoCurrencyForFx(payload.currency, walletCurrency) || walletCurrency;
    if (requestedCurrency !== walletCurrency) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Wallet withdrawal currency must match the customer's wallet currency."
      );
    }

    const spendableBalance = getWalletSpendableBalance(customer.userData);
    if (spendableBalance < amount) {
      throw new functions.https.HttpsError("failed-precondition", "Amount exceeds the customer's withdrawable balance.");
    }

    const localCurrency = resolveMobileMoneyCurrency({country, network}) || walletCurrency;
    const fxQuote = localCurrency === walletCurrency ?
      {
        localAmount: amount,
        localCurrency,
      } :
      await buildMobileMoneyPayoutFxQuote({
        amount,
        sourceCurrency: walletCurrency,
        localCurrency,
        senderData: agentData,
        authToken: (context.auth?.token || {}) as Record<string, unknown>,
        direction: "AGENT_CUSTOMER_WALLET_WITHDRAWAL",
        destinationCountry: country,
        destinationRoute: "MOBILE_MONEY",
      });

    await sendMobileMoneyPhoneOtpCode(customer.phoneE164);

    const sessionRef = db.collection("payout_requests").doc();
    const now = admin.firestore.Timestamp.now();
    const otpExpiresAtMs = Date.now() + AGENT_CUSTOMER_WALLET_WITHDRAWAL_OTP_TTL_MS;
    const sessionData: FirebaseFirestore.DocumentData = {
      type: AGENT_CUSTOMER_WALLET_WITHDRAWAL_TYPE,
      status: "PENDING",
      flowStage: "OTP_SENT",
      authMode: "PHONE_OTP",
      agentId,
      customerUserId: customer.uid,
      customerPhoneE164: customer.phoneE164,
      customerMaskedName: maskAgentCustomerName(getUserDisplayName(customer.userData)),
      customerMaskedPhone: maskPhoneNumberForOtp(customer.phoneE164),
      country,
      network,
      amount,
      currency: walletCurrency,
      localAmount: "localAmount" in fxQuote ? fxQuote.localAmount : amount,
      localCurrency: "localCurrency" in fxQuote ? fxQuote.localCurrency : walletCurrency,
      maxWithdrawableAmount: spendableBalance,
      otpSentAt: now,
      otpExpiresAt: admin.firestore.Timestamp.fromMillis(otpExpiresAtMs),
      otpExpiresAtMs,
      otpAttemptCount: 0,
      riskFlags: [],
      source: AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE,
      createdAt: now,
      updatedAt: now,
      processedAt: now,
    };
    await sessionRef.set(sessionData, {merge: true});

    return {
      ...buildAgentCustomerWalletSessionResponse(sessionRef.id, sessionData),
      message: `Verification code sent to ${maskPhoneNumberForOtp(customer.phoneE164)}.`,
    };
  });

export const agentVerifyCustomerWithdrawalOtp = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    throw legacyWalletCustodyDisabledError("Agent customer wallet withdrawals");
    const {uid: agentId} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerWalletOtpRequest;
    const sessionId = asNonEmptyString(payload.sessionId);
    const otpCode = String(payload.otpCode || "").trim();
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }
    if (!new RegExp(`^\\d{${MOBILE_MONEY_PHONE_OTP_CODE_LENGTH}}$`).test(otpCode)) {
      throw new functions.https.HttpsError("invalid-argument", "OTP code must be exactly 6 digits.");
    }

    const {ref: sessionRef, data: rawSessionData} = await loadAgentCustomerWalletSession(sessionId, agentId);
    const sessionData = await expireAgentCustomerWalletWithdrawalIfNeeded(sessionRef, rawSessionData);
    if (String(sessionData.flowStage || "").trim().toUpperCase() !== "OTP_SENT") {
      throw new functions.https.HttpsError("failed-precondition", "This withdrawal session is not waiting for an OTP.");
    }

    const currentAttempts = Math.max(0, Math.trunc(Number(sessionData.otpAttemptCount || 0)));
    if (currentAttempts >= AGENT_CUSTOMER_WALLET_WITHDRAWAL_MAX_OTP_ATTEMPTS) {
      throw new functions.https.HttpsError(
        "permission-denied",
        "Too many invalid attempts. Start a new wallet-withdrawal session."
      );
    }

    const verificationResult = await verifyMobileMoneyPhoneOtpCode(
      asNonEmptyString(sessionData.customerPhoneE164) || "",
      otpCode
    );
    const now = admin.firestore.Timestamp.now();
    if (!verificationResult.approved) {
      const nextAttempts = currentAttempts + 1;
      const shouldFail = nextAttempts >= AGENT_CUSTOMER_WALLET_WITHDRAWAL_MAX_OTP_ATTEMPTS;
      await sessionRef.set({
        otpAttemptCount: nextAttempts,
        lastOtpProviderStatus: verificationResult.status,
        status: shouldFail ? "FAILED" : (asNonEmptyString(sessionData.status) || "PENDING"),
        flowStage: shouldFail ? "FAILED" : "OTP_SENT",
        failureReason: shouldFail ? "Too many invalid OTP attempts." : admin.firestore.FieldValue.delete(),
        failedAt: shouldFail ? now : admin.firestore.FieldValue.delete(),
        updatedAt: now,
        processedAt: now,
      }, {merge: true});

      if (shouldFail) {
        throw new functions.https.HttpsError(
          "permission-denied",
          "Too many invalid attempts. Start a new wallet-withdrawal session."
        );
      }
      throw new functions.https.HttpsError("permission-denied", "Invalid verification code.");
    }

    await sessionRef.set({
      otpAttemptCount: currentAttempts + 1,
      flowStage: "OTP_VERIFIED",
      otpVerifiedAt: now,
      lastOtpProviderStatus: verificationResult.status,
      updatedAt: now,
      processedAt: now,
    }, {merge: true});

    const refreshed = await sessionRef.get();
    return {
      ...buildAgentCustomerWalletSessionResponse(sessionId, refreshed.data() || sessionData),
      nextAction: "REQUEST_CUSTOMER_APPROVAL",
      message: "Customer phone verification passed. Continue to reserve wallet funds.",
    };
  });

export const agentRequestCustomerWithdrawalApproval = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    throw legacyWalletCustodyDisabledError("Agent customer wallet withdrawals");
    const {uid: agentId} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerWalletSessionRequest;
    const sessionId = asNonEmptyString(payload.sessionId);
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const {ref: sessionRef, data: rawSessionData} = await loadAgentCustomerWalletSession(sessionId, agentId);
    const sessionData = await expireAgentCustomerWalletWithdrawalIfNeeded(sessionRef, rawSessionData);
    const stage = String(sessionData.flowStage || "").trim().toUpperCase();
    if (stage === "FUNDS_RESERVED" || stage === "CASH_HANDOVER_PENDING") {
      return buildAgentCustomerWalletSessionResponse(sessionId, sessionData);
    }
    if (stage !== "OTP_VERIFIED") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Customer phone verification must complete before wallet funds can be reserved."
      );
    }

    const amount = roundMoney(Number(sessionData.amount || 0));
    const customerUserId = asNonEmptyString(sessionData.customerUserId);
    if (!customerUserId || amount <= 0) {
      throw new functions.https.HttpsError("failed-precondition", "Session is missing customer or amount details.");
    }

    const reservationExpiresAtMs = Date.now() + AGENT_CUSTOMER_WALLET_WITHDRAWAL_RESERVATION_TTL_MS;
    await db.runTransaction(async (transaction) => {
      const freshSessionSnap = await transaction.get(sessionRef);
      if (!freshSessionSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Withdrawal session not found.");
      }
      const freshSessionData = freshSessionSnap.data() || sessionData;
      const freshStage = String(freshSessionData.flowStage || "").trim().toUpperCase();
      if (freshStage === "FUNDS_RESERVED" || freshStage === "CASH_HANDOVER_PENDING") {
        return;
      }
      if (freshStage !== "OTP_VERIFIED") {
        throw new functions.https.HttpsError("failed-precondition", "Wallet funds cannot be reserved in the current session state.");
      }

      const customerRef = db.collection("users").doc(customerUserId);
      const customerSnap = await transaction.get(customerRef);
      if (!customerSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Customer account not found.");
      }
      const customerData = (customerSnap.data() || {}) as Record<string, unknown>;
      assertLegacyInternalWalletAllowed(customerData, "Customer wallet withdrawal via agent");
      if (getWalletSpendableBalance(customerData) < amount) {
        transaction.set(sessionRef, {
          status: "FAILED",
          flowStage: "FAILED",
          failureReason: "Customer wallet balance is no longer sufficient.",
          failedAt: admin.firestore.Timestamp.now(),
          updatedAt: admin.firestore.Timestamp.now(),
          processedAt: admin.firestore.Timestamp.now(),
        }, {merge: true});
        throw new functions.https.HttpsError("failed-precondition", "Customer wallet balance is no longer sufficient.");
      }

      const now = admin.firestore.Timestamp.now();
      const customerTxRef = customerRef.collection("transactions").doc();
      transaction.update(customerRef, "wallet.balance", admin.firestore.FieldValue.increment(-amount));
      transaction.set(customerTxRef, {
        title: "Agent Wallet Withdrawal (Pending)",
        amount: -amount,
        type: "DEBIT",
        status: "PENDING",
        timestamp: now,
        note: "Wallet withdrawal reserved for agent cash handover.",
        source: AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE,
        payoutRequestId: sessionId,
      });
      transaction.set(sessionRef, {
        status: "PENDING",
        flowStage: "FUNDS_RESERVED",
        customerApprovedAt: now,
        fundsReservedAt: now,
        fundsReservationExpiresAt: admin.firestore.Timestamp.fromMillis(reservationExpiresAtMs),
        fundsReservationExpiresAtMs: reservationExpiresAtMs,
        cashHandoverExpiresAt: admin.firestore.Timestamp.fromMillis(reservationExpiresAtMs),
        cashHandoverExpiresAtMs: reservationExpiresAtMs,
        walletDebitedAmount: amount,
        senderTransactionIds: [customerTxRef.id],
        updatedAt: now,
        processedAt: now,
      }, {merge: true});
    });

    const refreshed = await sessionRef.get();
    return {
      ...buildAgentCustomerWalletSessionResponse(sessionId, refreshed.data() || sessionData),
      message: "Wallet funds reserved. Hand over cash, then confirm completion.",
    };
  });

