export const agentConfirmCustomerCashHandover = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    throw legacyWalletCustodyDisabledError("Agent customer wallet withdrawals");
    const {uid: agentId} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerWalletSessionRequest;
    const sessionId = asNonEmptyString(payload.sessionId);
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const {ref: sessionRef, data: rawSessionData} = await loadAgentCustomerWalletSession(sessionId, agentId);
    const sessionData = await expireAgentCustomerWalletWithdrawalIfNeeded(sessionRef, rawSessionData);
    const initialStage = String(sessionData.flowStage || "").trim().toUpperCase();
    if (!["CUSTOMER_APPROVED", "FUNDS_RESERVED", "CASH_HANDOVER_PENDING"].includes(initialStage)) {
      throw new functions.https.HttpsError("failed-precondition", "This session is not ready for cash handover confirmation.");
    }

    const amount = roundMoney(Number(sessionData.walletDebitedAmount || sessionData.amount || 0));
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new functions.https.HttpsError("failed-precondition", "Withdrawal session amount is invalid.");
    }

    const agentRef = db.collection("users").doc(agentId);
    await db.runTransaction(async (transaction) => {
      const [freshSessionSnap, agentSnap] = await Promise.all([
        transaction.get(sessionRef),
        transaction.get(agentRef),
      ]);
      if (!freshSessionSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Withdrawal session not found.");
      }
      if (!agentSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Agent account not found.");
      }

      const freshSessionData = freshSessionSnap.data() || sessionData;
      const freshStage = String(freshSessionData.flowStage || "").trim().toUpperCase();
      const freshStatus = String(freshSessionData.status || "").trim().toUpperCase();
      if (freshStage === "COMPLETED" || freshStatus === "COMPLETED") {
        return;
      }
      if (!["CUSTOMER_APPROVED", "FUNDS_RESERVED", "CASH_HANDOVER_PENDING"].includes(freshStage)) {
        throw new functions.https.HttpsError("failed-precondition", "This session is not ready for completion.");
      }

      const now = admin.firestore.Timestamp.now();
      const agentData = (agentSnap.data() || {}) as Record<string, unknown>;
      assertLegacyInternalWalletAllowed(agentData, "Agent customer wallet withdrawal settlement");
      const agentTxRef = agentRef.collection("transactions").doc();
      transaction.update(agentRef, "wallet.balance", admin.firestore.FieldValue.increment(amount));
      transaction.set(agentTxRef, {
        title: "Customer Wallet Withdrawal",
        amount,
        type: "CREDIT",
        status: "COMPLETED",
        timestamp: now,
        note: `Cash payout completed for ${asNonEmptyString(freshSessionData.customerMaskedName) || "customer"}.`,
        source: AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE,
        payoutRequestId: sessionId,
      });
      transaction.set(sessionRef, {
        status: "COMPLETED",
        flowStage: "COMPLETED",
        completedAt: now,
        cashConfirmedAt: now,
        agentWalletCreditedAt: now,
        updatedAt: now,
        processedAt: now,
      }, {merge: true});
    });

    const refreshed = await sessionRef.get();
    const refreshedData = refreshed.data() || sessionData;
    const customerUserId = asNonEmptyString(refreshedData.customerUserId);
    if (customerUserId) {
      await finalizeSenderTransactionsForPayout(
        customerUserId,
        sessionRef,
        refreshedData,
        "COMPLETED"
      );
    }
    return {
      ...buildAgentCustomerWalletSessionResponse(sessionId, refreshedData),
      message: "Cash handover confirmed and the agent wallet has been credited.",
    };
  });

export const agentCancelCustomerWithdrawal = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const {uid: agentId} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerWalletCancelRequest;
    const sessionId = asNonEmptyString(payload.sessionId);
    const reason = asNonEmptyString(payload.reason) || "CANCELLED_BY_AGENT";
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const {ref: sessionRef, data: rawSessionData} = await loadAgentCustomerWalletSession(sessionId, agentId);
    const sessionData = await expireAgentCustomerWalletWithdrawalIfNeeded(sessionRef, rawSessionData);
    const flowStage = String(sessionData.flowStage || "").trim().toUpperCase();
    const status = String(sessionData.status || "").trim().toUpperCase();
    if (["COMPLETED", "FAILED", "CANCELLED", "EXPIRED", "REVERSED"].includes(flowStage) ||
      ["COMPLETED", "FAILED", "CANCELLED", "EXPIRED", "REVERSED"].includes(status)) {
      return buildAgentCustomerWalletSessionResponse(sessionId, sessionData);
    }

    let finalData = sessionData;
    if (["CUSTOMER_APPROVED", "FUNDS_RESERVED", "CASH_HANDOVER_PENDING"].includes(flowStage)) {
      finalData = await reverseAgentCustomerWalletWithdrawalReservation({
        sessionRef,
        sessionData,
        finalStatus: "CANCELLED",
        finalStage: "CANCELLED",
        reason,
      });
    } else {
      const now = admin.firestore.Timestamp.now();
      await sessionRef.set({
        status: "CANCELLED",
        flowStage: "CANCELLED",
        failureReason: reason,
        cancelledAt: now,
        updatedAt: now,
        processedAt: now,
      }, {merge: true});
      const refreshed = await sessionRef.get();
      finalData = refreshed.data() || sessionData;
    }

    return {
      ...buildAgentCustomerWalletSessionResponse(sessionId, finalData),
      message: "Withdrawal session cancelled.",
    };
  });

export const agentProcessCustomerDepositByPhone = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    throw legacyWalletCustodyDisabledError("Agent customer wallet deposits");
    const {uid: agentId} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerWalletWithdrawalRequest;
    const amount = roundMoney(Number(payload.amount || 0));
    const currency = normalizeIsoCurrencyForFx(payload.currency, "USD") || "USD";
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new functions.https.HttpsError("invalid-argument", "Amount must be a positive number.");
    }

    const customer = await resolveAgentWalletCustomerByPhone({
      phoneNumber: payload.phoneNumber,
      expectedCustomerUserId: asNonEmptyString(payload.customerUserId),
    });
    if (customer.uid === agentId) {
      throw new functions.https.HttpsError("invalid-argument", "Agents cannot deposit into their own wallet from this portal flow.");
    }
    if (!isProfileOperational(customer.userData.profileStatus)) {
      throw new functions.https.HttpsError("failed-precondition", "Customer profile is not active for wallet deposit.");
    }
    assertLegacyInternalWalletAllowed(customer.userData, "Customer wallet deposit via agent");

    const agentRef = db.collection("users").doc(agentId);
    const customerRef = db.collection("users").doc(customer.uid);
    await db.runTransaction(async (transaction) => {
      const [agentSnap, customerSnap] = await Promise.all([
        transaction.get(agentRef),
        transaction.get(customerRef),
      ]);
      if (!agentSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Agent account not found.");
      }
      if (!customerSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Customer account not found.");
      }
      const agentData = (agentSnap.data() || {}) as Record<string, unknown>;
      assertLegacyInternalWalletAllowed(agentData, "Agent customer wallet deposit");
      const customerData = (customerSnap.data() || {}) as Record<string, unknown>;
      assertLegacyInternalWalletAllowed(customerData, "Customer wallet deposit via agent");
      if (getWalletSpendableBalance(agentData) < amount) {
        throw new functions.https.HttpsError("failed-precondition", "Insufficient wallet balance.");
      }

      const now = admin.firestore.Timestamp.now();
      const customerName = getUserDisplayName(customer.userData);
      const agentName = getUserDisplayName(agentData);
      const agentTxRef = agentRef.collection("transactions").doc();
      const customerTxRef = customerRef.collection("transactions").doc();
      transaction.update(agentRef, "wallet.balance", admin.firestore.FieldValue.increment(-amount));
      transaction.update(customerRef, "wallet.balance", admin.firestore.FieldValue.increment(amount));
      transaction.set(agentTxRef, {
        title: "Customer Wallet Deposit",
        amount: -amount,
        type: "DEBIT",
        status: "COMPLETED",
        timestamp: now,
        note: `Wallet deposit to ${customerName}.`,
        source: AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE,
        recipientId: customer.uid,
      });
      transaction.set(customerTxRef, {
        title: "Agent Wallet Deposit",
        amount,
        type: "CREDIT",
        status: "COMPLETED",
        timestamp: now,
        note: `Wallet deposit from ${agentName}.`,
        source: AGENT_CUSTOMER_WALLET_DEPOSIT_SOURCE,
        agentId,
      });
    });

    return {
      success: true,
      message: `Wallet deposit completed for ${amount.toFixed(2)} ${currency}.`,
    };
  });

export const agentStartCustomerMobileMoneyCollection = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    const {uid: agentId, userData: agentData} = await assertAgentCustomerPortalOperator(context);
    if (!userUsesProviderHostedWallet(agentData)) {
      throw legacyWalletCustodyDisabledError("Agent customer mobile-money collection");
    }
    const payload = (data || {}) as AgentCustomerMobileMoneyCollectionStartRequest;
    const country = asNonEmptyString(payload.country) || "";
    const network = asNonEmptyString(payload.network) || "";
    const phoneE164 = normalizeMobileMoneyPhoneE164(payload.phoneNumber);
    const phoneDigits = normalizeDigits(phoneE164);
    const localAmount = roundMoney(Number(payload.localAmount || 0));
    if (phoneDigits.length < 8 || phoneDigits.length > 15) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Provide a valid customer phone number in international format."
      );
    }
    if (!Number.isFinite(localAmount) || localAmount <= 0) {
      throw new functions.https.HttpsError("invalid-argument", "Collection amount must be a positive number.");
    }
    await assertNoActiveAgentCustomerPortalSession({
      agentId,
      phoneE164,
    });

    const canonicalCountry = canonicalMobileMoneyCountry(country);
    if (!canonicalCountry) {
      throw new functions.https.HttpsError("invalid-argument", "Mobile-money collection is not supported for this country.");
    }
    assertMobileMoneyDepositCountrySupportedForConfiguredProvider(canonicalCountry);

    const resolvedLocalCurrency = resolveMobileMoneyCurrency({
      country: canonicalCountry,
      network,
    });
    if (!resolvedLocalCurrency) {
      throw new functions.https.HttpsError("invalid-argument", "Unable to resolve a mobile-money currency for this network.");
    }
    const requestedLocalCurrency = normalizeIsoCurrencyForFx(payload.localCurrency);
    if (requestedLocalCurrency && requestedLocalCurrency !== resolvedLocalCurrency) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        `Collection currency must match the selected network currency (${resolvedLocalCurrency}).`
      );
    }

    const hostedWallet = await provisionAfriexHostedWalletMirror({
      uid: agentId,
      rootData: agentData,
      requestedCurrency: normalizeIsoCurrencyForFx(
        ((agentData.wallet || {}) as Record<string, unknown>).currency,
        "USD"
      ) || "USD",
    });
    const agentWalletCurrency = hostedWallet.currency || "USD";
    const feeExempt = isStaffFeeExempt(agentData, (context.auth?.token || {}) as Record<string, unknown>);
    const fx = await fetchAppFxRate({
      fromCurrency: resolvedLocalCurrency,
      toCurrency: agentWalletCurrency,
      feeExempt,
    });
    const walletAmount = roundMoney(localAmount * fx.appRate);
    if (!Number.isFinite(walletAmount) || walletAmount <= 0) {
      throw new functions.https.HttpsError("failed-precondition", "Unable to compute the agent wallet credit for this collection.");
    }

    const phoneMatch = await resolveAgentCustomerPhoneMatchSummary(phoneE164, phoneDigits);
    const sessionRef = db.collection("payout_requests").doc();
    const walletAmountCents = amountToCents(walletAmount);
    let sessionData: FirebaseFirestore.DocumentData = {};

    await db.runTransaction(async (transaction) => {
      const [freshAgentSnap, walletSnap] = await Promise.all([
        transaction.get(db.collection("users").doc(agentId)),
        transaction.get(providerWalletRef(agentId)),
      ]);
      if (!freshAgentSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Agent account not found.");
      }
      const freshAgentData = (freshAgentSnap.data() || {}) as Record<string, unknown>;
      if (!userUsesProviderHostedWallet(freshAgentData)) {
        throw legacyWalletCustodyDisabledError("Agent customer mobile-money collection");
      }
      const wallet = parseProviderWalletMirrorRecord(
        agentId,
        walletSnap.exists ? (walletSnap.data() || {}) as Record<string, unknown> : undefined,
        freshAgentData
      );
      const now = admin.firestore.Timestamp.now();
      const senderTxRef = db.collection("users").doc(agentId).collection("transactions").doc();
      const providerMirror = createPendingProviderMirrorTransactionInTransaction({
        transaction,
        userId: agentId,
        wallet,
        type: ProviderMirrorTransactionType.TopUp,
        amountCents: walletAmountCents,
        currency: agentWalletCurrency,
        lane: WalletProductLane.ProviderHostedWallet,
        localReference: sessionRef.id,
        idempotencyKey: sessionRef.id,
        providerCustomerId: wallet.providerCustomerId || hostedWallet.providerCustomerId || null,
        providerMessage: "Agent customer mobile-money collection started.",
      });
      sessionData = {
        senderId: agentId,
        agentId,
        type: "CASH_IN",
        status: "PENDING_PROVIDER",
        source: AGENT_CUSTOMER_MOBILE_COLLECTION_SOURCE,
        fundingSource: "EXTERNAL_MOBILE_MONEY",
        amount: walletAmount,
        currency: agentWalletCurrency,
        walletCurrency: agentWalletCurrency,
        localAmount,
        localCurrency: resolvedLocalCurrency,
        phone: phoneE164,
        recipientPhone: phoneE164,
        network,
        recipientNetwork: network,
        country: canonicalCountry,
        dialCode: getMobileMoneyDialCodeForCountry(canonicalCountry) || null,
        customerType: phoneMatch.customerType,
        customerUserId: phoneMatch.customerUserId,
        customerPhoneE164: phoneE164,
        customerMaskedName: phoneMatch.maskedName,
        customerMaskedPhone: maskPhoneNumberForOtp(phoneE164),
        agentCustomerPortalFlowStage: "COLLECTION_PENDING",
        riskFlags: phoneMatch.riskFlags,
        processor: "AFRIEX",
        collectionProcessor: "AFRIEX",
        providerMirrorTransactionId: providerMirror.txRef.id,
        providerMessage: "Collection request queued for Afriex confirmation.",
        senderTransactionIds: [senderTxRef.id],
        fx: {
          fromCurrency: resolvedLocalCurrency,
          toCurrency: agentWalletCurrency,
          rate: fx.appRate,
          realRate: fx.realRate,
          margin: fx.realRate > 0 ? Math.max(0, (fx.realRate - fx.appRate) / fx.realRate) : 0,
          provider: fx.provider,
          fetchedAtMs: fx.fetchedAtMs,
          requestUrl: fx.requestUrl,
          feeExempt,
          direction: "AGENT_CUSTOMER_MM_COLLECTION",
        },
        timestamp: now,
        createdAt: now,
        processedAt: now,
      };
      const authorizationPatch = buildMobileMoneyProviderAuthorizationPatch(
        sessionRef.id,
        sessionData,
        "agentStartCustomerMobileMoneyCollection:providerHosted"
      );

      transaction.set(senderTxRef, {
        title: "Agent Mobile Money Collection (Pending)",
        amount: walletAmount,
        type: "CREDIT",
        status: "PENDING",
        timestamp: now,
        note: `Customer collection from ${maskPhoneNumberForOtp(phoneE164)} (${canonicalCountry}) - provider collection ${localAmount.toFixed(2)} ${resolvedLocalCurrency}, mirrored balance credit pending ${walletAmount.toFixed(2)} ${agentWalletCurrency}.`,
        source: "AGENT_CUSTOMER_MM_COLLECTION",
        provider: "AFRIEX",
        payoutRequestId: sessionRef.id,
      });
      transaction.set(sessionRef, {
        ...sessionData,
        ...authorizationPatch,
      }, {merge: true});
      sessionData = {
        ...sessionData,
        ...authorizationPatch,
      };
    });

    return {
      ...buildAgentCustomerMobileMoneyCollectionSessionResponse(sessionRef.id, sessionData),
      message: "Approval request sent. Ask the customer to confirm it on their phone.",
    };
  });

