export const agentConfirmCustomerMobileMoneyCollectionCashHandover = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const {uid: agentId} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerMobileMoneyCollectionSessionRequest;
    const sessionId = asNonEmptyString(payload.sessionId);
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const {ref: sessionRef, data: sessionData} = await loadAgentCustomerMobileMoneyCollectionSession(sessionId, agentId);
    const status = String(sessionData.status || "").trim().toUpperCase();
    if (status !== "COMPLETED") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "The collection has not completed yet. Wait for provider confirmation before giving cash."
      );
    }
    if (sessionData.cashConfirmedAt) {
      return buildAgentCustomerMobileMoneyCollectionSessionResponse(sessionId, sessionData);
    }

    const now = admin.firestore.Timestamp.now();
    await sessionRef.set({
      cashConfirmedAt: now,
      cashConfirmedAtMs: now.toMillis(),
      agentCustomerPortalFlowStage: "COMPLETED",
      processedAt: now,
    }, {merge: true});

    const refreshed = await sessionRef.get();
    return {
      ...buildAgentCustomerMobileMoneyCollectionSessionResponse(sessionId, refreshed.data() || sessionData),
      message: "Cash handover confirmed for this customer collection.",
    };
  });

export const agentCancelCustomerMobileMoneyCollection = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    await assertAgentCustomerPortalOperator(context);
    const {uid: agentId} = await assertAgentCustomerPortalOperator(context);
    const payload = (data || {}) as AgentCustomerMobileMoneyCollectionCancelRequest;
    const sessionId = asNonEmptyString(payload.sessionId);
    const reason = asNonEmptyString(payload.reason) || "CANCELLED_BY_AGENT";
    if (!sessionId) {
      throw new functions.https.HttpsError("invalid-argument", "sessionId is required.");
    }

    const {ref: sessionRef, data: sessionData} = await loadAgentCustomerMobileMoneyCollectionSession(sessionId, agentId);
    const status = String(sessionData.status || "").trim().toUpperCase();
    const providerStatus = String(sessionData.providerStatus || "").trim().toUpperCase();
    if (["FAILED", "CANCELLED", "REVERSED"].includes(status)) {
      return buildAgentCustomerMobileMoneyCollectionSessionResponse(sessionId, sessionData);
    }
    if (status === "COMPLETED") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "This collection already completed. Use reversal controls instead of canceling it."
      );
    }
    if (status === "PROCESSING_PROVIDER" || providerStatus === "PROCESSING") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "This collection is already being processed by the provider and can no longer be canceled here."
      );
    }
    const providerTransferId = asNonEmptyString(sessionData.providerTransferId, sessionData.providerReference);
    if (providerTransferId && providerStatus !== "WAITING_MANUAL_PROVIDER") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "This collection already has a provider reference and can no longer be canceled here."
      );
    }

    const now = admin.firestore.Timestamp.now();
    await sessionRef.set({
      status: "CANCELLED",
      providerStatus: providerStatus || "CANCELLED",
      providerMessage: reason,
      failureReason: reason,
      cancelledAt: now,
      agentCustomerPortalFlowStage: "CANCELLED",
      processedAt: now,
    }, {merge: true});

    await finalizeSenderTransactionsForPayout(
      agentId,
      sessionRef,
      {
        ...sessionData,
        status: "CANCELLED",
        failureReason: reason,
        providerMessage: reason,
      },
      "FAILED"
    );

    const refreshed = await sessionRef.get();
    return {
      ...buildAgentCustomerMobileMoneyCollectionSessionResponse(sessionId, refreshed.data() || sessionData),
      message: "Customer collection session cancelled.",
    };
  });

export const processAgentPayout = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    assertTransactionOnlyCashServicesDisabled();
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in to perform this action.");
    }
    const agentId = context.auth.uid;
    const ownerUserId = getAppConfig().ownerUserId;
    if (!ownerUserId) {
      throw new functions.https.HttpsError("failed-precondition", "Owner account is not configured.");
    }

    const agentDoc = await db.collection("users").doc(agentId).get();
    const agentData = (agentDoc.data() || {}) as Record<string, unknown>;
    if (!isAuthorizedAgentOperator(agentData, (context.auth?.token || {}) as Record<string, unknown>)) {
      throw new functions.https.HttpsError("permission-denied", "You must be an authorized agent or staff operator.");
    }

    const rawSecretCode = (data as AgentPayoutRequest).secretCode;
    if (!rawSecretCode || typeof rawSecretCode !== "string") {
      throw new functions.https.HttpsError("invalid-argument", "The function must be called with a 'secretCode'.");
    }
    const secretCode = rawSecretCode.trim();
    if (!/^\d{6}$/.test(secretCode)) {
      throw new functions.https.HttpsError("invalid-argument", "Secret code must be exactly 6 digits.");
    }

    functions.logger.log("Agent payout attempt started.", {
      agentId,
      secretCodeLast2: secretCode.slice(-2),
    });

    const attemptRef = db.collection("agent_payout_attempts").doc(agentId);
    const now = admin.firestore.Timestamp.now();
    const nowMs = now.toMillis();
    const attemptSnap = await attemptRef.get();
    const attemptData = (attemptSnap.data() || {}) as Record<string, unknown>;
    const windowStartedAtMs = Number(attemptData.windowStartedAtMs || 0);
    const withinAttemptWindow = windowStartedAtMs > 0 && (nowMs - windowStartedAtMs) < AGENT_PAYOUT_ATTEMPT_WINDOW_MS;
    const invalidAttemptCount = withinAttemptWindow ?
      Math.max(0, Math.trunc(Number(attemptData.invalidAttemptCount || 0))) :
      0;

    if (invalidAttemptCount >= AGENT_PAYOUT_MAX_ATTEMPTS_PER_WINDOW) {
      const retryAfterSeconds = Math.max(
        1,
        Math.ceil((AGENT_PAYOUT_ATTEMPT_WINDOW_MS - (nowMs - windowStartedAtMs)) / 1000)
      );
      throw new functions.https.HttpsError(
        "resource-exhausted",
        `Too many invalid payout attempts. Try again in ${retryAfterSeconds}s.`
      );
    }

    const recordInvalidAttempt = async () => {
      await attemptRef.set({
        invalidAttemptCount: invalidAttemptCount + 1,
        windowStartedAt: withinAttemptWindow ?
          (attemptData.windowStartedAt || admin.firestore.Timestamp.fromMillis(windowStartedAtMs)) :
          now,
        windowStartedAtMs: withinAttemptWindow ? windowStartedAtMs : nowMs,
        lastInvalidAttemptAt: now,
        lastInvalidAttemptAtMs: nowMs,
        updatedAt: now,
      }, {merge: true});
    };

    const codeRef = agentPayoutCodeRef(secretCode);
    const codeSnap = await codeRef.get();
    let requestDoc: FirebaseFirestore.QueryDocumentSnapshot | FirebaseFirestore.DocumentSnapshot | null = null;

    if (codeSnap.exists) {
      const codeData = (codeSnap.data() || {}) as Record<string, unknown>;
      const codeStatus = String(codeData.status || "").trim().toUpperCase();
      const payoutRequestId = asNonEmptyString(codeData.payoutRequestId);
      if (codeStatus !== "RESERVED" || !payoutRequestId) {
        await recordInvalidAttempt();
        throw new functions.https.HttpsError("not-found", "Invalid, expired, or already used code.");
      }
      requestDoc = await db.collection("payout_requests").doc(payoutRequestId).get();
    } else {
      const legacyQuery = await db.collection("payout_requests")
        .where("secretCode", "==", secretCode)
        .where("status", "==", "PENDING")
        .limit(2)
        .get();
      if (legacyQuery.size > 1) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "This payout code matched multiple pending requests. Contact support."
        );
      }
      if (!legacyQuery.empty) {
        requestDoc = legacyQuery.docs[0];
      }
    }

    if (!requestDoc?.exists) {
      await recordInvalidAttempt();
      throw new functions.https.HttpsError("not-found", "Invalid, expired, or already used code.");
    }

    const requestId = requestDoc.id;
    const requestData = requestDoc.data() || {};
    const {senderId: userId, amount} = requestData;
    const reservedRequest = isReservedAgentCashOutRequest(requestData);
    if (!userId || typeof amount !== "number" || amount <= 0) {
      await requestDoc.ref.set({status: "FAILED", resultMessage: "Invalid request data."}, {merge: true});
      throw new functions.https.HttpsError("invalid-argument", "Invalid payout request data.");
    }

    const expiresAt = requestData.expiresAt as admin.firestore.Timestamp | Date | undefined;
    if (expiresAt) {
      const expiryMs = toMillisTimestamp(expiresAt);
      if (Number.isFinite(expiryMs) && expiryMs > 0 && expiryMs <= Date.now()) {
        if (reservedRequest) {
          await releaseReservedAgentPayout(
            requestDoc.ref,
            requestData,
            "Agent cash-out code expired before redemption.",
            "EXPIRED"
          );
        } else {
          await requestDoc.ref.set({status: "EXPIRED", resultMessage: "Code expired."}, {merge: true});
        }
        throw new functions.https.HttpsError("failed-precondition", "This code has expired.");
      }
    }

    try {
      let completedReservedRequest = reservedRequest;
      let completedRequestData: FirebaseFirestore.DocumentData = requestData;
      let completedUsesProviderMirror = false;
      let completedMirrorTransactionId: string | null = null;
      await db.runTransaction(async (transaction) => {
        const freshRequestSnap = await transaction.get(requestDoc.ref);
        if (!freshRequestSnap.exists) {
          throw new functions.https.HttpsError("not-found", "Invalid, expired, or already used code.");
        }
        const freshRequestData = freshRequestSnap.data() || {};
        if (asNonEmptyString(freshRequestData.secretCode) !== secretCode) {
          throw new functions.https.HttpsError("not-found", "Invalid, expired, or already used code.");
        }
        if (String(freshRequestData.status || "").toUpperCase() !== "PENDING") {
          throw new functions.https.HttpsError("not-found", "Invalid, expired, or already used code.");
        }

        const freshReservedRequest = isReservedAgentCashOutRequest(freshRequestData);
        completedReservedRequest = freshReservedRequest;
        const freshCodeSnap = await transaction.get(codeRef);
        if (freshCodeSnap.exists) {
          const freshCodeData = (freshCodeSnap.data() || {}) as Record<string, unknown>;
          const codeStatus = String(freshCodeData.status || "").trim().toUpperCase();
          const payoutRequestId = asNonEmptyString(freshCodeData.payoutRequestId);
          if (codeStatus !== "RESERVED" || payoutRequestId !== freshRequestSnap.id) {
            throw new functions.https.HttpsError("not-found", "Invalid, expired, or already used code.");
          }
        }

        const freshExpiresAtMs = toMillisTimestamp(freshRequestData.expiresAt) || Number(freshRequestData.expiresAtMs || 0);
        if (Number.isFinite(freshExpiresAtMs) && freshExpiresAtMs > 0 && freshExpiresAtMs <= Date.now()) {
          throw new Error("AGENT_PAYOUT_CODE_EXPIRED");
        }

        const userRef = db.collection("users").doc(userId);
        const agentRef = db.collection("users").doc(agentId);
        const [userSnap, agentSnap] = await Promise.all([
          transaction.get(userRef),
          transaction.get(agentRef),
        ]);
        const feeSettingsRef = db.collection("app_config").doc("fee_settings");
        const feeSettingsSnap = await transaction.get(feeSettingsRef);

        if (!userSnap.exists) {
          throw new functions.https.HttpsError("not-found", "The user for this code could not be found.");
        }
        if (!agentSnap.exists) {
          throw new functions.https.HttpsError("not-found", "Agent account not found.");
        }

        const userData = (userSnap.data() || {}) as Record<string, unknown>;
        const usesProviderMirror = isAfriexHostedAgentCashOutSource(freshRequestData.source);
        completedUsesProviderMirror = usesProviderMirror;
        const userStaffFeeExempt = isStaffFeeExempt(userData);
        const legacyFeeInfo = userStaffFeeExempt ? {rate: 0, fee: 0} : calculateAgentCashOutFee(amount);
        const feeSettingsData = (feeSettingsSnap.data() || {}) as Record<string, unknown>;
        const shareConfig = resolveAgentCashoutShareConfigFromFeeSettings(feeSettingsData);
        const feeInfo = freshReservedRequest ? {
          rate: Number(freshRequestData.feeRate || legacyFeeInfo.rate),
          fee: roundMoney(Number(freshRequestData.fee || legacyFeeInfo.fee)),
        } : legacyFeeInfo;
        const totalDebit = freshReservedRequest ?
          roundMoney(Number(freshRequestData.walletDebitedAmount || freshRequestData.totalDebit || (amount + feeInfo.fee))) :
          roundMoney(amount + feeInfo.fee);
        const storedShares = splitAgentCashOutFee(feeInfo.fee, shareConfig);
        const agentShare = freshReservedRequest ?
          roundMoney(Number(freshRequestData.agentShare || storedShares.agentShare)) :
          storedShares.agentShare;
        const ownerShare = freshReservedRequest ?
          roundMoney(Number(freshRequestData.ownerShare || storedShares.ownerShare)) :
          storedShares.ownerShare;
        const agentShareRate = freshReservedRequest ?
          Number(freshRequestData.agentShareRate || storedShares.agentShareRate) :
          storedShares.agentShareRate;
        const ownerShareRate = freshReservedRequest ?
          Number(freshRequestData.ownerShareRate || storedShares.ownerShareRate) :
          storedShares.ownerShareRate;
        completedMirrorTransactionId = asNonEmptyString(freshRequestData.providerMirrorTransactionId);

        if (usesProviderMirror) {
          if (!freshReservedRequest) {
            throw legacyWalletCustodyDisabledError("Agent payout completion");
          }
        } else {
          assertLegacyInternalWalletAllowed(userData, "Agent payout");
          assertLegacyInternalWalletAllowed(agentData, "Agent payout settlement");
          if (!freshReservedRequest) {
            const userBalance = getWalletSpendableBalance(userData);
            if (userBalance < totalDebit) {
              transaction.update(freshRequestSnap.ref, {status: "FAILED", resultMessage: "User had insufficient funds."});
              throw new functions.https.HttpsError("failed-precondition", "User has insufficient funds for this withdrawal.");
            }

            transaction.update(userRef, "wallet.balance", admin.firestore.FieldValue.increment(-totalDebit));
          }
          transaction.update(agentRef, "wallet.balance", admin.firestore.FieldValue.increment(amount));
        }
        if (agentShare > 0) {
          transaction.update(agentRef, "agentEarnings.balance", admin.firestore.FieldValue.increment(agentShare));
        }
        transaction.update(freshRequestSnap.ref, {
          status: "COMPLETED",
          reservationStatus: freshReservedRequest ? "CONSUMED" : freshRequestData.reservationStatus || null,
          walletDebitedAmount: totalDebit,
          agentId: agentId,
          fee: feeInfo.fee,
          feeRate: feeInfo.rate,
          agentShare,
          ownerShare,
          agentShareRate,
          ownerShareRate,
          providerStatus: "COMPLETED",
          providerMessage: usesProviderMirror ?
            "Agent confirmed cash handover against the mirrored provider balance." :
            "Agent payout completed.",
          providerReference: usesProviderMirror ? `agent_cashout_${agentId}_${secretCode}` : admin.firestore.FieldValue.delete(),
          processedAt: admin.firestore.Timestamp.now(),
        });
        transaction.set(codeRef, {
          payoutRequestId: freshRequestSnap.id,
          senderId: userId,
          secretCode,
          status: "CONSUMED",
          consumedByAgentId: agentId,
          consumedAt: admin.firestore.Timestamp.now(),
          updatedAt: admin.firestore.Timestamp.now(),
          legacyMigration: !codeSnap.exists,
        }, {merge: true});

        const timestamp = admin.firestore.Timestamp.now();

        if (ownerShare > 0) {
          recordPlatformRevenue(transaction, {
            source: "agentCashoutOwnerShare",
            amount: ownerShare,
            note: `Owner share from agent cash-out (${agentId})`,
            relatedUserId: userId,
          });
        }
        if (agentShare > 0) {
          transaction.set(platformRevenueRef, {
            agentCashoutAgentShareMirrored: admin.firestore.FieldValue.increment(agentShare),
            lastAgentCashoutSplitUpdate: timestamp,
          }, {merge: true});
        }
        const agentName = asNonEmptyString(
          agentData.name,
          agentData.displayName,
          agentData.username
        ) || "Agent";
        const userName = asNonEmptyString(
          userData.name,
          userData.displayName,
          userData.username
        ) || "User";
        const agentTransaction = {
          title: "Agent Payout Service",
          amount: usesProviderMirror ? 0 : amount,
          type: usesProviderMirror ? "INFO" : "CREDIT",
          status: "COMPLETED",
          timestamp,
          note: usesProviderMirror ?
            `Cash payout to ${userName} confirmed against the mirrored provider balance.` :
            `Cash payout to ${userName}`,
          source: "WALLET_AGENT",
        };
        const agentCommissionTransaction = {
          title: "Agent Commission",
          amount: agentShare,
          type: "CREDIT",
          status: "COMPLETED",
          timestamp,
          note: `Commission earned from ${userName}`,
          source: "AGENT_COMMISSION",
        };
        if (!freshReservedRequest) {
          const userTransaction = {
            title: "Agent Cash-out",
            amount: -totalDebit,
            fee: feeInfo.fee,
            type: "DEBIT",
            status: "COMPLETED",
            timestamp,
            note: userStaffFeeExempt ?
              `Withdrawal via agent ${agentName}. Staff fee exemption applied.` :
              `Withdrawal via agent ${agentName}. Fee $${feeInfo.fee.toFixed(2)} applied.`,
            source: "WALLET_AGENT",
          };
          transaction.set(db.collection("users").doc(userId).collection("transactions").doc(), userTransaction);
        }
        transaction.set(db.collection("users").doc(agentId).collection("transactions").doc(), agentTransaction);
        transaction.set(db.collection("users").doc(agentId).collection("transactions").doc(), agentCommissionTransaction);
        completedRequestData = freshRequestData;
      });

      functions.logger.log(`Successfully completed payout for request ${requestId} by agent ${agentId}.`);
      if (completedUsesProviderMirror && completedMirrorTransactionId) {
        await syncProviderMirrorTransactionStatusById({
          userId,
          mirrorTransactionId: completedMirrorTransactionId,
          nextStatus: ProviderMirrorTransactionStatus.Succeeded,
          providerTransactionId: `agent_cashout_${requestId}`,
          providerMessage: "Agent confirmed cash handover.",
          rawStatus: "AGENT_CASH_CONFIRMED",
        });
      }
      if (completedReservedRequest) {
        await finalizeSenderTransactionsForPayout(userId, requestDoc.ref, completedRequestData, "COMPLETED");
      }
      await attemptRef.set({
        invalidAttemptCount: 0,
        windowStartedAt: null,
        windowStartedAtMs: 0,
        lastSuccessAt: now,
        lastSuccessAtMs: nowMs,
        updatedAt: now,
      }, {merge: true});
      return {success: true, message: `Successfully paid out $${amount}.`};
    } catch (error) {
      functions.logger.error(`Payout transaction failed for request ${requestId}:`, error);
      if (error instanceof Error && error.message === "AGENT_PAYOUT_CODE_EXPIRED") {
        if (reservedRequest) {
          await releaseReservedAgentPayout(
            requestDoc.ref,
            requestData,
            "Agent cash-out code expired before redemption.",
            "EXPIRED"
          );
        } else {
          await requestDoc.ref.set({status: "EXPIRED", resultMessage: "Code expired."}, {merge: true}).catch();
        }
        throw new functions.https.HttpsError("failed-precondition", "This code has expired.");
      }
      if (error instanceof functions.https.HttpsError) throw error;
      if (!reservedRequest) {
        await requestDoc.ref.update({status: "FAILED", resultMessage: "An internal error occurred."}).catch();
      }
      throw new functions.https.HttpsError("internal", "An unexpected error occurred. Please try again.");
    }
  });

// =============================================================================
//  3B. AGENT EARNINGS CASH-OUT (NEW)
// =============================================================================

export const cashOutAgentEarnings = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    assertTransactionOnlyCashServicesDisabled();
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in to perform this action.");
    }

    const agentId = context.auth.uid;
    const agentRef = db.collection("users").doc(agentId);

    const agentSnap = await agentRef.get();
    if (!agentSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Agent account not found.");
    }

    const agentData = (agentSnap.data() || {}) as Record<string, unknown>;
    if (!isAuthorizedAgentOperator(agentData, (context.auth?.token || {}) as Record<string, unknown>)) {
      throw new functions.https.HttpsError("permission-denied", "You must be an authorized agent or staff operator.");
    }

    const agentEarnings = (agentData.agentEarnings || {}) as Record<string, unknown>;
    const earningsBalance = roundMoney(Number(agentEarnings.balance || 0));
    if (!earningsBalance || earningsBalance <= 0) {
      throw new functions.https.HttpsError("failed-precondition", "No earnings available to cash out.");
    }

    const lastCashout = agentEarnings.lastCashoutAt as admin.firestore.Timestamp | Date | undefined;
    if (lastCashout) {
      const lastDate = lastCashout instanceof admin.firestore.Timestamp ? lastCashout.toDate() : lastCashout;
      const nextEligibleAt = new Date(lastDate.getTime() + TWO_WEEKS_MS);
      if (Date.now() < nextEligibleAt.getTime()) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          `Next earnings cash-out available on ${nextEligibleAt.toDateString()}.`
        );
      }
    }

    const pendingPayoutRequestId = asNonEmptyString(
      agentEarnings.pendingPayoutRequestId,
      agentEarnings.pendingRequestId
    );
    if (pendingPayoutRequestId) {
      const pendingSnap = await db.collection("payout_requests").doc(pendingPayoutRequestId).get();
      const pendingStatus = String(pendingSnap.data()?.status || "").trim().toUpperCase();
      if (pendingSnap.exists && !LEGACY_CUSTODY_PAYOUT_TERMINAL_STATUSES.has(pendingStatus)) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "An agent earnings payout is already in progress. Wait for it to complete or fail before starting another cash-out."
        );
      }
    }

    let routeInfo: AfriexHostedWalletRecipientRoute;
    try {
      routeInfo = await resolveAfriexHostedWalletAppUserRecipientRoute({
        recipientUserId: agentId,
      });
    } catch (error) {
      const message = error instanceof functions.https.HttpsError ?
        error.message :
        parseProviderErrorMessage(error);
      throw new functions.https.HttpsError(
        "failed-precondition",
        message.includes("Afriex-ready") || message.includes("payment method") || message.includes("destination") ?
          "Save an Afriex-ready bank or mobile money destination in Wallet > Payment Methods before cashing out agent earnings." :
          message
      );
    }

    const payoutFx = await buildMobileMoneyPayoutFxQuote({
      amount: earningsBalance,
      sourceCurrency: "USD",
      localCurrency: routeInfo.recipientCurrency,
      senderData: agentData,
      authToken: (context.auth?.token || {}) as Record<string, unknown>,
      direction: "AGENT_EARNINGS_CASH_OUT",
      destinationCountry: routeInfo.recipientCountry,
      destinationRoute: routeInfo.payoutRoute,
    });
    const payoutRequestRef = db.collection("payout_requests").doc();
    const senderTxRef = agentRef.collection("transactions").doc();
    const routeLabel = routeInfo.payoutRoute === "BANK_ACCOUNT" ? "bank deposit" : "mobile money";
    const pendingNote = `Agent earnings payout to your saved ${routeLabel} destination.`;

    await db.runTransaction(async (transaction) => {
      const freshAgentSnap = await transaction.get(agentRef);
      if (!freshAgentSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Agent account not found.");
      }

      const freshAgentData = (freshAgentSnap.data() || {}) as Record<string, unknown>;
      if (!isAuthorizedAgentOperator(freshAgentData, (context.auth?.token || {}) as Record<string, unknown>)) {
        throw new functions.https.HttpsError("permission-denied", "You must be an authorized agent or staff operator.");
      }

      const freshAgentEarnings = (freshAgentData.agentEarnings || {}) as Record<string, unknown>;
      const freshBalance = roundMoney(Number(freshAgentEarnings.balance || 0));
      if (!freshBalance || freshBalance <= 0) {
        throw new functions.https.HttpsError("failed-precondition", "No earnings available to cash out.");
      }

      const freshPendingId = asNonEmptyString(
        freshAgentEarnings.pendingPayoutRequestId,
        freshAgentEarnings.pendingRequestId
      );
      if (freshPendingId) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "An agent earnings payout is already in progress."
        );
      }

      const now = admin.firestore.Timestamp.now();
      const payoutRequestData: FirebaseFirestore.DocumentData = {
        senderId: agentId,
        recipientUserId: agentId,
        recipientPaymentMethodId: routeInfo.recipientPaymentMethodId || null,
        recipientInfo: routeInfo.recipientInfo,
        recipientName: routeInfo.recipientName,
        recipientNetwork: routeInfo.recipientNetwork || null,
        recipientPhone: routeInfo.recipientPhone || null,
        recipientCountry: routeInfo.recipientCountry,
        amount: earningsBalance,
        amountInLocalCurrency: payoutFx.localAmount,
        localAmount: payoutFx.localAmount,
        localCurrency: payoutFx.localCurrency,
        currency: payoutFx.walletCurrency,
        walletCurrency: payoutFx.walletCurrency,
        fx: payoutFx.fx,
        status: "PENDING_PROVIDER",
        type: "BENEFICIARY_TRANSFER",
        source: AFRIEX_HOSTED_AGENT_EARNINGS_CASH_OUT_SOURCE,
        fundingSource: AGENT_EARNINGS_PAYOUT_FUNDING_SOURCE,
        afriexPayoutRoute: routeInfo.payoutRoute,
        senderTransactionIds: [senderTxRef.id],
        createdAt: now,
        processedAt: now,
        note: pendingNote,
      };
      const authorizationPatch = buildMobileMoneyProviderAuthorizationPatch(
        payoutRequestRef.id,
        payoutRequestData,
        "cashOutAgentEarnings"
      );

      transaction.set(payoutRequestRef, {
        ...payoutRequestData,
        ...authorizationPatch,
      });
      transaction.set(senderTxRef, {
        title: "Agent Earnings Cash-out (Pending)",
        amount: -earningsBalance,
        type: "DEBIT",
        status: "PENDING",
        timestamp: now,
        note: pendingNote,
        source: AFRIEX_HOSTED_AGENT_EARNINGS_CASH_OUT_SOURCE,
        payoutRequestId: payoutRequestRef.id,
      });
      transaction.set(agentRef, {
        agentEarnings: {
          ...freshAgentEarnings,
          pendingPayoutRequestId: payoutRequestRef.id,
          pendingPayoutAmount: earningsBalance,
          pendingPayoutCurrency: payoutFx.walletCurrency,
          pendingPayoutLocalAmount: payoutFx.localAmount,
          pendingPayoutLocalCurrency: payoutFx.localCurrency,
          pendingPayoutRoute: routeInfo.payoutRoute,
          pendingRequestedAt: now,
          pendingStatus: "PENDING_PROVIDER",
        },
      }, {merge: true});
    });

    return {
      success: true,
      payoutRequestId: payoutRequestRef.id,
      message: routeInfo.payoutRoute === "BANK_ACCOUNT" ?
        `Your agent earnings are being sent to your saved bank destination.` :
        `Your agent earnings are being sent to your saved mobile money destination.`,
    };
  });

export const reconcileExpiredAgentPayoutCodes = functions.pubsub
  .schedule("every 5 minutes")
  .onRun(async () => {
    const nowMs = Date.now();
    const pendingSnap = await db.collection("payout_requests")
      .where("type", "==", "AGENT_CASH_OUT")
      .where("status", "==", "PENDING")
      .limit(100)
      .get();

    for (const doc of pendingSnap.docs) {
      const data = doc.data() || {};
      const expiresAtMs = toMillisTimestamp(data.expiresAt) || Number(data.expiresAtMs || 0);
      if (!Number.isFinite(expiresAtMs) || expiresAtMs <= 0 || expiresAtMs > nowMs) {
        continue;
      }

      try {
        if (isReservedAgentCashOutRequest(data)) {
          await releaseReservedAgentPayout(
            doc.ref,
            data,
            "Agent cash-out code expired before redemption.",
            "EXPIRED"
          );
        } else {
          await doc.ref.set({
            status: "EXPIRED",
            resultMessage: "Code expired.",
            processedAt: admin.firestore.Timestamp.now(),
          }, {merge: true});
        }
      } catch (error) {
        functions.logger.error("Failed to reconcile expired agent payout code", {
          payoutRequestId: doc.id,
          error,
        });
      }
    }

    return null;
  });

export const reconcileExpiredAgentCustomerWalletWithdrawals = functions.pubsub
  .schedule("every 5 minutes")
  .onRun(async () => {
    const pendingSnap = await db.collection("payout_requests")
      .where("type", "==", AGENT_CUSTOMER_WALLET_WITHDRAWAL_TYPE)
      .where("status", "==", "PENDING")
      .limit(100)
      .get();

    for (const doc of pendingSnap.docs) {
      try {
        await expireAgentCustomerWalletWithdrawalIfNeeded(doc.ref, doc.data() || {});
      } catch (error) {
        functions.logger.error("Failed to reconcile agent customer wallet withdrawal expiry", {
          payoutRequestId: doc.id,
          error,
        });
      }
    }

    return null;
  });

// =============================================================================
//  3C. OWNER REVENUE CASH-OUT (NEW)
// =============================================================================

export const cashOutOwnerRevenue = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    await assertOwnerOrAdminCallableAccess(context);
    throw legacyWalletCustodyDisabledError("Owner revenue wallet cash-out");
    const ownerUserId = await assertOwnerCallableAccess(context);

    await db.runTransaction(async (transaction) => {
      const platformSnap = await transaction.get(platformRevenueRef);
      const balance = Number(platformSnap.data()?.balance || 0);
      if (!balance || balance <= 0) {
        throw new functions.https.HttpsError("failed-precondition", "No revenue available to cash out.");
      }

      const ownerRef = db.collection("users").doc(ownerUserId);
      const ownerSnap = await transaction.get(ownerRef);
      if (!ownerSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Owner account not found.");
      }
      const ownerData = (ownerSnap.data() || {}) as Record<string, unknown>;
      assertLegacyInternalWalletAllowed(ownerData, "Owner revenue cash-out");
      transaction.update(ownerRef, "wallet.balance", admin.firestore.FieldValue.increment(balance));
      transaction.set(ownerRef.collection("transactions").doc(), {
        title: "Owner Revenue Cash-out",
        amount: balance,
        type: "CREDIT",
        status: "COMPLETED",
        timestamp: admin.firestore.Timestamp.now(),
        note: "Platform revenue moved to wallet",
        source: "OWNER_REVENUE",
      });

      const timestamp = admin.firestore.Timestamp.now();
      transaction.set(platformRevenueRef, {
        balance: admin.firestore.FieldValue.increment(-balance),
        lastUpdate: timestamp,
      }, {merge: true});

      const txRef = platformRevenueRef.collection("transactions").doc();
      transaction.set(txRef, {
        source: "ownerCashout",
        amount: -balance,
        note: "Owner revenue cash-out",
        relatedUserId: ownerUserId,
        createdAt: timestamp,
      });
    });

    return {success: true, message: "Revenue transferred to your wallet."};
  });

// =============================================================================
//  3D. EVENT SIGN-UP PAYMENT SPLIT (OWNER 5%)
// =============================================================================

interface ApplyForEventRequest {
  eventId?: string;
  fundingPreference?: unknown;
}

type EventTicketFundingPreference = "STRIPE_CARD" | "AFRIEX_MOBILE_MONEY";

const normalizeEventTicketFundingPreference = (
  value: unknown
): EventTicketFundingPreference => {
  const normalized = String(value || "").trim().toUpperCase();
  // Existing released clients used card checkout. New clients make this choice explicit.
  if (!normalized || normalized === "STRIPE_CARD") return "STRIPE_CARD";
  if (normalized === "AFRIEX_MOBILE_MONEY") {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Mobile money checkout is not available for seller or organizer payments right now. Use a card so the recipient is paid through Stripe Connect."
    );
  }
  throw new functions.https.HttpsError(
    "invalid-argument",
    "Select a supported event-ticket payment method."
  );
};

/** Keeps direct/deep-link event applications aligned with the public Events listing. */
const assertEventOpenForApplications = (eventData: Record<string, unknown>): void => {
  if (eventData.isDeleted === true) {
    throw new functions.https.HttpsError("failed-precondition", "This event is no longer available.");
  }
  if (eventData.isActive === false) {
    throw new functions.https.HttpsError("failed-precondition", "This event is not accepting applications.");
  }

  const status = trimStringValue(eventData.status).toUpperCase();
  const supportedStatuses = ["OPEN", "UPCOMING", "ACTIVE", "PUBLISHED"];
  if (status && !supportedStatuses.includes(status)) {
    throw new functions.https.HttpsError("failed-precondition", "This event is closed for applications.");
  }
  if (eventData.closeEntries === true) {
    throw new functions.https.HttpsError("failed-precondition", "Event entries are closed.");
  }

  const rawEventDate = eventData.eventDateTime || eventData.eventTimestamp || eventData.timestamp || eventData.eventDate || eventData.date;
  let eventTimeMs: number | null = null;
  if (rawEventDate && typeof rawEventDate === "object" && "toMillis" in rawEventDate) {
    const candidate = (rawEventDate as {toMillis?: () => number}).toMillis?.();
    if (typeof candidate === "number" && Number.isFinite(candidate)) {
      eventTimeMs = candidate;
    }
  } else if (typeof rawEventDate === "number" && Number.isFinite(rawEventDate)) {
    eventTimeMs = rawEventDate > 1_000_000_000_000 ? rawEventDate : rawEventDate * 1000;
  } else if (typeof rawEventDate === "string") {
    const candidate = Number(rawEventDate.trim());
    if (Number.isFinite(candidate) && candidate > 0) {
      eventTimeMs = candidate > 1_000_000_000_000 ? candidate : candidate * 1000;
    }
  }
  if (eventTimeMs !== null && eventTimeMs < Date.now()) {
    throw new functions.https.HttpsError("failed-precondition", "This event has already started.");
  }
};

interface VolunteerListingsRequest {
  limit?: unknown;
}

interface ApplyForJobRequest {
  jobId?: unknown;
}

const publicListingText = (value: unknown, fallback = ""): string => {
  const text = String(value ?? "").trim();
  return text || fallback;
};

const publicListingDateMs = (value: unknown): number | null => {
  if (value && typeof (value as {toMillis?: unknown}).toMillis === "function") {
    const candidate = (value as {toMillis: () => number}).toMillis();
    return Number.isFinite(candidate) ? candidate : null;
  }
  if (typeof value === "number" && Number.isFinite(value)) {
    return value > 1_000_000_000_000 ? value : value * 1000;
  }
  if (typeof value === "string") {
    const numeric = Number(value.trim());
    if (Number.isFinite(numeric) && numeric > 0) {
      return numeric > 1_000_000_000_000 ? numeric : numeric * 1000;
    }
    const parsed = Date.parse(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
};

const isPublicVolunteerEvent = (data: Record<string, unknown>, nowMs: number): boolean => {
  if (data.isDeleted === true || data.isActive === false || data.closeEntries === true) return false;
  const status = publicListingText(data.status).toUpperCase();
  if (status && !["OPEN", "UPCOMING", "ACTIVE", "PUBLISHED"].includes(status)) return false;
  const dateMs = publicListingDateMs(data.eventDateTime ?? data.eventTimestamp ?? data.timestamp ?? data.eventDate ?? data.date);
  // Public listings must prove that they are still in the future. Older records
  // without a usable date remain in the owner's management history only.
  return dateMs !== null && dateMs > nowMs;
};

const isPublicVolunteerJob = (data: Record<string, unknown>, nowMs: number): boolean => {
  if (data.isDeleted === true || data.isActive === false) return false;
  const status = publicListingText(data.status, "OPEN").toUpperCase();
  if (!["OPEN", "ACTIVE"].includes(status)) return false;
  const deadlineMs = publicListingDateMs(
    data.applicationDeadline ?? data.deadline ?? data.eventDateTime ?? data.eventTimestamp ?? data.timestamp ?? data.eventDate ?? data.date,
  );
  return deadlineMs !== null && deadlineMs > nowMs;
};

/**
 * Provides a deliberately small public projection for the volunteer website.
 * Raw event/job documents remain Firestore-authenticated and are never exposed
 * to guests from the browser.
 */
export const getVolunteerListings = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const request = (data || {}) as VolunteerListingsRequest;
    const requestedLimit = Number(request.limit);
    const listingLimit = Number.isFinite(requestedLimit) ? Math.min(Math.max(Math.trunc(requestedLimit), 10), 50) : 40;
    const nowMs = Date.now();
    const [eventsSnapshot, jobsSnapshot] = await Promise.all([
      db.collection("events").limit(listingLimit).get(),
      db.collection("jobs").limit(listingLimit).get(),
    ]);

    const events = eventsSnapshot.docs
      .map((eventDoc) => ({id: eventDoc.id, data: eventDoc.data() as Record<string, unknown>}))
      .filter((event) => isPublicVolunteerEvent(event.data, nowMs))
      .map(({id, data: event}) => ({
        id,
        type: "EVENT",
        title: publicListingText(event.title, "Volunteer event"),
        description: publicListingText(event.description ?? event.details).slice(0, 2_000),
        category: publicListingText(event.category, "Community"),
        location: publicListingText(event.locationName ?? event.locationString ?? event.location, "Location to be confirmed"),
        occursAtMs: publicListingDateMs(event.eventDateTime ?? event.eventTimestamp ?? event.timestamp ?? event.eventDate ?? event.date),
        volunteerLimit: Math.max(0, Number(event.volunteerLimit ?? event.totalSlots ?? 0) || 0),
        participantsCount: Math.max(0, Number(event.participantsCount ?? event.appliedCount ?? 0) || 0),
        paymentUsd: Math.max(0, Number(event.eventFee ?? event.payment ?? 0) || 0),
      }))
      .sort((left, right) => (left.occursAtMs ?? Number.MAX_SAFE_INTEGER) - (right.occursAtMs ?? Number.MAX_SAFE_INTEGER));

    const jobs = jobsSnapshot.docs
      .map((jobDoc) => ({id: jobDoc.id, data: jobDoc.data() as Record<string, unknown>}))
      .filter((job) => isPublicVolunteerJob(job.data, nowMs))
      .map(({id, data: job}) => ({
        id,
        type: "JOB",
        title: publicListingText(job.title ?? job.eventName ?? job.jobTitle, "Volunteer opportunity"),
        roleTitle: publicListingText(job.jobTitle ?? job.roleTitle),
        organizationName: publicListingText(job.organizationName ?? job.employerName, "Organization"),
        description: publicListingText(job.description ?? job.details).slice(0, 2_000),
        category: publicListingText(job.category, "Community"),
        location: publicListingText(job.locationString ?? job.locationName ?? job.location, "Location to be confirmed"),
        occursAtMs: publicListingDateMs(job.eventDateTime ?? job.eventTimestamp ?? job.timestamp ?? job.eventDate ?? job.date ?? job.applicationDeadline ?? job.deadline),
        applicationDeadlineMs: publicListingDateMs(job.applicationDeadline ?? job.deadline ?? job.eventDateTime ?? job.eventTimestamp ?? job.timestamp ?? job.eventDate ?? job.date),
        applicantsCount: Math.max(0, Number(job.applicantsCount ?? job.applicationsCount ?? 0) || 0),
      }))
      .sort((left, right) => (left.occursAtMs ?? Number.MAX_SAFE_INTEGER) - (right.occursAtMs ?? Number.MAX_SAFE_INTEGER));

    const applicationStatusByListing = new Map<string, string>();
    if (context.auth?.uid) {
      const applicationRefs = [
        ...events.map((event) => db.collection("events").doc(event.id).collection("applications").doc(context.auth!.uid)),
        ...jobs.map((job) => db.collection("jobs").doc(job.id).collection("applications").doc(context.auth!.uid)),
      ];
      const applications = applicationRefs.length > 0 ? await db.getAll(...applicationRefs) : [];
      applications.forEach((application) => {
        if (!application.exists) return;
        const segments = application.ref.path.split("/");
        const collectionName = segments[0];
        const listingId = segments[1];
        const listingType = collectionName === "events" ? "EVENT" : collectionName === "jobs" ? "JOB" : "";
        if (!listingType || !listingId) return;
        applicationStatusByListing.set(`${listingType}:${listingId}`, publicListingText(application.data()?.status, "PENDING").toUpperCase());
      });
    }

    const decorateApplicationStatus = <T extends {id: string; type: string}>(listing: T) => ({
      ...listing,
      applicationStatus: applicationStatusByListing.get(`${listing.type}:${listing.id}`) || null,
    });

    return {
      events: events.map(decorateApplicationStatus),
      jobs: jobs.map(decorateApplicationStatus),
      generatedAtMs: nowMs,
    };
  });

/** Applies for a job from the authenticated volunteer website without exposing write rules to guests. */
export const applyForJob = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const userId = context.auth?.uid;
    if (!userId) {
      throw new functions.https.HttpsError("unauthenticated", "Sign in to apply for this opportunity.");
    }

    const request = (data || {}) as ApplyForJobRequest;
    const jobId = publicListingText(request.jobId);
    if (!jobId) {
      throw new functions.https.HttpsError("invalid-argument", "Missing required field: jobId.");
    }

    const userRef = db.collection("users").doc(userId);
    const jobRef = db.collection("jobs").doc(jobId);
    const rootApplicationRef = db.collection("applications").doc(`${jobId}_${userId}`);
    const jobApplicationRef = jobRef.collection("applications").doc(userId);

    return db.runTransaction(async (transaction) => {
      const [userSnapshot, jobSnapshot, rootApplicationSnapshot, jobApplicationSnapshot] = await Promise.all([
        transaction.get(userRef),
        transaction.get(jobRef),
        transaction.get(rootApplicationRef),
        transaction.get(jobApplicationRef),
      ]);
      if (!userSnapshot.exists) {
        throw new functions.https.HttpsError("not-found", "Your volunteer profile is not ready. Finish registration in the app and try again.");
      }
      if (!jobSnapshot.exists) {
        throw new functions.https.HttpsError("not-found", "This opportunity is no longer available.");
      }
      if (rootApplicationSnapshot.exists || jobApplicationSnapshot.exists) {
        throw new functions.https.HttpsError("already-exists", "You have already applied for this opportunity.");
      }

      const job = jobSnapshot.data() as Record<string, unknown>;
      if (!isPublicVolunteerJob(job, Date.now())) {
        throw new functions.https.HttpsError("failed-precondition", "This opportunity is closed for applications.");
      }
      const employerUid = publicListingText(job.employerUid ?? job.employerId);
      if (!employerUid) {
        throw new functions.https.HttpsError("failed-precondition", "This opportunity is missing its employer profile.");
      }
      if (employerUid === userId) {
        throw new functions.https.HttpsError("failed-precondition", "You cannot apply to your own opportunity.");
      }

      const user = userSnapshot.data() as Record<string, unknown>;
      const now = admin.firestore.Timestamp.now();
      const commonPayload = {
        jobId,
        jobTitle: publicListingText(job.title ?? job.eventName ?? job.jobTitle, "Volunteer opportunity"),
        roleTitle: publicListingText(job.jobTitle ?? job.roleTitle),
        organizationName: publicListingText(job.organizationName ?? job.employerName, "Organization"),
        userId,
        volunteerUid: userId,
        volunteerId: userId,
        volunteerName: publicListingText(user.name ?? user.displayName ?? user.username, "Volunteer"),
        volunteerEmail: publicListingText(user.email ?? context.auth?.token.email),
        employerUid,
        employerId: publicListingText(job.employerId, employerUid),
        status: "PENDING",
        appliedAt: now,
        appliedDate: now,
        lastUpdatedAt: now,
      };

      transaction.set(rootApplicationRef, {
        ...commonPayload,
        applicationId: rootApplicationRef.id,
      });
      transaction.set(jobApplicationRef, {
        ...commonPayload,
        applicationId: jobApplicationRef.id,
        rootApplicationId: rootApplicationRef.id,
      });
      transaction.update(jobRef, {
        applicantsCount: admin.firestore.FieldValue.increment(1),
        lastUpdatedAt: now,
      });

      return {
        success: true,
        jobId,
        status: "PENDING",
        message: "Application sent to the employer.",
      };
    });
  });

export const applyForEvent = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in to apply.");
    }

    const userId = context.auth.uid;
    const request = data as ApplyForEventRequest;
    const eventId = String(request?.eventId || "").trim();
    if (!eventId) {
      throw new functions.https.HttpsError("invalid-argument", "Missing required field: eventId.");
    }

    const userRef = db.collection("users").doc(userId);
    const eventRef = db.collection("events").doc(eventId);
    const applicationRef = eventRef.collection("applications").doc(userId);
    const [userDoc, eventDoc, applicationDoc] = await Promise.all([
      userRef.get(),
      eventRef.get(),
      applicationRef.get(),
    ]);

    if (!userDoc.exists) {
      throw new functions.https.HttpsError("not-found", "User profile not found.");
    }
    if (!eventDoc.exists) {
      throw new functions.https.HttpsError("not-found", "Event not found.");
    }
    if (applicationDoc.exists) {
      throw new functions.https.HttpsError("failed-precondition", "You have already applied for this event.");
    }

    const eventData = (eventDoc.data() || {}) as Record<string, unknown>;
    const organizerId = String(eventData.organizerId || eventData.organizerUid || "").trim();
    if (!organizerId) {
      throw new functions.https.HttpsError("failed-precondition", "Event organizer is missing.");
    }
    if (organizerId === userId) {
      throw new functions.https.HttpsError("failed-precondition", "Organizers cannot apply to their own event.");
    }
    assertEventOpenForApplications(eventData);

    const volunteerLimit = Number(eventData.volunteerLimit ?? 0);
    const participantsCount = Number(eventData.participantsCount ?? 0);
    if (Number.isFinite(volunteerLimit) && volunteerLimit > 0 && participantsCount >= volunteerLimit) {
      throw new functions.https.HttpsError("failed-precondition", "This event is full.");
    }

    const eventTitle = String(eventData.title || "Event").trim() || "Event";
    const eventFeeRaw = Number(eventData.eventFee ?? eventData.payment ?? 0);
    const eventFee = Number.isFinite(eventFeeRaw) ? roundMoney(Math.max(0, eventFeeRaw)) : 0;
    const userData = await withPrivateUserFields(
      userId,
      (userDoc.data() || {}) as Record<string, unknown>
    );
    const staffExempt = isStaffFeeExempt(
      userData,
      (context.auth?.token || {}) as Record<string, unknown>
    );
    const shouldChargeEventFee = eventFee > 0 && !staffExempt;
    const requestedFundingPreference = normalizeEventTicketFundingPreference(
      request.fundingPreference
    );
    // Capture the configured rate before collection so the Stripe and Afriex
    // branches use the same immutable fee split for this ticket.
    const feeSettingsSnap = await db.collection("app_config").doc("fee_settings").get();
    const eventTicketOwnerFeeRate = pickEventTicketOwnerFeeRate(
      (feeSettingsSnap.data() || {}) as Record<string, unknown>
    );
    const ownerFeeAmount = shouldChargeEventFee ? roundMoney(eventFee * eventTicketOwnerFeeRate) : 0;
    const organizerNetAmount = shouldChargeEventFee ? roundMoney(eventFee - ownerFeeAmount) : 0;
    const organizerAfriexPayoutPlan = shouldChargeEventFee ?
      await buildAfriexCommercePayoutPlanForUser(organizerId) :
      null;

    let chargeResult: StripeCommerceChargeResult | null = null;
    if (shouldChargeEventFee) {
      const organizerUserSnap = await db.collection("users").doc(organizerId).get();
      if (!organizerUserSnap.exists) {
        throw new functions.https.HttpsError("not-found", "Organizer account not found.");
      }
      const organizerUserData = await withPrivateUserFields(
        organizerId,
        (organizerUserSnap.data() || {}) as Record<string, unknown>
      );
      const settlementDecision = await resolveMarketplaceCheckoutSettlementDecision({
        recipientUserId: organizerId,
        recipientUserData: organizerUserData,
        flowName: "Event ticket payout",
        requestedFundingPreference,
      });
      if (settlementDecision.provider === "AFRIEX" && settlementDecision.executionMode === "LIVE") {
        const afriexRuntime = await resolveAfriexCommerceRuntime({
          buyerUserId: userId,
          recipientUserId: organizerId,
          recipientPayoutPlan: organizerAfriexPayoutPlan,
          grossAmount: eventFee,
          netAmount: organizerNetAmount,
          flowName: "Event ticket payout",
        });
        const collectionRef = db.collection("payout_requests").doc();
        await db.runTransaction(async (transaction) => {
          const [freshUserDoc, freshEventDoc, freshApplicationDoc] = await Promise.all([
            transaction.get(userRef),
            transaction.get(eventRef),
            transaction.get(applicationRef),
          ]);

          if (!freshUserDoc.exists) {
            throw new functions.https.HttpsError("not-found", "User profile not found.");
          }
          if (!freshEventDoc.exists) {
            throw new functions.https.HttpsError("not-found", "Event not found.");
          }
          if (freshApplicationDoc.exists) {
            throw new functions.https.HttpsError("failed-precondition", "You have already applied for this event.");
          }

          const freshEventData = (freshEventDoc.data() || {}) as Record<string, unknown>;
          assertEventOpenForApplications(freshEventData);
          const freshVolunteerLimit = Number(freshEventData.volunteerLimit ?? 0);
          const freshParticipantsCount = Number(freshEventData.participantsCount ?? 0);
          if (Number.isFinite(freshVolunteerLimit) && freshVolunteerLimit > 0 && freshParticipantsCount >= freshVolunteerLimit) {
            throw new functions.https.HttpsError("failed-precondition", "This event is full.");
          }

          const timestamp = admin.firestore.Timestamp.now();
          const collectionData: FirebaseFirestore.DocumentData = {
            senderId: userId,
            amount: eventFee,
            currency: "USD",
            phone: afriexRuntime.fundingMethod.phoneNumber,
            network: afriexRuntime.fundingMethod.network,
            country: afriexRuntime.fundingMethod.country,
            dialCode: afriexRuntime.fundingMethod.dialCode,
            localCurrency: afriexRuntime.fundingMethod.currency,
            paymentMethodId: afriexRuntime.fundingMethod.paymentMethodId,
            type: "CASH_IN",
            status: "PENDING",
            source: buildAfriexCommerceCollectionSource("EVENT"),
            fundingSource: "EXTERNAL_MOBILE_MONEY",
            fundingPreference: requestedFundingPreference,
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            createdAt: timestamp,
            processedAt: timestamp,
            transferIntent: {
              mode: AFRIEX_COMMERCE_TRANSFER_MODE,
              settlementCategory: "EVENT",
              commerceTitle: eventTitle,
              eventId,
              applicantUserId: userId,
              organizerId,
              eventTitle,
              grossAmount: eventFee,
              netAmount: organizerNetAmount,
              platformFee: ownerFeeAmount,
              ownerFeeRate: eventTicketOwnerFeeRate,
              fundingPreference: requestedFundingPreference,
              recipientUserId: organizerId,
              recipientName: asNonEmptyString(
                freshEventData.organizerName,
                freshEventData.organizerDisplayName,
                organizerUserData.name,
                organizerUserData.username
              ) || "Organizer",
              recipientPaymentMethodId: afriexRuntime.recipientTarget.paymentMethodId,
              recipientInfo: afriexRuntime.recipientTarget.recipientInfo,
              recipientLocalAmount: afriexRuntime.recipientTarget.localAmount,
              recipientLocalCurrency: afriexRuntime.recipientTarget.localCurrency,
              recipientFx: afriexRuntime.recipientTarget.payoutFx,
              afriexPayoutRoute: afriexRuntime.recipientTarget.route,
              requestedCurrency: "USD",
              processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            },
          };

          transaction.set(collectionRef, collectionData, {merge: true});
          transaction.set(applicationRef, {
            applicationId: applicationRef.id,
            eventId,
            eventTitle,
            organizerId,
            organizerUid: organizerId,
            volunteerUid: userId,
            volunteerId: userId,
            userId,
            volunteerName: String(freshUserDoc.data()?.name || freshUserDoc.data()?.displayName || "Volunteer"),
            volunteerEmail: String(freshUserDoc.data()?.email || context.auth?.token?.email || ""),
            status: "PENDING",
            transactionAmount: organizerNetAmount,
            ticketPrice: eventFee,
            ownerFeeRate: eventTicketOwnerFeeRate,
            ownerFeeAmount,
            organizerNetAmount,
            currency: "USD",
            paymentStatus: "COLLECTION_PENDING",
            paymentProcessor: "AFRIEX",
            fundingPreference: requestedFundingPreference,
            paymentIntentId: null,
            stripeChargeId: null,
            commercePayoutRequestId: null,
            providerCollectionRequestId: collectionRef.id,
            providerRoutingStatus: "COLLECTION_PENDING",
            providerRoutingMessage: "Awaiting Afriex buyer collection approval.",
            afriexPayoutProvider: "AFRIEX",
            afriexPreferredPayoutRoute: afriexRuntime.recipientTarget.route,
            afriexPayoutSelectionRequired: false,
            appliedDate: timestamp,
            paymentProcessedAt: null,
            updatedAt: timestamp,
          }, {merge: true});
          transaction.update(eventRef, {
            participantsCount: admin.firestore.FieldValue.increment(1),
            lastUpdatedAt: timestamp,
          });
        });

        return {
          success: true,
          eventId,
          charged: false,
          collectionPending: true,
          ticketPrice: eventFee,
          ownerFeeRate: eventTicketOwnerFeeRate,
          ownerFeeAmount,
          organizerNetAmount,
          staffExempt,
          processor: "AFRIEX",
          message: "Mobile money collection started. Approve the prompt on your phone to finish this event ticket.",
        };
      }
      if (settlementDecision.executionMode !== "LIVE" || settlementDecision.provider !== "STRIPE") {
        throw new functions.https.HttpsError(
          "failed-precondition",
          settlementDecision.message || "This event corridor is not ready for live checkout."
        );
      }
      const connectedAccountId = settlementDecision.destinationAccountId;
      if (!connectedAccountId) {
        throw new functions.https.HttpsError("failed-precondition", "Event ticket checkout is missing the organizer's Stripe account.");
      }
      try {
        chargeResult = await createStripeCardCommerceDirectCharge({
          payerUserId: userId,
          payerUserData: userData,
          amount: eventFee,
          currency: "USD",
          description: `Event ticket: ${eventTitle}`,
          connectedAccountId,
          applicationFeeAmount: ownerFeeAmount,
          metadata: {
            flow: "EVENT_TICKET",
            eventId,
            organizerId,
            applicantUserId: userId,
          },
          idempotencyKey: `event_ticket_${eventId}_${userId}`,
        });
      } catch (error) {
        throw mapStripeCommerceChargeError(error);
      }
    }
    const commercePayoutRef =
      shouldChargeEventFee && organizerNetAmount > 0 ?
        db.collection("payout_requests").doc() :
        null;

    try {
      const result = await db.runTransaction(async (transaction) => {
        const [freshUserDoc, freshEventDoc, freshApplicationDoc] = await Promise.all([
          transaction.get(userRef),
          transaction.get(eventRef),
          transaction.get(applicationRef),
        ]);

        if (!freshUserDoc.exists) {
          throw new functions.https.HttpsError("not-found", "User profile not found.");
        }
        if (!freshEventDoc.exists) {
          throw new functions.https.HttpsError("not-found", "Event not found.");
        }
        if (freshApplicationDoc.exists) {
          throw new functions.https.HttpsError("failed-precondition", "You have already applied for this event.");
        }

        const freshEventData = (freshEventDoc.data() || {}) as Record<string, unknown>;
        assertEventOpenForApplications(freshEventData);
        const freshVolunteerLimit = Number(freshEventData.volunteerLimit ?? 0);
        const freshParticipantsCount = Number(freshEventData.participantsCount ?? 0);
        if (Number.isFinite(freshVolunteerLimit) && freshVolunteerLimit > 0 && freshParticipantsCount >= freshVolunteerLimit) {
          throw new functions.https.HttpsError("failed-precondition", "This event is full.");
        }

        const timestamp = admin.firestore.Timestamp.now();
        if (shouldChargeEventFee && chargeResult) {
          transaction.set(userRef.collection("transactions").doc(), {
            title: `Event Ticket: ${eventTitle}`,
            amount: -eventFee,
            type: "DEBIT",
            status: "COMPLETED",
            timestamp,
            source: "EVENT_TICKET_STRIPE",
            processor: "STRIPE",
            fundingPreference: requestedFundingPreference,
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
            fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
            note: `Charged to your saved Stripe card. Platform fee (${(eventTicketOwnerFeeRate * 100).toFixed(2)}%): $${ownerFeeAmount.toFixed(2)}.`,
          });

          const organizerRef = db.collection("users").doc(organizerId);
          transaction.set(organizerRef.collection("transactions").doc(), {
            title: `Event Ticket Sale: ${eventTitle}`,
            amount: organizerNetAmount,
            type: "CREDIT",
            status: "COMPLETED",
            timestamp,
            source: "EVENT_TICKET_STRIPE_SALE",
            processor: "STRIPE",
            stripePaymentIntentId: chargeResult.paymentIntentId,
            stripeChargeId: chargeResult.latestChargeId,
            stripeConnectedAccountId: chargeResult.connectedAccountId,
            note: `Stripe direct sale from event ${eventId} after ${(eventTicketOwnerFeeRate * 100).toFixed(2)}% platform fee. Stripe processing fees settle in your merchant account.`,
            relatedUserId: userId,
          });

          if (commercePayoutRef) {
            transaction.set(commercePayoutRef, buildCompletedCommercePayoutRequestRecord({
              amount: organizerNetAmount,
              grossAmount: eventFee,
              currency: "USD",
              recipientId: organizerId,
              recipientName: asNonEmptyString(
                freshEventData.organizerName,
                freshEventData.organizerDisplayName
              ) || "Organizer",
              senderId: userId,
              source: "EVENT_STRIPE_PAYOUT",
              type: "EVENT_PAYOUT",
              settlementCategory: "EVENT",
              commerceRecordId: eventId,
              processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
              timestamp,
              providerMessage: "Stripe direct event sale completed in the organizer's Stripe account.",
              stripePaymentIntentId: chargeResult.paymentIntentId,
              stripeChargeId: chargeResult.latestChargeId,
              fundingPaymentMethodId: chargeResult.fundingPaymentMethodDocId,
              stripeConnectedAccountId: chargeResult.connectedAccountId,
              platformFee: ownerFeeAmount,
              extraContext: {
                eventId,
                eventTitle,
                organizerId,
                applicantUserId: userId,
                ownerFeeRate: eventTicketOwnerFeeRate,
                ownerFeeAmount,
              },
            }));
          }

          if (ownerFeeAmount > 0) {
            recordPlatformRevenue(transaction, {
              source: "eventTicketOwnerFee",
              amount: ownerFeeAmount,
              note: `${(eventTicketOwnerFeeRate * 100).toFixed(2)}% owner fee from event ${eventId} via Stripe`,
              relatedUserId: userId,
              processor: "STRIPE",
              provider: "STRIPE",
              settlementCategory: "EVENT",
              processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
            });
          }
        } else if (eventFee > 0) {
          transaction.set(userRef.collection("transactions").doc(), {
            title: `Event Ticket (Staff Exempt): ${eventTitle}`,
            amount: 0,
            type: "INFO",
            status: "COMPLETED",
            timestamp,
            source: "EVENT_TICKET_STAFF_EXEMPT",
            note: `Staff fee exemption applied. Standard ticket price $${eventFee.toFixed(2)} was waived.`,
          });
        } else {
          transaction.set(userRef.collection("transactions").doc(), {
            title: `Event Sign-up: ${eventTitle}`,
            amount: 0,
            type: "INFO",
            status: "COMPLETED",
            timestamp,
            source: "EVENT_SIGNUP_FREE",
            note: "Free event sign-up",
          });
        }

        transaction.set(applicationRef, {
          applicationId: applicationRef.id,
          eventId,
          eventTitle,
          organizerId,
          organizerUid: organizerId,
          volunteerUid: userId,
          volunteerId: userId,
          userId,
          volunteerName: String(freshUserDoc.data()?.name || freshUserDoc.data()?.displayName || "Volunteer"),
          volunteerEmail: String(freshUserDoc.data()?.email || context.auth?.token?.email || ""),
          status: eventFee > 0 ? "APPROVED" : "PENDING",
          transactionAmount: organizerNetAmount,
          ticketPrice: eventFee,
          ownerFeeRate: eventTicketOwnerFeeRate,
          ownerFeeAmount,
          organizerNetAmount,
          currency: "USD",
          paymentStatus: shouldChargeEventFee ? "PAID" : (eventFee > 0 ? "STAFF_EXEMPT" : "NOT_REQUIRED"),
          paymentProcessor: chargeResult ? "STRIPE" : null,
          fundingPreference: shouldChargeEventFee ? requestedFundingPreference : null,
          paymentIntentId: chargeResult?.paymentIntentId || null,
          stripeChargeId: chargeResult?.latestChargeId || null,
          stripeConnectedAccountId: chargeResult?.connectedAccountId || null,
          commercePayoutRequestId: commercePayoutRef?.id || null,
          appliedDate: timestamp,
          paymentProcessedAt: shouldChargeEventFee ? timestamp : null,
        });

        transaction.update(eventRef, {
          participantsCount: admin.firestore.FieldValue.increment(1),
          lastUpdatedAt: timestamp,
        });

        return {
          success: true,
          eventId,
          charged: shouldChargeEventFee,
          ticketPrice: eventFee,
          ownerFeeRate: eventTicketOwnerFeeRate,
          ownerFeeAmount,
          organizerNetAmount,
          staffExempt,
        };
      });

      return result;
    } catch (error) {
      if (chargeResult) {
        await refundStripeCommercePaymentIntent({
          paymentIntentId: chargeResult?.paymentIntentId || "",
          connectedAccountId: chargeResult?.connectedAccountId || null,
          directChargeAttemptId: `event_ticket_${eventId}_${userId}`,
          idempotencyKey: `event_ticket_refund_${eventId}_${userId}`,
          metadata: {
            flow: "EVENT_TICKET",
            eventId,
            applicantUserId: userId,
            reason: "post_charge_commit_failed",
          },
        });
      }
      throw error;
    }
  });

// --- Organizer wallet (global <-> organizer sub-ledger) — must not be client-writable ---
const isEventApplicationDocumentPath = (path: string): boolean => {
  const parts = path.split("/").filter(Boolean);
  const idx = parts.indexOf("events");
  return idx >= 0 && parts[idx + 2] === "applications";
};

const organizerAppStatusApprovedLike = (raw: unknown): boolean => {
  const s = String(raw ?? "").trim().toUpperCase().replace(/-/g, "_").replace(/\s+/g, "_");
  return ["APPROVED", "ACCEPTED", "ATTENDED", "COMPLETED"].includes(s);
};

const organizerAppStatusRejectedLike = (raw: unknown): boolean => {
  const s = String(raw ?? "").trim().toUpperCase().replace(/-/g, "_").replace(/\s+/g, "_");
  return ["REJECTED", "REJECTED_BY_EMPLOYER", "WITHDRAWN"].includes(s);
};

/** Paid event tickets: organizer net is already credited to `users/{organizer}/wallet` in `applyForEvent`. */
const eventTicketNetAlreadyInOrganizerUserWallet = (d: Record<string, unknown>): boolean => {
  const ps = String(d.paymentStatus ?? "").trim().toUpperCase();
  if (ps === "PAID") return true;
  if (d.paymentProcessedAt) return true;
  return false;
};

const readPositiveMoneyField = (data: Record<string, unknown>, keys: string[]): number => {
  for (const k of keys) {
    const v = data[k];
    if (typeof v === "number" && Number.isFinite(v) && v > 0) {
      return roundMoney(v);
    }
    if (typeof v === "string") {
      const n = Number.parseFloat(v.trim());
      if (Number.isFinite(n) && n > 0) return roundMoney(n);
    }
  }
  return 0;
};

const computeOrganizerApplicationNetUsd = async (organizerId: string): Promise<{ income: number; refunds: number }> => {
  const merged = new Map<string, FirebaseFirestore.QueryDocumentSnapshot>();
  const queries = [
    db.collectionGroup("applications").where("organizerId", "==", organizerId).limit(450),
    db.collectionGroup("applications").where("organizerUid", "==", organizerId).limit(450),
  ];
  for (const q of queries) {
    const snap = await q.get();
    for (const doc of snap.docs) {
      if (!isEventApplicationDocumentPath(doc.ref.path)) continue;
      merged.set(doc.ref.path, doc);
    }
  }
  let income = 0;
  let refunds = 0;
  for (const doc of merged.values()) {
    const d = doc.data() as Record<string, unknown>;
    const ticketPrice = readPositiveMoneyField(d, ["ticketPrice", "eventFee", "payment", "amount"]);
    const organizerNet = readPositiveMoneyField(d, ["organizerNetAmount", "transactionAmount"]);
    const settled = roundMoney(Math.max(organizerNet > 0 ? organizerNet : ticketPrice, 0));
    if (settled <= 0) continue;
    if (organizerAppStatusApprovedLike(d.status)) {
      if (eventTicketNetAlreadyInOrganizerUserWallet(d)) {
        continue;
      }
      income += settled;
    } else if (organizerAppStatusRejectedLike(d.status)) refunds += settled;
  }
  return {income: roundMoney(income), refunds: roundMoney(refunds)};
};

const parseOrganizerWalletTransferRowsFromOrganizerDoc = (
  data: FirebaseFirestore.DocumentData | undefined
): Array<Record<string, unknown>> => {
  const raw = (data?.walletTransfers ?? data?.organizerWalletTransfers ?? []) as unknown;
  if (!Array.isArray(raw)) return [];
  return raw.filter((r: unknown): r is Record<string, unknown> => Boolean(r) && typeof r === "object");
};

const organizerWalletTransferRowKind = (row: Record<string, unknown>): "FROM_GLOBAL" | "TO_GLOBAL" => {
  const raw = String(row.type ?? row.direction ?? row.kind ?? "")
    .trim()
    .toUpperCase()
    .replace(/\s+/g, "_")
    .replace(/-/g, "_");
  if (raw.includes("TO_GLOBAL") || raw === "WITHDRAW_TO_GLOBAL") return "TO_GLOBAL";
  return "FROM_GLOBAL";
};

const sumOrganizerWalletTransferLiquidityUsd = (
  rows: Array<Record<string, unknown>>
): { transferIn: number; transferOut: number } => {
  let transferIn = 0;
  let transferOut = 0;
  for (const row of rows) {
    const amount = Number(row.amount ?? row.value ?? row.transactionAmount);
    if (!Number.isFinite(amount) || amount <= 0) continue;
    const rounded = roundMoney(amount);
    if (organizerWalletTransferRowKind(row) === "TO_GLOBAL") transferOut += rounded;
    else transferIn += rounded;
  }
  return {transferIn: roundMoney(transferIn), transferOut: roundMoney(transferOut)};
};

interface CreateOrganizerWalletTransferRequest {
  type?: unknown;
  amount?: unknown;
  note?: unknown;
}

export const createOrganizerWalletTransfer = functions.runWith({enforceAppCheck: true}).https.onCall(async (data, context) => {
  if (!context.auth?.uid) {
    throw new functions.https.HttpsError("unauthenticated", "Sign in required.");
  }
  throw legacyWalletCustodyDisabledError("Organizer wallet transfers");

  const organizerId = context.auth.uid;
  const payload = (data || {}) as CreateOrganizerWalletTransferRequest;
  const rawType = String(payload.type ?? "").trim().toUpperCase().replace(/\s+/g, "_").replace(/-/g, "_");
  const transferKind: "FROM_GLOBAL" | "TO_GLOBAL" =
    rawType === "TO_GLOBAL" || rawType === "WITHDRAW_TO_GLOBAL" ? "TO_GLOBAL" : "FROM_GLOBAL";

  const amount = roundMoney(Number(payload.amount));
  if (!Number.isFinite(amount) || amount <= 0) {
    throw new functions.https.HttpsError("invalid-argument", "Amount must be a positive number.");
  }

  const noteRaw = typeof payload.note === "string" ? String(payload.note).trim() : "";
  const note = noteRaw.length > 280 ? noteRaw.slice(0, 280) : noteRaw;

  const {income, refunds} = await computeOrganizerApplicationNetUsd(organizerId);

  const userRef = db.collection("users").doc(organizerId);
  const organizerRef = db.collection("organizers").doc(organizerId);
  const transferId = db.collection("organizers").doc().id;
  const now = admin.firestore.Timestamp.now();

  const newRow: Record<string, unknown> = {
    id: transferId,
    type: transferKind,
    amount,
    status: "COMPLETED",
    createdAt: now,
  };
  if (note) newRow.note = note;

  await db.runTransaction(async (transaction) => {
    const userSnap = await transaction.get(userRef);
    const organizerSnap = await transaction.get(organizerRef);

    if (!userSnap.exists) {
      throw new functions.https.HttpsError("not-found", "User profile not found.");
    }
    const userData = (userSnap.data() || {}) as Record<string, unknown>;
    assertLegacyInternalWalletAllowed(userData, "Organizer wallet transfer");
    const balance = getWalletSpendableBalance(userData);

    const orgData = organizerSnap.data() || {};
    const rows = parseOrganizerWalletTransferRowsFromOrganizerDoc(orgData);
    const {transferIn, transferOut} = sumOrganizerWalletTransferLiquidityUsd(rows);
    const available = roundMoney(income - refunds + transferIn - transferOut);

    if (transferKind === "FROM_GLOBAL") {
      if (balance < amount) {
        throw new functions.https.HttpsError("failed-precondition", "Insufficient global wallet balance.");
      }
      transaction.update(userRef, "wallet.balance", admin.firestore.FieldValue.increment(-amount));
      transaction.set(userRef.collection("transactions").doc(), {
        title: "Organizer wallet: deposit from global",
        amount: -amount,
        type: "DEBIT",
        status: "COMPLETED",
        timestamp: now,
        source: "ORGANIZER_WALLET_FROM_GLOBAL",
        note: note || null,
      });
    } else {
      if (amount > available) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Insufficient organizer wallet balance for withdrawal."
        );
      }
      transaction.update(userRef, "wallet.balance", admin.firestore.FieldValue.increment(amount));
      transaction.set(userRef.collection("transactions").doc(), {
        title: "Organizer wallet: withdraw to global",
        amount,
        type: "CREDIT",
        status: "COMPLETED",
        timestamp: now,
        source: "ORGANIZER_WALLET_TO_GLOBAL",
        note: note || null,
      });
    }

    const mergedRows = [newRow, ...rows].slice(0, 200);
    transaction.set(
      organizerRef,
      {
        walletTransfers: mergedRows,
        walletUpdatedAt: now,
      },
      {merge: true}
    );
  });

  return {
    success: true,
    entry: {
      id: transferId,
      type: transferKind,
      amount,
      status: "COMPLETED",
      createdAt: now,
      ...(note ? {note} : {}),
    },
  };
});


// =============================================================================
//  4. BLIND DATE FUNCTION (UPDATED)
// =============================================================================

interface JoinBlindDateRequest {
  mediaUrls: string[];
  bio: string;
  gender: string;
  fundingPreference?: unknown;
}

interface RejoinBlindDateRequest {
  fundingPreference?: unknown;
}

type BlindDateFundingPreference = "STRIPE_CARD" | "AFRIEX_MOBILE_MONEY";

const normalizeBlindDateFundingPreference = (
  value: unknown
): BlindDateFundingPreference => {
  const normalized = String(value || "").trim().toUpperCase();
  // Legacy clients only supported mobile money; never infer a card charge without consent.
  if (!normalized || normalized === "AFRIEX_MOBILE_MONEY") return "AFRIEX_MOBILE_MONEY";
  if (normalized === "STRIPE_CARD") return "STRIPE_CARD";
  throw new functions.https.HttpsError(
    "invalid-argument",
    "Select a supported Blind Date payment method."
  );
};

const createBlindDateStripeFeeCharge = async (params: {
  userId: string;
  userData: Record<string, unknown>;
  feeUsd: number;
  flow: "BLIND_DATE_JOIN" | "BLIND_DATE_REJOIN";
}): Promise<Awaited<ReturnType<typeof createStripeCardCommerceCharge>>> => {
  const isRejoin = params.flow === "BLIND_DATE_REJOIN";
  return createStripeCardCommerceCharge({
    payerUserId: params.userId,
    payerUserData: params.userData,
    amount: params.feeUsd,
    currency: "USD",
    description: isRejoin ? "Blind Date rejoin fee" : "Blind Date entry fee",
    metadata: {
      flow: params.flow,
      userId: params.userId,
    },
    // A fresh checkout attempt permits recovery after a declined or expired saved card.
    idempotencyKey: `blind_date_${params.flow.toLowerCase()}_${params.userId}_${randomUUID()}`,
  });
};

export const joinBlindDate = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in to join.");
    }
    const userId = context.auth.uid;
    const requestData = data as JoinBlindDateRequest;
    if (!requestData.mediaUrls || !Array.isArray(requestData.mediaUrls) || requestData.mediaUrls.length === 0 || !requestData.bio || !requestData.gender) {
      throw new functions.https.HttpsError("invalid-argument", "Missing required data: mediaUrls, bio, or gender.");
    }

    const blindDateFee = await loadBlindDateFeeUsd();
    const userRef = db.collection("users").doc(userId);
    const blindDateProfileRef = db.collection("blindDateProfiles").doc(userId);
    const userRecord = await admin.auth().getUser(userId);
    const [userDoc, blindProfileDoc] = await Promise.all([
      userRef.get(),
      blindDateProfileRef.get(),
    ]);

    if (!userDoc.exists) {
      throw new functions.https.HttpsError("not-found", "User profile not found.");
    }

    await assertBlindDateFeatureEnabled();

    const userData = await withPrivateUserFields(
      userId,
      (userDoc.data() || {}) as Record<string, unknown>
    );
    assertUserCanAccessDating(userData);
    await assertDatingProfileExists(userId);
    assertBlindDateMediaUrlsOwnedByUser(userId, requestData.mediaUrls);

    if (blindProfileDoc.exists) {
      const existingStatus = String(blindProfileDoc.data()?.status ?? "").trim().toLowerCase();
      if (existingStatus === "active") {
        throw new functions.https.HttpsError("failed-precondition", "You are already active in Blind Date.");
      }
      if (existingStatus === "matched") {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "You are matched. Use Rejoin to return to the browse pool."
        );
      }
      if (existingStatus === "awaiting_payment" || existingStatus === "awaiting_rejoin_payment") {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Your previous Blind Date payment is still awaiting approval on your phone."
        );
      }
    }

    const isStaffOrOwner = isStaffFeeExempt(
      userData,
      (context.auth?.token || {}) as Record<string, unknown>
    );
    const shouldChargeBlindDateFee = blindDateFee > 0 && !isStaffOrOwner;
    const requestedFundingPreference = normalizeBlindDateFundingPreference(
      requestData.fundingPreference
    );
    let afriexFundingMethod: AfriexCommerceFundingMethod | null = null;
    let stripeChargeResult: Awaited<ReturnType<typeof createStripeCardCommerceCharge>> | null = null;
    if (shouldChargeBlindDateFee) {
      if (requestedFundingPreference === "AFRIEX_MOBILE_MONEY") {
        afriexFundingMethod = await resolveReadyAfriexCommerceFundingMethodForUser(userId);
        if (!afriexFundingMethod) {
          throw new functions.https.HttpsError(
            "failed-precondition",
            "Blind Date entry requires verified mobile money in an eligible collection country. Add or verify it in Wallet > Payment Methods, or pay by saved card."
          );
        }
      } else {
        try {
          stripeChargeResult = await createBlindDateStripeFeeCharge({
            userId,
            userData,
            feeUsd: blindDateFee,
            flow: "BLIND_DATE_JOIN",
          });
        } catch (error) {
          throw mapStripeCommerceChargeError(error);
        }
      }
    }

    functions.logger.log(`User ${userId} attempting to join blind date for a fee of ${blindDateFee}.`);

    try {
      let feeCharged = 0;
      let awaitingPayment = false;
      await db.runTransaction(async (transaction) => {
        const blindSnap = await transaction.get(blindDateProfileRef);
        if (blindSnap.exists) {
          const st = String(blindSnap.data()?.status ?? "").trim().toLowerCase();
          if (st === "active") {
            throw new functions.https.HttpsError("failed-precondition", "You are already active in Blind Date.");
          }
          if (st === "matched") {
            throw new functions.https.HttpsError(
              "failed-precondition",
              "You are matched. Use Rejoin to return to the browse pool."
            );
          }
          if (st === "awaiting_payment" || st === "awaiting_rejoin_payment") {
            throw new functions.https.HttpsError(
              "failed-precondition",
              "Your previous Blind Date payment is still awaiting approval on your phone."
            );
          }
        }
        const userDoc = await transaction.get(userRef);
        if (!userDoc.exists) throw new functions.https.HttpsError("not-found", "User profile not found.");
        const now = admin.firestore.Timestamp.now();
        const baseProfileData: FirebaseFirestore.DocumentData = {
          userId,
          name: userRecord.displayName ?? "Anonymous User",
          profilePictureUrl: userRecord.photoURL ?? "",
          gender: requestData.gender,
          media: requestData.mediaUrls,
          bio: requestData.bio,
          createdAt: now,
          updatedAt: now,
        };
        if (shouldChargeBlindDateFee && afriexFundingMethod) {
          const collectionRef = db.collection("payout_requests").doc();
          transaction.set(collectionRef, {
            senderId: userId,
            amount: blindDateFee,
            currency: "USD",
            phone: afriexFundingMethod.phoneNumber,
            network: afriexFundingMethod.network,
            country: afriexFundingMethod.country,
            dialCode: afriexFundingMethod.dialCode,
            localCurrency: afriexFundingMethod.currency,
            paymentMethodId: afriexFundingMethod.paymentMethodId,
            type: "CASH_IN",
            status: "PENDING",
            source: buildAfriexCommerceCollectionSource("BLIND_DATE_JOIN"),
            fundingSource: "EXTERNAL_MOBILE_MONEY",
            fundingPreference: requestedFundingPreference,
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            createdAt: now,
            processedAt: now,
            transferIntent: {
              mode: AFRIEX_COMMERCE_TRANSFER_MODE,
              settlementCategory: "BLIND_DATE_JOIN",
              commerceTitle: "Blind Date Entry",
              userId,
              grossAmount: blindDateFee,
              platformFee: blindDateFee,
              requestedCurrency: "USD",
              processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            },
          }, {merge: true});
          transaction.set(blindDateProfileRef, {
            ...baseProfileData,
            status: "awaiting_payment",
            paymentStatus: "AWAITING_COLLECTION",
            fundingPreference: requestedFundingPreference,
            paymentProcessor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            providerRoutingStatus: "PENDING_COLLECTION",
            providerRoutingMessage: "Mobile money collection started. Approve the prompt on your phone to activate your Blind Date profile.",
            pendingCollectionRequestId: collectionRef.id,
          }, {merge: true});
          feeCharged = blindDateFee;
          awaitingPayment = true;
        } else if (shouldChargeBlindDateFee && stripeChargeResult) {
          const transactionRef = userRef.collection("transactions").doc();
          transaction.set(transactionRef, {
            title: "Blind Date Entry",
            amount: -blindDateFee,
            type: "DEBIT",
            status: "COMPLETED",
            timestamp: now,
            source: "BLIND_DATE_STRIPE",
            processor: "STRIPE",
            stripePaymentIntentId: stripeChargeResult.paymentIntentId,
            stripeChargeId: stripeChargeResult.latestChargeId,
            fundingPaymentMethodId: stripeChargeResult.fundingPaymentMethodDocId,
            note: "Charged to your saved card for Blind Date entry.",
          });
          recordPlatformRevenue(transaction, {
            source: "blindDateFees",
            amount: blindDateFee,
            note: "Blind Date entry fee via Stripe",
            relatedUserId: userId,
            processor: "STRIPE",
            provider: "STRIPE",
            settlementCategory: "BLIND_DATE",
            processorMode: "STRIPE_CARD_COLLECTION",
          });
          transaction.set(blindDateProfileRef, {
            ...baseProfileData,
            status: "active",
            paymentStatus: "PAID",
            fundingPreference: requestedFundingPreference,
            paymentProcessor: "STRIPE",
            collectionProcessor: "STRIPE",
            settlementProvider: "STRIPE",
            processorMode: "STRIPE_CARD_COLLECTION",
            providerRoutingStatus: "COLLECTION_COMPLETED",
            providerRoutingMessage: "Card payment approved. Blind Date profile is now active.",
            stripePaymentIntentId: stripeChargeResult.paymentIntentId,
            stripeChargeId: stripeChargeResult.latestChargeId,
            fundingPaymentMethodId: stripeChargeResult.fundingPaymentMethodDocId,
            pendingCollectionRequestId: admin.firestore.FieldValue.delete(),
            activatedAt: now,
          }, {merge: true});
          feeCharged = blindDateFee;
        } else {
          const transactionRef = userRef.collection("transactions").doc();
          transaction.set(transactionRef, {
            title: "Blind Date Entry (Staff Exempt)",
            amount: 0,
            type: "INFO",
            status: "COMPLETED",
            timestamp: now,
            source: "BLIND_DATE_STAFF_EXEMPT",
            note: "Owner/admin/associate access applied. No fee charged.",
          });
          transaction.set(blindDateProfileRef, {
            ...baseProfileData,
            status: "active",
            paymentStatus: blindDateFee > 0 ? "WAIVED" : "NOT_REQUIRED",
            fundingPreference: requestedFundingPreference,
            paymentProcessor: blindDateFee > 0 ? "STAFF_EXEMPT" : null,
          }, {merge: true});
        }
      });
      functions.logger.log(`User ${userId} successfully started blind date join flow.`);
      return {
        success: true,
        charged: !awaitingPayment && feeCharged > 0,
        awaitingPayment,
        feeCharged,
        message: awaitingPayment ?
          `Your ${blindDateFee.toFixed(2)} USD Blind Date approval prompt has been sent. Approve it on your phone to activate your profile.` :
          (feeCharged > 0 ?
            "Card payment approved. Your Blind Date profile is now active." :
            (blindDateFee > 0 ?
            "Staff/owner exemption applied. You joined with no fee." :
            "You joined Blind Date. No entry fee is configured right now.")),
      };
    } catch (error) {
      if (stripeChargeResult) {
        try {
          await refundStripeCommercePaymentIntent({
            paymentIntentId: stripeChargeResult.paymentIntentId,
            idempotencyKey: `blind_date_join_refund_${stripeChargeResult.paymentIntentId}`,
            metadata: {flow: "BLIND_DATE_JOIN", userId, reason: "post_charge_commit_failed"},
          });
        } catch (refundError) {
          functions.logger.error("Blind Date join card refund failed after a commit error:", refundError);
        }
      }
      functions.logger.error(`Failed to join blind date for user ${userId}:`, error);
      if (error instanceof functions.https.HttpsError) throw error;
      throw new functions.https.HttpsError("internal", "An unexpected error occurred. Please try again.");
    }
  });


// =============================================================================
//  5. ACCEPT INVITATION FUNCTION (UPDATED)
// =============================================================================

interface AcceptInvitationRequest {
  senderId: string;
}

export const acceptBlindDateInvitation = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    const acceptorId = context.auth.uid;
    const senderId = (data as AcceptInvitationRequest).senderId;
    if (!senderId) throw new functions.https.HttpsError("invalid-argument", "The 'senderId' is required.");

    const acceptorProfileRef = db.collection("blindDateProfiles").doc(acceptorId);
    const senderProfileRef = db.collection("blindDateProfiles").doc(senderId);
    const acceptorInviteRef = db.collection("users").doc(acceptorId).collection("blindDateInvitations").doc(senderId);
    const senderSentInviteRef = db.collection("users").doc(senderId).collection("blindDateSentInvitations").doc(acceptorId);
    const newChatRef = db.collection("chats").doc();

    functions.logger.log(`User ${acceptorId} is attempting to accept invitation from ${senderId}.`);
    try {
      await assertBlindDateFeatureEnabled();
      await assertUsersAreNotBlocked(acceptorId, senderId);

      const [acceptorUserDoc, senderUserDoc] = await Promise.all([
        db.collection("users").doc(acceptorId).get(),
        db.collection("users").doc(senderId).get(),
      ]);
      if (!acceptorUserDoc.exists || !senderUserDoc.exists) {
        throw new functions.https.HttpsError("not-found", "User profile not found.");
      }
      const acceptorUserData = await withPrivateUserFields(
        acceptorId,
        (acceptorUserDoc.data() || {}) as Record<string, unknown>
      );
      const senderUserData = await withPrivateUserFields(
        senderId,
        (senderUserDoc.data() || {}) as Record<string, unknown>
      );
      assertUserCanAccessDating(acceptorUserData);
      assertUserCanAccessDating(senderUserData);

      await db.runTransaction(async (transaction) => {
        const acceptorProfile = await transaction.get(acceptorProfileRef);
        const senderProfile = await transaction.get(senderProfileRef);
        const acceptorInvite = await transaction.get(acceptorInviteRef);

        if (!acceptorProfile.exists || String(acceptorProfile.data()?.status || "").trim().toLowerCase() !== "active") {
          throw new functions.https.HttpsError("failed-precondition", "Your profile is not active for matching.");
        }
        if (!senderProfile.exists || String(senderProfile.data()?.status || "").trim().toLowerCase() !== "active") {
          throw new functions.https.HttpsError("failed-precondition", "The other user is no longer available for matching.");
        }
        if (!acceptorInvite.exists) throw new functions.https.HttpsError("not-found", "Invitation not found.");
        const invitationStatus = String(acceptorInvite.data()?.status || "").toLowerCase();
        if (invitationStatus !== "pending") throw new functions.https.HttpsError("failed-precondition", "This invitation is no longer pending.");

        const now = admin.firestore.Timestamp.now();
        const acceptorName = asNonEmptyString(
          acceptorProfile.data()?.name,
          acceptorUserDoc.get("name"),
          acceptorUserDoc.get("username")
        ) || "User";
        const senderName = asNonEmptyString(
          senderProfile.data()?.name,
          senderUserDoc.get("name"),
          senderUserDoc.get("username")
        ) || "User";
        const pairKey = buildDirectChatParticipantPairKey(acceptorId, senderId);
        const seedMessage = "Blind Date match! Say hi.";
        const chatData = {
          chatType: "direct",
          participants: [acceptorId, senderId],
          participantPairKey: pairKey,
          participantDisplayNames: {
            [acceptorId]: acceptorName,
            [senderId]: senderName,
          },
          exitedParticipantIds: [] as string[],
          lastMessage: seedMessage,
          lastMessageText: seedMessage,
          lastMessageTimestamp: now,
          lastMessageSenderId: senderId,
          lastMessageType: "TEXT",
          updatedAt: now,
        };
        const seedMessageRef = newChatRef.collection("messages").doc();
        transaction.set(newChatRef, chatData);
        transaction.set(seedMessageRef, {
          senderId,
          senderDisplayName: senderName,
          messageText: seedMessage,
          text: seedMessage,
          timestamp: now,
          messageType: "TEXT",
        });
        transaction.set(acceptorProfileRef, {
          status: "matched",
          matchedPartnerId: senderId,
          matchedChatId: newChatRef.id,
          formerMatchedPartnerId: admin.firestore.FieldValue.delete(),
          matchReleasedAt: admin.firestore.FieldValue.delete(),
          updatedAt: now,
        }, {merge: true});
        transaction.set(senderProfileRef, {
          status: "matched",
          matchedPartnerId: acceptorId,
          matchedChatId: newChatRef.id,
          formerMatchedPartnerId: admin.firestore.FieldValue.delete(),
          matchReleasedAt: admin.firestore.FieldValue.delete(),
          updatedAt: now,
        }, {merge: true});
        transaction.update(acceptorInviteRef, {
          status: "accepted",
          updatedAt: now,
          respondedAt: now,
          matchedChatId: newChatRef.id,
        });
        transaction.set(senderSentInviteRef, {
          status: "matched",
          updatedAt: now,
          respondedAt: now,
          matchedChatId: newChatRef.id,
        }, {merge: true});
      });
      functions.logger.log(`Successfully matched users ${acceptorId} and ${senderId}. Chat ID: ${newChatRef.id}`);
      return {success: true, chatId: newChatRef.id, otherUserId: senderId};
    } catch (error) {
      functions.logger.error(`Match creation failed between ${acceptorId} and ${senderId}:`, error);
      if (error instanceof functions.https.HttpsError) throw error;
      throw new functions.https.HttpsError("internal", "Failed to accept the invitation. Please try again.");
    }
  });

export const releaseStaleBlindDateMatchHolds = functions.pubsub
  .schedule("every 6 hours")
  .onRun(async () => {
    const now = admin.firestore.Timestamp.now();
    const cutoff = admin.firestore.Timestamp.fromMillis(now.toMillis() - BLIND_DATE_MATCH_HOLD_MS);
    const snapshot = await db.collection("blindDateProfiles")
      .where("matchReleasedAt", "<=", cutoff)
      .limit(250)
      .get();

    if (snapshot.empty) {
      return null;
    }

    let releasedCount = 0;
    let batch = db.batch();
    let batchCount = 0;

    for (const doc of snapshot.docs) {
      const data = (doc.data() || {}) as Record<string, unknown>;
      if (!asNonEmptyString(data.formerMatchedPartnerId)) {
        continue;
      }
      batch.set(doc.ref, {
        formerMatchedPartnerId: admin.firestore.FieldValue.delete(),
        matchHoldExpiredAt: now,
        updatedAt: now,
      }, {merge: true});
      releasedCount += 1;
      batchCount += 1;
      if (batchCount >= 400) {
        await batch.commit();
        batch = db.batch();
        batchCount = 0;
      }
    }

    if (batchCount > 0) {
      await batch.commit();
    }

    functions.logger.log(`Released ${releasedCount} expired Blind Date match holds.`);
    return null;
  });

interface DeclineInvitationRequest {
  senderId: string;
}

export const declineBlindDateInvitation = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    const recipientId = context.auth.uid;
    const senderId = (data as DeclineInvitationRequest).senderId;
    if (!senderId) throw new functions.https.HttpsError("invalid-argument", "The 'senderId' is required.");

    const recipientInviteRef = db.collection("users").doc(recipientId).collection("blindDateInvitations").doc(senderId);
    const senderSentInviteRef = db.collection("users").doc(senderId).collection("blindDateSentInvitations").doc(recipientId);

    functions.logger.log(`User ${recipientId} is declining invitation from ${senderId}.`);
    try {
      await assertBlindDateFeatureEnabled();
      await assertUsersAreNotBlocked(recipientId, senderId);

      const [recipientUserDoc, senderUserDoc] = await Promise.all([
        db.collection("users").doc(recipientId).get(),
        db.collection("users").doc(senderId).get(),
      ]);
      if (!recipientUserDoc.exists || !senderUserDoc.exists) {
        throw new functions.https.HttpsError("not-found", "User profile not found.");
      }
      const recipientUserData = await withPrivateUserFields(
        recipientId,
        (recipientUserDoc.data() || {}) as Record<string, unknown>
      );
      const senderUserData = await withPrivateUserFields(
        senderId,
        (senderUserDoc.data() || {}) as Record<string, unknown>
      );
      assertUserCanAccessDating(recipientUserData);
      assertUserCanAccessDating(senderUserData);

      await db.runTransaction(async (transaction) => {
        const recipientInvite = await transaction.get(recipientInviteRef);
        if (!recipientInvite.exists) throw new functions.https.HttpsError("not-found", "Invitation not found.");
        const invitationStatus = String(recipientInvite.data()?.status || "").toLowerCase();
        if (invitationStatus !== "pending") throw new functions.https.HttpsError("failed-precondition", "This invitation is no longer pending.");

        const now = admin.firestore.Timestamp.now();
        transaction.update(recipientInviteRef, {
          status: "declined",
          updatedAt: now,
          respondedAt: now,
        });
        transaction.set(senderSentInviteRef, {
          status: "declined",
          updatedAt: now,
          respondedAt: now,
        }, {merge: true});
      });
      return {success: true, message: "Invitation declined."};
    } catch (error) {
      functions.logger.error(`Failed to decline invitation for ${recipientId} from ${senderId}:`, error);
      if (error instanceof functions.https.HttpsError) throw error;
      throw new functions.https.HttpsError("internal", "Failed to decline invitation. Please try again.");
    }
  });


// =============================================================================
//  6. RE-JOIN BLIND DATE FUNCTION (UPDATED)
// =============================================================================

export const rejoinBlindDate = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) throw new functions.https.HttpsError("unauthenticated", "You must be logged in to rejoin.");
    const userId = context.auth.uid;
    const requestData = data as RejoinBlindDateRequest;
    const blindDateFee = await loadBlindDateFeeUsd();
    const userRef = db.collection("users").doc(userId);
    const blindDateProfileRef = db.collection("blindDateProfiles").doc(userId);
    const [userDoc, blindDateProfileDoc] = await Promise.all([
      userRef.get(),
      blindDateProfileRef.get(),
    ]);

    if (!userDoc.exists) {
      throw new functions.https.HttpsError("not-found", "User profile not found.");
    }
    if (!blindDateProfileDoc.exists) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "You do not have an existing blind date profile to rejoin."
      );
    }
    if (String(blindDateProfileDoc.data()?.status || "").trim().toLowerCase() !== "matched") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "You are not in a 'matched' state. You might already be active."
      );
    }

    await assertBlindDateFeatureEnabled();

    const userData = await withPrivateUserFields(
      userId,
      (userDoc.data() || {}) as Record<string, unknown>
    );
    assertUserCanAccessDating(userData);
    const isStaffOrOwner = isStaffFeeExempt(
      userData,
      (context.auth?.token || {}) as Record<string, unknown>
    );
    const shouldChargeBlindDateFee = blindDateFee > 0 && !isStaffOrOwner;
    const requestedFundingPreference = normalizeBlindDateFundingPreference(
      requestData.fundingPreference
    );
    let afriexFundingMethod: AfriexCommerceFundingMethod | null = null;
    let stripeChargeResult: Awaited<ReturnType<typeof createStripeCardCommerceCharge>> | null = null;
    if (shouldChargeBlindDateFee) {
      if (requestedFundingPreference === "AFRIEX_MOBILE_MONEY") {
        afriexFundingMethod = await resolveReadyAfriexCommerceFundingMethodForUser(userId);
        if (!afriexFundingMethod) {
          throw new functions.https.HttpsError(
            "failed-precondition",
            "Blind Date rejoin requires verified mobile money in an eligible collection country. Add or verify it in Wallet > Payment Methods, or pay by saved card."
          );
        }
      } else {
        try {
          stripeChargeResult = await createBlindDateStripeFeeCharge({
            userId,
            userData,
            feeUsd: blindDateFee,
            flow: "BLIND_DATE_REJOIN",
          });
        } catch (error) {
          throw mapStripeCommerceChargeError(error);
        }
      }
    }
    functions.logger.log(`User ${userId} attempting to RE-JOIN blind date for a fee of ${blindDateFee}.`);
    try {
      let feeCharged = 0;
      let awaitingPayment = false;
      await db.runTransaction(async (transaction) => {
        const userDoc = await transaction.get(userRef);
        const blindDateProfileDoc = await transaction.get(blindDateProfileRef);

        if (!userDoc.exists) throw new functions.https.HttpsError("not-found", "User profile not found.");
        if (!blindDateProfileDoc.exists) throw new functions.https.HttpsError("failed-precondition", "You do not have an existing blind date profile to rejoin.");
        if (String(blindDateProfileDoc.data()?.status || "").trim().toLowerCase() !== "matched") {
          throw new functions.https.HttpsError("failed-precondition", "You are not in a 'matched' state. You might already be active.");
        }
        const now = admin.firestore.Timestamp.now();
        if (shouldChargeBlindDateFee && afriexFundingMethod) {
          const collectionRef = db.collection("payout_requests").doc();
          transaction.set(collectionRef, {
            senderId: userId,
            amount: blindDateFee,
            currency: "USD",
            phone: afriexFundingMethod.phoneNumber,
            network: afriexFundingMethod.network,
            country: afriexFundingMethod.country,
            dialCode: afriexFundingMethod.dialCode,
            localCurrency: afriexFundingMethod.currency,
            paymentMethodId: afriexFundingMethod.paymentMethodId,
            type: "CASH_IN",
            status: "PENDING",
            source: buildAfriexCommerceCollectionSource("BLIND_DATE_REJOIN"),
            fundingSource: "EXTERNAL_MOBILE_MONEY",
            fundingPreference: requestedFundingPreference,
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            createdAt: now,
            processedAt: now,
            transferIntent: {
              mode: AFRIEX_COMMERCE_TRANSFER_MODE,
              settlementCategory: "BLIND_DATE_REJOIN",
              commerceTitle: "Blind Date Rejoin",
              userId,
              grossAmount: blindDateFee,
              platformFee: blindDateFee,
              requestedCurrency: "USD",
              processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            },
          }, {merge: true});
          transaction.set(blindDateProfileRef, {
            status: "awaiting_rejoin_payment",
            paymentStatus: "AWAITING_COLLECTION",
            fundingPreference: requestedFundingPreference,
            paymentProcessor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            providerRoutingStatus: "PENDING_COLLECTION",
            providerRoutingMessage: "Mobile money collection started. Approve the prompt on your phone to rejoin Blind Date.",
            pendingCollectionRequestId: collectionRef.id,
            updatedAt: now,
          }, {merge: true});
          feeCharged = blindDateFee;
          awaitingPayment = true;
        } else if (shouldChargeBlindDateFee && stripeChargeResult) {
          const transactionRef = userRef.collection("transactions").doc();
          transaction.set(transactionRef, {
            title: "Blind Date Rejoin",
            amount: -blindDateFee,
            type: "DEBIT",
            status: "COMPLETED",
            timestamp: now,
            source: "BLIND_DATE_REJOIN_STRIPE",
            processor: "STRIPE",
            stripePaymentIntentId: stripeChargeResult.paymentIntentId,
            stripeChargeId: stripeChargeResult.latestChargeId,
            fundingPaymentMethodId: stripeChargeResult.fundingPaymentMethodDocId,
            note: "Charged to your saved card for Blind Date rejoin.",
          });
          recordPlatformRevenue(transaction, {
            source: "blindDateFees",
            amount: blindDateFee,
            note: "Blind Date rejoin fee via Stripe",
            relatedUserId: userId,
            processor: "STRIPE",
            provider: "STRIPE",
            settlementCategory: "BLIND_DATE",
            processorMode: "STRIPE_CARD_COLLECTION",
          });
          finalizeBlindDateRejoinActivation(
            transaction,
            userId,
            (blindDateProfileDoc.data() || {}) as Record<string, unknown>,
            now,
            {
              paymentStatus: "PAID",
              fundingPreference: requestedFundingPreference,
              paymentProcessor: "STRIPE",
              collectionProcessor: "STRIPE",
              settlementProvider: "STRIPE",
              processorMode: "STRIPE_CARD_COLLECTION",
              providerRoutingStatus: "COLLECTION_COMPLETED",
              providerRoutingMessage: "Card payment approved. Blind Date profile is active again.",
              stripePaymentIntentId: stripeChargeResult.paymentIntentId,
              stripeChargeId: stripeChargeResult.latestChargeId,
              fundingPaymentMethodId: stripeChargeResult.fundingPaymentMethodDocId,
              pendingCollectionRequestId: admin.firestore.FieldValue.delete(),
              activatedAt: now,
            }
          );
          feeCharged = blindDateFee;
        } else {
          const transactionRef = userRef.collection("transactions").doc();
          transaction.set(transactionRef, {
            title: "Blind Date Rejoin (Staff Exempt)",
            amount: 0,
            type: "INFO",
            status: "COMPLETED",
            timestamp: now,
            source: "BLIND_DATE_REJOIN_STAFF_EXEMPT",
            note: "Owner/admin/associate access applied. No fee charged.",
          });
          finalizeBlindDateRejoinActivation(
            transaction,
            userId,
            (blindDateProfileDoc.data() || {}) as Record<string, unknown>,
            now,
            {
              paymentStatus: blindDateFee > 0 ? "WAIVED" : "NOT_REQUIRED",
              fundingPreference: requestedFundingPreference,
              paymentProcessor: blindDateFee > 0 ? "STAFF_EXEMPT" : null,
              pendingCollectionRequestId: admin.firestore.FieldValue.delete(),
            }
          );
        }
      });
      functions.logger.log(`User ${userId} successfully started blind date rejoin flow.`);
      return {
        success: true,
        charged: !awaitingPayment && feeCharged > 0,
        awaitingPayment,
        feeCharged,
        message: awaitingPayment ?
          `Your ${blindDateFee.toFixed(2)} USD Blind Date rejoin approval prompt has been sent. Approve it on your phone to become active again.` :
          (feeCharged > 0 ?
            "Card payment approved. You are active in Blind Date again." :
            (blindDateFee > 0 ?
            "Staff/owner exemption applied. You are back in the loop with no fee." :
            "You are back in the loop. No rejoin fee is configured right now.")),
      };
    } catch (error) {
      if (stripeChargeResult) {
        try {
          await refundStripeCommercePaymentIntent({
            paymentIntentId: stripeChargeResult.paymentIntentId,
            idempotencyKey: `blind_date_rejoin_refund_${stripeChargeResult.paymentIntentId}`,
            metadata: {flow: "BLIND_DATE_REJOIN", userId, reason: "post_charge_commit_failed"},
          });
        } catch (refundError) {
          functions.logger.error("Blind Date rejoin card refund failed after a commit error:", refundError);
        }
      }
      functions.logger.error(`Failed to rejoin blind date for user ${userId}:`, error);
      if (error instanceof functions.https.HttpsError) throw error;
      throw new functions.https.HttpsError("internal", "An unexpected error occurred. Please try again.");
    }
  });


