const REMITTANCE_FEE_SETTINGS_CACHE_TTL_MS = 60 * 1000;
const BLIND_DATE_FEE_SETTINGS_CACHE_TTL_MS = 60 * 1000;
// Keep normal quote traffic efficient while allowing an owner fee change to
// reach warm function instances promptly.
const PROJECT_FEE_SETTINGS_CACHE_TTL_MS = 15 * 1000;
let blindDateFeeSettingsCache: {expiresAtMs: number; feeUsd: number} | null = null;

const loadBlindDateFeeUsd = async (): Promise<number> => {
  if (blindDateFeeSettingsCache && blindDateFeeSettingsCache.expiresAtMs > Date.now()) {
    return blindDateFeeSettingsCache.feeUsd;
  }

  const snapshot = await db.collection("app_config").doc("fee_settings").get();
  const data = (snapshot.data() || {}) as Record<string, unknown>;
  let feeUsd = 0;
  if (snapshot.exists) {
    if (data.blindDateFeeUsd !== undefined && data.blindDateFeeUsd !== null) {
      feeUsd = Number(data.blindDateFeeUsd);
    } else if (data.blindDateFee !== undefined && data.blindDateFee !== null) {
      feeUsd = Number(data.blindDateFee);
    } else {
      feeUsd = Number.parseFloat(getAppConfig().blindDateFee);
    }
  } else {
    feeUsd = Number.parseFloat(getAppConfig().blindDateFee);
  }

  const resolved = roundMoney(Math.max(0, Number.isFinite(feeUsd) ? feeUsd : 0));
  blindDateFeeSettingsCache = {
    expiresAtMs: Date.now() + BLIND_DATE_FEE_SETTINGS_CACHE_TTL_MS,
    feeUsd: resolved,
  };
  return resolved;
};
let remittanceFeeSettingsCache: {
  expiresAtMs: number;
  snapshot: RemittanceFeeSettingsSnapshot;
} | null = null;

const parseNonNegativeFeeMap = (
  value: unknown,
  fallback: Record<string, number>
): Record<string, number> => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {...fallback};
  }

  const result: Record<string, number> = {...fallback};
  for (const [rawKey, rawValue] of Object.entries(value as Record<string, unknown>)) {
    const key = String(rawKey || "").trim();
    const fee = Number(rawValue);
    if (!key || !Number.isFinite(fee) || fee < 0) continue;
    result[key] = roundMoney(fee);
  }
  return result;
};

const parseUnitIntervalRateMap = (
  value: unknown,
  fallback: Record<string, number>
): Record<string, number> => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {...fallback};
  }

  const result: Record<string, number> = {...fallback};
  for (const [rawKey, rawValue] of Object.entries(value as Record<string, unknown>)) {
    const key = String(rawKey || "").trim();
    const rate = Number(rawValue);
    if (!key || !Number.isFinite(rate) || rate < 0 || rate > 1) continue;
    result[key] = rate;
  }
  return result;
};

const normalizeUnitIntervalRate = (value: unknown, fallback: number): number => {
  const candidate = Number(value);
  if (Number.isFinite(candidate) && candidate >= 0 && candidate <= 1) {
    return candidate;
  }
  const safeFallback = Number(fallback);
  if (Number.isFinite(safeFallback) && safeFallback >= 0 && safeFallback <= 1) {
    return safeFallback;
  }
  return 0;
};

type ProjectFeeSettingsSnapshot = {
  forexProfitMargin: number;
  stripeForexDepositProfitMargin: number;
  mobileMoneyHiddenFeeRate: number;
  walletExternalCurrencyChangeFeeRate: number;
  agentAuthorizationFeeUsd: number;
};

let projectFeeSettingsCache: {
  expiresAtMs: number;
  snapshot: ProjectFeeSettingsSnapshot;
} | null = null;

const loadProjectFeeSettings = async (): Promise<ProjectFeeSettingsSnapshot> => {
  if (projectFeeSettingsCache && projectFeeSettingsCache.expiresAtMs > Date.now()) {
    return projectFeeSettingsCache.snapshot;
  }

  const defaults = getAppConfig();
  const snapshot = await db.collection("app_config").doc("fee_settings").get();
  const data = (snapshot.data() || {}) as Record<string, unknown>;
  const readRate = (key: keyof ProjectFeeSettingsSnapshot, fallback: string): number =>
    normalizeUnitIntervalRate(data[key], Number.parseFloat(fallback));
  const readUsdFee = (key: keyof ProjectFeeSettingsSnapshot, fallback: string): number => {
    const configured = Number(data[key]);
    const fallbackValue = Number.parseFloat(fallback);
    const amount = Number.isFinite(configured) ? configured : fallbackValue;
    return roundMoney(Math.max(0, Number.isFinite(amount) ? amount : 0));
  };

  const resolved: ProjectFeeSettingsSnapshot = {
    forexProfitMargin: readRate("forexProfitMargin", defaults.forexProfitMargin),
    stripeForexDepositProfitMargin: readRate(
      "stripeForexDepositProfitMargin",
      defaults.stripeForexDepositProfitMargin
    ),
    mobileMoneyHiddenFeeRate: readRate(
      "mobileMoneyHiddenFeeRate",
      defaults.mobileMoneyHiddenFeeRate
    ),
    walletExternalCurrencyChangeFeeRate: readRate(
      "walletExternalCurrencyChangeFeeRate",
      defaults.walletExternalCurrencyChangeFeeRate
    ),
    agentAuthorizationFeeUsd: readUsdFee(
      "agentAuthorizationFeeUsd",
      defaults.agentAuthorizationFeeUsd
    ),
  };

  projectFeeSettingsCache = {
    expiresAtMs: Date.now() + PROJECT_FEE_SETTINGS_CACHE_TTL_MS,
    snapshot: resolved,
  };
  return resolved;
};

const loadRemittanceFeeSettings = async (): Promise<RemittanceFeeSettingsSnapshot> => {
  if (remittanceFeeSettingsCache && remittanceFeeSettingsCache.expiresAtMs > Date.now()) {
    return remittanceFeeSettingsCache.snapshot;
  }

  const snapshot = await db.collection("app_config").doc("fee_settings").get();
  const data = (snapshot.data() || {}) as Record<string, unknown>;
  const resolved: RemittanceFeeSettingsSnapshot = {
    defaultBankFeeUsd: roundMoney(Math.max(0, Number(data.remittanceDefaultBankFeeUsd || 0))),
    defaultMobileMoneyFeeUsd: roundMoney(Math.max(0, Number(data.remittanceDefaultMobileMoneyFeeUsd || 0))),
    defaultSwiftProviderFeeUsd: roundMoney(Math.max(0, Number(data.remittanceDefaultSwiftProviderFeeUsd || 0))),
    // Afriex's agreed USD SWIFT commercial is 0.25%. This remains a provider
    // cost, not platform revenue, and can be updated by the owner if terms change.
    swiftProviderFeeRate: normalizeUnitIntervalRate(data.remittanceSwiftProviderFeeRate, 0.0025),
    defaultBankTopUpUsd: roundMoney(Math.max(0, Number(data.remittanceDefaultBankTopUpUsd || 0))),
    defaultMobileMoneyTopUpUsd: roundMoney(Math.max(0, Number(data.remittanceDefaultMobileMoneyTopUpUsd || 0))),
    defaultSwiftTopUpUsd: roundMoney(Math.max(0, Number(data.remittanceDefaultSwiftTopUpUsd || 0))),
    swiftTopUpRate: normalizeUnitIntervalRate(data.remittanceSwiftTopUpRate, 0),
    swiftFxMargin: normalizeUnitIntervalRate(data.remittanceSwiftFxMargin, 0),
    stripeTransactionOwnerFeeRate: normalizeUnitIntervalRate(
      data.stripeTransactionOwnerFeeRate,
      Number.parseFloat(getAppConfig().stripeTransactionOwnerFeeRate)
    ),
    bankFeesByCountry: parseNonNegativeFeeMap(
      data.remittanceBankFeesByCountry,
      DEFAULT_REMITTANCE_BANK_FEES_BY_COUNTRY
    ),
    mobileMoneyFeesByCountry: parseNonNegativeFeeMap(
      data.remittanceMobileMoneyFeesByCountry,
      DEFAULT_REMITTANCE_MOBILE_MONEY_FEES_BY_COUNTRY
    ),
    bankTopUpByCountry: parseNonNegativeFeeMap(
      data.remittanceBankTopUpByCountry,
      {}
    ),
    mobileMoneyTopUpByCountry: parseNonNegativeFeeMap(
      data.remittanceMobileMoneyTopUpByCountry,
      {}
    ),
    bankFxMarginsByCountry: parseUnitIntervalRateMap(
      data.remittanceBankFxMarginsByCountry,
      {}
    ),
    mobileMoneyFxMarginsByCountry: parseUnitIntervalRateMap(
      data.remittanceMobileMoneyFxMarginsByCountry,
      {}
    ),
  };

  remittanceFeeSettingsCache = {
    expiresAtMs: Date.now() + REMITTANCE_FEE_SETTINGS_CACHE_TTL_MS,
    snapshot: resolved,
  };
  return resolved;
};

const normalizeRemittanceRoute = (value: unknown): "BANK_ACCOUNT" | "MOBILE_MONEY" | null => {
  const normalized = String(value || "").trim().toUpperCase();
  if (!normalized) return null;
  if (normalized === "BANK" || normalized === "BANK_ACCOUNT") {
    return "BANK_ACCOUNT";
  }
  if (normalized === "MOBILE_MONEY" || normalized === "MOBILE" || normalized === "MOMO") {
    return "MOBILE_MONEY";
  }
  return null;
};

const findRemittanceCountryKey = (
  value: unknown,
  feeMap: Record<string, number>
): string | null => {
  const rawCountry = asNonEmptyString(value);
  if (!rawCountry) return null;

  const candidateKeys = [
    rawCountry,
    canonicalMobileMoneyCountry(rawCountry),
  ]
    .filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0)
    .map((entry) => normalizeCountryKey(entry));

  for (const key of Object.keys(feeMap)) {
    if (candidateKeys.includes(normalizeCountryKey(key))) {
      return key;
    }
  }
  return null;
};

const resolveRemittanceCorridorFeeUsd = async (args: {
  destinationCountry?: unknown;
  destinationRoute?: unknown;
  providerChannel?: unknown;
}): Promise<{
  country: string;
  route: "BANK_ACCOUNT" | "MOBILE_MONEY";
  providerChannel?: string;
  providerFeeUsd: number;
  providerFeeRate: number;
  fixedTopUpFeeUsd: number;
  topUpRate: number;
  topUpFeeUsd: number;
  feeUsd: number;
} | null> => {
  const route = normalizeRemittanceRoute(args.destinationRoute);
  if (!route) return null;

  const settings = await loadRemittanceFeeSettings();
  const usesBankRoute = route === "BANK_ACCOUNT";
  const normalizedProviderChannel = String(args.providerChannel || "").trim().toUpperCase();
  const usesSwiftRoute = usesBankRoute && normalizedProviderChannel === "SWIFT";
  // Some confirmed bank corridors are delivered through SWIFT. Preserve their
  // country-specific commercial and owner top-up rather than falling back to
  // the generic SWIFT defaults simply because of the technical channel.
  const providerFeeMap = usesBankRoute ? settings.bankFeesByCountry : settings.mobileMoneyFeesByCountry;
  const topUpFeeMap = usesBankRoute ? settings.bankTopUpByCountry : settings.mobileMoneyTopUpByCountry;
  const defaultProviderFeeUsd = usesSwiftRoute ?
    settings.defaultSwiftProviderFeeUsd :
    (usesBankRoute ? settings.defaultBankFeeUsd : settings.defaultMobileMoneyFeeUsd);
  const defaultTopUpFeeUsd = usesSwiftRoute ?
    settings.defaultSwiftTopUpUsd :
    (usesBankRoute ? settings.defaultBankTopUpUsd : settings.defaultMobileMoneyTopUpUsd);
  const topUpRate = usesSwiftRoute ? settings.swiftTopUpRate : 0;
  const providerFeeCountryKey = findRemittanceCountryKey(args.destinationCountry, providerFeeMap);
  const topUpFeeCountryKey = findRemittanceCountryKey(args.destinationCountry, topUpFeeMap);
  const country =
    providerFeeCountryKey ||
    topUpFeeCountryKey ||
    asNonEmptyString(args.destinationCountry);
  if (!country) return null;

  const providerFeeUsd = roundMoney(
    providerFeeCountryKey ? Number(providerFeeMap[providerFeeCountryKey] || 0) : defaultProviderFeeUsd
  );
  const topUpFeeUsd = roundMoney(
    topUpFeeCountryKey ? Number(topUpFeeMap[topUpFeeCountryKey] || 0) : defaultTopUpFeeUsd
  );
  const feeUsd = roundMoney(providerFeeUsd + topUpFeeUsd);
  return {
    country,
    route,
    providerChannel: usesSwiftRoute ? "SWIFT" : undefined,
    providerFeeUsd,
    // Confirmed local-bank commercial fees replace the generic SWIFT percent
    // whenever a corridor has an explicit negotiated fixed price.
    providerFeeRate: usesSwiftRoute && !providerFeeCountryKey ? settings.swiftProviderFeeRate : 0,
    fixedTopUpFeeUsd: topUpFeeUsd,
    topUpRate,
    topUpFeeUsd,
    feeUsd,
  };
};

const resolveRemittanceCorridorFxMarginRate = async (args: {
  destinationCountry?: unknown;
  destinationRoute?: unknown;
  providerChannel?: unknown;
  fallbackMarginRate: number;
}): Promise<number> => {
  const route = normalizeRemittanceRoute(args.destinationRoute);
  const fallbackMarginRate = normalizeUnitIntervalRate(args.fallbackMarginRate, 0);
  if (!route) return fallbackMarginRate;

  const settings = await loadRemittanceFeeSettings();
  const normalizedProviderChannel = String(args.providerChannel || "").trim().toUpperCase();
  if (route === "BANK_ACCOUNT" && normalizedProviderChannel === "SWIFT") {
    const corridorKey = findRemittanceCountryKey(args.destinationCountry, settings.bankFxMarginsByCountry);
    if (corridorKey) {
      return normalizeUnitIntervalRate(settings.bankFxMarginsByCountry[corridorKey], fallbackMarginRate);
    }
    return normalizeUnitIntervalRate(settings.swiftFxMargin, fallbackMarginRate);
  }
  const marginMap = route === "BANK_ACCOUNT" ?
    settings.bankFxMarginsByCountry :
    settings.mobileMoneyFxMarginsByCountry;
  const corridorKey = findRemittanceCountryKey(args.destinationCountry, marginMap);
  if (!corridorKey) return fallbackMarginRate;

  return normalizeUnitIntervalRate(marginMap[corridorKey], fallbackMarginRate);
};

const buildRemittancePricingGuide = async (args: {
  sourceAmount: number;
  sourceCurrency: string;
  destinationCountry?: unknown;
  destinationRoute?: unknown;
  providerChannel?: unknown;
  fundingSourceType?: unknown;
  feeExempt?: boolean;
}): Promise<RemittancePricingGuide | null> => {
  if (!Number.isFinite(args.sourceAmount) || args.sourceAmount <= 0) {
    return null;
  }

  const corridor = await resolveRemittanceCorridorFeeUsd({
    destinationCountry: args.destinationCountry,
    destinationRoute: args.destinationRoute,
    providerChannel: args.providerChannel,
  });
  if (!corridor) return null;

  const sourceCurrency = normalizeIsoCurrencyForFx(args.sourceCurrency, "USD") || "USD";
  const fundingSourceType = normalizeInitiateTransferFundingSourceType(args.fundingSourceType);
  const appliesStripeTransactionOwnerFee =
    fundingSourceType === "EXTERNAL_CARD" && args.feeExempt !== true;
  const feeSettings = await loadRemittanceFeeSettings();
  const stripeTransactionOwnerFeeRate = appliesStripeTransactionOwnerFee ?
    feeSettings.stripeTransactionOwnerFeeRate :
    0;
  const stripeTransactionOwnerFeeAmount = roundMoney(
    args.sourceAmount * stripeTransactionOwnerFeeRate
  );
  let providerFeeAmount = corridor.providerFeeUsd;
  let sourceAmountUsd = args.sourceAmount;
  if ((corridor.providerFeeRate > 0 || corridor.topUpRate > 0 || stripeTransactionOwnerFeeRate > 0) && sourceCurrency !== "USD") {
    try {
      const sourceToUsdFx = await fetchAppFxRate({
        fromCurrency: sourceCurrency,
        toCurrency: "USD",
        feeExempt: true,
      });
      sourceAmountUsd = roundMoney(args.sourceAmount * sourceToUsdFx.realRate);
    } catch (error) {
      functions.logger.warn("Could not convert remittance fee base into USD.", {
        sourceCurrency,
        destinationCountry: corridor.country,
        destinationRoute: corridor.route,
        error,
      });
      throw new functions.https.HttpsError(
        "unavailable",
        `Transfer pricing is temporarily unavailable for ${sourceCurrency} sends. Refresh and try again.`
      );
    }
  }
  const providerRateFeeUsd = roundMoney(Math.max(0, sourceAmountUsd * corridor.providerFeeRate));
  corridor.providerFeeUsd = roundMoney(corridor.providerFeeUsd + providerRateFeeUsd);
  providerFeeAmount = corridor.providerFeeUsd;
  const rateTopUpUsd = roundMoney(Math.max(0, sourceAmountUsd * corridor.topUpRate));
  const topUpFeeUsd = roundMoney(corridor.fixedTopUpFeeUsd + rateTopUpUsd);
  const stripeTransactionOwnerFeeUsd = roundMoney(
    sourceAmountUsd * stripeTransactionOwnerFeeRate
  );
  let topUpFeeAmount = topUpFeeUsd;
  corridor.topUpFeeUsd = topUpFeeUsd;
  corridor.feeUsd = roundMoney(corridor.providerFeeUsd + topUpFeeUsd);
  let corridorFeeAmount = roundMoney(
    providerFeeAmount + topUpFeeAmount + stripeTransactionOwnerFeeAmount
  );
  let corridorFeeCurrency = "USD";

  if (corridor.feeUsd > 0 && sourceCurrency !== "USD") {
    try {
      const fx = await fetchAppFxRate({
        fromCurrency: "USD",
        toCurrency: sourceCurrency,
        feeExempt: true,
      });
      providerFeeAmount = roundMoney(corridor.providerFeeUsd * fx.realRate);
      topUpFeeAmount = roundMoney(corridor.topUpFeeUsd * fx.realRate);
      corridorFeeAmount = roundMoney(
        providerFeeAmount + topUpFeeAmount + stripeTransactionOwnerFeeAmount
      );
      corridorFeeCurrency = sourceCurrency;
    } catch (error) {
      functions.logger.warn("Could not convert remittance corridor fee guide into source currency.", {
        sourceCurrency,
        destinationCountry: corridor.country,
        destinationRoute: corridor.route,
        error,
      });
      throw new functions.https.HttpsError(
        "unavailable",
        `Transfer pricing is temporarily unavailable for ${sourceCurrency} sends. Refresh and try again.`
      );
    }
  } else if (sourceCurrency === "USD") {
    corridorFeeCurrency = "USD";
  } else {
    corridorFeeCurrency = sourceCurrency;
  }

  const routeLabel = "Transfer fee";
  const totalDebitAmount = roundMoney(args.sourceAmount + corridorFeeAmount);
  const note = corridorFeeAmount > 0 ?
    "The total debit shown here includes the transfer fee for this route before you confirm." :
    "The total debit shown here matches the transfer amount for this route.";

  return {
    corridorFeeAmount,
    corridorFeeCurrency,
    corridorFeeLabel: routeLabel,
    providerFeeAmount,
    topUpFeeAmount,
    providerFeeUsd: corridor.providerFeeUsd,
    providerFeeRate: corridor.providerFeeRate,
    topUpFeeUsd: corridor.topUpFeeUsd,
    stripeTransactionOwnerFeeAmount,
    stripeTransactionOwnerFeeUsd,
    stripeTransactionOwnerFeeRate,
    totalDebitAmount,
    totalDebitCurrency: sourceCurrency,
    note,
    destinationCountry: corridor.country,
    destinationRoute: corridor.route,
    destinationProviderChannel: corridor.providerChannel,
  };
};

const applyRemittancePricingGuideToDraft = (
  draft: FirebaseFirestore.DocumentData | Record<string, unknown>,
  pricingGuide: RemittancePricingGuide | null,
  walletCurrency: string,
  options: {markTopUpRevenuePending?: boolean} = {}
): void => {
  if (!pricingGuide) return;

  const resolvedWalletCurrency = normalizeIsoCurrencyForFx(walletCurrency, "USD") || "USD";
  const totalDebitAmount = roundMoney(Number(pricingGuide.totalDebitAmount || 0));
  if (totalDebitAmount > 0) {
    draft.totalDebitAmount = totalDebitAmount;
    draft.totalDebitCurrency = normalizeIsoCurrencyForFx(
      pricingGuide.totalDebitCurrency,
      resolvedWalletCurrency
    ) || resolvedWalletCurrency;
  }

  const transferFeeAmount = roundMoney(Number(pricingGuide.corridorFeeAmount || 0));
  draft.transferFeeAmount = transferFeeAmount;
  draft.transferFeeCurrency = normalizeIsoCurrencyForFx(
    pricingGuide.corridorFeeCurrency,
    resolvedWalletCurrency
  ) || resolvedWalletCurrency;
  draft.transferFeeLabel = asNonEmptyString(pricingGuide.corridorFeeLabel) || "Transfer fee";

  const transferFeeProviderAmount = roundMoney(Number(pricingGuide.providerFeeAmount || 0));
  draft.transferFeeProviderAmount = transferFeeProviderAmount;

  const transferFeeTopUpAmount = roundMoney(Number(pricingGuide.topUpFeeAmount || 0));
  draft.transferFeeTopUpAmount = transferFeeTopUpAmount;

  const transferFeeProviderUsd = roundMoney(Number(pricingGuide.providerFeeUsd || 0));
  draft.transferFeeProviderUsd = transferFeeProviderUsd;
  draft.transferFeeProviderRate = normalizeUnitIntervalRate(pricingGuide.providerFeeRate, 0);

  const transferFeeTopUpUsd = roundMoney(Number(pricingGuide.topUpFeeUsd || 0));
  draft.transferFeeTopUpUsd = transferFeeTopUpUsd;
  const stripeTransactionOwnerFeeAmount = roundMoney(
    Number(pricingGuide.stripeTransactionOwnerFeeAmount || 0)
  );
  draft.stripeTransactionOwnerFeeAmount = stripeTransactionOwnerFeeAmount;
  draft.stripeTransactionOwnerFeeCurrency = normalizeIsoCurrencyForFx(
    pricingGuide.totalDebitCurrency,
    resolvedWalletCurrency
  ) || resolvedWalletCurrency;
  draft.stripeTransactionOwnerFeeUsd = roundMoney(
    Number(pricingGuide.stripeTransactionOwnerFeeUsd || 0)
  );
  draft.stripeTransactionOwnerFeeRate = normalizeUnitIntervalRate(
    pricingGuide.stripeTransactionOwnerFeeRate,
    0
  );
  if (stripeTransactionOwnerFeeAmount > 0) {
    draft.stripeTransactionOwnerFeeRevenueRecorded = false;
  }
  if (transferFeeTopUpUsd > 0 && options.markTopUpRevenuePending) {
    draft.remittanceTopUpRevenueRecorded = false;
  }
};

const resolveWalletTransferQuoteDirection = (
  destinationRoute: "BANK_ACCOUNT" | "MOBILE_MONEY"
): WalletTransferQuoteDirection => destinationRoute === "BANK_ACCOUNT" ?
  "WALLET_TRANSFER_BANK_PAYOUT" :
  "WALLET_TRANSFER_MOBILE_MONEY_PAYOUT";

export const getSecureExchangeRate = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    functions.logger.log("=== getSecureExchangeRate CALLED ===");
    functions.logger.log("Received data:", JSON.stringify(data));
    functions.logger.log("Context auth UID:", context.auth?.uid || null);
    functions.logger.log("Context app ID:", context.app?.appId || null);

    try {
      functions.logger.log("--- START getSecureExchangeRate FUNCTION EXECUTION ---");

      const requestData = data as CalculateExchangeRequest;
      functions.logger.log("Parsed request data:", JSON.stringify(requestData));
      const fromCurrency = normalizeIsoCurrencyForFx(requestData.fromCurrency);
      const toCurrency = normalizeIsoCurrencyForFx(requestData.toCurrency);
      const sourceAmount = roundMoney(Number(requestData.amount || 0));
      const destinationRoute = normalizeRemittanceRoute(requestData.destinationRoute);
      if (!fromCurrency || !toCurrency) {
        throw new functions.https.HttpsError("invalid-argument", "Missing or invalid 'fromCurrency' or 'toCurrency'.");
      }
      let requesterData: Record<string, unknown> = {};
      if (context.auth?.uid) {
        const requesterSnap = await db.collection("users").doc(context.auth.uid).get();
        requesterData = (requesterSnap.data() || {}) as Record<string, unknown>;
      }
      const pricingGuide = await buildRemittancePricingGuide({
        sourceAmount,
        sourceCurrency: fromCurrency,
        destinationCountry: requestData.destinationCountry,
        destinationRoute,
        providerChannel: requestData.providerChannel,
        fundingSourceType: requestData.fundingSourceType,
        feeExempt: isStaffFeeExempt(
          requesterData,
          (context.auth?.token || {}) as Record<string, unknown>
        ),
      });
      if (destinationRoute && Number.isFinite(sourceAmount) && sourceAmount > 0) {
        const payoutFx = await buildMobileMoneyPayoutFxQuote({
          amount: sourceAmount,
          sourceCurrency: fromCurrency,
          localCurrency: toCurrency,
          senderData: requesterData,
          authToken: (context.auth?.token || {}) as Record<string, unknown>,
          direction: resolveWalletTransferQuoteDirection(destinationRoute),
          destinationCountry: requestData.destinationCountry,
          destinationRoute,
          providerChannel: requestData.providerChannel,
        });
        return {
          success: true,
          rate: payoutFx.fx.rate,
          realRate: payoutFx.fx.realRate,
          sourceAmount,
          recipientAmount: payoutFx.localAmount,
          sourceCurrency: fromCurrency,
          targetCurrency: toCurrency,
          staffFeeExempt: payoutFx.fx.feeExempt,
          fetchedAtMs: payoutFx.fx.fetchedAtMs,
          provider: payoutFx.fx.provider,
          requestUrl: payoutFx.fx.requestUrl,
          margin: payoutFx.fx.margin,
          direction: payoutFx.fx.direction,
          pricing: pricingGuide || undefined,
        };
      }
      if (fromCurrency === toCurrency) {
        return {
          success: true,
          rate: 1,
          sourceAmount: Number.isFinite(sourceAmount) && sourceAmount > 0 ? sourceAmount : undefined,
          recipientAmount: Number.isFinite(sourceAmount) && sourceAmount > 0 ? sourceAmount : undefined,
          sourceCurrency: fromCurrency,
          targetCurrency: toCurrency,
          fetchedAtMs: Date.now(),
          pricing: pricingGuide || undefined,
        };
      }

      const isStaffOrOwner = isStaffFeeExempt(
        requesterData,
        (context.auth?.token || {}) as Record<string, unknown>
      );
      const fx = await fetchAppFxRate({
        fromCurrency,
        toCurrency,
        feeExempt: isStaffOrOwner,
      });
      const recipientAmount = Number.isFinite(sourceAmount) && sourceAmount > 0 ?
        roundMoney(sourceAmount * fx.appRate) :
        undefined;
      functions.logger.log(
        `Rate for ${fromCurrency}->${toCurrency}: Real=${fx.realRate}, App=${fx.appRate}, StaffExempt=${isStaffOrOwner}`
      );
      return {
        success: true,
        rate: fx.appRate,
        realRate: fx.realRate,
        sourceAmount: Number.isFinite(sourceAmount) && sourceAmount > 0 ? sourceAmount : undefined,
        recipientAmount,
        sourceCurrency: fromCurrency,
        targetCurrency: toCurrency,
        staffFeeExempt: isStaffOrOwner,
        fetchedAtMs: fx.fetchedAtMs,
        provider: fx.provider,
        requestUrl: fx.requestUrl,
        pricing: pricingGuide || undefined,
      };
    } catch (error) {
      functions.logger.error("getSecureExchangeRate error:", error);
      if (error instanceof Error && error.message.includes("Could not fetch exchange rate")) {
        throw new functions.https.HttpsError(
          "unavailable",
          "Live exchange rate is temporarily unavailable right now. Refresh and try again."
        );
      }
      if (error instanceof functions.https.HttpsError) throw error;
      throw new functions.https.HttpsError("internal", "An unexpected error occurred while fetching the rate.");
    }
  });

export const getWalletTransferQuote = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    try {
      const payload = (data || {}) as CalculateExchangeRequest;
      const fromCurrency = normalizeIsoCurrencyForFx(payload.fromCurrency);
      const toCurrency = normalizeIsoCurrencyForFx(payload.toCurrency);
      const sourceAmount = roundMoney(Number(payload.amount || 0));
      const destinationRoute = normalizeRemittanceRoute(payload.destinationRoute);

      if (!fromCurrency || !toCurrency) {
        throw new functions.https.HttpsError("invalid-argument", "Missing or invalid 'fromCurrency' or 'toCurrency'.");
      }
      if (!destinationRoute) {
        throw new functions.https.HttpsError("invalid-argument", "A supported payout route is required.");
      }
      if (!Number.isFinite(sourceAmount) || sourceAmount <= 0) {
        throw new functions.https.HttpsError("invalid-argument", "Transfer amount must be positive.");
      }

      const requesterSnap = await db.collection("users").doc(context.auth.uid).get();
      const requesterData = (requesterSnap.data() || {}) as Record<string, unknown>;
      const payoutFx = await buildMobileMoneyPayoutFxQuote({
        amount: sourceAmount,
        sourceCurrency: fromCurrency,
        localCurrency: toCurrency,
        senderData: requesterData,
        authToken: (context.auth?.token || {}) as Record<string, unknown>,
        direction: resolveWalletTransferQuoteDirection(destinationRoute),
        destinationCountry: payload.destinationCountry,
        destinationRoute,
        providerChannel: payload.providerChannel,
      });
      const pricingGuide = await buildRemittancePricingGuide({
        sourceAmount,
        sourceCurrency: fromCurrency,
        destinationCountry: payload.destinationCountry,
        destinationRoute,
        providerChannel: payload.providerChannel,
        fundingSourceType: payload.fundingSourceType,
        feeExempt: isStaffFeeExempt(
          requesterData,
          (context.auth?.token || {}) as Record<string, unknown>
        ),
      });

      return {
        success: true,
        rate: payoutFx.fx.rate,
        realRate: payoutFx.fx.realRate,
        sourceAmount,
        recipientAmount: payoutFx.localAmount,
        sourceCurrency: fromCurrency,
        targetCurrency: toCurrency,
        staffFeeExempt: payoutFx.fx.feeExempt,
        fetchedAtMs: payoutFx.fx.fetchedAtMs,
        provider: payoutFx.fx.provider,
        requestUrl: payoutFx.fx.requestUrl,
        margin: payoutFx.fx.margin,
        direction: payoutFx.fx.direction,
        pricing: pricingGuide || undefined,
      };
    } catch (error) {
      // Quote diagnostics intentionally contain only route/pricing fields. They
      // let us distinguish malformed quote input from provider-rate failures
      // without logging an account number, recipient name, or funding method ID.
      const callableError = error as {code?: unknown; message?: unknown};
      const failedPayload = data && typeof data === "object" && !Array.isArray(data)
        ? data as Record<string, unknown>
        : {};
      functions.logger.error("getWalletTransferQuote failed", {
        code: asNonEmptyString(callableError?.code) || "INTERNAL",
        message: asNonEmptyString(callableError?.message) || "Unknown quote error.",
        fromCurrency: asNonEmptyString(failedPayload.fromCurrency) || null,
        toCurrency: asNonEmptyString(failedPayload.toCurrency) || null,
        destinationCountry: asNonEmptyString(failedPayload.destinationCountry) || null,
        destinationRoute: asNonEmptyString(failedPayload.destinationRoute) || null,
        providerChannel: asNonEmptyString(failedPayload.providerChannel) || null,
        fundingSourceType: asNonEmptyString(
          failedPayload.fundingSourceType,
          failedPayload.fundingType,
          failedPayload.fundingTypeSource
        ) || null,
      });
      if (error instanceof functions.https.HttpsError) throw error;
      throw new functions.https.HttpsError(
        "internal",
        "Live transfer quote is unavailable right now. Refresh and try again."
      );
    }
  });


