type AgentAuthorizationFundingPreference = "STRIPE_CARD" | "AFRIEX_MOBILE_MONEY";

const normalizeAgentAuthorizationFundingPreference = (
  value: unknown
): AgentAuthorizationFundingPreference => {
  const normalized = String(value || "").trim().toUpperCase();
  // Existing released clients charged the saved card. New clients show the choice first.
  if (!normalized || normalized === "STRIPE_CARD") return "STRIPE_CARD";
  if (normalized === "AFRIEX_MOBILE_MONEY") return "AFRIEX_MOBILE_MONEY";
  throw new functions.https.HttpsError(
    "invalid-argument",
    "Select a supported agent-enrollment payment method."
  );
};

export const payForAgentRole = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    assertTransactionOnlyCashServicesDisabled();
    functions.logger.log("=== payForAgentRole CALLED ===", {
      authUid: context.auth?.uid || null,
      appId: context.app?.appId || null,
    });
    if (!context.auth?.uid) throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    const userId = context.auth.uid;
    const userRef = db.collection("users").doc(userId);
    let chargeResult: StripeCommerceChargeResult | null = null;
    let afriexCollectionQueued = false;
    let cardEnrollmentAttemptId: string | null = null;
    try {
      const userDoc = await userRef.get();
      if (!userDoc.exists) throw new functions.https.HttpsError("not-found", "User profile not found.");
      if (userDoc.data()?.role === "agent") {
        throw new functions.https.HttpsError("failed-precondition", "You are already an agent.");
      }
      const existingEnrollmentStatus = asNonEmptyString(userDoc.data()?.agentEnrollmentStatus)
        ?.toUpperCase() || "";
      if (["AWAITING_PAYMENT", "PROCESSING_CARD"].includes(existingEnrollmentStatus)) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Your agent enrollment payment is already in progress. Approve the mobile money prompt or wait for the saved-card payment to finish."
        );
      }

      const userData = await withPrivateUserFields(
        userId,
        (userDoc.data() || {}) as Record<string, unknown>
      );
      const isStaffOrOwner = isStaffFeeExempt(
        userData,
        (context.auth?.token || {}) as Record<string, unknown>
      );
      const configuredFee = (await loadProjectFeeSettings()).agentAuthorizationFeeUsd;
      if (!isStaffOrOwner && (!Number.isFinite(configuredFee) || configuredFee < 0)) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Agent enrollment is unavailable until its fee configuration is corrected."
        );
      }
      const fee = isStaffOrOwner ? 0 : roundMoney(configuredFee);
      const requestedFundingPreference = normalizeAgentAuthorizationFundingPreference(
        (data || {}).fundingPreference
      );
      const shouldUseAfriexHostedCollection =
        fee > 0 && requestedFundingPreference === "AFRIEX_MOBILE_MONEY";

      if (shouldUseAfriexHostedCollection) {
        const afriexFundingMethod = await resolveReadyAfriexCommerceFundingMethodForUser(userId);
        if (!afriexFundingMethod) {
          throw new functions.https.HttpsError(
            "failed-precondition",
            "Agent access in this corridor requires a verified default mobile money funding source in a live mobile-money collection country before the enrollment fee can be collected."
          );
        }
        const collectionRef = db.collection("payout_requests").doc();
        await db.runTransaction(async (transaction) => {
          const freshUserDoc = await transaction.get(userRef);
          if (!freshUserDoc.exists) {
            throw new functions.https.HttpsError("not-found", "User profile not found.");
          }
          if (freshUserDoc.data()?.role === "agent") {
            throw new functions.https.HttpsError("failed-precondition", "You are already an agent.");
          }
          const freshEnrollmentStatus = asNonEmptyString(
            freshUserDoc.data()?.agentEnrollmentStatus
          )?.toUpperCase() || "";
          if (["AWAITING_PAYMENT", "PROCESSING_CARD"].includes(freshEnrollmentStatus)) {
            throw new functions.https.HttpsError(
              "failed-precondition",
              "Your agent enrollment payment is already in progress."
            );
          }

          const now = admin.firestore.Timestamp.now();
          transaction.set(collectionRef, {
            senderId: userId,
            amount: fee,
            currency: "USD",
            phone: afriexFundingMethod.phoneNumber,
            network: afriexFundingMethod.network,
            country: afriexFundingMethod.country,
            dialCode: afriexFundingMethod.dialCode,
            localCurrency: afriexFundingMethod.currency,
            paymentMethodId: afriexFundingMethod.paymentMethodId,
            type: "CASH_IN",
            status: "PENDING",
            source: buildAfriexCommerceCollectionSource("AGENT_AUTHORIZATION"),
            fundingSource: "EXTERNAL_MOBILE_MONEY",
            fundingPreference: requestedFundingPreference,
            processor: "AFRIEX",
            collectionProcessor: "AFRIEX",
            settlementProvider: "AFRIEX",
            processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            createdAt: now,
            processedAt: now,
            transferIntent: {
              mode: AFRIEX_COMMERCE_TRANSFER_MODE,
              settlementCategory: "AGENT_AUTHORIZATION",
              commerceTitle: "Agent Portal enrollment",
              userId,
              grossAmount: fee,
              platformFee: fee,
              fundingPreference: requestedFundingPreference,
              requestedCurrency: "USD",
              processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
            },
          }, {merge: true});
          transaction.set(userRef, {
            agentEnrollmentStatus: "AWAITING_PAYMENT",
            pendingAgentAuthorizationCollectionId: collectionRef.id,
            updatedAt: now,
          }, {merge: true});
        });
        afriexCollectionQueued = true;
        functions.logger.log(`User ${userId} started Afriex-funded agent enrollment.`);
        return {
          success: true,
          awaitingPayment: true,
          payoutRequestId: collectionRef.id,
          message: `Mobile money collection started for the ${fee.toFixed(2)} USD agent enrollment fee. Approve the prompt on your phone to unlock Agent Portal.`,
        };
      }

      if (fee > 0) {
        cardEnrollmentAttemptId = randomUUID();
        const attemptId = cardEnrollmentAttemptId;
        await db.runTransaction(async (transaction) => {
          const freshUserDoc = await transaction.get(userRef);
          if (!freshUserDoc.exists) {
            throw new functions.https.HttpsError("not-found", "User profile not found.");
          }
          if (freshUserDoc.data()?.role === "agent") {
            throw new functions.https.HttpsError("failed-precondition", "You are already an agent.");
          }
          const freshEnrollmentStatus = asNonEmptyString(
            freshUserDoc.data()?.agentEnrollmentStatus
          )?.toUpperCase() || "";
          if (["AWAITING_PAYMENT", "PROCESSING_CARD"].includes(freshEnrollmentStatus)) {
            throw new functions.https.HttpsError(
              "failed-precondition",
              "Your agent enrollment payment is already in progress."
            );
          }
          transaction.set(userRef, {
            agentEnrollmentStatus: "PROCESSING_CARD",
            agentEnrollmentAttemptId: attemptId,
            agentAuthorizationFailureReason: admin.firestore.FieldValue.delete(),
            updatedAt: admin.firestore.Timestamp.now(),
          }, {merge: true});
        });
        try {
          chargeResult = await createStripeCardCommerceCharge({
            payerUserId: userId,
            payerUserData: userData,
            amount: fee,
            currency: "USD",
            description: "Agent Portal enrollment",
            metadata: {
              flow: "AGENT_AUTHORIZATION",
              userId,
              fundingPreference: requestedFundingPreference,
            },
            // A declined/expired card must be allowed to start a fresh payment attempt.
            idempotencyKey: `agent_authorization_${userId}_${attemptId}`,
          });
        } catch (error) {
          throw mapStripeCommerceChargeError(error);
        }
      }

      await db.runTransaction(async (transaction) => {
        const userDoc = await transaction.get(userRef);
        if (!userDoc.exists) throw new functions.https.HttpsError("not-found", "User profile not found.");
        if (userDoc.data()?.role === "agent") throw new functions.https.HttpsError("failed-precondition", "You are already an agent.");
        if (cardEnrollmentAttemptId && userDoc.data()?.agentEnrollmentAttemptId !== cardEnrollmentAttemptId) {
          throw new functions.https.HttpsError(
            "aborted",
            "Agent enrollment changed while the payment was processing. No further action was taken."
          );
        }

        functions.logger.log(`User ${userId} attempting to become an agent for a fee of $${fee}.`);
        transaction.set(userRef, {
          role: "agent",
          agentEnrollmentStatus: fee > 0 ? "PAID" : "STAFF_EXEMPT",
          agentEnrollmentAttemptId: admin.firestore.FieldValue.delete(),
          pendingAgentAuthorizationCollectionId: admin.firestore.FieldValue.delete(),
          agentAuthorizedAt: admin.firestore.Timestamp.now(),
          updatedAt: admin.firestore.Timestamp.now(),
        }, {merge: true});
        const transactionRef = userRef.collection("transactions").doc();
        transaction.set(transactionRef, {
          title: fee > 0 ? "Agent Authorization" : "Agent Authorization (Staff Exempt)",
          amount: fee > 0 ? -fee : 0,
          type: fee > 0 ? "DEBIT" : "INFO",
          status: "COMPLETED",
          timestamp: admin.firestore.Timestamp.now(),
          source: fee > 0 ? "AGENT_FEE_STRIPE" : "AGENT_FEE_STAFF_EXEMPT",
          processor: fee > 0 ? "STRIPE" : null,
          fundingPreference: fee > 0 ? requestedFundingPreference : null,
          stripePaymentIntentId: fee > 0 ? chargeResult?.paymentIntentId || null : null,
          stripeChargeId: fee > 0 ? chargeResult?.latestChargeId || null : null,
          fundingPaymentMethodId: fee > 0 ? chargeResult?.fundingPaymentMethodDocId || null : null,
          note: fee > 0 ?
            `Charged to your saved Stripe card${chargeResult?.fundingCardLast4 ? ` ending in ${chargeResult.fundingCardLast4}` : ""}.` :
            "Staff fee exemption applied.",
        });
        if (fee > 0) {
          recordPlatformRevenue(transaction, {
            source: "agentAuthorizationFees",
            amount: fee,
            note: "Agent authorization fee via Stripe",
            relatedUserId: userId,
            processor: "STRIPE",
            provider: "STRIPE",
            settlementCategory: "AGENT_AUTHORIZATION",
            processorMode: "DIRECT_CARD_CHARGE",
          });
        }
      });
      functions.logger.log(`User ${userId} successfully became an agent.`);
      return {success: true, message: "Congratulations! You are now an authorized agent."};
    } catch (error) {
      if (cardEnrollmentAttemptId) {
        try {
          await db.runTransaction(async (transaction) => {
            const freshUserDoc = await transaction.get(userRef);
            if (!freshUserDoc.exists || freshUserDoc.data()?.role === "agent") return;
            if (freshUserDoc.data()?.agentEnrollmentAttemptId !== cardEnrollmentAttemptId) return;
            transaction.set(userRef, {
              agentEnrollmentStatus: "PAYMENT_FAILED",
              agentEnrollmentAttemptId: admin.firestore.FieldValue.delete(),
              agentAuthorizationFailureReason: error instanceof Error ? error.message : "Card payment failed.",
              updatedAt: admin.firestore.Timestamp.now(),
            }, {merge: true});
          });
        } catch (rollbackError) {
          functions.logger.error("Could not release the failed agent card enrollment attempt.", {
            userId,
            rollbackError,
          });
        }
      }
      if (chargeResult && !afriexCollectionQueued) {
        await refundStripeCommercePaymentIntent({
          paymentIntentId: chargeResult.paymentIntentId,
          idempotencyKey: `agent_authorization_refund_${userId}`,
          metadata: {
            flow: "AGENT_AUTHORIZATION",
            userId,
          },
        });
      }
      functions.logger.error(`Agent authorization failed for user ${userId}:`, error);
      if (error instanceof functions.https.HttpsError) throw error;
      throw new functions.https.HttpsError("internal", "An unexpected error occurred.");
    }
  });


