export const initializeProviderHostedWallet = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const uid = context.auth.uid;
    const payload = (data || {}) as Record<string, unknown>;
    const provider = normalizeWalletRuntimeProvider(
      payload.provider,
      WalletRuntimeProvider.Afriex
    );
    if (!providerWalletMirrorUsesHostedCustody(provider)) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Only provider-hosted wallet providers can be initialized here."
      );
    }

    const rootSnap = await rootUserRef(uid).get();
    if (!rootSnap.exists) {
      throw new functions.https.HttpsError("not-found", "User account not found.");
    }

    const mergedUserData = await withPrivateUserFields(uid, (rootSnap.data() || {}) as Record<string, unknown>);
    let record: ProviderWalletMirrorRecord;
    if (provider === WalletRuntimeProvider.Afriex) {
      record = await provisionAfriexHostedWalletMirror({
        uid,
        rootData: mergedUserData,
        requestedCurrency: asNonEmptyString(payload.currency),
      });
    } else {
      record = {
        ...(await loadProviderWalletMirrorRecord(uid, mergedUserData)),
        provider,
      };
      await persistProviderWalletMirrorRecord(uid, record);
    }

    return {
      success: true,
      provider: record.provider,
      providerCustomerId: record.providerCustomerId || null,
      providerWalletId: record.providerWalletId || null,
      currency: record.currency,
      availableBalanceCents: record.availableBalanceCents,
      pendingDebitCents: record.pendingDebitCents,
      pendingCreditCents: record.pendingCreditCents,
      balance: centsToMoney(record.availableBalanceCents),
      walletMode: providerWalletMirrorUsesHostedCustody(record.provider) ?
        "PROVIDER_HOSTED_MIRROR" :
        "INTERNAL_LEDGER",
    };
  });

