  const raw = asNonEmptyString(
    process.env.AFRIEX_MOBILE_MONEY_DEPOSIT_UAT_COUNTRIES,
    process.env.MOBILE_MONEY_DEPOSIT_UAT_COUNTRIES
  );
  if (!raw) return [];

