const MOBILE_MONEY_PHONE_OTP_COLLECTION = "mobile_money_phone_otp_codes";
const MOBILE_MONEY_PHONE_OTP_CODE_LENGTH = 6;
const MOBILE_MONEY_PHONE_OTP_TTL_MS = 10 * 60 * 1000;
const MOBILE_MONEY_PHONE_OTP_RESEND_COOLDOWN_MS = 60 * 1000;
const MOBILE_MONEY_PHONE_OTP_MAX_ATTEMPTS = 5;
type MobileMoneyPhoneOtpPurpose = "ACCOUNT_PHONE" | "MOBILE_MONEY_METHOD";
const ACCOUNT_PHONE_FALLBACK_DIAL_DIGITS_BY_COUNTRY: Record<string, string> = {
  "canada": "1",
  "united kingdom": "44",
  "united states": "1",
};

// Some corridors, such as Cote d'Ivoire (+225), require the leading national
// "0" to remain part of the significant number even in E.164 form.
const MOBILE_MONEY_SIGNIFICANT_LEADING_ZERO_DIAL_DIGITS = new Set<string>(["225"]);

const getMobileMoneyPhoneOtpConfig = (): {
  provider: string;
  twilioAccountSid?: string;
  twilioAuthToken?: string;
  twilioVerifyServiceSid?: string;
  codeSecret: string;
} => {
  const provider = String(process.env.MOBILE_MONEY_PHONE_OTP_PROVIDER || "disabled")
    .trim()
    .toLowerCase();
  const twilioAccountSid = asNonEmptyString(process.env.TWILIO_ACCOUNT_SID);
  const twilioAuthToken = asNonEmptyString(process.env.TWILIO_AUTH_TOKEN);
  const twilioVerifyServiceSid = asNonEmptyString(process.env.TWILIO_VERIFY_SERVICE_SID);
  const codeSecret =
    asNonEmptyString(process.env.MOBILE_MONEY_PHONE_OTP_SECRET) ||
    asNonEmptyString(process.env.EMAIL_VERIFICATION_CODE_SECRET) ||
    asNonEmptyString(process.env.ADMIN_PAYOUT_REVERSAL_SECRET) ||
    "volunteersapp-mobile-money-phone-otp-default-secret";
  return {
    provider,
    twilioAccountSid: twilioAccountSid || undefined,
    twilioAuthToken: twilioAuthToken || undefined,
    twilioVerifyServiceSid: twilioVerifyServiceSid || undefined,
    codeSecret,
  };
};

const normalizeMobileMoneyPhoneE164 = (phone: unknown, dialCode?: unknown): string => {
  const rawPhone = String(phone || "").trim();
  const rawDialCode = String(dialCode || "").trim();
  let phoneDigits = normalizeDigits(rawPhone);
  const dialDigits = normalizeDigits(rawDialCode);
  const preserveLeadingNationalZero = MOBILE_MONEY_SIGNIFICANT_LEADING_ZERO_DIAL_DIGITS.has(dialDigits);
  if (!phoneDigits) return "";

  if (preserveLeadingNationalZero && dialDigits.length > 0) {
    if (rawPhone.startsWith("+") && phoneDigits.startsWith(dialDigits)) {
      const nationalDigits = phoneDigits.slice(dialDigits.length);
      if (nationalDigits.length === 9 && !nationalDigits.startsWith("0")) {
        phoneDigits = `${dialDigits}0${nationalDigits}`;
      }
    } else if (
      !rawPhone.startsWith("+") &&
      !phoneDigits.startsWith(dialDigits) &&
      phoneDigits.length === 9 &&
      !phoneDigits.startsWith("0")
    ) {
      phoneDigits = `0${phoneDigits}`;
    }
  }

  // National trunk "0" before country code merge (e.g. Ghana 055… + dial 233 → +23355…, not +233055…).
  if (!preserveLeadingNationalZero && !rawPhone.startsWith("+") && dialDigits.length > 0) {
    if (phoneDigits.startsWith("0") && !phoneDigits.startsWith(dialDigits)) {
      const stripped = phoneDigits.replace(/^0+/, "");
      if (stripped.length >= 8 && stripped.length <= 15) {
        phoneDigits = stripped;
      }
    }
  }
  if (
    !preserveLeadingNationalZero &&
    rawPhone.startsWith("+") &&
    dialDigits.length > 0 &&
    phoneDigits.startsWith(dialDigits)
  ) {
    const nationalDigits = phoneDigits.slice(dialDigits.length);
    if (nationalDigits.startsWith("0")) {
      const strippedNational = nationalDigits.replace(/^0+/, "");
      if (strippedNational.length >= 8 && strippedNational.length <= 15) {
        phoneDigits = `${dialDigits}${strippedNational}`;
      }
    }
  }

  if (rawPhone.startsWith("+")) {
    return `+${phoneDigits}`;
  }
  if (dialDigits) {
    const mergedDigits = phoneDigits.startsWith(dialDigits) ?
      phoneDigits :
      `${dialDigits}${phoneDigits}`;
    return `+${mergedDigits}`;
  }
  return `+${phoneDigits}`;
};

const inferAccountPhoneDialDigits = (country: unknown): string => {
  const normalizedCountry = String(country || "").trim().toLowerCase();
  if (!normalizedCountry) return "";
  if (ACCOUNT_PHONE_FALLBACK_DIAL_DIGITS_BY_COUNTRY[normalizedCountry]) {
    return ACCOUNT_PHONE_FALLBACK_DIAL_DIGITS_BY_COUNTRY[normalizedCountry];
  }
  const africanMatch = Object.entries(mobileMoneyCurrencyMap)
    .find(([key]) => key.trim().toLowerCase() === normalizedCountry);
  if (!africanMatch) return "";
  const canonicalCountry = africanMatch[0];
  const dialMap: Record<string, string> = {
    "Algeria": "213",
    "Angola": "244",
    "Benin": "229",
    "Botswana": "267",
    "Burkina Faso": "226",
    "Burundi": "257",
    "Cabo Verde": "238",
    "Cameroon": "237",
    "Central African Republic": "236",
    "Chad": "235",
    "Comoros": "269",
    "Cote d'Ivoire": "225",
    "Democratic Republic of the Congo": "243",
    "Djibouti": "253",
    "Egypt": "20",
    "Equatorial Guinea": "240",
    "Eritrea": "291",
    "Eswatini": "268",
    "Ethiopia": "251",
    "Gabon": "241",
    "Gambia": "220",
    "Ghana": "233",
    "Guinea": "224",
    "Guinea-Bissau": "245",
    "Kenya": "254",
    "Lesotho": "266",
    "Liberia": "231",
    "Libya": "218",
    "Madagascar": "261",
    "Malawi": "265",
    "Mali": "223",
    "Mauritania": "222",
    "Mauritius": "230",
    "Morocco": "212",
    "Mozambique": "258",
    "Namibia": "264",
    "Niger": "227",
    "Nigeria": "234",
    "Republic of the Congo": "242",
    "Rwanda": "250",
    "Sao Tome and Principe": "239",
    "Senegal": "221",
    "Seychelles": "248",
    "Sierra Leone": "232",
    "Somalia": "252",
    "South Africa": "27",
    "South Sudan": "211",
    "Sudan": "249",
    "Tanzania": "255",
    "Togo": "228",
    "Tunisia": "216",
    "Uganda": "256",
    "Zambia": "260",
    "Zimbabwe": "263",
  };
  return dialMap[canonicalCountry] || "";
};

const normalizeStoredAccountPhoneE164 = (
  userData: Record<string, unknown>
): string => {
  const rawPhone = asNonEmptyString(
    userData.phoneNumber,
    userData.phone,
    userData.mobileNumber
  );
  if (!rawPhone) return "";

  const explicitDialDigits = normalizeDigits(
    asNonEmptyString(userData.dialCode, userData.countryDialCode)
  );
  const inferredDialDigits = explicitDialDigits || inferAccountPhoneDialDigits(
    asNonEmptyString(userData.country, userData.countryName)
  );
  const rawPlusCount = (rawPhone.match(/\+/g) || []).length;
  let phoneE164 = normalizeMobileMoneyPhoneE164(
    rawPhone,
    inferredDialDigits ? `+${inferredDialDigits}` : ""
  );
  let phoneDigits = normalizeDigits(phoneE164);

  if (
    rawPlusCount > 1 &&
    inferredDialDigits &&
    phoneDigits.startsWith(inferredDialDigits + inferredDialDigits)
  ) {
    phoneDigits = inferredDialDigits + phoneDigits.slice(inferredDialDigits.length * 2);
    phoneE164 = `+${phoneDigits}`;
  }

  return phoneE164;
};

const maskPhoneNumberForOtp = (phone: string): string => {
  const digits = normalizeDigits(phone);
  if (!digits) return "***";
  if (digits.length <= 4) return `***${digits}`;
  return `***${digits.slice(-4)}`;
};

/**
 * Twilio HTTP failures from Verify API. Use non-INTERNAL gRPC codes so the Firebase iOS SDK
 * keeps the `message` field; for status INTERNAL it discards server text and surfaces "INTERNAL".
 * @see FirebaseFunctions Swift `FunctionsError.init?(httpStatusCode:...)` guard on `.internal`.
 */
const throwTwilioVerifyAxiosError = (
  operation: "send" | "check",
  error: unknown,
  fallbackMessage: string
): never => {
  if (!axios.isAxiosError(error) || !error.response) {
    const timedOut = axios.isAxiosError(error) && error.code === "ECONNABORTED";
    throw new functions.https.HttpsError(
      "unavailable",
      timedOut ? "Verification request timed out. Please try again." : fallbackMessage
    );
  }

  const status = error.response.status;
  const data = (error.response.data || {}) as Record<string, unknown>;
  const twilioMessage = asNonEmptyString(data.message);
  const twilioCode = data.code;

  functions.logger.error("Twilio Verify API request failed", {
    operation,
    httpStatus: status,
    twilioCode,
    twilioMessage,
  });

  if (status === 404 && operation === "check") {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "No active verification for this number. Request a new SMS code and try again."
    );
  }

  if (status === 401 || status === 403) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Phone verification is temporarily unavailable. Please try again later or contact support."
    );
  }

  if (status === 404) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Verification service is misconfigured. Contact support."
    );
  }

  if (status === 429) {
    throw new functions.https.HttpsError(
      "resource-exhausted",
      "Too many verification attempts. Please wait a few minutes and try again."
    );
  }

  if (status === 503 || status === 504) {
    throw new functions.https.HttpsError(
      "unavailable",
      "Verification service is busy. Please try again in a moment."
    );
  }

  if (status >= 500) {
    throw new functions.https.HttpsError(
      "unavailable",
      twilioMessage || "Could not reach the verification service. Please try again."
    );
  }

  if (status === 400) {
    throw new functions.https.HttpsError(
      "invalid-argument",
      twilioMessage || "Invalid phone number or verification request. Check the number and try again."
    );
  }

  throw new functions.https.HttpsError("unavailable", twilioMessage || fallbackMessage);
};

const buildMobileMoneyOtpDocId = (uid: string, phoneDigits: string): string => {
  const config = getMobileMoneyPhoneOtpConfig();
  const seed = `${uid}:${phoneDigits}:${config.codeSecret}`;
  return createHash("sha256").update(seed).digest("hex").slice(0, 48);
};

const getMobileMoneyOtpRef = (
  uid: string,
  phoneDigits: string
): FirebaseFirestore.DocumentReference => {
  const docId = buildMobileMoneyOtpDocId(uid, phoneDigits);
  return db.collection(MOBILE_MONEY_PHONE_OTP_COLLECTION).doc(docId);
};

const sendMobileMoneyPhoneOtpCode = async (phoneE164: string): Promise<void> => {
  const config = getMobileMoneyPhoneOtpConfig();
  if (config.provider !== "twilio_verify") {
    functions.logger.error("Mobile money phone OTP provider is not configured", {
      provider: config.provider || "disabled",
      hint: "Set MOBILE_MONEY_PHONE_OTP_PROVIDER=twilio_verify plus TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_VERIFY_SERVICE_SID, then redeploy functions.",
    });
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Phone verification is not available right now. Please try again later or contact support."
    );
  }
  if (!config.twilioAccountSid || !config.twilioAuthToken || !config.twilioVerifyServiceSid) {
    functions.logger.error("Twilio Verify credentials are incomplete for mobile money phone OTP", {
      hasAccountSid: !!config.twilioAccountSid,
      hasAuthToken: !!config.twilioAuthToken,
      hasVerifyServiceSid: !!config.twilioVerifyServiceSid,
    });
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Phone verification is not available right now. Please try again later or contact support."
    );
  }

  const body = new URLSearchParams();
  body.append("To", phoneE164);
  body.append("Channel", "sms");

  try {
    await axios.post(
      `https://verify.twilio.com/v2/Services/${config.twilioVerifyServiceSid}/Verifications`,
      body.toString(),
      {
        timeout: 15000,
        auth: {
          username: config.twilioAccountSid,
          password: config.twilioAuthToken,
        },
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
      }
    );
  } catch (error) {
    throwTwilioVerifyAxiosError(
      "send",
      error,
      "Could not send verification code. Please try again."
    );
  }
};

const verifyMobileMoneyPhoneOtpCode = async (
  phoneE164: string,
  code: string
): Promise<{approved: boolean; status: string}> => {
  const config = getMobileMoneyPhoneOtpConfig();
  if (config.provider !== "twilio_verify") {
    functions.logger.error("Mobile money phone OTP provider is not configured", {
      provider: config.provider || "disabled",
      hint: "Set MOBILE_MONEY_PHONE_OTP_PROVIDER=twilio_verify plus Twilio Verify credentials, then redeploy functions.",
    });
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Phone verification is not available right now. Please try again later or contact support."
    );
  }
  if (!config.twilioAccountSid || !config.twilioAuthToken || !config.twilioVerifyServiceSid) {
    functions.logger.error("Twilio Verify credentials are incomplete for mobile money phone OTP", {
      hasAccountSid: !!config.twilioAccountSid,
      hasAuthToken: !!config.twilioAuthToken,
      hasVerifyServiceSid: !!config.twilioVerifyServiceSid,
    });
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Phone verification is not available right now. Please try again later or contact support."
    );
  }

  const body = new URLSearchParams();
  body.append("To", phoneE164);
  body.append("Code", code);

  try {
    const response = await axios.post(
      `https://verify.twilio.com/v2/Services/${config.twilioVerifyServiceSid}/VerificationCheck`,
      body.toString(),
      {
        timeout: 15000,
        auth: {
          username: config.twilioAccountSid,
          password: config.twilioAuthToken,
        },
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
      }
    );
    const responseData = (response.data || {}) as {status?: unknown};
    const status = String(responseData.status || "").trim().toLowerCase();
    return {
      approved: status === "approved",
      status: status || "unknown",
    };
  } catch (error) {
    throwTwilioVerifyAxiosError(
      "check",
      error,
      "Could not verify the code at this time. Please try again."
    );
  }
};

interface AddPaymentMethodRequest {
  type?: string;
  label?: string;
  cardHolderName?: string;
  cardNumber?: string;
  expiryDate?: string;
  brand?: string;
  last4?: string;
  bankName?: string;
  accountHolderName?: string;
  accountNumber?: string;
  routingNumber?: string;
  phoneNumber?: string;
  network?: string;
  registeredName?: string;
  country?: string;
  dialCode?: string;
  currency?: string;
  institutionCode?: string;
  isDefault?: boolean;
  [key: string]: unknown;
}

interface ListRecipientPayoutMethodsRequest {
  recipientUserId?: unknown;
  limit?: unknown;
}

const normalizeMethodType = (value: unknown): string =>
  String(value || "").trim().toUpperCase();

const normalizeText = (value: unknown): string =>
  String(value || "").trim().toLowerCase();

const normalizeDigits = (value: unknown): string =>
  String(value || "").replace(/\D/g, "");

const normalizeExpiry = (value: unknown): string => {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const match = raw.match(/^(\d{1,2})\s*\/\s*(\d{2}|\d{4})$/);
  if (!match) return raw.replace(/\s+/g, "");
  const month = match[1].padStart(2, "0");
  const year = match[2].slice(-2);
  return `${month}-${year}`;
};

const normalizeMobileMoneyPhoneOtpPurpose = (value: unknown): MobileMoneyPhoneOtpPurpose => {
  const normalized = String(value || "").trim().toUpperCase();
  return normalized === "ACCOUNT_PHONE" ? "ACCOUNT_PHONE" : "MOBILE_MONEY_METHOD";
};

const toSafeKeyPart = (value: string): string => {
  const safe = value.replace(/[^a-z0-9_-]/g, "");
  return safe || "na";
};

const buildPaymentMethodDedupeKey = (data: AddPaymentMethodRequest): string | null => {
  const type = normalizeMethodType(data.type);

  if (type === "CARD") {
    const last4 = normalizeDigits(data.last4 || data.cardNumber).slice(-4);
    const expiry = normalizeExpiry(data.expiryDate);
    if (!last4 || !expiry) return null;
    return `card_${toSafeKeyPart(last4)}_${toSafeKeyPart(expiry)}`;
  }

  if (type === "BANK") {
    const last4 = normalizeDigits(data.last4 || data.accountNumber).slice(-4);
    const routing = normalizeDigits(data.routingNumber) || "norouting";
    const country = normalizeText(data.country) || "na";
    if (!last4) return null;
    return `bank_${toSafeKeyPart(country)}_${toSafeKeyPart(routing)}_${toSafeKeyPart(last4)}`;
  }

  if (type === "MOBILE_MONEY") {
    const phone = normalizeDigits(data.phoneNumber);
    const network = normalizeText(data.network) || "na";
    if (!phone) return null;
    return `mobile_${toSafeKeyPart(network)}_${toSafeKeyPart(phone)}`;
  }

  return null;
};

const duplicateMessageForType = (type: string): string => {
  switch (type) {
  case "CARD":
    return "This card is already saved.";
  case "BANK":
    return "This bank account is already saved.";
  case "MOBILE_MONEY":
    return "This mobile money number is already saved.";
  default:
    return "This payment method is already saved.";
  }
};

const getStoredPaymentMethodDedupeKey = (
  data: AddPaymentMethodRequest | Record<string, unknown>
): string | null => {
  const explicitKey = asNonEmptyString((data as Record<string, unknown>).dedupeKey);
  if (explicitKey) return explicitKey;
  return buildPaymentMethodDedupeKey(data as AddPaymentMethodRequest);
};

const buildMaskedCardDisplayNumber = (last4: string): string =>
  `**** **** **** ${last4}`;

const buildMaskedBankDisplayNumber = (last4: string): string =>
  `********${last4}`;

const normalizeIsoCurrencyCode = (value: unknown): string | null => {
  const normalized = asNonEmptyString(value)?.trim().toUpperCase() || "";
  return normalized.length === 3 ? normalized : null;
};

const normalizeStoredCountry = (value: unknown): string | null => {
  const normalized = asNonEmptyString(value)?.trim() || "";
  if (!normalized) return null;
  if (normalized.length <= 3) {
    return normalized.toUpperCase();
  }
  return normalized;
};

const isReadyRecipientExternalPayoutMethod = (
  methodData: Record<string, unknown>
): boolean => {
  const methodType = normalizeMethodType(methodData.type);
  if (methodType !== "CARD" && methodType !== "BANK") return false;

  const status = String(methodData.status || "").trim().toUpperCase();
  if (status.includes("DISABLED") || status.includes("REVOKED")) {
    return false;
  }

  const externalAccountId = asNonEmptyString(
    methodData.externalAccountId,
    methodData.stripeExternalAccountId
  );
  if (!externalAccountId) return false;
  if (methodData.requiresPayoutSetup === true) return false;

  if (methodType === "BANK" && methodData.achCreditEnabled === false) {
    return false;
  }

  return true;
};

const buildRecipientPayoutMethodSummary = (
  paymentMethodId: string,
  rawData: Record<string, unknown>
): Record<string, unknown> | null => {
  const methodType = normalizeMethodType(rawData.type);
  if (methodType !== "CARD" && methodType !== "BANK") return null;

  const payoutReady = isReadyRecipientExternalPayoutMethod(rawData);
  if (!payoutReady) return null;

  return {
    id: paymentMethodId,
    type: methodType,
    label: asNonEmptyString(rawData.label) || null,
    isDefault: rawData.isDefault === true,
    brand: asNonEmptyString(rawData.brand) || null,
    last4: asNonEmptyString(rawData.last4, rawData.accountLast4) || null,
    cardHolderName: asNonEmptyString(rawData.cardHolderName) || null,
    accountHolderName: asNonEmptyString(rawData.accountHolderName) || null,
    bankName: asNonEmptyString(rawData.bankName, rawData.bank, rawData.institutionName) || null,
    country: asNonEmptyString(rawData.country, rawData.countryCode) || null,
    currency: asNonEmptyString(rawData.currency)?.toUpperCase() || null,
    status: asNonEmptyString(rawData.status) || null,
    achCreditEnabled: rawData.achCreditEnabled === true,
    requiresPayoutSetup: rawData.requiresPayoutSetup === true,
    payoutReady: true,
  };
};

/** Afriex hosted-wallet receive routes (bank / mobile money). Not Stripe Connect payout setup. */
const buildHostedWalletReceiveMethodSummary = (
  paymentMethodId: string,
  rawData: Record<string, unknown>
): Record<string, unknown> | null => {
  // Another signed-in member can request this display summary while choosing
  // an app-user route. Resolve provider IDs and full destination details only
  // on the server when the transfer is actually submitted.
  if (isAfriexHostedWalletMobileMoneyMethodReady(rawData)) {
    const mobileNumber = asNonEmptyString(
      rawData.phoneNumber,
      rawData.phone,
      rawData.mobileNumber
    );
    return {
      id: paymentMethodId,
      type: "MOBILE_MONEY",
      label: asNonEmptyString(rawData.label) || null,
      isDefault: rawData.isDefault === true,
      brand: asNonEmptyString(rawData.network, rawData.brand, rawData.provider) || null,
      network: asNonEmptyString(rawData.network, rawData.brand, rawData.provider) || null,
      phoneNumber: mobileNumber ? maskPhoneNumberForOtp(mobileNumber) : null,
      country: asNonEmptyString(rawData.country, rawData.countryCode) || null,
      currency: asNonEmptyString(rawData.currency)?.toUpperCase() || null,
      status: asNonEmptyString(rawData.status) || null,
      verificationStatus: asNonEmptyString(rawData.verificationStatus) || null,
      phoneOwnershipVerified: rawData.phoneOwnershipVerified === true,
      payoutReady: true,
    };
  }

  if (isAfriexHostedWalletBankMethodReady(rawData)) {
    return {
      id: paymentMethodId,
      type: "BANK",
      label: asNonEmptyString(rawData.label) || null,
      isDefault: rawData.isDefault === true,
      accountHolderName: asNonEmptyString(
        rawData.accountHolderName,
        rawData.registeredName,
        rawData.holderName,
        rawData.name
      ) || null,
      bankName: asNonEmptyString(rawData.bankName, rawData.bank, rawData.institutionName) || null,
      last4: asNonEmptyString(rawData.last4, rawData.accountLast4) || null,
      country: asNonEmptyString(rawData.country, rawData.countryCode) || null,
      currency: asNonEmptyString(rawData.currency)?.toUpperCase() || null,
      status: asNonEmptyString(rawData.status) || null,
      payoutReady: true,
    };
  }

  return null;
};

const buildRecipientReceiveMethodSummaries = (
  paymentMethodId: string,
  rawData: Record<string, unknown>
): Record<string, unknown>[] => {
  const externalPayout = buildRecipientPayoutMethodSummary(paymentMethodId, rawData);
  const hostedReceive = buildHostedWalletReceiveMethodSummary(paymentMethodId, rawData);
  if (externalPayout && hostedReceive) {
    return [{
      ...hostedReceive,
      ...externalPayout,
      payoutReady: externalPayout.payoutReady === true,
    }];
  }
  return [externalPayout, hostedReceive].filter(
    (item): item is Record<string, unknown> => !!item
  );
};

type AfriexCommercePayoutRoute = "BANK" | "MOBILE_MONEY";

const canonicalAfriexCommerceCountry = (
  value: unknown,
  route: AfriexPayoutRoute = "MOBILE_MONEY"
): string | null => {
  const canonical = canonicalMobileMoneyCountry(asNonEmptyString(value));
  if (!canonical) return null;
  return isPayoutCountrySupportedByProvider("AFRIEX", canonical, route) ? canonical : null;
};

const isReadyAfriexCommerceBankMethod = (
  methodData: Record<string, unknown>
): boolean => {
  if (normalizeMethodType(methodData.type) !== "BANK") return false;
  const requestedProviderChannel = normalizeAfriexBankProviderChannel(asNonEmptyString(
    methodData.providerChannel,
    methodData.afriexProviderChannel
  ));
  const countryInput = asNonEmptyString(methodData.country, methodData.countryCode);
  const country = requestedProviderChannel === "SWIFT" ?
    canonicalAfriexSwiftPayoutCountry(countryInput) :
    canonicalAfriexCommerceCountry(countryInput, "BANK_ACCOUNT");
  if (!country) return false;

  const status = String(methodData.status || "").trim().toUpperCase();
  if (status.includes("DISABLED") || status.includes("REVOKED")) {
    return false;
  }

  const hasProvisionedDestination =
    !!getAfriexCustomerIdFromRecord(methodData) &&
    !!getAfriexDestinationPaymentMethodId(methodData, methodData);
  const hasSwiftInputs = requestedProviderChannel !== "SWIFT" || (
    !!getAfriexInstitutionCodeFromRecord(methodData) &&
    !!asNonEmptyString(methodData.recipientEmail, methodData.email) &&
    !!asNonEmptyString(methodData.recipientAddress, methodData.address) &&
    !!asNonEmptyString(methodData.institutionAddress, methodData.bankAddress)
  );

  return hasSwiftInputs && hasProvisionedDestination;
};

const isReadyAfriexCommerceMobileMoneyMethod = (
  methodData: Record<string, unknown>
): boolean => {
  if (normalizeMethodType(methodData.type) !== "MOBILE_MONEY") return false;
  const country = canonicalAfriexCommerceCountry(
    asNonEmptyString(methodData.country, methodData.countryCode)
  );
  if (!country) return false;

  const verificationStatus = String(methodData.verificationStatus || "")
    .trim()
    .toUpperCase();
  if (methodData.phoneOwnershipVerified !== true) return false;
  if (verificationStatus && verificationStatus !== "VERIFIED") return false;

  const phone = asNonEmptyString(methodData.phoneNumber);
  const network = asNonEmptyString(methodData.network);
  return !!phone &&
    !!network &&
    !!getAfriexCustomerIdFromRecord(methodData) &&
    !!getAfriexDestinationPaymentMethodId(methodData, methodData);
};

const buildAfriexCommercePayoutOption = (
  paymentMethodId: string,
  rawData: Record<string, unknown>
): Record<string, unknown> | null => {
  const methodType = normalizeMethodType(rawData.type);
  if (methodType === "BANK") {
    const requestedProviderChannel = normalizeAfriexBankProviderChannel(asNonEmptyString(
      rawData.providerChannel,
      rawData.afriexProviderChannel
    ));
    const countryInput = asNonEmptyString(rawData.country, rawData.countryCode);
    const country = requestedProviderChannel === "SWIFT" ?
      canonicalAfriexSwiftPayoutCountry(countryInput) :
      canonicalAfriexCommerceCountry(countryInput, "BANK_ACCOUNT");
    if (!country) return null;
    if (!isReadyAfriexCommerceBankMethod(rawData)) return null;
    return {
      provider: "AFRIEX",
      route: "BANK" as AfriexCommercePayoutRoute,
      paymentMethodId,
      type: "BANK",
      isDefault: rawData.isDefault === true,
      label: asNonEmptyString(rawData.label) || null,
      bankName: asNonEmptyString(rawData.bankName, rawData.bank, rawData.institutionName) || null,
      accountHolderName: asNonEmptyString(rawData.accountHolderName) || null,
      last4: asNonEmptyString(rawData.last4, rawData.accountLast4) || null,
      institutionCode: getAfriexInstitutionCodeFromRecord(rawData) || null,
      providerChannel: requestedProviderChannel || null,
      afriexProviderChannel: requestedProviderChannel || null,
      recipientEmail: asNonEmptyString(rawData.recipientEmail, rawData.email) || null,
      recipientAddress: asNonEmptyString(rawData.recipientAddress, rawData.address) || null,
      institutionAddress: asNonEmptyString(rawData.institutionAddress, rawData.bankAddress) || null,
      swiftBic: asNonEmptyString(rawData.swiftBic, rawData.institutionCode) || null,
      providerCustomerId: getAfriexCustomerIdFromRecord(rawData) || null,
      providerDestinationPaymentMethodId: getAfriexDestinationPaymentMethodId(rawData, rawData) || null,
      country,
      countryIso2: getAfriexCountryIso2(country),
      currency: requestedProviderChannel === "SWIFT" ? "USD" : (asNonEmptyString(rawData.currency)?.toUpperCase() || null),
      status: asNonEmptyString(rawData.status) || null,
    };
  }

  if (methodType === "MOBILE_MONEY") {
    const country = canonicalAfriexCommerceCountry(
      asNonEmptyString(rawData.country, rawData.countryCode)
    );
    if (!country) return null;
    if (!isReadyAfriexCommerceMobileMoneyMethod(rawData)) return null;
    const phoneDigits = normalizeDigits(asNonEmptyString(rawData.phoneNumber) || "");
    return {
      provider: "AFRIEX",
      route: "MOBILE_MONEY" as AfriexCommercePayoutRoute,
      paymentMethodId,
      type: "MOBILE_MONEY",
      isDefault: rawData.isDefault === true,
      label: asNonEmptyString(rawData.label) || null,
      registeredName: asNonEmptyString(rawData.registeredName, rawData.accountHolderName) || null,
      network: asNonEmptyString(rawData.network, rawData.brand) || null,
      phoneLast4: phoneDigits ? phoneDigits.slice(-4) : null,
      dialCode: asNonEmptyString(rawData.dialCode) || null,
      institutionCode: getAfriexInstitutionCodeFromRecord(rawData) || null,
      providerCustomerId: getAfriexCustomerIdFromRecord(rawData) || null,
      providerDestinationPaymentMethodId: getAfriexDestinationPaymentMethodId(rawData, rawData) || null,
      country,
      countryIso2: getAfriexCountryIso2(country),
      currency: resolveMobileMoneyCurrency(rawData) || asNonEmptyString(rawData.currency)?.toUpperCase() || null,
      verificationStatus: "VERIFIED",
    };
  }

  return null;
};

const compareAfriexCommercePayoutOptions = (
  lhs: Record<string, unknown>,
  rhs: Record<string, unknown>
): number => {
  const lhsDefault = lhs.isDefault === true ? 1 : 0;
  const rhsDefault = rhs.isDefault === true ? 1 : 0;
  if (lhsDefault !== rhsDefault) return rhsDefault - lhsDefault;

  const lhsRoute = String(lhs.route || "");
  const rhsRoute = String(rhs.route || "");
  if (lhsRoute !== rhsRoute) return lhsRoute.localeCompare(rhsRoute);

  const lhsLabel = asNonEmptyString(lhs.label, lhs.bankName, lhs.network) || "";
  const rhsLabel = asNonEmptyString(rhs.label, rhs.bankName, rhs.network) || "";
  return lhsLabel.localeCompare(rhsLabel);
};

const buildAfriexCommercePayoutPlanForUser = async (
  userId: string
): Promise<Record<string, unknown> | null> => {
  const methodsSnap = await db.collection("users").doc(userId)
    .collection("payment_methods")
    .get();

  const options: Record<string, unknown>[] = [];
  for (const doc of methodsSnap.docs) {
    const mergedMethodData = await withPrivatePaymentMethodFields(
      userId,
      doc.id,
      (doc.data() || {}) as Record<string, unknown>
    );
    const option = buildAfriexCommercePayoutOption(
      doc.id,
      mergedMethodData
    );
    if (option) {
      options.push(option);
    }
  }

  if (!options.length) {
    return null;
  }

  options.sort(compareAfriexCommercePayoutOptions);
  const availableRoutes = Array.from(new Set(
    options
      .map((option) => asNonEmptyString(option.route) || "")
      .filter((value) => value.length > 0)
  ));
  const supportedCountries = Array.from(new Set(
    options
      .map((option) => asNonEmptyString(option.country) || "")
      .filter((value) => value.length > 0)
  ));

  const defaultOption = options.find((option) => option.isDefault === true) || null;
  let preferredOption: Record<string, unknown> | null = defaultOption;
  if (!preferredOption) {
    if (options.length === 1 || availableRoutes.length === 1) {
      preferredOption = options[0];
    }
  }

  return {
    provider: "AFRIEX",
    availableRoutes,
    availableOptions: options,
    preferredOption,
    preferredRoute: preferredOption ? asNonEmptyString(preferredOption.route) || null : null,
    preferredPaymentMethodId: preferredOption ? asNonEmptyString(preferredOption.paymentMethodId) || null : null,
    selectionRequired: !preferredOption && options.length > 1,
    supportedCountries,
  };
};

interface CompletedCommercePayoutRecordParams {
  amount: number;
  grossAmount: number;
  currency: string;
  recipientId: string;
  recipientName: string;
  senderId: string;
  source: string;
  type: string;
  settlementCategory: string;
  commerceRecordId: string;
  processorMode: string;
  timestamp: admin.firestore.Timestamp;
  providerMessage: string;
  stripePaymentIntentId?: string | null;
  stripeChargeId?: string | null;
  fundingPaymentMethodId?: string | null;
  destinationAccountId?: string | null;
  stripeConnectedAccountId?: string | null;
  platformFee?: number;
  afriexPayoutPlan?: Record<string, unknown> | null;
  extraContext?: Record<string, unknown>;
}

const buildCompletedCommercePayoutRequestRecord = (
  params: CompletedCommercePayoutRecordParams
): FirebaseFirestore.DocumentData => {
  const payload: FirebaseFirestore.DocumentData = {
    amount: params.amount,
    grossAmount: params.grossAmount,
    currency: params.currency,
    recipientId: params.recipientId,
    recipientName: params.recipientName,
    senderId: params.senderId,
    source: params.source,
    type: params.type,
    settlementCategory: params.settlementCategory,
    commerceCategory: params.settlementCategory,
    commerceFlow: params.settlementCategory,
    commerceRecordId: params.commerceRecordId,
    status: "COMPLETED",
    processor: "STRIPE",
    collectionProcessor: "STRIPE",
    provider: "STRIPE",
    payoutProvider: "STRIPE",
    settlementProvider: "STRIPE",
    processorMode: params.processorMode,
    providerStatus: "COMPLETED",
    providerMessage: params.providerMessage,
    stripePaymentIntentId: params.stripePaymentIntentId || null,
    stripeChargeId: params.stripeChargeId || null,
    fundingPaymentMethodId: params.fundingPaymentMethodId || null,
    destinationAccountId: params.destinationAccountId || null,
    stripeConnectedAccountId: params.stripeConnectedAccountId || params.destinationAccountId || null,
    platformFee: Number.isFinite(params.platformFee) ? params.platformFee : 0,
    createdAt: params.timestamp,
    processedAt: params.timestamp,
    completedAt: params.timestamp,
  };

  if (params.afriexPayoutPlan) {
    payload.afriexPayoutProvider = "AFRIEX";
    payload.payoutProvider = "AFRIEX";
    payload.settlementProvider = "AFRIEX";
    payload.afriexPayoutPlan = params.afriexPayoutPlan;
    payload.afriexAvailableRoutes = Array.isArray(params.afriexPayoutPlan.availableRoutes) ?
      params.afriexPayoutPlan.availableRoutes :
      [];
    payload.afriexPreferredRoute = asNonEmptyString(params.afriexPayoutPlan.preferredRoute) || null;
    payload.afriexPreferredPaymentMethodId =
      asNonEmptyString(params.afriexPayoutPlan.preferredPaymentMethodId) || null;
    payload.afriexSelectionRequired = params.afriexPayoutPlan.selectionRequired === true;
  }

  if (params.extraContext && typeof params.extraContext === "object") {
    Object.assign(payload, params.extraContext);
  }

  return payload;
};

type LiveCommerceSettlementProvider = "STRIPE" | "AFRIEX" | "UNSUPPORTED";

type LiveCommerceSettlementDecision = {
  provider: LiveCommerceSettlementProvider;
  executionMode: "LIVE" | "BLOCKED";
  collectionProcessor: "STRIPE" | "AFRIEX" | null;
  settlementProvider: "STRIPE" | "AFRIEX" | null;
  processorMode: string | null;
  destinationAccountId: string | null;
  afriexPayoutPlan: Record<string, unknown> | null;
  message: string | null;
};

const getStripeCommerceDestinationAccountIdIfSupported = async (
  userId: string,
  userData: Record<string, unknown>,
  flowName: string
): Promise<{available: true; destinationAccountId: string} | {available: false; reason: string}> => {
  try {
    const destinationAccountId = await ensureStripeCommerceDestinationAccountId(
      userId,
      userData,
      flowName
    );
    return {available: true, destinationAccountId};
  } catch (error) {
    if (error instanceof functions.https.HttpsError && error.code === "failed-precondition") {
      return {
        available: false,
        reason: error.message || `${flowName} cannot use Stripe right now.`,
      };
    }
    throw error;
  }
};

const buildAfriexCommerceRouteBlockedMessage = (params: {
  flowName: string;
  stripeReason?: string | null;
  afriexPayoutPlan?: Record<string, unknown> | null;
}): string => {
  const route = asNonEmptyString(params.afriexPayoutPlan?.preferredRoute) || null;
  const routeLabel = route ? route.replace(/_/g, " ").toLowerCase() : "bank or mobile-money";
  const selectionRequired = params.afriexPayoutPlan?.selectionRequired === true;
  if (selectionRequired) {
    return `${params.flowName} is not ready for this seller corridor yet. The seller still needs to choose a default payout destination in Wallet > Payment Methods before live partner settlement can be enabled.`;
  }

  const stripeReason = asNonEmptyString(params.stripeReason);
  const suffix = stripeReason ? ` Stripe status: ${stripeReason}` : "";
  return `${params.flowName} is routed to partner ${routeLabel} settlement for this corridor, but live buyer collection on that checkout path is not enabled yet.${suffix}`;
};

const buildUnsupportedCommerceSettlementMessage = (
  flowName: string,
  stripeReason?: string | null
): string =>
  `${flowName} is not available because the recipient does not currently have a supported live payout lane.${stripeReason ? ` Stripe status: ${stripeReason}` : ""} Ask them to finish payout setup in Wallet > Payment Methods.`;

const resolveLiveCommerceSettlementDecision = async (params: {
  recipientUserId: string;
  recipientUserData: Record<string, unknown>;
  flowName: string;
  afriexPayoutPlan?: Record<string, unknown> | null;
}): Promise<LiveCommerceSettlementDecision> => {
  const stripePath = await getStripeCommerceDestinationAccountIdIfSupported(
    params.recipientUserId,
    params.recipientUserData,
    params.flowName
  );
  let stripeUnavailableReason: string | null = null;
  if ("reason" in stripePath) {
    stripeUnavailableReason = stripePath.reason;
  }
  if (stripePath.available) {
    return {
      provider: "STRIPE",
      executionMode: "LIVE",
      collectionProcessor: "STRIPE",
      settlementProvider: "STRIPE",
      processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
      destinationAccountId: stripePath.destinationAccountId,
      afriexPayoutPlan: params.afriexPayoutPlan || null,
      message: null,
    };
  }

  if (params.afriexPayoutPlan) {
    return {
      provider: "AFRIEX",
      executionMode: "BLOCKED",
      collectionProcessor: null,
      settlementProvider: "AFRIEX",
      processorMode: "AFRIEX_COLLECTION_REQUIRED",
      destinationAccountId: null,
      afriexPayoutPlan: params.afriexPayoutPlan,
      message: buildAfriexCommerceRouteBlockedMessage({
        flowName: params.flowName,
        stripeReason: stripeUnavailableReason,
        afriexPayoutPlan: params.afriexPayoutPlan,
      }),
    };
  }

  return {
    provider: "UNSUPPORTED",
    executionMode: "BLOCKED",
    collectionProcessor: null,
    settlementProvider: null,
    processorMode: "UNSUPPORTED_PAYOUT_LANE",
    destinationAccountId: null,
    afriexPayoutPlan: null,
    message: buildUnsupportedCommerceSettlementMessage(
      params.flowName,
      stripeUnavailableReason
    ),
  };
};

type MarketplaceCheckoutFundingPreference = "STRIPE_CARD" | "AFRIEX_MOBILE_MONEY";

const normalizeMarketplaceCheckoutFundingPreference = (
  value: unknown
): MarketplaceCheckoutFundingPreference => {
  const normalized = String(value || "").trim().toUpperCase();
  // Legacy clients did not send a preference and have always used card checkout.
  if (!normalized || normalized === "STRIPE_CARD") return "STRIPE_CARD";
  if (normalized === "AFRIEX_MOBILE_MONEY") return "AFRIEX_MOBILE_MONEY";
  throw new functions.https.HttpsError(
    "invalid-argument",
    "Select a supported marketplace checkout method."
  );
};

const resolveMarketplaceCheckoutSettlementDecision = async (params: {
  recipientUserId: string;
  recipientUserData: Record<string, unknown>;
  flowName: string;
  requestedFundingPreference: MarketplaceCheckoutFundingPreference;
  afriexPayoutPlan?: Record<string, unknown> | null;
}): Promise<LiveCommerceSettlementDecision> => {
  if (params.requestedFundingPreference === "AFRIEX_MOBILE_MONEY") {
    if (!params.afriexPayoutPlan) {
      return {
        provider: "AFRIEX",
        executionMode: "BLOCKED",
        collectionProcessor: null,
        settlementProvider: "AFRIEX",
        processorMode: "AFRIEX_COLLECTION_REQUIRED",
        destinationAccountId: null,
        afriexPayoutPlan: null,
        message: "Mobile money checkout is not available until the seller saves a supported payout destination in Wallet > Payment Methods.",
      };
    }
    if (params.afriexPayoutPlan.selectionRequired === true) {
      return {
        provider: "AFRIEX",
        executionMode: "BLOCKED",
        collectionProcessor: null,
        settlementProvider: "AFRIEX",
        processorMode: "AFRIEX_COLLECTION_REQUIRED",
        destinationAccountId: null,
        afriexPayoutPlan: params.afriexPayoutPlan,
        message: "Mobile money checkout is not available until the seller chooses a default payout destination in Wallet > Payment Methods.",
      };
    }
    return {
      provider: "AFRIEX",
      executionMode: "LIVE",
      collectionProcessor: "AFRIEX",
      settlementProvider: "AFRIEX",
      processorMode: AFRIEX_COMMERCE_PROCESSOR_MODE,
      destinationAccountId: null,
      afriexPayoutPlan: params.afriexPayoutPlan,
      message: null,
    };
  }

  const stripePath = await getStripeCommerceDestinationAccountIdIfSupported(
    params.recipientUserId,
    params.recipientUserData,
    params.flowName
  );
  const stripeUnavailableReason = "reason" in stripePath ? stripePath.reason : null;
  if (stripePath.available) {
    return {
      provider: "STRIPE",
      executionMode: "LIVE",
      collectionProcessor: "STRIPE",
      settlementProvider: "STRIPE",
      processorMode: STRIPE_CONNECT_DIRECT_CHARGE_MODE,
      destinationAccountId: stripePath.destinationAccountId,
      // Card checkout must not silently switch to partner settlement.
      afriexPayoutPlan: null,
      message: null,
    };
  }

  return {
    provider: "STRIPE",
    executionMode: "BLOCKED",
    collectionProcessor: null,
    settlementProvider: null,
    processorMode: "STRIPE_CARD_COLLECTION_REQUIRED",
    destinationAccountId: null,
    afriexPayoutPlan: null,
    message: `Card checkout is not available for this seller yet.${stripeUnavailableReason ? ` ${stripeUnavailableReason}` : " Ask the seller to finish payout setup in Wallet > Payment Methods."}`,
  };
};

const buildLiveCommerceSettlementMetadata = (
  decision: LiveCommerceSettlementDecision
): Record<string, unknown> => ({
  processor: decision.collectionProcessor || admin.firestore.FieldValue.delete(),
  collectionProcessor: decision.collectionProcessor || admin.firestore.FieldValue.delete(),
  settlementProvider: decision.settlementProvider || admin.firestore.FieldValue.delete(),
  processorMode: decision.processorMode || admin.firestore.FieldValue.delete(),
  afriexPayoutProvider: decision.afriexPayoutPlan ? "AFRIEX" : null,
  afriexPreferredPayoutRoute: decision.afriexPayoutPlan ?
    (asNonEmptyString(decision.afriexPayoutPlan.preferredRoute) || null) :
    null,
  afriexPayoutSelectionRequired: decision.afriexPayoutPlan?.selectionRequired === true,
  providerRoutingStatus: decision.executionMode === "LIVE" ? "LIVE_READY" : "ACTION_REQUIRED",
  providerRoutingMessage: decision.message || null,
});

const AFRIEX_COMMERCE_COLLECTION_SOURCE_PREFIX = "AFRIEX_COMMERCE_COLLECTION";
const AFRIEX_COMMERCE_PAYOUT_SOURCE = "AFRIEX_COMMERCE_PAYOUT";
const AFRIEX_COMMERCE_TRANSFER_MODE = "COMMERCE_SETTLEMENT";
const AFRIEX_COMMERCE_PROCESSOR_MODE = "AFRIEX_COMMERCE_COLLECTION";

type AfriexCommerceFundingMethod = {
  paymentMethodId: string;
  phoneNumber: string;
  network: string;
  country: string;
  dialCode: string | null;
  currency: string;
  label: string | null;
};

type AfriexCommerceRecipientTarget = {
  route: AfriexCommercePayoutRoute;
  paymentMethodId: string;
  recipientInfo: Record<string, unknown>;
  localCurrency: string;
  localAmount: number;
  payoutFx: MobileMoneyPayoutFxQuote["fx"];
  actionRequiredMessage: string | null;
};

const buildAfriexCommerceCollectionSource = (settlementCategory: string): string =>
  `${AFRIEX_COMMERCE_COLLECTION_SOURCE_PREFIX}_${String(settlementCategory || "UNKNOWN")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")}`;

const isAfriexCommerceCollectionSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase().startsWith(AFRIEX_COMMERCE_COLLECTION_SOURCE_PREFIX);

const isAfriexCommercePayoutSource = (source: unknown): boolean =>
  String(source || "").trim().toUpperCase() === AFRIEX_COMMERCE_PAYOUT_SOURCE;

const isVerifiedAfriexCommerceFundingMethod = (
  methodData: Record<string, unknown>
): boolean => {
  if (normalizeMethodType(methodData.type) !== "MOBILE_MONEY") return false;
  const country = canonicalAfriexCommerceCountry(
    asNonEmptyString(methodData.country, methodData.countryCode)
  );
  if (!country) return false;
  if (!isMobileMoneyDepositCountrySupportedByProvider("AFRIEX", country)) return false;
  const verificationStatus = String(methodData.verificationStatus || "")
    .trim()
    .toUpperCase();
  if (methodData.phoneOwnershipVerified !== true) return false;
  if (verificationStatus !== "VERIFIED") return false;
  const phone = asNonEmptyString(methodData.phoneNumber);
  const network = asNonEmptyString(methodData.network);
  const currency = normalizeIsoCurrencyForFx(methodData.currency) ||
    resolveMobileMoneyCurrency(methodData);
  return !!phone && !!network && !!currency;
};

const compareAfriexCommerceFundingMethods = (
  lhs: Record<string, unknown>,
  rhs: Record<string, unknown>
): number => {
  const lhsDefault = lhs.isDefault === true ? 1 : 0;
  const rhsDefault = rhs.isDefault === true ? 1 : 0;
  if (lhsDefault !== rhsDefault) return rhsDefault - lhsDefault;

  const lhsLabel = asNonEmptyString(lhs.label, lhs.network, lhs.phoneNumber) || "";
  const rhsLabel = asNonEmptyString(rhs.label, rhs.network, rhs.phoneNumber) || "";
  return lhsLabel.localeCompare(rhsLabel);
};

const resolveReadyAfriexCommerceFundingMethodForUser = async (
  userId: string
): Promise<AfriexCommerceFundingMethod | null> => {
  const methodsSnap = await db.collection("users").doc(userId)
    .collection("payment_methods")
    .get();

  const readyMethods = methodsSnap.docs
    .map((doc) => ({id: doc.id, data: (doc.data() || {}) as Record<string, unknown>}))
    .filter(({data}) => isVerifiedAfriexCommerceFundingMethod(data))
    .sort((left, right) => compareAfriexCommerceFundingMethods(left.data, right.data));

  const winner = readyMethods[0];
  if (!winner) return null;

  const canonicalCountry = canonicalAfriexCommerceCountry(
    asNonEmptyString(winner.data.country, winner.data.countryCode)
  );
  const currency = normalizeIsoCurrencyForFx(winner.data.currency) ||
    resolveMobileMoneyCurrency(winner.data);
  if (!canonicalCountry || !currency) return null;

  return {
    paymentMethodId: winner.id,
    phoneNumber: asNonEmptyString(winner.data.phoneNumber) || "",
    network: asNonEmptyString(winner.data.network) || "",
    country: canonicalCountry,
    dialCode: asNonEmptyString(winner.data.dialCode) || null,
    currency,
    label: asNonEmptyString(winner.data.label, winner.data.network) || null,
  };
};

const getStoredFullBankAccountNumber = (
  methodData: Record<string, unknown>
): string | null => {
  const raw = asNonEmptyString(
    methodData.accountNumberRaw,
    methodData.fullAccountNumber,
    methodData.bankAccountNumber,
    methodData.unmaskedAccountNumber,
    methodData.providerAccountNumber
  );
  if (!raw || raw.includes("*")) return null;
  const digits = normalizeDigits(raw);
  return digits.length >= 6 ? digits : null;
};

const buildAfriexCommerceRecipientTargetForUser = async (params: {
  recipientUserId: string;
  amount: number;
  payoutPlan: Record<string, unknown>;
}): Promise<AfriexCommerceRecipientTarget | null> => {
  const preferredMethodId = asNonEmptyString(params.payoutPlan.preferredPaymentMethodId);
  if (!preferredMethodId) {
    return {
      route: "MOBILE_MONEY",
      paymentMethodId: "",
      recipientInfo: {},
      localCurrency: "USD",
      localAmount: params.amount,
      payoutFx: {
        fromCurrency: "USD",
        toCurrency: "USD",
        rate: 1,
        realRate: 1,
        margin: 0,
        provider: "IDENTITY",
        fetchedAtMs: Date.now(),
        requestUrl: "local://identity",
        feeExempt: true,
        direction: "AFRIEX_COMMERCE_PAYOUT",
      },
      actionRequiredMessage: "The seller still needs to choose a default payout destination in Wallet > Payment Methods.",
    };
  }

  const methodSnap = await db.collection("users").doc(params.recipientUserId)
    .collection("payment_methods")
    .doc(preferredMethodId)
    .get();
  if (!methodSnap.exists) {
    return {
      route: "MOBILE_MONEY",
      paymentMethodId: preferredMethodId,
      recipientInfo: {},
      localCurrency: "USD",
      localAmount: params.amount,
      payoutFx: {
        fromCurrency: "USD",
        toCurrency: "USD",
        rate: 1,
        realRate: 1,
        margin: 0,
        provider: "IDENTITY",
        fetchedAtMs: Date.now(),
        requestUrl: "local://identity",
        feeExempt: true,
        direction: "AFRIEX_COMMERCE_PAYOUT",
      },
      actionRequiredMessage: "The saved payout destination could not be found. Ask the seller to reopen Wallet > Payment Methods and save it again.",
    };
  }

  const methodData = await withPrivatePaymentMethodFields(
    params.recipientUserId,
    preferredMethodId,
    (methodSnap.data() || {}) as Record<string, unknown>
  );
  const route = asNonEmptyString(params.payoutPlan.preferredRoute)?.toUpperCase() === "BANK" ?
    "BANK" as AfriexCommercePayoutRoute :
    "MOBILE_MONEY" as AfriexCommercePayoutRoute;
  const country = canonicalAfriexCommerceCountry(
    asNonEmptyString(methodData.country, methodData.countryCode),
    route === "BANK" ? "BANK_ACCOUNT" : "MOBILE_MONEY"
  );
  if (!country) {
    return null;
  }

  if (route === "MOBILE_MONEY") {
    if (!isReadyAfriexCommerceMobileMoneyMethod(methodData)) {
      return {
        route,
        paymentMethodId: preferredMethodId,
        recipientInfo: {},
        localCurrency: "USD",
        localAmount: params.amount,
        payoutFx: {
          fromCurrency: "USD",
          toCurrency: "USD",
          rate: 1,
          realRate: 1,
          margin: 0,
          provider: "IDENTITY",
          fetchedAtMs: Date.now(),
          requestUrl: "local://identity",
          feeExempt: true,
          direction: "AFRIEX_COMMERCE_PAYOUT",
        },
        actionRequiredMessage: "The seller's default mobile money destination is not verified yet.",
      };
    }

    const localCurrency = normalizeIsoCurrencyForFx(methodData.currency) ||
      resolveMobileMoneyCurrency(methodData);
    if (!localCurrency) return null;

    const payoutFx = await buildMobileMoneyPayoutFxQuote({
      amount: params.amount,
      sourceCurrency: "USD",
      localCurrency,
      direction: "AFRIEX_COMMERCE_PAYOUT",
      destinationCountry: country,
      destinationRoute: "MOBILE_MONEY",
    });
    const phoneNumber = asNonEmptyString(methodData.phoneNumber) || "";

    return {
      route,
      paymentMethodId: preferredMethodId,
      recipientInfo: {
        id: preferredMethodId,
        type: "MOBILE_MONEY",
        name: asNonEmptyString(methodData.registeredName, methodData.accountHolderName) || "Seller",
        registeredName: asNonEmptyString(methodData.registeredName, methodData.accountHolderName) || null,
        mobileNumber: phoneNumber,
        accountNumber: phoneNumber,
        phone: phoneNumber,
        network: asNonEmptyString(methodData.network) || null,
        country,
        dialCode: asNonEmptyString(methodData.dialCode) || null,
        currency: payoutFx.localCurrency,
        institutionCode: getAfriexInstitutionCodeFromRecord(methodData) || null,
        afriexCustomerId: getAfriexCustomerIdFromRecord(methodData) || null,
        providerCustomerId: getAfriexCustomerIdFromRecord(methodData) || null,
        afriexDestinationPaymentMethodId: getAfriexDestinationPaymentMethodId(methodData, methodData) || null,
        providerDestinationPaymentMethodId: getAfriexDestinationPaymentMethodId(methodData, methodData) || null,
      },
      localCurrency: payoutFx.localCurrency,
      localAmount: payoutFx.localAmount,
      payoutFx: payoutFx.fx,
      actionRequiredMessage: null,
    };
  }

  const providerDestinationPaymentMethodId = getAfriexDestinationPaymentMethodId(methodData, methodData) || null;
  const providerCustomerId = getAfriexCustomerIdFromRecord(methodData) || null;
  const accountNumber = getStoredFullBankAccountNumber(methodData);
  const institutionCode = getAfriexInstitutionCodeFromRecord(methodData) || null;
  const bankName = asNonEmptyString(
    methodData.bankName,
    methodData.institutionName,
    methodData.providerInstitutionName,
    methodData.label
  ) || null;
  const accountHolderName = asNonEmptyString(
    methodData.accountHolderName,
    methodData.registeredName,
    methodData.name
  );
  const bankCurrency = normalizeIsoCurrencyForFx(methodData.currency) ||
    resolveMobileMoneyCurrency({country}) ||
    null;
  if (!bankCurrency) return null;

  const payoutFx = await buildMobileMoneyPayoutFxQuote({
    amount: params.amount,
    sourceCurrency: "USD",
    localCurrency: bankCurrency,
    direction: "AFRIEX_COMMERCE_PAYOUT",
    destinationCountry: country,
    destinationRoute: "BANK_ACCOUNT",
  });

  const destinationReady =
    (!!providerDestinationPaymentMethodId && !!providerCustomerId) ||
    (!!accountNumber && !!accountHolderName && !!asNonEmptyString(institutionCode, bankName));

  return {
    route,
    paymentMethodId: preferredMethodId,
    recipientInfo: {
      id: preferredMethodId,
      type: "BANK_ACCOUNT",
      name: accountHolderName || "Seller",
      accountHolderName: accountHolderName || null,
      bankName,
      institutionName: bankName,
      accountNumber: accountNumber || asNonEmptyString(methodData.accountNumber) || null,
      accountNumberRaw: accountNumber,
      fullAccountNumber: accountNumber,
      country,
      currency: payoutFx.localCurrency,
      institutionCode,
      afriexCustomerId: providerCustomerId,
      providerCustomerId,
      afriexDestinationPaymentMethodId: providerDestinationPaymentMethodId,
      providerDestinationPaymentMethodId,
    },
    localCurrency: payoutFx.localCurrency,
    localAmount: payoutFx.localAmount,
    payoutFx: payoutFx.fx,
    actionRequiredMessage: destinationReady ?
      null :
      "The seller selected bank payout, but the saved bank destination is still missing required provider details. Re-save the bank account in Wallet > Payment Methods so it can be provisioned.",
  };
};

const resolveAfriexCommerceRuntime = async (params: {
  buyerUserId: string;
  recipientUserId: string;
  recipientPayoutPlan: Record<string, unknown> | null;
  grossAmount: number;
  netAmount: number;
  flowName: string;
}): Promise<{
  fundingMethod: AfriexCommerceFundingMethod;
  recipientTarget: AfriexCommerceRecipientTarget;
}> => {
  const fundingMethod = await resolveReadyAfriexCommerceFundingMethodForUser(params.buyerUserId);
  if (!fundingMethod) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      `${params.flowName} can use mobile-money collection in this corridor, but the buyer still needs a verified default mobile money funding source in a live mobile-money collection country.`
    );
  }
  if (!params.recipientPayoutPlan) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      `${params.flowName} can use partner settlement in this corridor, but the seller still needs to save a payout destination in Wallet > Payment Methods.`
    );
  }
  const recipientTarget = await buildAfriexCommerceRecipientTargetForUser({
    recipientUserId: params.recipientUserId,
    amount: params.netAmount,
    payoutPlan: params.recipientPayoutPlan,
  });
  if (!recipientTarget) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      `${params.flowName} can use partner settlement in this corridor, but the seller payout destination could not be prepared.`
    );
  }
  if (recipientTarget.actionRequiredMessage) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      recipientTarget.actionRequiredMessage
    );
  }

  return {fundingMethod, recipientTarget};
};

const getAccountPhoneVerificationTarget = async (
  uid: string
): Promise<{phoneE164: string; phoneDigits: string} | null> => {
  const userRef = db.collection("users").doc(uid);
  const userSnap = await userRef.get();
  if (!userSnap.exists) {
    throw new functions.https.HttpsError("not-found", "User profile not found.");
  }

  const userData = (userSnap.data() || {}) as Record<string, unknown>;
  const accountPhoneE164 = normalizeStoredAccountPhoneE164(userData);
  const accountPhoneDigits = normalizeDigits(accountPhoneE164);
  if (!accountPhoneDigits) {
    return null;
  }
  return {
    phoneE164: accountPhoneE164,
    phoneDigits: accountPhoneDigits,
  };
};

const isAccountPhoneVerificationTarget = async (
  uid: string,
  phoneDigits: string
): Promise<boolean> => {
  const target = await getAccountPhoneVerificationTarget(uid);
  return !!target && target.phoneDigits === phoneDigits;
};

const assertAccountPhoneVerificationTarget = async (
  uid: string,
  phoneDigits: string
): Promise<void> => {
  const matches = await isAccountPhoneVerificationTarget(uid, phoneDigits);
  if (!matches) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "This OTP flow can only verify the phone number saved on your account."
    );
  }
};

const markAccountPhoneVerifiedFromOtp = async (
  uid: string,
  phoneE164: string,
  phoneDigits: string
): Promise<void> => {
  const now = admin.firestore.Timestamp.now();
  await setPrivateUserFields(uid, {
    phoneVerifiedNumber: phoneE164,
    phoneVerifiedDigits: phoneDigits,
    updatedAt: now,
  });
  await db.collection("users").doc(uid).set({
    phoneVerified: true,
    phoneVerifiedAt: now,
    phoneVerificationMethod: "ACCOUNT_PHONE_OTP",
    updatedAt: now,
  }, {merge: true});
};

const savedMessageForType = (type: string): string => {
  switch (type) {
  case "CARD":
    return "Card saved. Deposit setup and withdrawal payout setup complete separately.";
  case "BANK":
    return "Bank account saved. Deposit setup and withdrawal payout setup complete separately.";
  case "MOBILE_MONEY":
    return "Mobile money number saved successfully.";
  default:
    return "Payment method saved successfully.";
  }
};

const missingIdentityMessageForType = (type: string): string => {
  switch (type) {
  case "CARD":
    return "Card details are incomplete. Please provide last4 and expiry date.";
  case "BANK":
    return "Bank account details are incomplete. Please provide account details.";
  case "MOBILE_MONEY":
    return "Mobile money details are incomplete. Please provide a phone number.";
  default:
    return "Payment method data is incomplete.";
  }
};

const isAlreadyExistsError = (error: unknown): boolean => {
  const code = (error as {code?: string | number})?.code;
  if (code === 6 || code === "already-exists") return true;
  const message = String((error as {message?: string})?.message || "");
  return message.includes("ALREADY_EXISTS") || message.includes("already exists");
};

const assertMobileMoneyPhoneOtpVerified = async (params: {
  uid: string;
  phoneNumber?: unknown;
  dialCode?: unknown;
}): Promise<{phoneE164: string; phoneDigits: string; verifiedAtMs: number | null}> => {
  const phoneE164 = normalizeMobileMoneyPhoneE164(params.phoneNumber, params.dialCode);
  const phoneDigits = normalizeDigits(phoneE164);
  if (phoneDigits.length < 8 || phoneDigits.length > 15) {
    throw new functions.https.HttpsError(
      "invalid-argument",
      "A valid mobile money phone number is required."
    );
  }

  const otpRef = getMobileMoneyOtpRef(params.uid, phoneDigits);
  const otpSnap = await otpRef.get();
  if (!otpSnap.exists) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Verify this mobile money phone number with OTP before saving."
    );
  }

  const otpData = (otpSnap.data() || {}) as Record<string, unknown>;
  const otpStatus = String(otpData.status || "").trim().toUpperCase();
  if (otpStatus !== "VERIFIED") {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Verify this mobile money phone number with OTP before saving."
    );
  }

  const verifiedAtMs = toMillisTimestamp(otpData.verifiedAt) || Number(otpData.verifiedAtMs || 0) || null;
  return {phoneE164, phoneDigits, verifiedAtMs};
};

export const addPaymentMethod = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) throw new functions.https.HttpsError("unauthenticated", "You must be logged in to add a payment method.");
    const userId = context.auth.uid;
    const requestData = (data || {}) as AddPaymentMethodRequest;
    const methodType = normalizeMethodType(requestData.type);
    if (!methodType) throw new functions.https.HttpsError("invalid-argument", "Payment method data is incomplete.");
    if (!["CARD", "BANK", "MOBILE_MONEY"].includes(methodType)) {
      throw new functions.https.HttpsError("invalid-argument", "Unsupported payment method type.");
    }

    const normalizedData: AddPaymentMethodRequest = {
      ...requestData,
      type: methodType,
    };

    const dedupeKey = buildPaymentMethodDedupeKey(normalizedData);
    const mustHaveIdentity = methodType === "CARD" || methodType === "BANK" || methodType === "MOBILE_MONEY";
    if (mustHaveIdentity && !dedupeKey) {
      throw new functions.https.HttpsError("invalid-argument", missingIdentityMessageForType(methodType));
    }

    const userRef = db.collection("users").doc(userId);
    const methodsRef = userRef.collection("payment_methods");
    try {
      const existingSnap = await methodsRef.get();
      if (dedupeKey) {
        const hasDuplicate = existingSnap.docs.some((doc) => {
          const existingData = doc.data() as AddPaymentMethodRequest;
          return normalizeMethodType(existingData.type) === methodType &&
            getStoredPaymentMethodDedupeKey(existingData) === dedupeKey;
        });

        if (hasDuplicate) {
          throw new functions.https.HttpsError("already-exists", duplicateMessageForType(methodType));
        }
      }

      const now = admin.firestore.Timestamp.now();
      const shouldBeDefault = normalizedData.isDefault === true || existingSnap.empty;
      let payload: Record<string, unknown> = {
        type: methodType,
        dedupeKey: dedupeKey || null,
        isDefault: shouldBeDefault,
        createdAt: now,
        updatedAt: now,
      };

      if (methodType === "CARD") {
        const last4 = normalizeDigits(normalizedData.last4 || normalizedData.cardNumber).slice(-4);
        const expiry = normalizeExpiry(normalizedData.expiryDate);
        payload = {
          ...payload,
          label: asNonEmptyString(normalizedData.label) || `Card ending in ${last4}`,
          cardHolderName: asNonEmptyString(normalizedData.cardHolderName) || null,
          cardNumber: last4 ? buildMaskedCardDisplayNumber(last4) : null,
          expiryDate: expiry || null,
          brand: asNonEmptyString(normalizedData.brand)?.toUpperCase() || null,
          last4: last4 || null,
        };
        payload.requiresRelinkForCharges = true;
        payload.requiresPayoutSetup = true;
        payload.chargeSetupCheckedAt = now;
        payload.payoutSetupCheckedAt = now;
      }

      if (methodType === "BANK") {
        const last4 = normalizeDigits(normalizedData.last4 || normalizedData.accountNumber).slice(-4);
        const normalizedCountry = normalizeStoredCountry(normalizedData.country);
        const normalizedCurrency =
          normalizedCountry === "US" || normalizedCountry === "USA" || normalizedCountry === "United States" ?
            "USD" :
            normalizeIsoCurrencyCode(normalizedData.currency);
        payload = {
          ...payload,
          label: asNonEmptyString(normalizedData.label, normalizedData.bankName) || "Bank Account",
          bankName: asNonEmptyString(normalizedData.bankName) || null,
          accountHolderName: asNonEmptyString(normalizedData.accountHolderName) || null,
          accountNumber: last4 ? buildMaskedBankDisplayNumber(last4) : null,
          last4: last4 || null,
          routingNumber: normalizeDigits(normalizedData.routingNumber) || null,
          country: normalizedCountry,
          currency: normalizedCurrency,
          institutionCode: asNonEmptyString(normalizedData.institutionCode) || null,
        };
        payload.requiresRelinkForCharges = true;
        payload.requiresPayoutSetup = true;
        payload.chargeSetupCheckedAt = now;
        payload.payoutSetupCheckedAt = now;
      }

      if (methodType === "MOBILE_MONEY") {
        const otpVerification = await assertMobileMoneyPhoneOtpVerified({
          uid: userId,
          phoneNumber: normalizedData.phoneNumber,
          dialCode: normalizedData.dialCode,
        });
        const canonicalCountry = assertCountrySupportedForConfiguredProvider(normalizedData.country);
        const payoutCurrency = resolveMobileMoneyCurrency({
          country: canonicalCountry || normalizedData.country,
        });
        if (!canonicalCountry || !payoutCurrency) {
          throw new functions.https.HttpsError(
            "invalid-argument",
            "Unsupported mobile money country or currency."
          );
        }

        const registeredName = asNonEmptyString(normalizedData.registeredName);
        if (!registeredName) {
          throw new functions.https.HttpsError(
            "invalid-argument",
            "Registered account name is required for mobile money."
          );
        }
        const destinationDecision = await runBeneficiaryVerificationDecision({
          prepared: prepareBeneficiaryVerificationInput({
            beneficiary: {
              name: registeredName,
              accountNumber: otpVerification.phoneE164,
              mobileNumber: otpVerification.phoneE164,
              phone: otpVerification.phoneE164,
              network: asNonEmptyString(normalizedData.network) || "MOBILE_MONEY",
              country: canonicalCountry,
              currency: payoutCurrency.toUpperCase(),
              type: "MOBILE_MONEY",
              route: "MOBILE_MONEY",
              afriexPayoutRoute: "MOBILE_MONEY",
            },
            requestedCurrency: payoutCurrency,
          }),
        });
        if (!destinationDecision.canProceed) {
          functions.logger.warn("Afriex mobile-money precheck rejected payment-method registration", {
            userId,
            country: canonicalCountry,
            network: asNonEmptyString(normalizedData.network) || null,
            reasonCode: destinationDecision.reasonCode,
            providerStatus: destinationDecision.provider.rawStatus,
            providerDiagnostic: summarizeProviderHttpDiagnostic(
              destinationDecision.provider.httpDiagnostic
            ),
          });
          throw new functions.https.HttpsError(
            "failed-precondition",
            destinationDecision.reasonMessage || "The payment partner could not verify this mobile money destination."
          );
        }

        payload = {
          ...payload,
          label: asNonEmptyString(normalizedData.label) || `${asNonEmptyString(normalizedData.network) || "Mobile Money"} (${maskPhoneNumberForOtp(otpVerification.phoneE164)})`,
          phoneNumber: otpVerification.phoneE164,
          phoneDigits: otpVerification.phoneDigits,
          network: asNonEmptyString(
            destinationDecision.provider.resolvedInstitutionName,
            normalizedData.network
          ) || null,
          registeredName: asNonEmptyString(
            destinationDecision.provider.providerAccountName,
            registeredName
          ) || null,
          country: canonicalCountry,
          dialCode: asNonEmptyString(normalizedData.dialCode) || null,
          currency: payoutCurrency.toUpperCase(),
          institutionCode: asNonEmptyString(destinationDecision.provider.resolvedInstitutionCode) || null,
          providerInstitutionCode: asNonEmptyString(destinationDecision.provider.resolvedInstitutionCode) || null,
          afriexInstitutionCode: asNonEmptyString(destinationDecision.provider.resolvedInstitutionCode) || null,
          providerInstitutionName: asNonEmptyString(destinationDecision.provider.resolvedInstitutionName) || null,
          providerRecipientName: asNonEmptyString(destinationDecision.provider.providerAccountName) || null,
        };
        const providerResolveConfirmed =
          destinationDecision.matchLevel === "PHONE_AND_PROVIDER_CONFIRMED";
        payload.phoneOtpVerified = true;
        payload.phoneOtpVerifiedAt = otpVerification.verifiedAtMs ?
          admin.firestore.Timestamp.fromMillis(otpVerification.verifiedAtMs) :
          now;
        payload.phoneOwnershipVerified = true;
        payload.verificationStatus = providerResolveConfirmed ?
          "VERIFIED" :
          "PENDING_PROVIDER_VERIFICATION";
        const providerReturnedName =
          asNonEmptyString(destinationDecision.provider.providerAccountName) !== undefined;
        payload.verificationMethod = providerResolveConfirmed ?
          (providerReturnedName ?
            "OTP_AND_AFRIEX_NAME_MATCH" :
            "OTP_AND_AFRIEX_ROUTE_VALIDATED") :
          "OTP_PENDING_AFRIEX_DESTINATION_RESOLVE";
        payload.verificationCompletedAt = providerResolveConfirmed ? now : null;
        // A resolve confirms the recipient details; only the later payment-method
        // creation confirms the destination can receive an Afriex payout.
        payload.providerDestinationVerified = false;
        payload.providerDestinationSyncStatus = "PENDING";
        payload.providerDestinationCheckedAt = now;
        payload.lastProviderDestinationSyncError = null;
        payload.lastVerificationError = providerResolveConfirmed ?
          null :
          "Provider destination verification is pending. This route cannot receive transfers until activation succeeds.";
      }

      let paymentMethodId: string;
      if (dedupeKey) {
        const docRef = methodsRef.doc(`dedupe_${dedupeKey}`);
        try {
          await docRef.create(payload);
        } catch (error) {
          if (isAlreadyExistsError(error)) {
            throw new functions.https.HttpsError("already-exists", duplicateMessageForType(methodType));
          }
          throw error;
        }
        paymentMethodId = docRef.id;
      } else {
        const docRef = await methodsRef.add(payload);
        paymentMethodId = docRef.id;
      }

      if (shouldBeDefault) {
        const batch = db.batch();
        existingSnap.docs.forEach((doc) => {
          batch.set(doc.ref, {isDefault: false, updatedAt: now}, {merge: true});
        });
        batch.set(methodsRef.doc(paymentMethodId), {isDefault: true, updatedAt: now}, {merge: true});
        await batch.commit();
      }

      if (methodType === "BANK") {
        const normalizedAccountNumber = normalizeDigits(normalizedData.accountNumber);
        if (normalizedAccountNumber.length >= 6) {
          await setPrivatePaymentMethodFields(userId, paymentMethodId, {
            accountNumberRaw: normalizedAccountNumber,
            fullAccountNumber: normalizedAccountNumber,
            bankAccountNumber: normalizedAccountNumber,
            unmaskedAccountNumber: normalizedAccountNumber,
            providerAccountNumber: normalizedAccountNumber,
          });
        }
      }

      // Make provider activation client-independent. A route is marked ready only
      // when Afriex returns a payout destination ID; a failed activation leaves the
      // saved method editable and records a safe status for the next refresh.
      if (methodType === "BANK" || methodType === "MOBILE_MONEY") {
        const [savedMethodSnapshot, userSnapshot] = await Promise.all([
          methodsRef.doc(paymentMethodId).get(),
          userRef.get(),
        ]);
        if (savedMethodSnapshot.exists && userSnapshot.exists) {
          const userData = await withPrivateUserFields(
            userId,
            (userSnapshot.data() || {}) as Record<string, unknown>
          );
          try {
            await syncAfriexPayoutDestinationForSavedMethod({
              userId,
              userData,
              methodDoc: savedMethodSnapshot as FirebaseFirestore.QueryDocumentSnapshot,
            });
          } catch (error) {
            const message = parseProviderErrorMessage(error) ||
              "Provider destination could not be activated yet.";
            await markAfriexPayoutMethodSync({
              methodRef: methodsRef.doc(paymentMethodId),
              state: "FAILED",
              message,
            });
            functions.logger.warn("Saved payment method needs a later Afriex route sync", {
              userId,
              paymentMethodId,
              methodType,
              message,
              providerDiagnostic: summarizeProviderHttpDiagnostic(
                extractProviderHttpDiagnostic(error)
              ),
            });
          }
        }
      }

      const message = savedMessageForType(methodType);
      functions.logger.log(`Successfully added payment method of type ${methodType} for user ${userId}.`);
      return {success: true, message, paymentMethodId};
    } catch (error) {
      if (error instanceof functions.https.HttpsError) {
        throw error;
      }
      functions.logger.error(`Failed to add payment method for user ${userId}:`, error);
      throw new functions.https.HttpsError("internal", "Could not save the payment method.");
    }
  });

interface SyncAfriexPayoutMethodsRequest {
  paymentMethodId?: unknown;
}

type AfriexPayoutMethodSyncOutcome = {
  paymentMethodId: string;
  state: "VERIFIED" | "PENDING" | "SKIPPED" | "FAILED";
  message: string;
};

const markAfriexPayoutMethodSync = async (params: {
  methodRef: FirebaseFirestore.DocumentReference;
  state: "VERIFIED" | "PENDING" | "SKIPPED" | "FAILED";
  message?: string | null;
  patch?: Record<string, unknown>;
}): Promise<void> => {
  const now = admin.firestore.Timestamp.now();
  const isVerified = params.state === "VERIFIED";
  await params.methodRef.set({
    providerDestinationVerified: isVerified,
    providerDestinationSyncStatus: params.state,
    providerDestinationCheckedAt: now,
    lastProviderDestinationSyncError: isVerified ? null : (params.message || null),
    ...(isVerified ? {
      lastVerificationError: null,
      verificationCompletedAt: now,
    } : {}),
    ...(params.patch || {}),
    updatedAt: now,
  }, {merge: true});
};

const ensureAfriexCustomerForSavedPayoutMethod = async (params: {
  userId: string;
  userData: Record<string, unknown>;
  methodData: Record<string, unknown>;
  countryCode: string;
  country: string;
}): Promise<string> => {
  const existingCustomerId = asNonEmptyString(
    params.methodData.providerCustomerId,
    params.methodData.afriexCustomerId,
    params.userData.afriexCustomerId,
    params.userData.providerCustomerId
  );
  if (existingCustomerId) return existingCustomerId;

  const profile = resolveAfriexCustomerProfile(params.userData);
  const fullName = resolveHostedWalletFullName(params.userData);
  const email = normalizeEmailLower(asNonEmptyString(params.userData.email));
  const destinationPhone = normalizeAfriexCustomerPhoneForCountry(
    asNonEmptyString(
      params.methodData.phoneNumber,
      params.methodData.phone,
      params.methodData.mobileNumber,
      profile.phone
    ),
    params.country
  );
  if (!fullName || !email || !destinationPhone) {
    const missing = [
      fullName ? "" : "full name",
      email ? "" : "email",
      destinationPhone ? "" : "phone number",
    ].filter((value) => value.length > 0);
    throw new functions.https.HttpsError(
      "failed-precondition",
      `Complete your profile with ${missing.join(", ")} before activating this payout destination.`
    );
  }

  const provider = getMobileMoneyProviderHttpOptions();
  if (provider.providerName !== "AFRIEX") {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "This payout destination can only be activated when Afriex is the configured provider."
    );
  }
  const customerId = await createAfriexCustomer({
    providerUrl: provider.providerUrl,
    headers: provider.headers,
    timeoutMs: provider.timeoutMs,
    fullName,
    email,
    phone: destinationPhone,
    countryCode: params.countryCode,
    senderId: params.userId,
  });
  await setPrivateUserFields(params.userId, {
    afriexCustomerId: customerId,
    afriexCustomerProvisionedAtMs: Date.now(),
  });
  return customerId;
};

const syncAfriexPayoutDestinationForSavedMethod = async (params: {
  userId: string;
  userData: Record<string, unknown>;
  methodDoc: FirebaseFirestore.QueryDocumentSnapshot;
}): Promise<AfriexPayoutMethodSyncOutcome> => {
  const methodRef = params.methodDoc.ref;
  const methodId = params.methodDoc.id;
  const methodData = await withPrivatePaymentMethodFields(
    params.userId,
    methodId,
    (params.methodDoc.data() || {}) as Record<string, unknown>
  );
  const methodType = normalizeMethodType(methodData.type);
  if (methodType !== "MOBILE_MONEY" && methodType !== "BANK") {
    return {paymentMethodId: methodId, state: "SKIPPED", message: "This method is not an Afriex payout destination."};
  }

  const existingDestinationId = getAfriexDestinationPaymentMethodId(methodData, methodData);
  if (existingDestinationId) {
    await markAfriexPayoutMethodSync({
      methodRef,
      state: "VERIFIED",
    });
    return {paymentMethodId: methodId, state: "VERIFIED", message: "Provider payout destination is already active."};
  }

  const provider = getMobileMoneyProviderHttpOptions();
  if (provider.providerName !== "AFRIEX") {
    return {paymentMethodId: methodId, state: "SKIPPED", message: "Afriex is not the active payout provider."};
  }

  if (methodType === "MOBILE_MONEY") {
    const country = canonicalAfriexCommerceCountry(asNonEmptyString(methodData.country, methodData.countryCode));
    const phone = asNonEmptyString(methodData.phoneNumber, methodData.phone, methodData.mobileNumber);
    const network = asNonEmptyString(methodData.network, methodData.brand);
    const registeredName = asNonEmptyString(methodData.registeredName, methodData.accountHolderName);
    const verificationStatus = String(methodData.verificationStatus || "").trim().toUpperCase();
    if (!country || !phone || !network || !registeredName) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Mobile money country, verified phone, network, and registered name are required before provider activation."
      );
    }
    if (methodData.phoneOwnershipVerified !== true || verificationStatus !== "VERIFIED") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Verify phone ownership before activating this mobile money payout destination."
      );
    }

    const countryCode = getAfriexCountryIso2(country);
    const institution = await resolveAfriexMobileMoneyInstitution({
      providerUrl: provider.providerUrl,
      headers: provider.headers,
      timeoutMs: provider.timeoutMs,
      countryCode,
      network,
      records: [methodData],
    });
    let resolvedName: string | null = null;
    let resolvedInstitutionCode = institution.institutionCode || null;
    let resolvedInstitutionName = institution.institutionName || null;
    try {
      const resolved = await resolveAfriexMobileMoneyPaymentMethod({
        providerUrl: provider.providerUrl,
        headers: provider.headers,
        timeoutMs: provider.timeoutMs,
        phoneNumber: phone,
        countryCode,
        institutionCode: resolvedInstitutionCode || undefined,
      });
      resolvedName = resolved.recipientName;
      resolvedInstitutionCode = resolved.institutionCode || resolvedInstitutionCode;
      resolvedInstitutionName = resolved.institutionName || resolvedInstitutionName;
      if (resolvedName && beneficiaryNameMatchScore(registeredName, resolvedName) < 100) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "The mobile money account name does not match the provider record. Update it before saving."
        );
      }
    } catch (error) {
      if (!isAfriexMobileMoneyResolveCountryUnsupportedError(error)) throw error;
    }
    if (!resolvedInstitutionCode) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Select a supported mobile money network before activating this payout destination."
      );
    }

    const customerId = await ensureAfriexCustomerForSavedPayoutMethod({
      userId: params.userId,
      userData: params.userData,
      methodData,
      countryCode,
      country,
    });
    const destinationId = await createAfriexPaymentMethod({
      providerUrl: provider.providerUrl,
      headers: provider.headers,
      timeoutMs: provider.timeoutMs,
      customerId,
      channel: "MOBILE_MONEY",
      accountName: resolvedName || registeredName,
      accountNumber: phone,
      countryCode,
      institutionCode: resolvedInstitutionCode,
      institutionName: resolvedInstitutionName,
      senderId: params.userId,
      beneficiaryId: methodId,
    });
    await markAfriexPayoutMethodSync({
      methodRef,
      state: "VERIFIED",
      patch: {
        afriexCustomerId: customerId,
        providerCustomerId: customerId,
        mobileMoneyProviderCustomerId: customerId,
        afriexDestinationPaymentMethodId: destinationId,
        providerDestinationPaymentMethodId: destinationId,
        destinationId,
        institutionCode: resolvedInstitutionCode,
        providerInstitutionCode: resolvedInstitutionCode,
        afriexInstitutionCode: resolvedInstitutionCode,
        mobileMoneyInstitutionCode: resolvedInstitutionCode,
        providerInstitutionName: resolvedInstitutionName,
        // Afriex returns names only for corridors that support name enquiry.
        // Never copy the user-entered name into this provider-confirmed field.
        providerRecipientName: resolvedName,
        registeredName,
        verificationStatus: "VERIFIED",
        verificationMethod: resolvedName ?
          "OTP_AND_AFRIEX_NAME_MATCH" :
          "OTP_AND_AFRIEX_ROUTE_VALIDATED",
      },
    });
    return {
      paymentMethodId: methodId,
      state: "VERIFIED",
      message: resolvedName ?
        "Mobile money payout destination verified, name matched, and synced." :
        "Mobile money number and network validated; this corridor does not return the account holder name. The payout destination is ready.",
    };
  }

  const countryInput = asNonEmptyString(methodData.country, methodData.countryCode);
  const country = canonicalAfriexCommerceCountry(countryInput, "BANK_ACCOUNT");
  if (!country) {
    return {paymentMethodId: methodId, state: "SKIPPED", message: "This bank is outside the currently enabled Afriex local-bank corridors."};
  }
  const countryCode = getAfriexCountryIso2(country);
  const providerChannel = resolveAfriexBankProviderChannel(
    countryCode,
    asNonEmptyString(methodData.institutionCode, methodData.providerInstitutionCode, methodData.afriexInstitutionCode),
    asNonEmptyString(methodData.providerChannel, methodData.afriexProviderChannel)
  );
  if (providerChannel !== "BANK_ACCOUNT") {
    return {paymentMethodId: methodId, state: "SKIPPED", message: "International bank routes are verified when their complete SWIFT transfer details are supplied."};
  }
  if (isAfriexSandboxBankAccountUnavailable(countryCode)) {
    return {paymentMethodId: methodId, state: "SKIPPED", message: buildAfriexSandboxBankAccountUnavailableMessage(countryCode)};
  }

  const accountNumber = getStoredFullBankAccountNumber(methodData);
  const accountHolderName = asNonEmptyString(methodData.accountHolderName, methodData.registeredName, methodData.name);
  const bankName = asNonEmptyString(methodData.bankName, methodData.institutionName, methodData.providerInstitutionName);
  if (!accountNumber || !accountHolderName || !bankName) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Bank name, account holder, and full account number are required before provider activation."
    );
  }
  const institution = await resolveAfriexBankInstitution({
    providerUrl: provider.providerUrl,
    headers: provider.headers,
    timeoutMs: provider.timeoutMs,
    countryCode,
    channel: "BANK_ACCOUNT",
    bankName,
    records: [methodData],
  });
  const institutionCode = asNonEmptyString(
    methodData.institutionCode,
    methodData.providerInstitutionCode,
    methodData.afriexInstitutionCode,
    institution.institutionCode
  );
  if (!institutionCode) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Select a supported bank before activating this payout destination."
    );
  }
  const resolved: AfriexResolvedPaymentMethod = countryCode === "US" ? {
    recipientName: null,
    recipientPhone: null,
    institutionName: institution.institutionName || bankName,
    institutionCode,
    raw: {},
  } : await resolveAfriexBankPaymentMethod({
    providerUrl: provider.providerUrl,
    headers: provider.headers,
    timeoutMs: provider.timeoutMs,
    accountNumber,
    countryCode,
    institutionCode,
    channel: "BANK_ACCOUNT",
  });
  const resolvedName = resolved.recipientName || accountHolderName;
  if (resolved.recipientName && beneficiaryNameMatchScore(accountHolderName, resolved.recipientName) < 100) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "The bank account holder does not match the provider record. Update it before saving."
    );
  }
  const customerId = await ensureAfriexCustomerForSavedPayoutMethod({
    userId: params.userId,
    userData: params.userData,
    methodData,
    countryCode,
    country,
  });
  const destinationId = await createAfriexPaymentMethod({
    providerUrl: provider.providerUrl,
    headers: provider.headers,
    timeoutMs: provider.timeoutMs,
    customerId,
    channel: "BANK_ACCOUNT",
    accountName: resolvedName,
    accountNumber,
    countryCode,
    institutionCode,
    institutionName: resolved.institutionName || institution.institutionName || bankName,
    senderId: params.userId,
    beneficiaryId: methodId,
  });
  await markAfriexPayoutMethodSync({
    methodRef,
    state: "VERIFIED",
    patch: {
      afriexCustomerId: customerId,
      providerCustomerId: customerId,
      afriexDestinationPaymentMethodId: destinationId,
      providerDestinationPaymentMethodId: destinationId,
      destinationId,
      institutionCode,
      providerInstitutionCode: institutionCode,
      afriexInstitutionCode: institutionCode,
      providerInstitutionName: resolved.institutionName || institution.institutionName || bankName,
      accountHolderName: resolvedName,
      providerChannel: "BANK_ACCOUNT",
      afriexProviderChannel: "BANK_ACCOUNT",
    },
  });
  return {paymentMethodId: methodId, state: "VERIFIED", message: "Bank payout destination verified and synced."};
};

/**
 * Mirrors a user's verified Afriex payout destinations into their private payment-method list.
 * It never reads the business-wide payment-method list and never moves or stores customer funds.
 */
export const syncAfriexPayoutMethods = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    const userId = context.auth.uid;
    const request = (data || {}) as SyncAfriexPayoutMethodsRequest;
    const requestedMethodId = trimStringValue(request.paymentMethodId);
    const userRef = db.collection("users").doc(userId);
    const userSnap = await userRef.get();
    if (!userSnap.exists) {
      throw new functions.https.HttpsError("not-found", "User account not found.");
    }
    const userData = await withPrivateUserFields(
      userId,
      (userSnap.data() || {}) as Record<string, unknown>
    );
    const methodsRef = userRef.collection("payment_methods");
    let methods: FirebaseFirestore.QueryDocumentSnapshot[];
    if (requestedMethodId) {
      const methodSnapshot = await methodsRef.doc(requestedMethodId).get();
      methods = methodSnapshot.exists ?
        [methodSnapshot as FirebaseFirestore.QueryDocumentSnapshot] :
        [];
    } else {
      methods = (await methodsRef.get()).docs;
    }
    if (requestedMethodId && methods.length === 0) {
      throw new functions.https.HttpsError("not-found", "Payment method not found.");
    }

    const outcomes: AfriexPayoutMethodSyncOutcome[] = [];
    for (const methodDoc of methods) {
      const methodType = normalizeMethodType((methodDoc.data() || {}).type);
      if (methodType !== "MOBILE_MONEY" && methodType !== "BANK") continue;
      try {
        outcomes.push(await syncAfriexPayoutDestinationForSavedMethod({
          userId,
          userData,
          methodDoc,
        }));
      } catch (error) {
        const message = parseProviderErrorMessage(error) || "Provider destination could not be activated yet.";
        await markAfriexPayoutMethodSync({
          methodRef: methodDoc.ref,
          state: "FAILED",
          message,
        });
        outcomes.push({paymentMethodId: methodDoc.id, state: "FAILED", message});
      }
    }

    const syncedCount = outcomes.filter((outcome) => outcome.state === "VERIFIED").length;
    const failedCount = outcomes.filter((outcome) => outcome.state === "FAILED").length;
    const skippedCount = outcomes.filter((outcome) => outcome.state === "SKIPPED").length;
    const firstMessage = outcomes.find((outcome) => outcome.state === "FAILED")?.message ||
      outcomes.find((outcome) => outcome.state === "SKIPPED")?.message ||
      outcomes.find((outcome) => outcome.state === "VERIFIED")?.message ||
      "No Afriex payout methods require syncing.";
    functions.logger.info("syncAfriexPayoutMethods completed", {
      userId,
      requestedMethodId: requestedMethodId || null,
      syncedCount,
      failedCount,
      skippedCount,
    });
    return {
      success: failedCount === 0,
      syncedCount,
      failedCount,
      skippedCount,
      message: firstMessage,
      methods: outcomes,
    };
  });

interface DeletePaymentMethodRequest {
  paymentMethodId?: unknown;
}

const isStripeMissingResourceError = (error: unknown): boolean => {
  const stripeError = error as Stripe.errors.StripeError | undefined;
  const message = String(stripeError?.message || "").toLowerCase();
  return stripeError?.statusCode === 404 ||
    message.includes("no such") ||
    message.includes("resource_missing");
};

/**
 * Removes a saved method and its local sensitive mirror. Stripe cleanup is best-effort:
 * a missing or old-mode provider object must never stop the user from removing it locally.
 */
export const deletePaymentMethod = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    const userId = context.auth.uid;
    const request = (data || {}) as DeletePaymentMethodRequest;
    const paymentMethodId = trimStringValue(request.paymentMethodId);
    if (!paymentMethodId) {
      throw new functions.https.HttpsError("invalid-argument", "Payment method id is required.");
    }

    const userRef = db.collection("users").doc(userId);
    const methodRef = userRef.collection("payment_methods").doc(paymentMethodId);
    const [methodSnap, userSnap] = await Promise.all([methodRef.get(), userRef.get()]);
    if (!methodSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Payment method not found.");
    }

    const methodData = (methodSnap.data() || {}) as Record<string, unknown>;
    const userData = userSnap.exists ? await withPrivateUserFields(
      userId,
      (userSnap.data() || {}) as Record<string, unknown>
    ) : {};
    const methodType = normalizeMethodType(methodData.type);
    const externalAccountId = asNonEmptyString(
      methodData.externalAccountId,
      methodData.stripeExternalAccountId
    );
    const chargePaymentMethodId = asNonEmptyString(
      methodData.chargePaymentMethodId,
      methodData.stripePaymentMethodId
    );
    const chargeSourceId = asNonEmptyString(methodData.chargeSourceId);
    const chargeCustomerId = asNonEmptyString(
      methodData.chargeCustomerId,
      userData.paymentCustomerId
    );
    const connectAccountIds = [...new Set([
      asNonEmptyString(userData.payoutAccountId),
      asNonEmptyString(userData.stripeAccountId),
    ].filter((value): value is string => !!value))];

    let stripeObjectsRemoved = 0;
    if (externalAccountId) {
      for (const connectAccountId of connectAccountIds) {
        try {
          await getStripe().accounts.deleteExternalAccount(connectAccountId, externalAccountId);
          stripeObjectsRemoved += 1;
          break;
        } catch (error) {
          if (isStripeMissingResourceError(error)) continue;
          functions.logger.warn("Could not remove Stripe Connect external account during payment-method deletion", {
            userId,
            paymentMethodId,
            methodType,
            connectAccountId,
            stripeMessage: (error as Stripe.errors.StripeError | undefined)?.message || null,
          });
          break;
        }
      }
    }

    if (chargePaymentMethodId) {
      try {
        const paymentMethod = await getStripe().paymentMethods.retrieve(chargePaymentMethodId) as Stripe.PaymentMethod;
        const paymentMethodCustomerId = stripePaymentMethodOwnerCustomerId(paymentMethod);
        if (paymentMethodCustomerId && chargeCustomerId === paymentMethodCustomerId) {
          await getStripe().paymentMethods.detach(chargePaymentMethodId);
          stripeObjectsRemoved += 1;
        }
      } catch (error) {
        if (!isStripeMissingResourceError(error)) {
          functions.logger.warn("Could not detach Stripe card during payment-method deletion", {
            userId,
            paymentMethodId,
            methodType,
            stripeMessage: (error as Stripe.errors.StripeError | undefined)?.message || null,
          });
        }
      }
    }

    if (chargeSourceId && chargeCustomerId) {
      try {
        await getStripe().customers.deleteSource(chargeCustomerId, chargeSourceId);
        stripeObjectsRemoved += 1;
      } catch (error) {
        if (!isStripeMissingResourceError(error)) {
          functions.logger.warn("Could not remove Stripe bank source during payment-method deletion", {
            userId,
            paymentMethodId,
            methodType,
            stripeMessage: (error as Stripe.errors.StripeError | undefined)?.message || null,
          });
        }
      }
    }

    const remainingMethods = await userRef.collection("payment_methods").get();
    const remaining = remainingMethods.docs.filter((doc) => doc.id !== paymentMethodId);
    const removedWasDefault = methodData.isDefault === true;
    const anotherDefaultExists = remaining.some((doc) => doc.data().isDefault === true);
    const batch = db.batch();
    batch.delete(methodRef);
    batch.delete(paymentMethodPrivateRef(userId, paymentMethodId));
    if (remaining.length > 0 && (removedWasDefault || !anotherDefaultExists)) {
      batch.set(remaining[0].ref, {
        isDefault: true,
        updatedAt: admin.firestore.Timestamp.now(),
      }, {merge: true});
    }
    await batch.commit();

    functions.logger.info("deletePaymentMethod completed", {
      userId,
      paymentMethodId,
      methodType,
      stripeObjectsRemoved,
      hadAfriexDestination: !!getAfriexDestinationPaymentMethodId(methodData, methodData),
    });
    return {
      success: true,
      stripeObjectsRemoved,
      message: "Payment method removed.",
    };
  });

export const listRecipientPayoutMethods = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const request = (data || {}) as ListRecipientPayoutMethodsRequest;
    const recipientUserId = asNonEmptyString(request.recipientUserId);
    if (!recipientUserId) {
      throw new functions.https.HttpsError("invalid-argument", "Recipient user id is required.");
    }
    if (recipientUserId !== context.auth.uid) {
      await assertUsersAreNotBlocked(context.auth.uid, recipientUserId);
    }

    const limitCandidate = Math.trunc(Number(request.limit || 20));
    const limit = Math.min(60, Math.max(1, Number.isFinite(limitCandidate) ? limitCandidate : 20));
    const fetchLimit = Math.min(120, Math.max(limit, limit * 4));

    const methodsSnap = await db.collection("users").doc(recipientUserId)
      .collection("payment_methods")
      .limit(fetchLimit)
      .get();

    const methodsWithPrivateFields = await Promise.all(methodsSnap.docs.map(async (doc) => ({
      id: doc.id,
      data: await withPrivatePaymentMethodFields(
        recipientUserId,
        doc.id,
        (doc.data() || {}) as Record<string, unknown>
      ),
    })));

    const items = methodsWithPrivateFields
      .flatMap((method) => buildRecipientReceiveMethodSummaries(
        method.id,
        method.data
      ))
      .sort((left, right) => {
        const leftDefault = left["isDefault"] === true ? 1 : 0;
        const rightDefault = right["isDefault"] === true ? 1 : 0;
        if (leftDefault !== rightDefault) {
          return rightDefault - leftDefault;
        }
        const leftLabel = String(left["label"] || left["bankName"] || left["brand"] || "").toLowerCase();
        const rightLabel = String(right["label"] || right["bankName"] || right["brand"] || "").toLowerCase();
        return leftLabel.localeCompare(rightLabel);
      })
      .slice(0, limit);

    return {
      success: true,
      recipientUserId,
      items,
      count: items.length,
    };
  });

