const toMillisTimestamp = (value: unknown): number | null => {
  if (value instanceof admin.firestore.Timestamp) {
    return value.toMillis();
  }
  if (value instanceof Date) {
    return value.getTime();
  }
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }
  return null;
};

const normalizeStatusFilters = (value: unknown): string[] => {
  if (!Array.isArray(value)) return [];
  return [...new Set(
    value
      .map((item) => String(item || "").trim().toUpperCase())
      .filter((item) => item.length > 0)
  )];
};

const humanizeFundingMethodType = (value: unknown): string => {
  const normalized = String(value || "").trim().toUpperCase();
  switch (normalized) {
  case "CARD":
    return "Card";
  case "BANK":
    return "Bank";
  case "MOBILE_MONEY":
    return "Mobile Money";
  default:
    return normalized ?
      normalized
        .toLowerCase()
        .split("_")
        .map((part) => part ? part.charAt(0).toUpperCase() + part.slice(1) : "")
        .join(" ") :
      "Method";
  }
};

const buildAdminPaymentMethodSourceLabel = (
  methodData: FirebaseFirestore.DocumentData | undefined,
  fallbackType: string
): string | null => {
  if (!methodData) {
    return fallbackType ? humanizeFundingMethodType(fallbackType) : null;
  }

  const methodType = asNonEmptyString(methodData.type, methodData.methodType, fallbackType) || "";
  const label = asNonEmptyString(methodData.label);
  const brand = asNonEmptyString(methodData.brand);
  const bankName = asNonEmptyString(methodData.bankName);
  const network = asNonEmptyString(methodData.network);
  const last4 = asNonEmptyString(methodData.last4, methodData.accountLast4);
  const phoneNumber = asNonEmptyString(methodData.phoneNumber, methodData.phone, methodData.mobileNumber);

  switch (methodType.trim().toUpperCase()) {
  case "CARD":
    if (brand && last4) return `${brand} •••• ${last4}`;
    if (label) return label;
    if (last4) return `Card •••• ${last4}`;
    return "Card";
  case "BANK":
    if (bankName && last4) return `${bankName} •••• ${last4}`;
    if (label) return label;
    if (last4) return `Bank •••• ${last4}`;
    return "Bank";
  case "MOBILE_MONEY":
    if (network && phoneNumber) return `${network} (${phoneNumber})`;
    if (label) return label;
    if (phoneNumber) return phoneNumber;
    return "Mobile Money";
  default:
    return label || humanizeFundingMethodType(methodType);
  }
};

const isAdminRoleValue = (value: unknown): boolean => {
  const role = String(value || "").trim().toLowerCase();
  return role === "admin" || role === "owner";
};

const isAssociateRoleValue = (value: unknown): boolean => {
  const role = String(value || "").trim().toLowerCase();
  return role === "associate" || role === "support" || role === "support_associate";
};

const resolveCanonicalRoleFromUserData = (userData: Record<string, unknown> | undefined): string => {
  return asNonEmptyString(
    userData?.role,
    userData?.userRole,
    userData?.userType
  )?.trim().toLowerCase() || "";
};

const normalizeEmailLower = (value: unknown): string =>
  String(value || "").trim().toLowerCase();

const looksLikeEmailAddress = (value: unknown): boolean => {
  const normalized = normalizeEmailLower(value);
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized);
};

const resolveHostedWalletFullName = (
  userData: Record<string, unknown>
): string | null => {
  const candidates = [
    userData.name,
    userData.displayName,
    userData.fullName,
    userData.legalName,
    userData.username,
  ];

  for (const candidate of candidates) {
    const trimmed = asNonEmptyString(candidate)?.trim();
    if (!trimmed) continue;
    if (looksLikeEmailAddress(trimmed)) continue;
    return trimmed;
  }

  return null;
};

const normalizePhoneDigits = (value: unknown): string =>
  String(value || "").replace(/\D/g, "");

const readUserPhone = (userData: Record<string, unknown>): string =>
  String(userData.phoneNumber || userData.phone || "").trim();

const chunkArray = <T>(items: T[], size: number): T[][] => {
  if (size <= 0) return [items];
  const out: T[][] = [];
  for (let index = 0; index < items.length; index += size) {
    out.push(items.slice(index, index + size));
  }
  return out;
};

const EMAIL_VERIFICATION_COLLECTION = "email_verification_codes";
const EMAIL_VERIFICATION_CODE_LENGTH = 6;
const EMAIL_VERIFICATION_TTL_MS = 10 * 60 * 1000;
const EMAIL_VERIFICATION_RESEND_COOLDOWN_MS = 2 * 60 * 1000;
const EMAIL_VERIFICATION_MAX_ATTEMPTS = 5;

const getEmailVerificationConfig = (): {
  provider: string;
  resendApiKey?: string;
  fromEmail?: string;
  codeSecret: string;
} => {
  const provider = String(process.env.EMAIL_VERIFICATION_PROVIDER || "disabled")
    .trim()
    .toLowerCase();
  const resendApiKey = asNonEmptyString(process.env.RESEND_API_KEY);
  const fromEmail = asNonEmptyString(process.env.EMAIL_FROM_ADDRESS, process.env.RESEND_FROM_EMAIL);
  const codeSecret =
    asNonEmptyString(process.env.EMAIL_VERIFICATION_CODE_SECRET) ||
    asNonEmptyString(process.env.ADMIN_PAYOUT_REVERSAL_SECRET) ||
    "volunteersapp-email-verification-default-secret";
  return {
    provider,
    resendApiKey: resendApiKey || undefined,
    fromEmail: fromEmail || undefined,
    codeSecret,
  };
};

const getPasswordResetEmailConfig = (): {
  provider: string;
  resendApiKey?: string;
  fromEmail?: string;
  appName: string;
} => {
  const resendApiKey = asNonEmptyString(process.env.RESEND_API_KEY);
  const fromEmail = asNonEmptyString(
    process.env.PASSWORD_RESET_FROM_EMAIL,
    process.env.EMAIL_FROM_ADDRESS,
    process.env.RESEND_FROM_EMAIL
  );
  const explicitProvider = asNonEmptyString(
    process.env.PASSWORD_RESET_EMAIL_PROVIDER,
    process.env.EMAIL_VERIFICATION_PROVIDER
  );
  const provider = explicitProvider ?
    explicitProvider.trim().toLowerCase() :
    (resendApiKey && fromEmail ? "resend" : "disabled");

  return {
    provider,
    resendApiKey: resendApiKey || undefined,
    fromEmail: fromEmail || undefined,
    appName: asNonEmptyString(process.env.PASSWORD_RESET_APP_NAME, "VolunteersApp") || "VolunteersApp",
  };
};

const normalizeHostName = (value: unknown): string =>
  String(value || "")
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/\/.*$/, "");

const getExpectedPasswordResetHosts = (): string[] => {
  const projectId = asNonEmptyString(
    process.env.GCLOUD_PROJECT,
    admin.app().options.projectId
  );
  const configuredHosts = String(process.env.PASSWORD_RESET_EXPECTED_HOSTS || "")
    .split(",")
    .map((entry) => normalizeHostName(entry))
    .filter(Boolean);
  const defaultHosts = projectId ? [
    `${projectId}.firebaseapp.com`,
    `${projectId}.web.app`,
  ] : [];
  return Array.from(new Set([...configuredHosts, ...defaultHosts]));
};

const maskEmailAddress = (email: string): string => {
  const normalized = String(email || "").trim().toLowerCase();
  const atIndex = normalized.indexOf("@");
  if (atIndex <= 0) return "***";
  const local = normalized.slice(0, atIndex);
  const domain = normalized.slice(atIndex + 1);
  const maskedLocal = local.length <= 2 ?
    `${local.charAt(0)}*` :
    `${local.slice(0, 2)}${"*".repeat(Math.max(local.length - 2, 2))}`;
  return `${maskedLocal}@${domain}`;
};

const generateSixDigitEmailVerificationCode = (): string =>
  String(randomInt(0, 10 ** EMAIL_VERIFICATION_CODE_LENGTH)).padStart(EMAIL_VERIFICATION_CODE_LENGTH, "0");

const hashEmailVerificationCode = (params: {
  uid: string;
  email: string;
  code: string;
}): string => {
  const config = getEmailVerificationConfig();
  const payload = `${params.uid}:${params.email.trim().toLowerCase()}:${params.code}:${config.codeSecret}`;
  return createHash("sha256").update(payload).digest("hex");
};

const sendEmailVerificationCodeMessage = async (params: {
  toEmail: string;
  code: string;
  expiresInMinutes: number;
}): Promise<void> => {
  const config = getEmailVerificationConfig();
  const toEmail = params.toEmail.trim().toLowerCase();
  if (!toEmail) {
    throw new functions.https.HttpsError("failed-precondition", "User email is missing.");
  }

  if (config.provider === "resend") {
    if (!config.resendApiKey || !config.fromEmail) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Resend email provider is enabled but RESEND_API_KEY or EMAIL_FROM_ADDRESS is missing."
      );
    }

    const subject = "Your VolunteersApp verification code";
    const text = `Your verification code is ${params.code}. It expires in ${params.expiresInMinutes} minutes.`;
    const html = `<p>Your verification code is <strong style="font-size:20px;letter-spacing:2px;">${params.code}</strong>.</p>
<p>This code expires in ${params.expiresInMinutes} minutes.</p>`;

    await axios.post(
      "https://api.resend.com/emails",
      {
        from: config.fromEmail,
        to: [toEmail],
        subject,
        text,
        html,
      },
      {
        timeout: 15000,
        headers: {
          "Authorization": `Bearer ${config.resendApiKey}`,
          "Content-Type": "application/json",
        },
      }
    );
    return;
  }

  throw new functions.https.HttpsError(
    "failed-precondition",
    "EMAIL_VERIFICATION_PROVIDER is not configured for 6-digit email codes. Set EMAIL_VERIFICATION_PROVIDER=resend."
  );
};

const escapeHtmlAttribute = (value: string): string =>
  String(value)
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

const sendPasswordResetLinkMessage = async (params: {
  toEmail: string;
  resetLink: string;
}): Promise<void> => {
  const config = getPasswordResetEmailConfig();
  const toEmail = normalizeEmailLower(params.toEmail);
  if (!toEmail) {
    throw new functions.https.HttpsError("failed-precondition", "User email is missing.");
  }

  if (config.provider === "resend") {
    if (!config.resendApiKey || !config.fromEmail) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Resend password reset email is enabled but RESEND_API_KEY or EMAIL_FROM_ADDRESS is missing."
      );
    }

    const safeHref = escapeHtmlAttribute(params.resetLink);
    const subject = `Reset your ${config.appName} password`;
    const text = [
      `We received a request to reset your ${config.appName} password.`,
      "",
      `Open this secure link to choose a new password:`,
      params.resetLink,
      "",
      "If the button does not open, copy and paste the full URL into your browser.",
      "Requesting another reset replaces this link — use only the newest email.",
      "If you did not request this reset, you can ignore this email.",
    ].join("\n");
    // Single <a href> per message: some mail scanners prefetch every link; a second identical
    // <a> increased the chance the one-time Firebase code was consumed before the user clicked.
    const html = `<p>We received a request to reset your <strong>${config.appName}</strong> password.</p>
<p><a href="${safeHref}" style="display:inline-block;padding:12px 18px;background:#0b63f6;color:#ffffff;text-decoration:none;border-radius:10px;font-weight:600;">Reset Password</a></p>
<p style="word-break:break-all;">If the button does not open, copy and paste this secure link into your browser:<br><span style="font-family:ui-monospace,Menlo,monospace;font-size:12px;">${safeHref}</span></p>
<p style="font-size:13px;color:#555;">Requesting another reset replaces this link — use only the newest email.</p>
<p>If you did not request this reset, you can ignore this email.</p>`;

    await axios.post(
      "https://api.resend.com/emails",
      {
        from: config.fromEmail,
        to: [toEmail],
        subject,
        text,
        html,
      },
      {
        timeout: 15000,
        headers: {
          "Authorization": `Bearer ${config.resendApiKey}`,
          "Content-Type": "application/json",
        },
      }
    );
    return;
  }

  throw new functions.https.HttpsError(
    "failed-precondition",
    "Password reset email provider is not configured. Set PASSWORD_RESET_EMAIL_PROVIDER=resend and configure RESEND_API_KEY / EMAIL_FROM_ADDRESS."
  );
};

const requestEmailVerificationCodeCore = async (uid: string): Promise<{
  success: boolean;
  alreadyVerified: boolean;
  cooldownSeconds: number;
  expiresInSeconds: number;
  maskedEmail: string;
}> => {
  const authUser = await admin.auth().getUser(uid);
  const email = asNonEmptyString(authUser.email);
  if (!email) {
    throw new functions.https.HttpsError("failed-precondition", "Your account email is missing.");
  }

  if (authUser.emailVerified) {
    const now = admin.firestore.Timestamp.now();
    await db.collection("users").doc(uid).set({
      emailVerified: true,
      emailVerifiedAt: now,
      updatedAt: now,
    }, {merge: true});
    return {
      success: true,
      alreadyVerified: true,
      cooldownSeconds: 0,
      expiresInSeconds: Math.trunc(EMAIL_VERIFICATION_TTL_MS / 1000),
      maskedEmail: maskEmailAddress(email),
    };
  }

  const codeRef = db.collection(EMAIL_VERIFICATION_COLLECTION).doc(uid);
  const nowMs = Date.now();
  const codeSnap = await codeRef.get();
  if (codeSnap.exists) {
    const existing = (codeSnap.data() || {}) as Record<string, unknown>;
    const sentAtMs = toMillisTimestamp(existing.sentAt) || Number(existing.sentAtMs || 0);
    if (sentAtMs > 0) {
      const elapsedMs = nowMs - sentAtMs;
      const remainingMs = EMAIL_VERIFICATION_RESEND_COOLDOWN_MS - elapsedMs;
      if (remainingMs > 0) {
        const cooldownSeconds = Math.max(1, Math.ceil(remainingMs / 1000));
        throw new functions.https.HttpsError(
          "failed-precondition",
          `Please wait ${cooldownSeconds}s before requesting another code.`,
          {cooldownSeconds}
        );
      }
    }
  }

  const code = generateSixDigitEmailVerificationCode();
  const codeHash = hashEmailVerificationCode({uid, email, code});
  const expiresAtMs = nowMs + EMAIL_VERIFICATION_TTL_MS;
  const expiresInMinutes = Math.max(1, Math.ceil(EMAIL_VERIFICATION_TTL_MS / 60000));
  await sendEmailVerificationCodeMessage({
    toEmail: email,
    code,
    expiresInMinutes,
  });

  const now = admin.firestore.Timestamp.now();
  const expiresAt = admin.firestore.Timestamp.fromMillis(expiresAtMs);
  await codeRef.set({
    uid,
    email: email.trim().toLowerCase(),
    codeHash,
    status: "SENT",
    attempts: 0,
    maxAttempts: EMAIL_VERIFICATION_MAX_ATTEMPTS,
    sentAt: now,
    sentAtMs: nowMs,
    expiresAt,
    expiresAtMs,
    updatedAt: now,
  }, {merge: true});

  await db.collection("users").doc(uid).set({
    verificationEmailLastSentAtMs: nowMs,
    updatedAt: now,
  }, {merge: true});

  return {
    success: true,
    alreadyVerified: false,
    cooldownSeconds: Math.trunc(EMAIL_VERIFICATION_RESEND_COOLDOWN_MS / 1000),
    expiresInSeconds: Math.trunc(EMAIL_VERIFICATION_TTL_MS / 1000),
    maskedEmail: maskEmailAddress(email),
  };
};

const assertSupportCallableAccess = async (
  context: functions.https.CallableContext
): Promise<{uid: string; isAdmin: boolean; role: string}> => {
  if (!context.auth?.uid) {
    throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
  }

  const uid = context.auth.uid;
  const ownerUserId = getAppConfig().ownerUserId;
  const userSnap = await db.collection("users").doc(uid).get();
  const mergedUserData = await withPrivateUserFields(uid, (userSnap.data() || {}) as Record<string, unknown>);
  const userRole = resolveCanonicalRoleFromUserData(mergedUserData) ||
    normalizeRoleForFeePolicy(context.auth.token?.role);
  const hasAdminClaim = context.auth.token?.admin === true || isAdminRoleValue(context.auth.token?.role);
  if (hasAdminClaim || isAdminRoleValue(userRole) || (ownerUserId && uid === ownerUserId)) {
    if (userRole !== "owner") {
      assertActiveStaffAccessForRole("admin", mergedUserData);
    }
    return {uid, isAdmin: true, role: userRole === "owner" ? "owner" : "admin"};
  }
  if (isAssociateRoleValue(userRole) || isAssociateRoleValue(context.auth.token?.role)) {
    assertActiveStaffAccessForRole(userRole || normalizeRoleForFeePolicy(context.auth.token?.role), mergedUserData);
    return {uid, isAdmin: false, role: String(userRole || context.auth.token?.role || "associate")};
  }

  throw new functions.https.HttpsError("permission-denied", "Support access required.");
};

const assertOwnerOrAdminCallableAccess = async (context: functions.https.CallableContext): Promise<string> => {
  if (!context.auth?.uid) {
    throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
  }

  const callerUid = context.auth.uid;
  const ownerUserId = getAppConfig().ownerUserId;
  const callerTokenRole = String(context.auth.token?.role || "").trim().toLowerCase();
  const callerSnap = await db.collection("users").doc(callerUid).get();
  const mergedUserData = await withPrivateUserFields(
    callerUid,
    (callerSnap.data() || {}) as Record<string, unknown>
  );
  const callerRole = resolveCanonicalRoleFromUserData(mergedUserData) ||
    normalizeRoleForFeePolicy(context.auth.token?.role);
  const isOwnerCaller =
    context.auth.token?.owner === true ||
    callerTokenRole === "owner" ||
    callerRole === "owner" ||
    (ownerUserId ? callerUid === ownerUserId : false);

  if (isOwnerCaller) {
    return callerUid;
  }

  const isAdminCaller =
    context.auth.token?.admin === true ||
    isAdminRoleValue(callerTokenRole) ||
    isAdminRoleValue(callerRole);
  if (isAdminCaller) {
    assertActiveStaffAccessForRole("admin", mergedUserData);
    return callerUid;
  }

  throw new functions.https.HttpsError("permission-denied", "Owner or admin access required.");
};

const assertOwnerCallableAccess = async (context: functions.https.CallableContext): Promise<string> => {
  if (!context.auth?.uid) {
    throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
  }

  const callerUid = context.auth.uid;
  const ownerUserId = getAppConfig().ownerUserId;
  const callerTokenRole = String(context.auth.token?.role || "").trim().toLowerCase();
  let isOwnerCaller =
    context.auth.token?.owner === true ||
    callerTokenRole === "owner" ||
    (ownerUserId ? callerUid === ownerUserId : false);

  if (!isOwnerCaller) {
    const callerSnap = await db.collection("users").doc(callerUid).get();
    const callerRole = resolveCanonicalRoleFromUserData(
      (callerSnap.data() || {}) as Record<string, unknown>
    );
    isOwnerCaller = callerRole === "owner" || (ownerUserId ? callerUid === ownerUserId : false);
  }

  if (!isOwnerCaller) {
    throw new functions.https.HttpsError("permission-denied", "Owner access required.");
  }

  return callerUid;
};

const assertActiveStaffAccessForRole = (
  role: string,
  userData: Record<string, unknown>
): void => {
  if (!STAFF_FREE_ROLES.has(role)) {
    return;
  }
  if (!isStaffOnboardingActive(userData.staffOnboardingStatus) || !isProfileOperational(userData.profileStatus)) {
    throw new functions.https.HttpsError(
      "permission-denied",
      "This staff account is currently inactive."
    );
  }
};

const resolveFallbackRoleForFormerStaff = async (
  uid: string,
  userData: Record<string, unknown>
): Promise<string> => {
  const storedRole = resolveNonStaffRoleFromUserData(userData);
  if (storedRole) {
    return storedRole;
  }
  const [organizerSnap, employerSnap] = await Promise.all([
    db.collection("organizers").doc(uid).get(),
    db.collection("employers").doc(uid).get(),
  ]);
  if (organizerSnap.exists) return "organizer";
  if (employerSnap.exists) return "employer";
  return "volunteer";
};

const canCallerManageStaffRole = (
  callerRole: string,
  callerUid: string,
  targetUid: string,
  targetStaffRole: string
): boolean => {
  if (!targetStaffRole || targetStaffRole === "owner" || callerUid === targetUid) {
    return false;
  }
  if (callerRole === "owner") {
    return STAFF_MANAGEABLE_ROLES.has(targetStaffRole);
  }
  if (callerRole === "admin") {
    return ADMIN_MANAGEABLE_STAFF_ROLES.has(targetStaffRole);
  }
  return false;
};

const normalizeStaffManagementAction = (value: unknown): "activate" | "on_hold" | "disable" | "revoke" => {
  const action = String(value || "").trim().toLowerCase();
  switch (action) {
  case "activate":
  case "active":
  case "resume":
  case "enable":
    return "activate";
  case "on_hold":
  case "hold":
  case "pause":
  case "paused":
    return "on_hold";
  case "disable":
  case "disabled":
    return "disable";
  case "revoke":
  case "remove":
  case "delete":
    return "revoke";
  default:
    throw new functions.https.HttpsError(
      "invalid-argument",
      "Unsupported staff action. Use activate, on_hold, disable, or revoke."
    );
  }
};

const resolveStaffManagementAccess = async (
  context: functions.https.CallableContext
): Promise<{uid: string; role: string; isOwner: boolean}> => {
  if (!context.auth?.uid) {
    throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
  }

  const uid = context.auth.uid;
  const ownerUserId = getAppConfig().ownerUserId;
  const userSnap = await db.collection("users").doc(uid).get();
  const mergedUserData = await withPrivateUserFields(uid, (userSnap.data() || {}) as Record<string, unknown>);
  const resolvedRole = resolveCanonicalRoleFromUserData(mergedUserData) ||
    normalizeRoleForFeePolicy(context.auth.token?.role);
  const isOwner = resolvedRole === "owner" || (ownerUserId ? uid === ownerUserId : false) || context.auth.token?.owner === true;
  if (isOwner) {
    return {uid, role: "owner", isOwner: true};
  }
  if (resolvedRole === "admin" || context.auth.token?.admin === true) {
    assertActiveStaffAccessForRole("admin", mergedUserData);
    return {uid, role: "admin", isOwner: false};
  }
  throw new functions.https.HttpsError("permission-denied", "Owner or admin access required.");
};

const buildSupportUserSummary = (doc: FirebaseFirestore.QueryDocumentSnapshot): Record<string, unknown> => {
  const userData = (doc.data() || {}) as Record<string, unknown>;
  const walletDisplay = getVisibleWalletBalanceForAdmin(doc.id, userData);
  return {
    userId: doc.id,
    username: asNonEmptyString(userData.username, userData.name) || "Unknown",
    email: asNonEmptyString(userData.email) || "",
    phone: readUserPhone(userData),
    role: asNonEmptyString(userData.role) || "volunteer",
    walletBalance: walletDisplay.balance,
    walletCurrency: walletDisplay.currency,
    profilePictureUrl: asNonEmptyString(userData.profilePictureUrl, userData.profileImageUrl) || null,
    createdAtMs: toMillisTimestamp(userData.createdAt),
    updatedAtMs: toMillisTimestamp(userData.updatedAt),
  };
};

export const bootstrapOwnerSelf = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const uid = context.auth.uid;
    const callerEmail = normalizeEmailLower(context.auth.token?.email);
    const ownerBootstrapEmail = normalizeEmailLower(getAppConfig().ownerBootstrapEmail);
    if (!ownerBootstrapEmail) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Owner bootstrap is not configured. Set CONFIG_OWNER_BOOTSTRAP_EMAIL."
      );
    }
    if (!callerEmail || callerEmail !== ownerBootstrapEmail) {
      throw new functions.https.HttpsError(
        "permission-denied",
        "This account is not authorized for owner bootstrap."
      );
    }
    if (context.auth.token?.email_verified !== true) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Verify your email before requesting owner access."
      );
    }

    const now = admin.firestore.Timestamp.now();
    const userRef = db.collection("users").doc(uid);
    await setPrivateUserFields(uid, {
      isStaff: true,
      supportAccess: true,
      staffAccessScope: "SUPPORT_CONSOLE",
      staffOnboardingStatus: "ACTIVE",
      ownerBootstrappedAt: now,
      updatedAt: now,
    });
    await userRef.set({
      uid,
      email: callerEmail,
      role: "owner",
      userType: "owner",
      profileStatus: "active",
      updatedAt: now,
    }, {merge: true});

    try {
      const authUser = await admin.auth().getUser(uid);
      const existingClaims = authUser.customClaims || {};
      await admin.auth().setCustomUserClaims(uid, {
        ...existingClaims,
        admin: true,
        owner: true,
        role: "owner",
      });
    } catch (error) {
      functions.logger.warn("Failed to set owner custom claims during bootstrap.", {
        uid,
        error,
      });
    }

    return {
      success: true,
      uid,
      role: "owner",
      email: callerEmail,
      ownerUserId: uid,
      message: "Owner access bootstrapped.",
    };
  });

export const ownerGrantAdminByEmail = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const callerUid = await assertOwnerCallableAccess(context);

    const payload = (data || {}) as {email?: string; targetEmail?: string};
    const targetEmail = normalizeEmailLower(payload.email || payload.targetEmail);
    if (!targetEmail) {
      throw new functions.https.HttpsError("invalid-argument", "Provide a valid email.");
    }

    let targetUid = "";
    const byEmailSnap = await db.collection("users")
      .where("email", "==", targetEmail)
      .limit(1)
      .get();
    if (!byEmailSnap.empty) {
      targetUid = byEmailSnap.docs[0].id;
    } else {
      try {
        const authUser = await admin.auth().getUserByEmail(targetEmail);
        targetUid = authUser.uid;
      } catch {
        // no-op: handled by not-found below
      }
    }

    if (!targetUid) {
      throw new functions.https.HttpsError(
        "not-found",
        "User account not found for the provided email."
      );
    }

    const targetRef = db.collection("users").doc(targetUid);
    const targetSnap = await targetRef.get();
    const targetData = (targetSnap.data() || {}) as Record<string, unknown>;
    const targetRole = String(targetData.role || "").trim().toLowerCase();
    if (targetRole === "owner") {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Owner account role cannot be downgraded to admin."
      );
    }

    const now = admin.firestore.Timestamp.now();
    const previousRole =
      resolveNonStaffRoleFromUserData(targetData) ||
      await resolveFallbackRoleForFormerStaff(targetUid, targetData);
    await setPrivateUserFields(targetUid, {
      isStaff: true,
      supportAccess: true,
      staffAccessScope: staffAccessScopeForRole("admin"),
      staffOnboardingStatus: "ACTIVE",
      staffAssignedRole: "admin",
      staffPreviousRole: previousRole,
      grantedByOwnerId: callerUid,
      grantedAdminAt: now,
      updatedAt: now,
    });
    await targetRef.set({
      email: targetEmail,
      role: "admin",
      userRole: "admin",
      userType: "admin",
      profileStatus: "active",
      updatedAt: now,
    }, {merge: true});

    try {
      const authUser = await admin.auth().getUser(targetUid);
      const existingClaims = (authUser.customClaims || {}) as Record<string, unknown>;
      await admin.auth().setCustomUserClaims(targetUid, buildCustomClaimsForRole(existingClaims, "admin"));
    } catch (error) {
      functions.logger.warn("Failed to set custom claims for owner-granted admin role.", {
        targetUid,
        error,
      });
    }

    const updatedSnap = await targetRef.get();
    const updatedData = (updatedSnap.data() || {}) as Record<string, unknown>;
    return {
      success: true,
      message: "Admin access granted successfully.",
      admin: {
        userId: targetUid,
        email: asNonEmptyString(updatedData.email) || targetEmail,
        role: asNonEmptyString(updatedData.role) || "admin",
        grantedByOwnerId: asNonEmptyString(updatedData.grantedByOwnerId) || callerUid,
        grantedAdminAtMs: toMillisTimestamp(updatedData.grantedAdminAt),
      },
    };
  });

export const ownerSaveFeeSettings = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const callerUid = await assertOwnerCallableAccess(context);

    const payload = (data || {}) as Record<string, unknown>;
    const blindDateFeeUsd = Number(payload.blindDateFeeUsd);
    const agentAuthorizationFeeUsd = Number(payload.agentAuthorizationFeeUsd);
    const adPostFeeUsd = Number(payload.adPostFeeUsd);
    const forexProfitMargin = Number(payload.forexProfitMargin);
    const stripeForexDepositProfitMargin = Number(payload.stripeForexDepositProfitMargin);
    const mobileMoneyHiddenFeeRate = Number(payload.mobileMoneyHiddenFeeRate);
    const existingFeeSnap = await db.collection("app_config").doc("fee_settings").get();
    const existingFee = existingFeeSnap.data() || {};
    let stripeTransactionOwnerFeeRate = Number(
      payload.stripeTransactionOwnerFeeRate ??
      existingFee.stripeTransactionOwnerFeeRate
    );
    if (!Number.isFinite(stripeTransactionOwnerFeeRate)) {
      stripeTransactionOwnerFeeRate = Number.parseFloat(getAppConfig().stripeTransactionOwnerFeeRate);
    }
    const remittanceDefaultBankFeeUsd = Number(payload.remittanceDefaultBankFeeUsd);
    const remittanceDefaultMobileMoneyFeeUsd = Number(payload.remittanceDefaultMobileMoneyFeeUsd);
    const remittanceDefaultSwiftProviderFeeUsd = Number(
      payload.remittanceDefaultSwiftProviderFeeUsd ??
      existingFee.remittanceDefaultSwiftProviderFeeUsd ??
      0
    );
    const remittanceSwiftProviderFeeRate = Number(
      payload.remittanceSwiftProviderFeeRate ??
      existingFee.remittanceSwiftProviderFeeRate ??
      0.0025
    );
    const remittanceDefaultBankTopUpUsd = Number(
      payload.remittanceDefaultBankTopUpUsd ??
      existingFee.remittanceDefaultBankTopUpUsd ??
      0
    );
    const remittanceDefaultMobileMoneyTopUpUsd = Number(
      payload.remittanceDefaultMobileMoneyTopUpUsd ??
      existingFee.remittanceDefaultMobileMoneyTopUpUsd ??
      0
    );
    const remittanceDefaultSwiftTopUpUsd = Number(
      payload.remittanceDefaultSwiftTopUpUsd ??
      existingFee.remittanceDefaultSwiftTopUpUsd ??
      0
    );
    const remittanceSwiftTopUpRate = Number(
      payload.remittanceSwiftTopUpRate ??
      existingFee.remittanceSwiftTopUpRate ??
      0
    );
    const remittanceSwiftFxMargin = Number(
      payload.remittanceSwiftFxMargin ??
      existingFee.remittanceSwiftFxMargin ??
      0
    );
    const eventTicketOwnerFeeRate = Number(payload.eventTicketOwnerFeeRate);
    const marketplacePlatinumFeeRate = Number(payload.marketplacePlatinumFeeRate);
    const garageSaleFeeRate = Number(payload.garageSaleFeeRate);
    const agentCashoutAgentShareRate = Number(
      payload.agentCashoutAgentShareRate ??
      payload.agentCashoutAgentShare
    );
    const agentCashoutOwnerShareRate = Number(
      payload.agentCashoutOwnerShareRate ??
      payload.agentCashoutOwnerShare
    );
    let walletExternalCurrencyChangeFeeRate = Number(
      payload.walletExternalCurrencyChangeFeeRate ??
      payload.wallet_external_currency_change_fee_rate ??
      existingFee.walletExternalCurrencyChangeFeeRate
    );
    if (!Number.isFinite(walletExternalCurrencyChangeFeeRate)) {
      walletExternalCurrencyChangeFeeRate = Number.parseFloat(getAppConfig().walletExternalCurrencyChangeFeeRate);
    }

    const parseCountryFeeMap = (
      raw: unknown
    ): Record<string, number> => {
      if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
        return {};
      }
      const normalized: Record<string, number> = {};
      for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
        const country = String(key || "").trim();
        if (!country) continue;
        const amount = Number(value);
        normalized[country] = amount;
      }
      return normalized;
    };

    const remittanceBankFeesByCountry = parseCountryFeeMap(payload.remittanceBankFeesByCountry);
    const remittanceMobileMoneyFeesByCountry = parseCountryFeeMap(payload.remittanceMobileMoneyFeesByCountry);
    const remittanceBankTopUpByCountry = Object.prototype.hasOwnProperty.call(payload, "remittanceBankTopUpByCountry") ?
      parseCountryFeeMap(payload.remittanceBankTopUpByCountry) :
      parseNonNegativeFeeMap(existingFee.remittanceBankTopUpByCountry, {});
    const remittanceMobileMoneyTopUpByCountry = Object.prototype.hasOwnProperty.call(payload, "remittanceMobileMoneyTopUpByCountry") ?
      parseCountryFeeMap(payload.remittanceMobileMoneyTopUpByCountry) :
      parseNonNegativeFeeMap(existingFee.remittanceMobileMoneyTopUpByCountry, {});
    const parseCountryRateMap = (
      raw: unknown
    ): Record<string, number> => {
      if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
        return {};
      }
      const normalized: Record<string, number> = {};
      for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
        const country = String(key || "").trim();
        if (!country) continue;
        normalized[country] = Number(value);
      }
      return normalized;
    };
    const remittanceBankFxMarginsByCountry = Object.prototype.hasOwnProperty.call(payload, "remittanceBankFxMarginsByCountry") ?
      parseCountryRateMap(payload.remittanceBankFxMarginsByCountry) :
      parseUnitIntervalRateMap(existingFee.remittanceBankFxMarginsByCountry, {});
    const remittanceMobileMoneyFxMarginsByCountry = Object.prototype.hasOwnProperty.call(payload, "remittanceMobileMoneyFxMarginsByCountry") ?
      parseCountryRateMap(payload.remittanceMobileMoneyFxMarginsByCountry) :
      parseUnitIntervalRateMap(existingFee.remittanceMobileMoneyFxMarginsByCountry, {});

    const finite = (n: number) => Number.isFinite(n) && !Number.isNaN(n);
    if (![
      blindDateFeeUsd,
      agentAuthorizationFeeUsd,
      adPostFeeUsd,
      forexProfitMargin,
      stripeForexDepositProfitMargin,
      stripeTransactionOwnerFeeRate,
      mobileMoneyHiddenFeeRate,
      remittanceDefaultBankFeeUsd,
      remittanceDefaultMobileMoneyFeeUsd,
      remittanceDefaultSwiftProviderFeeUsd,
      remittanceSwiftProviderFeeRate,
      remittanceDefaultBankTopUpUsd,
      remittanceDefaultMobileMoneyTopUpUsd,
      remittanceDefaultSwiftTopUpUsd,
      remittanceSwiftTopUpRate,
      remittanceSwiftFxMargin,
      eventTicketOwnerFeeRate,
      marketplacePlatinumFeeRate,
      garageSaleFeeRate,
      agentCashoutAgentShareRate,
      agentCashoutOwnerShareRate,
      walletExternalCurrencyChangeFeeRate,
    ].every(finite)) {
      throw new functions.https.HttpsError("invalid-argument", "All fee fields must be valid numbers.");
    }
    if (
      blindDateFeeUsd < 0 ||
      agentAuthorizationFeeUsd < 0 ||
      adPostFeeUsd < 0 ||
      remittanceDefaultBankFeeUsd < 0 ||
      remittanceDefaultMobileMoneyFeeUsd < 0 ||
      remittanceDefaultSwiftProviderFeeUsd < 0 ||
      remittanceDefaultBankTopUpUsd < 0 ||
      remittanceDefaultMobileMoneyTopUpUsd < 0 ||
      remittanceDefaultSwiftTopUpUsd < 0
    ) {
      throw new functions.https.HttpsError("invalid-argument", "USD fee values cannot be negative.");
    }
    if (
      Object.values(remittanceBankFeesByCountry).some((value) => !finite(value) || value < 0) ||
      Object.values(remittanceMobileMoneyFeesByCountry).some((value) => !finite(value) || value < 0) ||
      Object.values(remittanceBankTopUpByCountry).some((value) => !finite(value) || value < 0) ||
      Object.values(remittanceMobileMoneyTopUpByCountry).some((value) => !finite(value) || value < 0)
    ) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Remittance corridor fees must be valid non-negative numbers."
      );
    }
    if (
      Object.values(remittanceBankFxMarginsByCountry).some((value) => !finite(value) || value < 0 || value > 1) ||
      Object.values(remittanceMobileMoneyFxMarginsByCountry).some((value) => !finite(value) || value < 0 || value > 1)
    ) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Remittance corridor FX margins must be between 0 and 1."
      );
    }
    const inZeroOne = (n: number) => n >= 0 && n <= 1;
    if (
      !inZeroOne(forexProfitMargin) ||
      !inZeroOne(stripeForexDepositProfitMargin) ||
      !inZeroOne(stripeTransactionOwnerFeeRate) ||
      !inZeroOne(mobileMoneyHiddenFeeRate) ||
      !inZeroOne(remittanceSwiftProviderFeeRate) ||
      !inZeroOne(remittanceSwiftTopUpRate) ||
      !inZeroOne(remittanceSwiftFxMargin) ||
      !inZeroOne(eventTicketOwnerFeeRate) ||
      !inZeroOne(marketplacePlatinumFeeRate) ||
      !inZeroOne(garageSaleFeeRate) ||
      !inZeroOne(agentCashoutAgentShareRate) ||
      !inZeroOne(agentCashoutOwnerShareRate) ||
      !inZeroOne(walletExternalCurrencyChangeFeeRate)
    ) {
      throw new functions.https.HttpsError("invalid-argument", "Margin and fee-rate values must be between 0 and 1.");
    }
    if (Math.abs((agentCashoutAgentShareRate + agentCashoutOwnerShareRate) - 1) > 0.000001) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Agent cash-out split must add up to 1.0 (for example 0.70 and 0.30)."
      );
    }

    const now = admin.firestore.Timestamp.now();
    blindDateFeeSettingsCache = null;
    remittanceFeeSettingsCache = null;
    projectFeeSettingsCache = null;

    await db.collection("app_config").doc("fee_settings").set({
      blindDateFeeUsd,
      agentAuthorizationFeeUsd,
      adPostFeeUsd,
      sponsoredAdFeeUsd: adPostFeeUsd,
      forexProfitMargin,
      stripeForexDepositProfitMargin,
      stripeTransactionOwnerFeeRate,
      mobileMoneyHiddenFeeRate,
      remittanceDefaultBankFeeUsd,
      remittanceDefaultMobileMoneyFeeUsd,
      remittanceDefaultSwiftProviderFeeUsd,
      remittanceSwiftProviderFeeRate,
      remittanceDefaultBankTopUpUsd,
      remittanceDefaultMobileMoneyTopUpUsd,
      remittanceDefaultSwiftTopUpUsd,
      remittanceSwiftTopUpRate,
      remittanceSwiftFxMargin,
      remittanceBankFeesByCountry,
      remittanceMobileMoneyFeesByCountry,
      remittanceBankTopUpByCountry,
      remittanceMobileMoneyTopUpByCountry,
      remittanceBankFxMarginsByCountry,
      remittanceMobileMoneyFxMarginsByCountry,
      eventTicketOwnerFeeRate,
      marketplacePlatinumFeeRate,
      garageSaleFeeRate,
      agentCashoutAgentShareRate,
      agentCashoutOwnerShareRate,
      walletExternalCurrencyChangeFeeRate,
      updatedAt: now,
      updatedByOwnerId: callerUid,
    }, {merge: true});

    return {success: true, message: "Fee settings saved."};
  });

// Customer previews must not expose the private fee settings document, which
// also contains provider costs, route margins, and owner-only fee splits.
export const getPublicCommerceFeeSettings = functions
  .runWith({enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }

    const feeSnap = await db.collection("app_config").doc("fee_settings").get();
    const feeData = (feeSnap.data() || {}) as Record<string, unknown>;
    const blindDateFee = Number(
      feeData.blindDateFeeUsd ??
      feeData.blindDateFee ??
      getAppConfig().blindDateFee
    );

    return {
      blindDateFeeUsd: Number.isFinite(blindDateFee) && blindDateFee >= 0 ?
        roundMoney(blindDateFee) :
        0,
      sponsoredAdListingFeeUsd: pickAdListingFeeUsd(feeSnap),
      garageSalePlatformFeeRate: pickGarageSaleFeeRate(feeData),
      marketplacePlatinumFeeRate: pickMarketplacePlatinumFeeRate(feeData),
    };
  });

export const ownerSaveSystemConfig = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const callerUid = await assertOwnerCallableAccess(context);

    const payload = (data || {}) as Record<string, unknown>;
    const maintenanceMode = payload.maintenanceMode === true;
    const allowNewSignups = payload.allowNewSignups !== false;
    const enableBlindDate = payload.enableBlindDate !== false;
    const enableLiveStreams = payload.enableLiveStreams !== false;
    const maxUploadMbRaw = Number(payload.maxUploadMb);
    const maxUploadMb = Number.isFinite(maxUploadMbRaw) ? Math.trunc(maxUploadMbRaw) : NaN;
    if (!Number.isFinite(maxUploadMb) || Number.isNaN(maxUploadMb)) {
      throw new functions.https.HttpsError("invalid-argument", "Max upload must be a whole number.");
    }
    if (maxUploadMb < 1 || maxUploadMb > 2048) {
      throw new functions.https.HttpsError("invalid-argument", "Max upload must be between 1 MB and 2048 MB.");
    }

    const now = admin.firestore.Timestamp.now();
    await db.collection("app_config").doc("system_config").set({
      maintenanceMode,
      allowNewSignups,
      enableBlindDate,
      enableLiveStreams,
      maxUploadMb,
      updatedAt: now,
      updatedByOwnerId: callerUid,
    }, {merge: true});

    return {success: true, message: "System config saved."};
  });

export const adminAddSupportAssociate = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const adminUid = await assertAdminCallableAccess(context);
    const payload = (data || {}) as AdminAddAssociatePayload;
    const associateUid = asNonEmptyString(payload.associateUid);
    const associateEmail = normalizeEmailLower(payload.associateEmail);
    if (!associateUid && !associateEmail) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Provide associateEmail or associateUid."
      );
    }

    let targetUid = associateUid || "";
    if (!targetUid && associateEmail) {
      const byEmailSnap = await db.collection("users")
        .where("email", "==", associateEmail)
        .limit(1)
        .get();
      if (!byEmailSnap.empty) {
        targetUid = byEmailSnap.docs[0].id;
      } else {
        try {
          const authUser = await admin.auth().getUserByEmail(associateEmail);
          targetUid = authUser.uid;
        } catch {
          // no-op: handled by not-found below
        }
      }
    }

    if (!targetUid) {
      throw new functions.https.HttpsError("not-found", "Associate account not found for the provided email.");
    }

    const targetRef = db.collection("users").doc(targetUid);
    const targetSnap = await targetRef.get();
    const targetData = (targetSnap.data() || {}) as Record<string, unknown>;
    const existingRole = String(targetData.role || "").trim().toLowerCase();
    if (isAdminRoleValue(existingRole)) {
      throw new functions.https.HttpsError("failed-precondition", "Target account already has admin-level access.");
    }

    const now = admin.firestore.Timestamp.now();
    const previousRole =
      resolveNonStaffRoleFromUserData(targetData) ||
      await resolveFallbackRoleForFormerStaff(targetUid, targetData);
    await setPrivateUserFields(targetUid, {
      isStaff: true,
      supportAccess: true,
      staffAccessScope: staffAccessScopeForRole("associate"),
      staffOnboardingStatus: "ACTIVE",
      staffAssignedRole: "associate",
      staffPreviousRole: previousRole,
      supportNote: asNonEmptyString(payload.note) || null,
      supportGrantedAt: now,
      supportGrantedBy: adminUid,
      updatedAt: now,
    });
    await targetRef.set({
      email: associateEmail || targetData.email || null,
      role: "associate",
      userRole: "associate",
      userType: "associate",
      profileStatus: "active",
      updatedAt: now,
    }, {merge: true});

    try {
      const authUser = await admin.auth().getUser(targetUid);
      const existingClaims = (authUser.customClaims || {}) as Record<string, unknown>;
      await admin.auth().setCustomUserClaims(targetUid, buildCustomClaimsForRole(existingClaims, "associate"));
    } catch (error) {
      functions.logger.warn("Failed to set custom claims for associate role.", {
        targetUid,
        error,
      });
    }

    const updatedSnap = await targetRef.get();
    const updatedData = (updatedSnap.data() || {}) as Record<string, unknown>;
    return {
      success: true,
      message: "Associate access granted successfully.",
      associate: {
        userId: targetUid,
        username: asNonEmptyString(updatedData.username, updatedData.name) || "Unknown",
        email: asNonEmptyString(updatedData.email) || associateEmail || "",
        role: asNonEmptyString(updatedData.role) || "associate",
        supportGrantedAtMs: toMillisTimestamp(updatedData.supportGrantedAt),
      },
    };
  });

export const adminListStaffAccounts = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const access = await resolveStaffManagementAccess(context);
    const payload = (data || {}) as AdminListStaffAccountsPayload;
    const parsedLimit = Number(payload.limit);
    const limit = Math.min(Math.max(Number.isFinite(parsedLimit) ? Math.trunc(parsedLimit) : 120, 1), 250);
    const query = String(payload.query || "").trim().toLowerCase();
    const fetchLimit = query ? Math.min(limit * 3, 250) : limit;

    const [privateStaffSnap, legacyRoleSnap] = await Promise.all([
      db.collection(USER_PRIVATE_COLLECTION)
        .where("isStaff", "==", true)
        .limit(fetchLimit)
        .get(),
      db.collection("users")
        .where("role", "in", Array.from(STAFF_MANAGEABLE_ROLES))
        .limit(fetchLimit)
        .get(),
    ]);

    const rootDocsById = new Map<string, FirebaseFirestore.DocumentSnapshot>();
    for (const doc of legacyRoleSnap.docs) {
      rootDocsById.set(doc.id, doc);
    }

    const staffUserIds = new Set<string>();
    for (const doc of privateStaffSnap.docs) {
      staffUserIds.add(doc.id);
    }
    for (const doc of legacyRoleSnap.docs) {
      staffUserIds.add(doc.id);
    }

    const missingRootIds = Array.from(staffUserIds).filter((uid) => !rootDocsById.has(uid));
    for (const chunk of chunkArray(missingRootIds, 30)) {
      const rootSnap = await db.collection("users")
        .where(admin.firestore.FieldPath.documentId(), "in", chunk)
        .get();
      for (const doc of rootSnap.docs) {
        rootDocsById.set(doc.id, doc);
      }
    }

    const items: Record<string, unknown>[] = [];
    for (const uid of staffUserIds) {
      const rootDoc = rootDocsById.get(uid);
      if (!rootDoc?.exists) {
        continue;
      }
      const rootData = (rootDoc.data() || {}) as Record<string, unknown>;
      const mergedUserData = await withPrivateUserFields(uid, rootData);
      const staffRole = resolveStaffAssignedRoleFromUserData(mergedUserData);
      if (!staffRole) {
        continue;
      }

      const username = asNonEmptyString(rootData.username, rootData.name) || "Unknown";
      const email = asNonEmptyString(rootData.email) || "";
      const phone = readUserPhone(rootData);
      const profileStatus = asNonEmptyString(rootData.profileStatus) || "active";
      const onboardingStatus = asNonEmptyString(mergedUserData.staffOnboardingStatus)?.toUpperCase() || "ACTIVE";
      const supportAccess = mergedUserData.supportAccess === true;
      const currentRole = resolveCanonicalRoleFromUserData(rootData) || "volunteer";
      const walletDisplay = getVisibleWalletBalanceForAdmin(uid, rootData);

      if (query) {
        const haystack = [
          username.toLowerCase(),
          email.toLowerCase(),
          phone.toLowerCase(),
          staffRole,
          onboardingStatus.toLowerCase(),
          profileStatus.toLowerCase(),
          currentRole.toLowerCase(),
        ].join(" ");
        if (!haystack.includes(query)) {
          continue;
        }
      }

      items.push({
        userId: uid,
        username,
        email,
        phone,
        staffRole,
        currentRole,
        profileStatus,
        staffOnboardingStatus: onboardingStatus,
        supportAccess,
        staffAccessScope: asNonEmptyString(mergedUserData.staffAccessScope) || staffAccessScopeForRole(staffRole),
        walletBalance: walletDisplay.balance,
        walletCurrency: walletDisplay.currency,
        canManage: canCallerManageStaffRole(access.role, access.uid, uid, staffRole),
      });
    }

    items.sort((lhs, rhs) => {
      const lRole = String(lhs.staffRole || "");
      const rRole = String(rhs.staffRole || "");
      if (lRole !== rRole) return lRole.localeCompare(rRole);
      return String(lhs.username || "").localeCompare(String(rhs.username || ""));
    });

    return {
      requestedBy: access.uid,
      role: access.role,
      items: items.slice(0, limit),
    };
  });

export const adminUpdateStaffAccountStatus = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const access = await resolveStaffManagementAccess(context);
    const payload = (data || {}) as AdminUpdateStaffAccountStatusPayload;
    const targetUid = asNonEmptyString(payload.userId);
    if (!targetUid) {
      throw new functions.https.HttpsError("invalid-argument", "Missing userId.");
    }

    const action = normalizeStaffManagementAction(payload.action);
    const targetRef = db.collection("users").doc(targetUid);
    const targetSnap = await targetRef.get();
    if (!targetSnap.exists) {
      throw new functions.https.HttpsError("not-found", "Staff account not found.");
    }

    const rootData = (targetSnap.data() || {}) as Record<string, unknown>;
    const mergedUserData = await withPrivateUserFields(targetUid, rootData);
    const staffRole = resolveStaffAssignedRoleFromUserData(mergedUserData);
    if (!staffRole) {
      throw new functions.https.HttpsError("failed-precondition", "Target user is not a managed staff account.");
    }
    if (!canCallerManageStaffRole(access.role, access.uid, targetUid, staffRole)) {
      throw new functions.https.HttpsError(
        "permission-denied",
        "You can only manage lower-level staff accounts."
      );
    }

    const fallbackRole = await resolveFallbackRoleForFormerStaff(targetUid, mergedUserData);
    const now = admin.firestore.Timestamp.now();

    let nextRole = fallbackRole;
    let nextProfileStatus = "active";
    let nextStaffStatus = "REVOKED";
    let nextSupportAccess = false;
    let nextIsStaff = true;

    switch (action) {
    case "activate":
      nextRole = staffRole;
      nextProfileStatus = "active";
      nextStaffStatus = "ACTIVE";
      nextSupportAccess = true;
      break;
    case "on_hold":
      nextRole = fallbackRole;
      nextProfileStatus = "on_hold";
      nextStaffStatus = "ON_HOLD";
      nextSupportAccess = false;
      break;
    case "disable":
      nextRole = fallbackRole;
      nextProfileStatus = "disabled";
      nextStaffStatus = "DISABLED";
      nextSupportAccess = false;
      break;
    case "revoke":
      nextRole = fallbackRole;
      nextProfileStatus = "active";
      nextStaffStatus = "REVOKED";
      nextSupportAccess = false;
      nextIsStaff = true;
      break;
    }

    await setPrivateUserFields(targetUid, {
      isStaff: nextIsStaff,
      supportAccess: nextSupportAccess,
      staffAccessScope: staffAccessScopeForRole(staffRole),
      staffOnboardingStatus: nextStaffStatus,
      staffAssignedRole: staffRole,
      staffPreviousRole: fallbackRole,
      updatedAt: now,
    });
    await targetRef.set({
      role: nextRole,
      userRole: nextRole,
      userType: nextRole,
      profileStatus: nextProfileStatus,
      updatedAt: now,
    }, {merge: true});

    try {
      const authUser = await admin.auth().getUser(targetUid);
      const existingClaims = (authUser.customClaims || {}) as Record<string, unknown>;
      await admin.auth().setCustomUserClaims(targetUid, buildCustomClaimsForRole(existingClaims, nextRole));
      await admin.auth().updateUser(targetUid, {disabled: action === "disable"});
    } catch (error) {
      functions.logger.warn("Failed to update staff auth state.", {
        targetUid,
        action,
        error,
      });
    }

    const message = (() => {
      switch (action) {
      case "activate":
        return "Staff access restored.";
      case "on_hold":
        return "Staff account placed on hold.";
      case "disable":
        return "Staff account disabled.";
      case "revoke":
        return "Staff access removed.";
      }
    })();

    return {
      success: true,
      message,
      staff: {
        userId: targetUid,
        staffRole,
        currentRole: nextRole,
        profileStatus: nextProfileStatus,
        staffOnboardingStatus: nextStaffStatus,
        supportAccess: nextSupportAccess,
      },
    };
  });

export const supportListUsers = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const access = await assertSupportCallableAccess(context);
    const payload = (data || {}) as SupportListUsersPayload;
    const parsedLimit = Number(payload.limit);
    const limit = Math.min(Math.max(Number.isFinite(parsedLimit) ? Math.trunc(parsedLimit) : 80, 1), 200);
    const cursor = asNonEmptyString(payload.cursor);
    const query = String(payload.query || "").trim();
    const queryLower = query.toLowerCase();
    const queryDigits = normalizePhoneDigits(query);
    const fetchLimit = query ? Math.min(limit * 5, 500) : limit;

    let usersQuery = db.collection("users")
      .orderBy(admin.firestore.FieldPath.documentId())
      .limit(fetchLimit);
    if (cursor) {
      usersQuery = usersQuery.startAfter(cursor);
    }

    const usersSnap = await usersQuery.get();
    let items = usersSnap.docs.map((doc) => buildSupportUserSummary(doc));
    if (query) {
      items = items.filter((item) => {
        const email = normalizeEmailLower(item.email);
        const username = String(item.username || "").toLowerCase();
        const phoneDigits = normalizePhoneDigits(item.phone);
        return email.includes(queryLower) ||
          username.includes(queryLower) ||
          (queryDigits.length > 0 && phoneDigits.includes(queryDigits));
      }).slice(0, limit);
    }

    const nextCursor = usersSnap.docs.length > 0 ?
      usersSnap.docs[usersSnap.docs.length - 1].id :
      null;

    return {
      requestedBy: access.uid,
      isAdmin: access.isAdmin,
      role: access.role,
      items,
      nextCursor,
      hasMore: usersSnap.docs.length === fetchLimit,
    };
  });

export const supportGetUserAccountDetails = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const access = await assertSupportCallableAccess(context);
    const payload = (data || {}) as SupportGetUserAccountPayload;
    const userId = asNonEmptyString(payload.userId);
    if (!userId) {
      throw new functions.https.HttpsError("invalid-argument", "Missing userId.");
    }

    const targetRef = db.collection("users").doc(userId);
    const targetSnap = await targetRef.get();
    if (!targetSnap.exists) {
      throw new functions.https.HttpsError("not-found", "User account not found.");
    }
    const userData = (targetSnap.data() || {}) as Record<string, unknown>;
    const mergedUserData = await withPrivateUserFields(userId, userData);
    const storedEmail = normalizeEmailLower(userData.email);
    const storedPhoneDigits = normalizePhoneDigits(readUserPhone(userData));

    if (!access.isAdmin) {
      const verificationEmail = normalizeEmailLower(payload.verificationEmail);
      const verificationPhoneDigits = normalizePhoneDigits(payload.verificationPhone);
      if (!verificationEmail || !verificationPhoneDigits) {
        throw new functions.https.HttpsError(
          "failed-precondition",
          "Associates must verify both customer email and phone before viewing account details."
        );
      }
      const emailMatches = storedEmail.length > 0 && verificationEmail === storedEmail;
      const phoneMatches = storedPhoneDigits.length > 0 && verificationPhoneDigits === storedPhoneDigits;
      if (!emailMatches || !phoneMatches) {
        throw new functions.https.HttpsError(
          "permission-denied",
          "Verification failed. Customer email/phone do not match the selected account."
        );
      }
    }

    const walletDisplay = getVisibleWalletBalanceForAdmin(targetSnap.id, userData);
    const txSnap = await targetRef.collection("transactions")
      .orderBy("timestamp", "desc")
      .limit(25)
      .get();
    const transactions = txSnap.docs.map((doc) => {
      const tx = (doc.data() || {}) as Record<string, unknown>;
      return {
        transactionId: doc.id,
        title: asNonEmptyString(tx.title) || "Transaction",
        amount: Number(tx.amount || 0),
        type: asNonEmptyString(tx.type) || "UNKNOWN",
        status: asNonEmptyString(tx.status) || "UNKNOWN",
        source: asNonEmptyString(tx.source) || null,
        note: asNonEmptyString(tx.note) || null,
        timestampMs: toMillisTimestamp(tx.timestamp),
      };
    });

    const complaints: Array<Record<string, unknown>> = [];
    if (storedEmail.length > 0) {
      const [reportsSnake, reportsCamel] = await Promise.all([
        db.collection("user_reports").where("reportedUserEmail", "==", storedEmail).limit(25).get(),
        db.collection("userReports").where("reportedUserEmail", "==", storedEmail).limit(25).get(),
      ]);
      const pushReports = (snap: FirebaseFirestore.QuerySnapshot) => {
        for (const doc of snap.docs) {
          const report = (doc.data() || {}) as Record<string, unknown>;
          complaints.push({
            reportId: doc.id,
            reportedUserName: asNonEmptyString(report.reportedUserName) || null,
            reportedUserEmail: asNonEmptyString(report.reportedUserEmail) || null,
            reasonForReport: asNonEmptyString(report.reasonForReport) || asNonEmptyString(report.reason) || "No reason provided.",
            eventName: asNonEmptyString(report.eventName) || null,
            reportingUserId: asNonEmptyString(report.reportingUserId) || null,
            reportingUserDisplayName: asNonEmptyString(report.reportingUserDisplayName) || null,
            timestampMs: toMillisTimestamp(report.timestamp),
          });
        }
      };
      pushReports(reportsSnake);
      pushReports(reportsCamel);
    }

    complaints.sort((a, b) => Number(b.timestampMs || 0) - Number(a.timestampMs || 0));

    return {
      requestedBy: access.uid,
      isAdmin: access.isAdmin,
      role: access.role,
      requiresVerification: !access.isAdmin,
      verified: true,
      user: {
        userId: targetSnap.id,
        username: asNonEmptyString(userData.username, userData.name) || "Unknown",
        email: asNonEmptyString(userData.email) || "",
        phone: readUserPhone(userData),
        role: asNonEmptyString(userData.role) || "volunteer",
        profilePictureUrl: asNonEmptyString(userData.profilePictureUrl, userData.profileImageUrl) || null,
        walletBalance: walletDisplay.balance,
        walletCurrency: walletDisplay.currency,
        payoutAccountId: trimStringValue(mergedUserData.payoutAccountId) ||
          trimStringValue(mergedUserData.stripeAccountId) || null,
        chargesEnabled: userData.chargesEnabled === true,
        payoutsEnabled: userData.payoutsEnabled === true,
        detailsSubmitted: userData.detailsSubmitted === true,
      },
      transactions,
      complaints: complaints.slice(0, 25),
    };
  });

export const requestEmailVerificationCode = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (_data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    return requestEmailVerificationCodeCore(context.auth.uid);
  });

export const requestPasswordResetLink = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, _context) => {
    const payload = (data || {}) as {email?: unknown};
    const email = normalizeEmailLower(payload.email);
    if (!email || !email.includes("@")) {
      throw new functions.https.HttpsError("invalid-argument", "Enter a valid email address.");
    }

    const maskedEmail = maskEmailAddress(email);

    try {
      const resetLink = await admin.auth().generatePasswordResetLink(email);
      await sendPasswordResetLinkMessage({toEmail: email, resetLink});

      let linkHost = "";
      try {
        linkHost = new URL(resetLink).host;
      } catch {
        linkHost = "";
      }
      const expectedHosts = getExpectedPasswordResetHosts();
      const matchesExpectedHost = !!linkHost &&
        (expectedHosts.length === 0 || expectedHosts.includes(normalizeHostName(linkHost)));

      if (!matchesExpectedHost) {
        functions.logger.warn("Password reset link host does not match expected hosts.", {
          maskedEmail,
          linkHost,
          expectedHosts,
        });
      }

      functions.logger.info("Password reset link generated and emailed.", {
        maskedEmail,
        linkHost,
        matchesExpectedHost,
        expectedHosts,
      });
    } catch (error) {
      const authCode = String(
        (error as {code?: unknown})?.code ||
        (error as {errorInfo?: {code?: unknown}})?.errorInfo?.code ||
        ""
      ).trim();
      if (authCode === "auth/user-not-found") {
        functions.logger.info("Password reset requested for unknown email.", {maskedEmail});
      } else {
        functions.logger.error("Password reset link flow failed.", {
          maskedEmail,
          authCode,
          error,
        });
        if (error instanceof functions.https.HttpsError) {
          throw error;
        }
        throw new functions.https.HttpsError(
          "internal",
          "Unable to send password reset email right now."
        );
      }
    }

    return {
      success: true,
      maskedEmail,
    };
  });

export const verifyEmailVerificationCode = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const payload = (data || {}) as {code?: unknown; email?: unknown};
    const rawCode = String(payload.code || "").trim();
    if (!/^\d{6}$/.test(rawCode)) {
      throw new functions.https.HttpsError("invalid-argument", "Code must be exactly 6 digits.");
    }

    let uid = context.auth?.uid || "";
    let authUser: admin.auth.UserRecord;
    const providedEmail = normalizeEmailLower(payload.email);
    if (uid) {
      authUser = await admin.auth().getUser(uid);
    } else {
      if (!providedEmail) {
        throw new functions.https.HttpsError(
          "invalid-argument",
          "Email is required when verification session is not active."
        );
      }
      try {
        authUser = await admin.auth().getUserByEmail(providedEmail);
      } catch {
        throw new functions.https.HttpsError("not-found", "No account found for the provided email.");
      }
      uid = authUser.uid;
    }

    const email = asNonEmptyString(authUser.email);
    if (!email) {
      throw new functions.https.HttpsError("failed-precondition", "Your account email is missing.");
    }

    // If the client provided an email, it must match the authenticated account.
    if (providedEmail && normalizeEmailLower(email) !== providedEmail) {
      throw new functions.https.HttpsError(
        "permission-denied",
        "Provided email does not match the signed-in account."
      );
    }

    if (authUser.emailVerified) {
      const now = admin.firestore.Timestamp.now();
      await db.collection("users").doc(uid).set({
        emailVerified: true,
        emailVerifiedAt: now,
        updatedAt: now,
      }, {merge: true});
      return {
        success: true,
        alreadyVerified: true,
      };
    }

    const codeRef = db.collection(EMAIL_VERIFICATION_COLLECTION).doc(uid);
    const codeSnap = await codeRef.get();
    if (!codeSnap.exists) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Verification code not found. Request a new code."
      );
    }

    const codeData = (codeSnap.data() || {}) as Record<string, unknown>;
    const status = String(codeData.status || "SENT").trim().toUpperCase();
    if (status === "VERIFIED") {
      await admin.auth().updateUser(uid, {emailVerified: true});
      const now = admin.firestore.Timestamp.now();
      await db.collection("users").doc(uid).set({
        emailVerified: true,
        emailVerifiedAt: now,
        updatedAt: now,
      }, {merge: true});
      return {
        success: true,
        alreadyVerified: true,
      };
    }

    if (status === "LOCKED") {
      throw new functions.https.HttpsError(
        "permission-denied",
        "Too many invalid attempts. Request a new verification code."
      );
    }

    const nowMs = Date.now();
    const expiresAtMs = toMillisTimestamp(codeData.expiresAt) || Number(codeData.expiresAtMs || 0);
    if (!Number.isFinite(expiresAtMs) || expiresAtMs <= nowMs) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Verification code expired. Request a new code."
      );
    }

    const attempts = Math.max(0, Math.trunc(Number(codeData.attempts || 0)));
    const maxAttempts = Math.max(1, Math.trunc(Number(codeData.maxAttempts || EMAIL_VERIFICATION_MAX_ATTEMPTS)));
    if (attempts >= maxAttempts) {
      await codeRef.set({
        status: "LOCKED",
        updatedAt: admin.firestore.Timestamp.now(),
      }, {merge: true});
      throw new functions.https.HttpsError(
        "permission-denied",
        "Too many invalid attempts. Request a new verification code."
      );
    }

    const storedHash = asNonEmptyString(codeData.codeHash);
    if (!storedHash) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Verification code state is invalid. Request a new code."
      );
    }

    const incomingHash = hashEmailVerificationCode({
      uid,
      email,
      code: rawCode,
    });

    if (incomingHash !== storedHash) {
      const nextAttempts = attempts + 1;
      const remainingAttempts = Math.max(0, maxAttempts - nextAttempts);
      const shouldLock = nextAttempts >= maxAttempts;
      await codeRef.set({
        attempts: nextAttempts,
        status: shouldLock ? "LOCKED" : status,
        lastAttemptAt: admin.firestore.Timestamp.now(),
        updatedAt: admin.firestore.Timestamp.now(),
      }, {merge: true});

      if (shouldLock) {
        throw new functions.https.HttpsError(
          "permission-denied",
          "Too many invalid attempts. Request a new verification code."
        );
      }
      throw new functions.https.HttpsError(
        "permission-denied",
        `Invalid code. ${remainingAttempts} attempt(s) remaining.`
      );
    }

    const now = admin.firestore.Timestamp.now();
    await admin.auth().updateUser(uid, {emailVerified: true});
    await codeRef.set({
      status: "VERIFIED",
      verifiedAt: now,
      verifiedAtMs: nowMs,
      attempts: attempts + 1,
      updatedAt: now,
    }, {merge: true});
    await db.collection("users").doc(uid).set({
      emailVerified: true,
      emailVerifiedAt: now,
      updatedAt: now,
    }, {merge: true});

    return {
      success: true,
      alreadyVerified: false,
    };
  });

export const requestMobileMoneyPhoneOtp = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    const uid = context.auth.uid;
    const payload = (data || {}) as {phoneNumber?: unknown; dialCode?: unknown; purpose?: unknown};
    const phoneE164 = normalizeMobileMoneyPhoneE164(payload.phoneNumber, payload.dialCode);
    const phoneDigits = normalizeDigits(phoneE164);
    const purpose = normalizeMobileMoneyPhoneOtpPurpose(payload.purpose);
    if (phoneDigits.length < 8 || phoneDigits.length > 15) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Provide a valid phone number in international format."
      );
    }
    const matchesAccountPhone = await isAccountPhoneVerificationTarget(uid, phoneDigits);
    if (purpose === "ACCOUNT_PHONE") {
      await assertAccountPhoneVerificationTarget(uid, phoneDigits);
    }

    const otpRef = getMobileMoneyOtpRef(uid, phoneDigits);
    const nowMs = Date.now();
    const now = admin.firestore.Timestamp.now();
    const existingSnap = await otpRef.get();
    if (existingSnap.exists) {
      const existing = (existingSnap.data() || {}) as Record<string, unknown>;
      const status = String(existing.status || "").trim().toUpperCase();
      if (status === "VERIFIED") {
        if (purpose === "ACCOUNT_PHONE" && matchesAccountPhone) {
          await markAccountPhoneVerifiedFromOtp(uid, phoneE164, phoneDigits);
        }
        return {
          success: true,
          alreadyVerified: true,
          message: "This number is already verified for your account.",
          cooldownSeconds: 0,
          expiresInSeconds: Math.trunc(MOBILE_MONEY_PHONE_OTP_TTL_MS / 1000),
          maskedPhone: maskPhoneNumberForOtp(phoneE164),
        };
      }

      const sentAtMs = toMillisTimestamp(existing.sentAt) || Number(existing.sentAtMs || 0);
      if (sentAtMs > 0) {
        const elapsedMs = nowMs - sentAtMs;
        const remainingMs = MOBILE_MONEY_PHONE_OTP_RESEND_COOLDOWN_MS - elapsedMs;
        if (remainingMs > 0) {
          const cooldownSeconds = Math.max(1, Math.ceil(remainingMs / 1000));
          throw new functions.https.HttpsError(
            "failed-precondition",
            `Please wait ${cooldownSeconds}s before requesting another code.`,
            {cooldownSeconds}
          );
        }
      }
    }

    await sendMobileMoneyPhoneOtpCode(phoneE164);

    const expiresAtMs = nowMs + MOBILE_MONEY_PHONE_OTP_TTL_MS;
    await otpRef.set({
      uid,
      phoneNumber: phoneE164,
      phoneDigits,
      status: "SENT",
      attempts: 0,
      maxAttempts: MOBILE_MONEY_PHONE_OTP_MAX_ATTEMPTS,
      purpose,
      sentAt: now,
      sentAtMs: nowMs,
      expiresAt: admin.firestore.Timestamp.fromMillis(expiresAtMs),
      expiresAtMs,
      updatedAt: now,
    }, {merge: true});

    await setPrivateUserFields(uid, {
      mobileMoneyPhoneOtpLastSentPhone: phoneE164,
      mobileMoneyPhoneOtpLastSentPhoneDigits: phoneDigits,
      updatedAt: now,
    });
    await db.collection("users").doc(uid).set({
      mobileMoneyPhoneOtpLastSentAtMs: nowMs,
      updatedAt: now,
    }, {merge: true});

    return {
      success: true,
      alreadyVerified: false,
      message: `Code sent to ${maskPhoneNumberForOtp(phoneE164)}.`,
      cooldownSeconds: Math.trunc(MOBILE_MONEY_PHONE_OTP_RESEND_COOLDOWN_MS / 1000),
      expiresInSeconds: Math.trunc(MOBILE_MONEY_PHONE_OTP_TTL_MS / 1000),
      maskedPhone: maskPhoneNumberForOtp(phoneE164),
    };
  });

export const verifyMobileMoneyPhoneOtp = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    if (!context.auth?.uid) {
      throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
    }
    const payload = (data || {}) as {phoneNumber?: unknown; dialCode?: unknown; code?: unknown; purpose?: unknown};
    const rawCode = String(payload.code || "").trim();
    if (!new RegExp(`^\\d{${MOBILE_MONEY_PHONE_OTP_CODE_LENGTH}}$`).test(rawCode)) {
      throw new functions.https.HttpsError("invalid-argument", "Code must be exactly 6 digits.");
    }

    const uid = context.auth.uid;
    const phoneE164 = normalizeMobileMoneyPhoneE164(payload.phoneNumber, payload.dialCode);
    const phoneDigits = normalizeDigits(phoneE164);
    const purpose = normalizeMobileMoneyPhoneOtpPurpose(payload.purpose);
    if (phoneDigits.length < 8 || phoneDigits.length > 15) {
      throw new functions.https.HttpsError(
        "invalid-argument",
        "Provide a valid phone number in international format."
      );
    }
    const matchesAccountPhone = await isAccountPhoneVerificationTarget(uid, phoneDigits);
    if (purpose === "ACCOUNT_PHONE") {
      await assertAccountPhoneVerificationTarget(uid, phoneDigits);
    }

    const otpRef = getMobileMoneyOtpRef(uid, phoneDigits);
    const otpSnap = await otpRef.get();
    if (!otpSnap.exists) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Verification code not found. Request a new code."
      );
    }

    const otpData = (otpSnap.data() || {}) as Record<string, unknown>;
    const status = String(otpData.status || "SENT").trim().toUpperCase();
    if (status === "VERIFIED") {
      if (purpose === "ACCOUNT_PHONE" && matchesAccountPhone) {
        await markAccountPhoneVerifiedFromOtp(uid, phoneE164, phoneDigits);
      }
      return {
        success: true,
        alreadyVerified: true,
        message: "This number is already verified.",
      };
    }
    if (status === "LOCKED") {
      throw new functions.https.HttpsError(
        "permission-denied",
        "Too many invalid attempts. Request a new verification code."
      );
    }

    const nowMs = Date.now();
    const now = admin.firestore.Timestamp.now();
    const expiresAtMs = toMillisTimestamp(otpData.expiresAt) || Number(otpData.expiresAtMs || 0);
    if (!Number.isFinite(expiresAtMs) || expiresAtMs <= nowMs) {
      throw new functions.https.HttpsError(
        "failed-precondition",
        "Verification code expired. Request a new code."
      );
    }

    const attempts = Math.max(0, Math.trunc(Number(otpData.attempts || 0)));
    const maxAttempts = Math.max(1, Math.trunc(Number(otpData.maxAttempts || MOBILE_MONEY_PHONE_OTP_MAX_ATTEMPTS)));
    if (attempts >= maxAttempts) {
      await otpRef.set({
        status: "LOCKED",
        updatedAt: now,
      }, {merge: true});
      throw new functions.https.HttpsError(
        "permission-denied",
        "Too many invalid attempts. Request a new verification code."
      );
    }

    const verificationResult = await verifyMobileMoneyPhoneOtpCode(phoneE164, rawCode);
    if (!verificationResult.approved) {
      const nextAttempts = attempts + 1;
      const remainingAttempts = Math.max(0, maxAttempts - nextAttempts);
      const shouldLock = nextAttempts >= maxAttempts;
      await otpRef.set({
        attempts: nextAttempts,
        status: shouldLock ? "LOCKED" : "SENT",
        lastAttemptAt: now,
        lastProviderStatus: verificationResult.status,
        updatedAt: now,
      }, {merge: true});

      if (shouldLock) {
        throw new functions.https.HttpsError(
          "permission-denied",
          "Too many invalid attempts. Request a new verification code."
        );
      }
      throw new functions.https.HttpsError(
        "permission-denied",
        `Invalid code. ${remainingAttempts} attempt(s) remaining.`
      );
    }

    await otpRef.set({
      phoneNumber: phoneE164,
      phoneDigits,
      status: "VERIFIED",
      attempts: attempts + 1,
      verifiedAt: now,
      verifiedAtMs: nowMs,
      purpose,
      lastProviderStatus: verificationResult.status,
      updatedAt: now,
    }, {merge: true});
    await setPrivateUserFields(uid, {
      mobileMoneyPhoneOtpVerifiedPhone: phoneE164,
      mobileMoneyPhoneOtpVerifiedPhoneDigits: phoneDigits,
      updatedAt: now,
    });
    await db.collection("users").doc(uid).set({
      mobileMoneyPhoneOtpVerifiedAt: now,
      updatedAt: now,
    }, {merge: true});
    if (purpose === "ACCOUNT_PHONE" && matchesAccountPhone) {
      await markAccountPhoneVerifiedFromOtp(uid, phoneE164, phoneDigits);
    }

    return {
      success: true,
      alreadyVerified: false,
      message: "Phone number verified. You can save this mobile money method.",
      maskedPhone: maskPhoneNumberForOtp(phoneE164),
    };
  });

const isMobileMoneyPayoutType = (value: unknown): boolean => {
  const type = String(value || "").trim().toUpperCase();
  return type === "CASH_OUT" || type === "CASH_IN" || type === "BENEFICIARY_TRANSFER";
};

const assertAdminCallableAccess = async (context: functions.https.CallableContext): Promise<string> => {
  if (!context.auth?.uid) {
    throw new functions.https.HttpsError("unauthenticated", "You must be logged in.");
  }

  const uid = context.auth.uid;
  const ownerUserId = getAppConfig().ownerUserId;
  const userSnap = await db.collection("users").doc(uid).get();
  const mergedUserData = await withPrivateUserFields(uid, (userSnap.data() || {}) as Record<string, unknown>);
  const resolvedRole = resolveCanonicalRoleFromUserData(mergedUserData) ||
    normalizeRoleForFeePolicy(context.auth.token?.role);
  const hasAdminClaim = context.auth.token?.admin === true || isAdminRoleValue(context.auth.token?.role);
  if (resolvedRole === "owner" || (ownerUserId && uid === ownerUserId)) {
    return uid;
  }
  if (hasAdminClaim || isAdminRoleValue(resolvedRole)) {
    assertActiveStaffAccessForRole("admin", mergedUserData);
    return uid;
  }

  throw new functions.https.HttpsError("permission-denied", "Admin access required.");
};

type WalletUsdExchangeRateSnapshot = {
  fromCurrency: string;
  toCurrency: "USD";
  rate: number;
  provider: string;
  fetchedAtMs: number;
  requestUrl: string;
};

const toRecord = (value: unknown): Record<string, unknown> => {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : {};
};

const getWalletUsdMigrationMarker = (userData: Record<string, unknown>): Record<string, unknown> | null => {
  const walletMigration = toRecord(userData.walletMigration);
  const usdOneTime = toRecord(walletMigration.usdOneTime);
  return Object.keys(usdOneTime).length > 0 ? usdOneTime : null;
};

const fetchRawExchangeRateToUsd = async (fromCurrencyRaw: string): Promise<WalletUsdExchangeRateSnapshot> => {
  const fromCurrency = String(fromCurrencyRaw || "USD").trim().toUpperCase();
  if (fromCurrency === "USD") {
    return {
      fromCurrency: "USD",
      toCurrency: "USD",
      rate: 1,
      provider: "IDENTITY",
      fetchedAtMs: Date.now(),
      requestUrl: "local://identity",
    };
  }

  const apiKey = getApiKeys().exchangeRate;
  if (!apiKey) {
    throw new functions.https.HttpsError(
      "failed-precondition",
      "Exchange rate API key is not configured. Set EXCHANGERATE_API_KEY."
    );
  }

  const requestUrl = `https://v6.exchangerate-api.com/v6/${apiKey}/pair/${fromCurrency}/USD`;
  const response = await axios.get(requestUrl, {timeout: 15000});
  const responseData = response.data as {result?: string; conversion_rate?: number};
  const rate = Number(responseData.conversion_rate || 0);
  if (responseData.result !== "success" || !Number.isFinite(rate) || rate <= 0) {
    throw new Error(`Could not fetch exchange rate for ${fromCurrency} -> USD.`);
  }

  return {
    fromCurrency,
    toCurrency: "USD",
    rate,
    provider: "EXCHANGERATE_API_V6",
    fetchedAtMs: Date.now(),
    requestUrl,
  };
};

export const adminMigrateWalletCurrenciesToUsd = functions.runWith({enforceAppCheck: true, timeoutSeconds: 540})
  .https.onCall(async (data, context) => {
    const adminUid = await assertAdminCallableAccess(context);
    const payload = (data || {}) as AdminMigrateWalletsToUsdPayload;

    const dryRun = payload.dryRun !== false;
    const parsedLimit = Number(payload.limit);
    const limit = Math.min(Math.max(Number.isFinite(parsedLimit) ? Math.trunc(parsedLimit) : 100, 1), 300);
    const startAfterUserId = asNonEmptyString(payload.startAfterUserId);
    const runId = asNonEmptyString(payload.runId) || `wallet_usd_migration_${Date.now()}`;
    const explicitUserIds = [...new Set(
      (payload.userIds || [])
        .map((value) => String(value || "").trim())
        .filter((value) => value.length > 0)
    )].slice(0, limit);

    let userDocs: FirebaseFirestore.DocumentSnapshot[] = [];
    let nextCursor: string | null = null;
    if (explicitUserIds.length > 0) {
      userDocs = await Promise.all(
        explicitUserIds.map((userId) => db.collection("users").doc(userId).get())
      );
    } else {
      let usersQuery = db.collection("users")
        .orderBy(admin.firestore.FieldPath.documentId())
        .limit(limit);
      if (startAfterUserId) {
        usersQuery = usersQuery.startAfter(startAfterUserId);
      }
      const usersSnap = await usersQuery.get();
      userDocs = usersSnap.docs;
      nextCursor = usersSnap.docs.length === limit ?
        usersSnap.docs[usersSnap.docs.length - 1].id :
        null;
    }

    const currenciesToFetch = new Set<string>();
    for (const userDoc of userDocs) {
      if (!userDoc.exists) continue;
      const userData = toRecord(userDoc.data());
      const marker = getWalletUsdMigrationMarker(userData);
      if (marker) continue;

      const wallet = toRecord(userData.wallet);
      const previousCurrency = (asNonEmptyString(wallet.currency) || "USD").toUpperCase();
      const previousBalance = Number(wallet.balance || 0);
      if (previousCurrency !== "USD" && Number.isFinite(previousBalance) && previousBalance !== 0) {
        currenciesToFetch.add(previousCurrency);
      }
    }

    const rateSnapshots = new Map<string, WalletUsdExchangeRateSnapshot>();
    const rateErrors = new Map<string, string>();
    await Promise.all([...currenciesToFetch].map(async (currency) => {
      try {
        const snapshot = await fetchRawExchangeRateToUsd(currency);
        rateSnapshots.set(currency, snapshot);
      } catch (error) {
        rateErrors.set(currency, parseProviderErrorMessage(error));
      }
    }));

    const results: WalletUsdMigrationResultItem[] = [];
    let migratedCount = 0;
    let previewCount = 0;
    let skippedCount = 0;
    let errorCount = 0;

    for (const userDoc of userDocs) {
      const userId = userDoc.id;
      if (!userDoc.exists) {
        skippedCount += 1;
        results.push({
          userId,
          outcome: "SKIPPED",
          reason: "User document not found.",
          migrationRunId: runId,
        });
        continue;
      }

      const userData = toRecord(userDoc.data());
      const marker = getWalletUsdMigrationMarker(userData);
      if (marker) {
        skippedCount += 1;
        results.push({
          userId,
          outcome: "SKIPPED",
          reason: "Wallet USD one-time migration already completed for this user.",
          previousCurrency: (asNonEmptyString(toRecord(userData.wallet).currency) || "USD").toUpperCase(),
          previousBalance: Number(toRecord(userData.wallet).balance || 0),
          migrationRunId: String(marker.runId || ""),
        });
        continue;
      }

      const wallet = toRecord(userData.wallet);
      const previousCurrency = (asNonEmptyString(wallet.currency) || "USD").toUpperCase();
      const previousBalance = Number(wallet.balance || 0);
      if (!Number.isFinite(previousBalance)) {
        errorCount += 1;
        results.push({
          userId,
          outcome: "ERROR",
          reason: "Wallet balance is not a finite number.",
          previousCurrency,
          migrationRunId: runId,
        });
        continue;
      }

      if (previousCurrency === "USD") {
        skippedCount += 1;
        results.push({
          userId,
          outcome: "SKIPPED",
          reason: "Wallet currency is already USD.",
          previousCurrency,
          previousBalance,
          migrationRunId: runId,
        });
        continue;
      }

      const rateSnapshot = previousBalance === 0 ?
        {
          fromCurrency: previousCurrency,
          toCurrency: "USD" as const,
          rate: 1,
          provider: "ZERO_BALANCE_IDENTITY",
          fetchedAtMs: Date.now(),
          requestUrl: "local://zero-balance",
        } :
        rateSnapshots.get(previousCurrency);

      if (!rateSnapshot) {
        errorCount += 1;
        results.push({
          userId,
          outcome: "ERROR",
          reason: rateErrors.get(previousCurrency) || `Missing exchange rate snapshot for ${previousCurrency}.`,
          previousCurrency,
          previousBalance,
          migrationRunId: runId,
        });
        continue;
      }

      const computedUsdBalance = roundMoney(previousBalance * rateSnapshot.rate);
      const auditId = `${runId}_${userId}`;
      if (dryRun) {
        previewCount += 1;
        results.push({
          userId,
          outcome: "PREVIEW",
          reason: "Dry run only. No writes performed.",
          previousCurrency,
          previousBalance,
          newUsdBalance: computedUsdBalance,
          rate: rateSnapshot.rate,
          rateProvider: rateSnapshot.provider,
          rateFetchedAtMs: rateSnapshot.fetchedAtMs,
          auditId,
          migrationRunId: runId,
        });
        continue;
      }

      try {
        let writeOutcome: "MIGRATED" | "SKIPPED" = "MIGRATED";
        await db.runTransaction(async (transaction) => {
          const freshSnap = await transaction.get(userDoc.ref);
          if (!freshSnap.exists) {
            writeOutcome = "SKIPPED";
            return;
          }

          const freshData = toRecord(freshSnap.data());
          const freshMarker = getWalletUsdMigrationMarker(freshData);
          if (freshMarker) {
            writeOutcome = "SKIPPED";
            return;
          }

          const freshWallet = toRecord(freshData.wallet);
          const freshCurrency = (asNonEmptyString(freshWallet.currency) || "USD").toUpperCase();
          const freshBalance = Number(freshWallet.balance || 0);
          if (!Number.isFinite(freshBalance)) {
            throw new Error("Wallet balance is not a finite number at write time.");
          }
          if (freshCurrency === "USD") {
            writeOutcome = "SKIPPED";
            return;
          }

          const freshRateSnapshot = freshBalance === 0 ?
            {
              fromCurrency: freshCurrency,
              toCurrency: "USD" as const,
              rate: 1,
              provider: "ZERO_BALANCE_IDENTITY",
              fetchedAtMs: Date.now(),
              requestUrl: "local://zero-balance",
            } :
            rateSnapshots.get(freshCurrency);
          if (!freshRateSnapshot) {
            throw new Error(`Missing exchange rate snapshot for ${freshCurrency} at write time.`);
          }

          const exactUsdBalance = freshBalance * freshRateSnapshot.rate;
          const newUsdBalance = roundMoney(exactUsdBalance);
          const now = admin.firestore.Timestamp.now();
          const fetchedAtTimestamp = admin.firestore.Timestamp.fromMillis(freshRateSnapshot.fetchedAtMs);
          const roundingDelta = Number((newUsdBalance - exactUsdBalance).toFixed(8));

          transaction.update(userDoc.ref, {
            "wallet.balance": newUsdBalance,
            "wallet.currency": "USD",
            "walletMigration.usdOneTime": {
              runId,
              migratedBy: adminUid,
              migratedAt: now,
              previousCurrency: freshCurrency,
              previousBalance: freshBalance,
              newUsdBalance,
              rate: freshRateSnapshot.rate,
              rateProvider: freshRateSnapshot.provider,
              rateFetchedAt: fetchedAtTimestamp,
              roundingDelta,
              auditId,
            },
          });

          const auditRef = db.collection("wallet_currency_migrations").doc(auditId);
          transaction.set(auditRef, {
            runId,
            userId,
            migratedBy: adminUid,
            migratedAt: now,
            previousCurrency: freshCurrency,
            previousBalance: freshBalance,
            newUsdBalance,
            exactUsdBalance,
            roundingDelta,
            rateSnapshot: {
              fromCurrency: freshRateSnapshot.fromCurrency,
              toCurrency: freshRateSnapshot.toCurrency,
              rate: freshRateSnapshot.rate,
              provider: freshRateSnapshot.provider,
              fetchedAt: fetchedAtTimestamp,
              requestUrl: freshRateSnapshot.requestUrl,
            },
            beforeWallet: {
              balance: freshBalance,
              currency: freshCurrency,
            },
            afterWallet: {
              balance: newUsdBalance,
              currency: "USD",
            },
            oneTimeMigration: true,
          }, {merge: true});
        });

        if (writeOutcome === "MIGRATED") {
          migratedCount += 1;
          results.push({
            userId,
            outcome: "MIGRATED",
            reason: "Wallet converted to USD and audit snapshot recorded.",
            previousCurrency,
            previousBalance,
            newUsdBalance: computedUsdBalance,
            rate: rateSnapshot.rate,
            rateProvider: rateSnapshot.provider,
            rateFetchedAtMs: rateSnapshot.fetchedAtMs,
            auditId,
            migrationRunId: runId,
          });
        } else {
          skippedCount += 1;
          results.push({
            userId,
            outcome: "SKIPPED",
            reason: "User wallet changed before migration commit; no conversion applied.",
            previousCurrency,
            previousBalance,
            migrationRunId: runId,
          });
        }
      } catch (error) {
        errorCount += 1;
        results.push({
          userId,
          outcome: "ERROR",
          reason: parseProviderErrorMessage(error),
          previousCurrency,
          previousBalance,
          migrationRunId: runId,
        });
      }
    }

    functions.logger.info("Wallet USD migration run completed.", {
      runId,
      dryRun,
      requestedBy: adminUid,
      scanned: userDocs.length,
      migratedCount,
      previewCount,
      skippedCount,
      errorCount,
      nextCursor,
    });

    return {
      runId,
      dryRun,
      requestedBy: adminUid,
      scanned: userDocs.length,
      summary: {
        migrated: migratedCount,
        preview: previewCount,
        skipped: skippedCount,
        errors: errorCount,
      },
      nextCursor,
      results,
    };
  });

export const adminQuarantineLegacyWalletBalances = functions.runWith({enforceAppCheck: true, timeoutSeconds: 540})
  .https.onCall(async (data, context) => {
    const adminUid = await assertAdminCallableAccess(context);
    const payload = (data || {}) as AdminQuarantineLegacyWalletBalancesPayload;

    const dryRun = payload.dryRun !== false;
    const parsedLimit = Number(payload.limit);
    const limit = Math.min(Math.max(Number.isFinite(parsedLimit) ? Math.trunc(parsedLimit) : 100, 1), 300);
    const startAfterUserId = asNonEmptyString(payload.startAfterUserId);
    const runId = asNonEmptyString(payload.runId) || `legacy_wallet_quarantine_${Date.now()}`;
    const includeNonProviderHosted = payload.includeNonProviderHosted === true;
    const reason = asNonEmptyString(payload.reason) ||
      "Legacy internal wallet balance frozen after provider-wallet migration. This balance is hidden from live wallet state and should not be used for customer funds.";
    const explicitUserIds = [...new Set(
      (payload.userIds || [])
        .map((value) => String(value || "").trim())
        .filter((value) => value.length > 0)
    )].slice(0, limit);

    let userDocs: FirebaseFirestore.DocumentSnapshot[] = [];
    let nextCursor: string | null = null;
    if (explicitUserIds.length > 0) {
      userDocs = await Promise.all(
        explicitUserIds.map((userId) => db.collection("users").doc(userId).get())
      );
    } else {
      let usersQuery = db.collection("users")
        .orderBy(admin.firestore.FieldPath.documentId())
        .limit(limit);
      if (startAfterUserId) {
        usersQuery = usersQuery.startAfter(startAfterUserId);
      }
      const usersSnap = await usersQuery.get();
      userDocs = usersSnap.docs;
      nextCursor = usersSnap.docs.length === limit ?
        usersSnap.docs[usersSnap.docs.length - 1].id :
        null;
    }

    type LegacyWalletQuarantineResultItem = {
      userId: string;
      outcome: "QUARANTINED" | "PREVIEW" | "SKIPPED" | "ERROR";
      reason: string;
      provider: string;
      previousBalance?: number;
      previousAvailableBalance?: number;
      previousCurrentBalance?: number;
      previousCurrency?: string;
      auditId?: string;
      runId?: string;
    };

    const results: LegacyWalletQuarantineResultItem[] = [];
    let quarantinedCount = 0;
    let previewCount = 0;
    let skippedCount = 0;
    let errorCount = 0;

    for (const userDoc of userDocs) {
      const userId = userDoc.id;
      if (!userDoc.exists) {
        skippedCount += 1;
        results.push({
          userId,
          outcome: "SKIPPED",
          reason: "User document not found.",
          provider: "UNKNOWN",
          runId,
        });
        continue;
      }

      const userData = toRecord(userDoc.data());
      const wallet = toRecord(userData.wallet);
      const provider = getUserWalletRuntimeProvider(userData);
      const providerHosted = providerWalletMirrorUsesHostedCustody(provider);
      const alreadyFrozen = isLegacyWalletBalanceFrozen(userData);
      const previousBalance = roundMoney(Number(wallet.balance || 0));
      const previousAvailableBalance = roundMoney(Number(wallet.availableBalance || 0));
      const previousCurrentBalance = roundMoney(Number(wallet.currentBalance || 0));
      const previousCurrency = normalizeProviderWalletCurrency(wallet.currency, userData.walletCurrency, userData.currency);
      const hasLegacyBalance =
        previousBalance !== 0 ||
        previousAvailableBalance !== 0 ||
        previousCurrentBalance !== 0;

      if (!includeNonProviderHosted && !providerHosted) {
        skippedCount += 1;
        results.push({
          userId,
          outcome: "SKIPPED",
          reason: "User is not on a provider-hosted wallet profile.",
          provider,
          previousBalance,
          previousAvailableBalance,
          previousCurrentBalance,
          previousCurrency,
          runId,
        });
        continue;
      }

      if (!hasLegacyBalance && alreadyFrozen) {
        skippedCount += 1;
        results.push({
          userId,
          outcome: "SKIPPED",
          reason: "Legacy wallet balance was already quarantined.",
          provider,
          previousBalance,
          previousAvailableBalance,
          previousCurrentBalance,
          previousCurrency,
          runId,
        });
        continue;
      }

      if (!hasLegacyBalance) {
        skippedCount += 1;
        results.push({
          userId,
          outcome: "SKIPPED",
          reason: "No legacy app-held balance remains on this wallet.",
          provider,
          previousBalance,
          previousAvailableBalance,
          previousCurrentBalance,
          previousCurrency,
          runId,
        });
        continue;
      }

      const auditId = `${runId}_${userId}`;
      if (dryRun) {
        previewCount += 1;
        results.push({
          userId,
          outcome: "PREVIEW",
          reason: "Dry run only. Legacy wallet balance would be frozen and hidden from live state.",
          provider,
          previousBalance,
          previousAvailableBalance,
          previousCurrentBalance,
          previousCurrency,
          auditId,
          runId,
        });
        continue;
      }

      try {
        let writeOutcome: "QUARANTINED" | "SKIPPED" = "QUARANTINED";
        await db.runTransaction(async (transaction) => {
          const freshSnap = await transaction.get(userDoc.ref);
          if (!freshSnap.exists) {
            writeOutcome = "SKIPPED";
            return;
          }

          const freshData = toRecord(freshSnap.data());
          const freshWallet = toRecord(freshData.wallet);
          const freshProvider = getUserWalletRuntimeProvider(freshData);
          const freshProviderHosted = providerWalletMirrorUsesHostedCustody(freshProvider);
          if (!includeNonProviderHosted && !freshProviderHosted) {
            writeOutcome = "SKIPPED";
            return;
          }

          const freshBalance = roundMoney(Number(freshWallet.balance || 0));
          const freshAvailableBalance = roundMoney(Number(freshWallet.availableBalance || 0));
          const freshCurrentBalance = roundMoney(Number(freshWallet.currentBalance || 0));
          const freshCurrency = normalizeProviderWalletCurrency(
            freshWallet.currency,
            freshData.walletCurrency,
            freshData.currency
          );
          const freshHasLegacyBalance =
            freshBalance !== 0 ||
            freshAvailableBalance !== 0 ||
            freshCurrentBalance !== 0;
          if (!freshHasLegacyBalance && isLegacyWalletBalanceFrozen(freshData)) {
            writeOutcome = "SKIPPED";
            return;
          }
          if (!freshHasLegacyBalance) {
            writeOutcome = "SKIPPED";
            return;
          }

          const now = admin.firestore.Timestamp.now();
          transaction.update(userDoc.ref, {
            "wallet.legacyBalanceFrozen": true,
            "wallet.legacyBalanceHidden": true,
            "wallet.legacyFrozenAt": now,
            "wallet.legacyFrozenBy": adminUid,
            "wallet.legacyFrozenReason": reason,
            "wallet.legacyFrozenRunId": runId,
            "wallet.legacyFrozenAmount": freshBalance,
            "wallet.legacyFrozenAvailableBalance": freshAvailableBalance,
            "wallet.legacyFrozenCurrentBalance": freshCurrentBalance,
            "wallet.legacyFrozenCurrency": freshCurrency,
            "wallet.balance": 0,
            "wallet.availableBalance": 0,
            "wallet.currentBalance": 0,
            updatedAt: now,
          });

          transaction.set(db.collection("legacy_wallet_balance_quarantines").doc(auditId), {
            auditId,
            runId,
            userId,
            quarantinedBy: adminUid,
            quarantinedAt: now,
            provider: freshProvider,
            providerHosted: freshProviderHosted,
            reason,
            previousWallet: {
              balance: freshBalance,
              availableBalance: freshAvailableBalance,
              currentBalance: freshCurrentBalance,
              currency: freshCurrency,
            },
            afterWallet: {
              balance: 0,
              availableBalance: 0,
              currentBalance: 0,
              currency: freshCurrency,
            },
          }, {merge: true});
        });

        if (writeOutcome === "QUARANTINED") {
          quarantinedCount += 1;
          results.push({
            userId,
            outcome: "QUARANTINED",
            reason: "Legacy wallet balance was frozen and removed from live wallet state.",
            provider,
            previousBalance,
            previousAvailableBalance,
            previousCurrentBalance,
            previousCurrency,
            auditId,
            runId,
          });
        } else {
          skippedCount += 1;
          results.push({
            userId,
            outcome: "SKIPPED",
            reason: "User wallet changed before quarantine commit; no write was performed.",
            provider,
            previousBalance,
            previousAvailableBalance,
            previousCurrentBalance,
            previousCurrency,
            runId,
          });
        }
      } catch (error) {
        errorCount += 1;
        results.push({
          userId,
          outcome: "ERROR",
          reason: parseProviderErrorMessage(error),
          provider,
          previousBalance,
          previousAvailableBalance,
          previousCurrentBalance,
          previousCurrency,
          runId,
        });
      }
    }

    functions.logger.info("Legacy wallet balance quarantine run completed.", {
      runId,
      dryRun,
      requestedBy: adminUid,
      scanned: userDocs.length,
      includeNonProviderHosted,
      quarantinedCount,
      previewCount,
      skippedCount,
      errorCount,
      nextCursor,
    });

    return {
      runId,
      dryRun,
      requestedBy: adminUid,
      scanned: userDocs.length,
      summary: {
        quarantined: quarantinedCount,
        preview: previewCount,
        skipped: skippedCount,
        errors: errorCount,
      },
      nextCursor,
      results,
    };
  });

export const adminListPayoutRequests = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const adminUid = await assertAdminCallableAccess(context);
    const payload = (data || {}) as AdminListPayoutRequestsPayload;
    const parsedLimit = Number(payload.limit);
    const limit = Math.min(Math.max(Number.isFinite(parsedLimit) ? Math.trunc(parsedLimit) : 120, 1), 250);
    const statusFilters = normalizeStatusFilters(payload.statuses);
    const statusFilterSet = new Set(statusFilters);
    const mobileMoneyOnly = payload.mobileMoneyOnly === true;

    const snap = await db.collection("payout_requests")
      .orderBy("createdAt", "desc")
      .limit(limit)
      .get();

    const reversibleStatuses = new Set<string>([
      "PENDING",
      "PROCESSING",
      "PENDING_BANK_SETTLEMENT",
      "PROCESSING_BANK_SETTLEMENT",
      "PENDING_PROVIDER",
      "PROCESSING_PROVIDER",
      "FAILED",
      "COMPLETED",
    ]);

    const items = snap.docs.map((doc) => {
      const payoutData = doc.data() || {};
      const recipientInfo = (payoutData.recipientInfo || {}) as Record<string, unknown>;
      const status = String(payoutData.status || "UNKNOWN").trim().toUpperCase();
      const type = String(payoutData.type || "UNKNOWN").trim().toUpperCase();
      const isMobileMoneyType = isMobileMoneyPayoutType(type);
      const createdAtMs = toMillisTimestamp(payoutData.createdAt);
      const processedAtMs = toMillisTimestamp(payoutData.processedAt);
      const providerPendingAgeMs = computeMobileMoneyProviderPendingAgeMs(payoutData);
      const providerPendingAgeMinutes = providerPendingAgeMs !== null ?
        Math.max(1, Math.ceil(providerPendingAgeMs / 60000)) :
        null;
      const providerAttentionRequired =
        payoutData.providerAttentionRequired === true ||
        (providerPendingAgeMs !== null && providerPendingAgeMs >= getMobileMoneyProviderStaleAttentionThresholdMs());
      const providerAttentionMessage = asNonEmptyString(payoutData.providerAttentionMessage) ||
        (providerAttentionRequired && providerPendingAgeMinutes !== null ?
          buildMobileMoneyProviderStaleAttentionMessage(providerPendingAgeMinutes) :
          null);
      const refunded = payoutData.refundProcessed === true || status === "REFUNDED";
      const reversible = !refunded && reversibleStatuses.has(status);
      const senderTransactionIds = Array.isArray(payoutData.senderTransactionIds) ?
        payoutData.senderTransactionIds.map((value) => String(value || "").trim()).filter((value) => value.length > 0) :
        [];

      return {
        payoutRequestId: doc.id,
        senderId: asNonEmptyString(payoutData.senderId) || "",
        recipientId: asNonEmptyString(payoutData.recipientId) || null,
        type,
        status,
        providerStatus: asNonEmptyString(payoutData.providerStatus) || null,
        providerTransferId: asNonEmptyString(payoutData.providerTransferId) || null,
        providerMessage: asNonEmptyString(payoutData.providerMessage) || null,
        errorMessage: asNonEmptyString(payoutData.errorMessage) || null,
        fundingSourceType: asNonEmptyString(
          payoutData.fundingSourceType,
          payoutData.fundingSource
        ) || null,
        processor: asNonEmptyString(
          payoutData.processor,
          payoutData.collectionProcessor
        ) || null,
        processorMode: asNonEmptyString(payoutData.processorMode) || null,
        settlementProvider: asNonEmptyString(
          payoutData.settlementProvider,
          payoutData.payoutProvider,
          payoutData.afriexPayoutProvider,
          payoutData.provider
        ) || null,
        settlementCategory: asNonEmptyString(
          payoutData.settlementCategory,
          payoutData.commerceCategory,
          payoutData.commerceFlow
        ) || null,
        amount: Number(payoutData.amount || 0),
        currency: asNonEmptyString(payoutData.currency, payoutData.localCurrency)?.toUpperCase() || "USD",
        transferFeeAmount: payoutData.transferFeeAmount !== undefined &&
          payoutData.transferFeeAmount !== null &&
          Number.isFinite(Number(payoutData.transferFeeAmount)) ?
          roundMoney(Math.max(0, Number(payoutData.transferFeeAmount))) :
          null,
        transferFeeCurrency: asNonEmptyString(payoutData.transferFeeCurrency)?.toUpperCase() || null,
        transferFeeProviderAmount: payoutData.transferFeeProviderAmount !== undefined &&
          payoutData.transferFeeProviderAmount !== null &&
          Number.isFinite(Number(payoutData.transferFeeProviderAmount)) ?
          roundMoney(Math.max(0, Number(payoutData.transferFeeProviderAmount))) :
          null,
        transferFeeTopUpAmount: payoutData.transferFeeTopUpAmount !== undefined &&
          payoutData.transferFeeTopUpAmount !== null &&
          Number.isFinite(Number(payoutData.transferFeeTopUpAmount)) ?
          roundMoney(Math.max(0, Number(payoutData.transferFeeTopUpAmount))) :
          null,
        transferFeeProviderUsd: payoutData.transferFeeProviderUsd !== undefined &&
          payoutData.transferFeeProviderUsd !== null &&
          Number.isFinite(Number(payoutData.transferFeeProviderUsd)) ?
          roundMoney(Math.max(0, Number(payoutData.transferFeeProviderUsd))) :
          null,
        transferFeeTopUpUsd: payoutData.transferFeeTopUpUsd !== undefined &&
          payoutData.transferFeeTopUpUsd !== null &&
          Number.isFinite(Number(payoutData.transferFeeTopUpUsd)) ?
          roundMoney(Math.max(0, Number(payoutData.transferFeeTopUpUsd))) :
          null,
        stripeTransactionOwnerFeeAmount: payoutData.stripeTransactionOwnerFeeAmount !== undefined &&
          payoutData.stripeTransactionOwnerFeeAmount !== null &&
          Number.isFinite(Number(payoutData.stripeTransactionOwnerFeeAmount)) ?
          roundMoney(Math.max(0, Number(payoutData.stripeTransactionOwnerFeeAmount))) :
          null,
        stripeTransactionOwnerFeeUsd: payoutData.stripeTransactionOwnerFeeUsd !== undefined &&
          payoutData.stripeTransactionOwnerFeeUsd !== null &&
          Number.isFinite(Number(payoutData.stripeTransactionOwnerFeeUsd)) ?
          roundMoney(Math.max(0, Number(payoutData.stripeTransactionOwnerFeeUsd))) :
          null,
        totalDebitAmount: payoutData.totalDebitAmount !== undefined &&
          payoutData.totalDebitAmount !== null &&
          Number.isFinite(Number(payoutData.totalDebitAmount)) ?
          roundMoney(Math.max(0, Number(payoutData.totalDebitAmount))) :
          null,
        totalDebitCurrency: asNonEmptyString(payoutData.totalDebitCurrency)?.toUpperCase() || null,
        afriexPayoutProvider: asNonEmptyString(payoutData.afriexPayoutProvider) || null,
        afriexPreferredPayoutRoute: asNonEmptyString(payoutData.afriexPreferredRoute) || null,
        providerChannel: asNonEmptyString(
          payoutData.providerChannel,
          payoutData.afriexProviderChannel,
          recipientInfo["providerChannel"],
          recipientInfo["afriexProviderChannel"]
        )?.toUpperCase() || null,
        afriexPreferredPaymentMethodId: asNonEmptyString(payoutData.afriexPreferredPaymentMethodId) || null,
        afriexSelectionRequired: payoutData.afriexSelectionRequired === true,
        afriexAvailableRoutes: Array.isArray(payoutData.afriexAvailableRoutes) ?
          payoutData.afriexAvailableRoutes.map((value) => String(value || "").trim()).filter((value) => value.length > 0) :
          [],
        recipientName: asNonEmptyString(
          payoutData.recipientName,
          recipientInfo["name"],
          recipientInfo["registeredName"]
        ) || null,
        recipientPhone: asNonEmptyString(
          payoutData.recipientPhone,
          recipientInfo["mobileNumber"],
          recipientInfo["phone"],
          recipientInfo["accountNumber"]
        ) || null,
        recipientCountry: asNonEmptyString(
          payoutData.recipientCountry,
          payoutData.country,
          recipientInfo["country"]
        ) || null,
        recipientNetwork: asNonEmptyString(
          payoutData.recipientNetwork,
          payoutData.network,
          recipientInfo["network"]
        ) || null,
        senderTransactionIds,
        refundProcessed: refunded,
        refundSkipped: payoutData.refundSkipped === true,
        refundActionRequired: payoutData.refundActionRequired === true,
        refundSkipReason: asNonEmptyString(payoutData.refundSkipReason) || null,
        refundAmount: Number(payoutData.refundAmount || 0),
        walletCreditSkipped: payoutData.walletCreditSkipped === true,
        walletCreditSkipReason: asNonEmptyString(payoutData.walletCreditSkipReason) || null,
        providerAttentionRequired,
        providerAttentionMessage,
        providerPendingAgeMinutes,
        createdAtMs,
        processedAtMs,
        isMobileMoneyType,
        reversible,
      };
    }).filter((item) => {
      if (mobileMoneyOnly && !item.isMobileMoneyType) {
        return false;
      }
      if (statusFilterSet.size > 0 && !statusFilterSet.has(item.status)) {
        return false;
      }
      return true;
    }).map((item) => {
      const {isMobileMoneyType, ...sanitizedItem} = item;
      return isMobileMoneyType ? sanitizedItem : sanitizedItem;
    });

    return {
      requestedBy: adminUid,
      requestedLimit: limit,
      returnedCount: items.length,
      filters: {
        statuses: statusFilters,
        mobileMoneyOnly,
      },
      items,
    };
  });

export const adminListDepositRequests = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const adminUid = await assertAdminCallableAccess(context);
    const payload = (data || {}) as AdminListDepositRequestsPayload;
    const parsedLimit = Number(payload.limit);
    const limit = Math.min(Math.max(Number.isFinite(parsedLimit) ? Math.trunc(parsedLimit) : 120, 1), 250);
    const statusFilters = normalizeStatusFilters(payload.statuses);
    const statusFilterSet = new Set(statusFilters);

    const snap = await db.collection("deposit_requests")
      .orderBy("createdAt", "desc")
      .limit(limit)
      .get();

    const baseItems = snap.docs.map((doc) => {
      const depositData = doc.data() || {};
      const status = String(depositData.status || "UNKNOWN").trim().toUpperCase();
      return {
        depositRequestId: doc.id,
        userId: asNonEmptyString(depositData.userId) || "",
        paymentMethodId: asNonEmptyString(depositData.paymentMethodId) || "",
        amount: Number(depositData.amount || 0),
        currency: asNonEmptyString(depositData.currency)?.toUpperCase() || "USD",
        status,
        methodType: asNonEmptyString(depositData.methodType, depositData.fundingSourceType) || "",
        walletCredited: depositData.walletCredited === true,
        disputeStatus: asNonEmptyString(depositData.disputeStatus) || null,
        disputeResolution: asNonEmptyString(depositData.disputeResolution) || null,
        disputeReason: asNonEmptyString(depositData.disputeReason) || null,
        disputeAmount: Number.isFinite(Number(depositData.disputeAmount)) ? Number(depositData.disputeAmount) : null,
        disputeCurrency: asNonEmptyString(depositData.disputeCurrency)?.toUpperCase() || null,
        stripeDisputeId: asNonEmptyString(depositData.stripeDisputeId) || null,
        stripeChargeId: asNonEmptyString(depositData.stripeChargeId, depositData.bankChargeId) || null,
        errorMessage: asNonEmptyString(depositData.errorMessage) || null,
        settlementMessage: asNonEmptyString(depositData.settlementMessage) || null,
        providerMessage: asNonEmptyString(depositData.providerMessage) || null,
        createdAtMs: toMillisTimestamp(depositData.createdAt),
        processedAtMs: toMillisTimestamp(depositData.processedAt),
        lastStatusCheckAtMs: toMillisTimestamp(depositData.lastStatusCheckAt),
        disputeOpenedAtMs: toMillisTimestamp(depositData.disputeOpenedAt),
        disputeClosedAtMs: toMillisTimestamp(depositData.disputeClosedAt),
      };
    }).filter((item) => {
      if (statusFilterSet.size > 0 && !statusFilterSet.has(item.status)) {
        return false;
      }
      return true;
    });

    const userIds = [...new Set(baseItems.map((item) => item.userId).filter((value) => value.length > 0))];
    const userEntries = await Promise.all(userIds.map(async (userId) => {
      try {
        const userSnap = await db.collection("users").doc(userId).get();
        const userData = userSnap.data() || {};
        return [
          userId,
          asNonEmptyString(userData.username, userData.displayName, userData.name, userData.email) || "User",
        ] as const;
      } catch (error) {
        functions.logger.warn("Failed to load user for admin deposit queue", {userId, error});
        return [userId, "User"] as const;
      }
    }));
    const userNameMap = new Map<string, string>(userEntries);

    const items = await Promise.all(baseItems.map(async (item) => {
      let sourceLabel: string | null = null;
      let methodType = item.methodType;

      if (item.userId && item.paymentMethodId) {
        try {
          const methodSnap = await db.collection("users")
            .doc(item.userId)
            .collection("payment_methods")
            .doc(item.paymentMethodId)
            .get();
          if (methodSnap.exists) {
            const methodData = methodSnap.data() || {};
            methodType = asNonEmptyString(methodType, methodData.type, methodData.methodType) || "";
            sourceLabel = buildAdminPaymentMethodSourceLabel(methodData, methodType);
          }
        } catch (error) {
          functions.logger.warn("Failed to load payment method for admin deposit queue", {
            userId: item.userId,
            paymentMethodId: item.paymentMethodId,
            error,
          });
        }
      }

      if (!sourceLabel && methodType) {
        sourceLabel = humanizeFundingMethodType(methodType);
      }

      return {
        depositRequestId: item.depositRequestId,
        userId: item.userId,
        requesterName: userNameMap.get(item.userId) || "User",
        paymentMethodId: item.paymentMethodId,
        methodType: methodType || "UNKNOWN",
        sourceLabel,
        amount: item.amount,
        currency: item.currency,
        status: item.status,
        walletCredited: item.walletCredited,
        disputeStatus: item.disputeStatus,
        disputeResolution: item.disputeResolution,
        disputeReason: item.disputeReason,
        disputeAmount: item.disputeAmount,
        disputeCurrency: item.disputeCurrency,
        stripeDisputeId: item.stripeDisputeId,
        stripeChargeId: item.stripeChargeId,
        errorMessage: item.errorMessage,
        settlementMessage: item.settlementMessage,
        providerMessage: item.providerMessage,
        createdAtMs: item.createdAtMs,
        processedAtMs: item.processedAtMs,
        lastStatusCheckAtMs: item.lastStatusCheckAtMs,
        disputeOpenedAtMs: item.disputeOpenedAtMs,
        disputeClosedAtMs: item.disputeClosedAtMs,
      };
    }));

    return {
      requestedBy: adminUid,
      requestedLimit: limit,
      returnedCount: items.length,
      filters: {
        statuses: statusFilters,
      },
      items,
    };
  });

const reversiblePayoutStatuses = new Set<string>([
  "PENDING",
  "PROCESSING",
  "PENDING_BANK_SETTLEMENT",
  "PROCESSING_BANK_SETTLEMENT",
  "PENDING_PROVIDER",
  "PROCESSING_PROVIDER",
  "FAILED",
]);

const reverseSinglePayoutRequestToWallet = async (
  payoutRequestId: string,
  options: {
    allowCompleted: boolean;
    reason: string;
    performedBy: string;
  }
): Promise<ReversePayoutExecutionResult> => {
  const payoutRef = db.collection("payout_requests").doc(payoutRequestId);
  const payoutSnap = await payoutRef.get();
  if (!payoutSnap.exists) {
    return {
      payoutRequestId,
      outcome: "SKIPPED",
      message: "Payout request not found.",
    };
  }

  const payoutData = payoutSnap.data() || {};
  const payoutType = String(payoutData.type || "").toUpperCase();
  const isWalletWithdrawPayout = isWalletTransferExternalPayout(payoutData);
  if (!isWalletWithdrawPayout && payoutType !== "CASH_OUT" && payoutType !== "BENEFICIARY_TRANSFER") {
    return {
      payoutRequestId,
      outcome: "SKIPPED",
      message: `Payout type ${payoutType || "UNKNOWN"} is not eligible for this reversal tool.`,
    };
  }

  const senderId = asNonEmptyString(payoutData.senderId);
  if (!senderId) {
    return {
      payoutRequestId,
      outcome: "ERROR",
      message: "Missing senderId on payout request.",
    };
  }

  const status = String(payoutData.status || "").toUpperCase();
  const canReverse = reversiblePayoutStatuses.has(status) || (options.allowCompleted && status === "COMPLETED");
  if (!canReverse) {
    return {
      payoutRequestId,
      outcome: "SKIPPED",
      message: `Status ${status || "UNKNOWN"} is not reversible for this request.`,
    };
  }

  // Match automatic failure refunds: wallet→card/bank debits `walletDebitedTotal` (amount + fees).
  // Mobile-money flows use `walletDebitedAmount` or `amount`.
  const refundAmount = roundMoney(
    Number(
      payoutData.walletDebitedTotal ??
      payoutData.walletDebitedAmount ??
      payoutData.amount ??
      0
    )
  );
  if (!Number.isFinite(refundAmount) || refundAmount <= 0) {
    return {
      payoutRequestId,
      outcome: "ERROR",
      message: "Invalid refund amount on payout request.",
    };
  }

  const userRef = db.collection("users").doc(senderId);
  let alreadyRefunded = false;
  let providerActionRequired = false;
  let providerActionMessage: string | null = null;
  let providerMirrorTransactionId: string | null = null;
  let shouldFinalizeProviderFailure = false;
  let shouldCancelMirrorReservation = false;

  await db.runTransaction(async (transaction) => {
    const [freshPayoutSnap, userSnap] = await Promise.all([
      transaction.get(payoutRef),
      transaction.get(userRef),
    ]);
    if (!freshPayoutSnap.exists || !userSnap.exists) {
      throw new Error("Payout request disappeared during reversal.");
    }

    const freshPayoutData = freshPayoutSnap.data() || {};
    if (freshPayoutData.refundProcessed === true || String(freshPayoutData.status || "").toUpperCase() === "REFUNDED") {
      alreadyRefunded = true;
      return;
    }

    const senderUsesHostedWallet = userUsesProviderHostedWallet((userSnap.data() || {}) as Record<string, unknown>);
    const now = admin.firestore.Timestamp.now();
    const freshStatus = String(freshPayoutData.status || status || "UNKNOWN").toUpperCase();

    // Transaction-only releases never recreate an internal customer balance.
    // Older legacy payout rows can still appear in the admin queue, but their
    // reversal must be reconciled on the original provider rail instead.
    if (TRANSACTION_ONLY_RELEASE || senderUsesHostedWallet) {
      const existingProviderStatus = asNonEmptyString(freshPayoutData.providerStatus) || null;
      const isCompletedProviderPayout = freshStatus === "COMPLETED" || existingProviderStatus === "COMPLETED";
      const reportingOnlyReversal = TRANSACTION_ONLY_RELEASE;
      const providerOnlyMessage = isCompletedProviderPayout ?
        "This payout already completed with the provider. Reverse it with the payment partner; no in-app wallet refund was issued." :
        (reportingOnlyReversal ?
          "This reversal was recorded for provider-side reconciliation. Transaction-only mode never creates an in-app wallet refund." :
          "This provider-hosted payout was marked for provider-side reversal. No in-app wallet refund was issued.");

      providerActionRequired = true;
      providerActionMessage = providerOnlyMessage;
      providerMirrorTransactionId = asNonEmptyString(freshPayoutData.providerMirrorTransactionId);
      shouldFinalizeProviderFailure = !isCompletedProviderPayout;
      shouldCancelMirrorReservation = !isCompletedProviderPayout && providerMirrorTransactionId !== null;

      transaction.set(payoutRef, {
        status: isCompletedProviderPayout ? freshStatus : "FAILED",
        refundProcessed: false,
        refundSkipped: true,
        refundSkippedAt: now,
        refundSkipReason: reportingOnlyReversal ?
          "Transaction-only mode: admin reversal never credits an internal wallet; reconcile on the original provider rail." :
          "Provider-hosted payouts are reconciled with the provider mirror; admin reversal does not credit an internal wallet.",
        refundActionRequired: true,
        refundReason: options.reason,
        manualReversalRequestedBy: options.performedBy,
        manualReversalRequestedAt: now,
        manualReversalRequestReason: options.reason,
        providerStatus: isCompletedProviderPayout ? existingProviderStatus || "COMPLETED" : "FAILED",
        providerMessage: providerOnlyMessage,
        errorMessage: isCompletedProviderPayout ?
          admin.firestore.FieldValue.delete() :
          providerOnlyMessage,
        processedAt: now,
      }, {merge: true});
      return;
    }

    const freshDestinationType = String(freshPayoutData.destinationType || "").trim().toUpperCase();
    const freshWalletWithdraw = isWalletTransferExternalPayout(freshPayoutData);
    const reversalTitle = freshWalletWithdraw ?
      (freshDestinationType === "CARD" ?
        "Card Withdrawal Reversal" :
        freshDestinationType === "BANK" ?
          "Bank Withdrawal Reversal" :
          "Wallet Transfer Reversal") :
      "Mobile Money Transfer Reversal";
    const reversalSource = freshWalletWithdraw ? "WALLET_TRANSFER_REVERSAL" : "MOBILE_MONEY_REVERSAL";

    const txRef = userRef.collection("transactions").doc();
    transaction.update(userRef, "wallet.balance", admin.firestore.FieldValue.increment(refundAmount));
    transaction.set(txRef, {
      title: reversalTitle,
      amount: refundAmount,
      type: "CREDIT",
      status: "COMPLETED",
      timestamp: now,
      note: `${options.reason} (payoutRequestId: ${payoutRequestId})`,
      source: reversalSource,
      payoutRequestId,
    });

    transaction.set(payoutRef, {
      status: "REFUNDED",
      refundProcessed: true,
      refundAmount,
      refundTransactionId: txRef.id,
      refundReason: options.reason,
      refundedBy: options.performedBy,
      refundedAt: now,
      reversedFromStatus: String(freshPayoutData.status || status || "UNKNOWN"),
      providerStatus: "REFUNDED",
      providerMessage: "Funds returned to sender wallet by admin reversal tool.",
      processedAt: now,
    }, {merge: true});
  });

  if (alreadyRefunded) {
    return {
      payoutRequestId,
      outcome: "SKIPPED",
      message: "Already refunded.",
    };
  }

  if (providerActionRequired) {
    if (shouldCancelMirrorReservation && providerMirrorTransactionId) {
      await syncProviderMirrorTransactionStatusById({
        userId: senderId,
        mirrorTransactionId: providerMirrorTransactionId,
        nextStatus: ProviderMirrorTransactionStatus.Cancelled,
        providerMessage: options.reason,
        rawStatus: "FAILED",
      });
    }
    if (shouldFinalizeProviderFailure) {
      await finalizeSenderTransactionsForPayout(senderId, payoutRef, payoutData, "FAILED");
    }
    return {
      payoutRequestId,
      outcome: "ACTION_REQUIRED",
      message: providerActionMessage || "Provider-side refund action is still required; no in-app wallet refund was issued.",
    };
  }

  await finalizeSenderTransactionsForPayout(senderId, payoutRef, payoutData, "FAILED");

  return {
    payoutRequestId,
    outcome: "REFUNDED",
    message: "Funds returned to sender wallet.",
    refundAmount,
  };
};

const reversePayoutRequestsToWallet = async (
  payload: ReversePayoutRequestsPayload,
  contextData: {performedBy: string}
): Promise<{results: ReversePayoutExecutionResult[]; totals: {requested: number; refunded: number; actionRequired: number; skipped: number; errors: number; refundedAmount: number}}> => {
  const uniqueIds = [...new Set((payload.payoutRequestIds || []).map((id) => String(id || "").trim()).filter((id) => id.length > 0))];
  const allowCompleted = payload.allowCompleted === true;
  const reason = asNonEmptyString(payload.reason) || "Payout did not settle with provider; reconcile the refund on the original payment rail or provider mirror.";
  const performedBy = contextData.performedBy;

  const results: ReversePayoutExecutionResult[] = [];
  let refunded = 0;
  let actionRequired = 0;
  let skipped = 0;
  let errors = 0;
  let refundedAmount = 0;

  for (const payoutRequestId of uniqueIds) {
    try {
      const result = await reverseSinglePayoutRequestToWallet(payoutRequestId, {
        allowCompleted,
        reason,
        performedBy,
      });
      results.push(result);
      if (result.outcome === "REFUNDED") {
        refunded += 1;
        refundedAmount += Number(result.refundAmount || 0);
      } else if (result.outcome === "ACTION_REQUIRED") {
        actionRequired += 1;
      } else if (result.outcome === "SKIPPED") {
        skipped += 1;
      } else {
        errors += 1;
      }
    } catch (error) {
      results.push({
        payoutRequestId,
        outcome: "ERROR",
        message: parseProviderErrorMessage(error),
      });
      errors += 1;
    }
  }

  return {
    results,
    totals: {
      requested: uniqueIds.length,
      refunded,
      actionRequired,
      skipped,
      errors,
      refundedAmount: Number(refundedAmount.toFixed(2)),
    },
  };
};

export const adminReversePayoutRequestsCallable = functions.runWith({enforceAppCheck: true})
  .https.onCall(async (data, context) => {
    const adminUid = await assertAdminCallableAccess(context);
    const payload = (data || {}) as ReversePayoutRequestsPayload;
    if (!Array.isArray(payload.payoutRequestIds) || payload.payoutRequestIds.length === 0) {
      throw new functions.https.HttpsError("invalid-argument", "payoutRequestIds must be a non-empty array.");
    }

    return reversePayoutRequestsToWallet(payload, {
      performedBy: `adminCallable:${adminUid}`,
    });
  });

export const adminReversePayoutRequests = functions.https.onRequest(async (req, res) => {
  if (req.method !== "POST") {
    res.status(405).json({error: "Method not allowed. Use POST."});
    return;
  }

  const expectedSecret = asNonEmptyString(process.env.ADMIN_PAYOUT_REVERSAL_SECRET);
  if (!expectedSecret) {
    res.status(503).json({error: "ADMIN_PAYOUT_REVERSAL_SECRET is not configured."});
    return;
  }

  const providedSecret = req.header("x-admin-reversal-secret") || "";
  if (providedSecret !== expectedSecret) {
    res.status(403).json({error: "Invalid reversal secret."});
    return;
  }

  const body = (req.body || {}) as ReversePayoutRequestsPayload;
  if (!Array.isArray(body.payoutRequestIds) || body.payoutRequestIds.length === 0) {
    res.status(400).json({error: "payoutRequestIds must be a non-empty array."});
    return;
  }

  const result = await reversePayoutRequestsToWallet(body, {
    performedBy: "adminReversePayoutRequests",
  });
  res.status(200).json(result);
});

type ReconcilePayoutRequestsPayload = {
  payoutRequestIds?: string[];
  stripeChargeIds?: string[];
  stripePaymentIntentIds?: string[];
  senderId?: string;
  includeRecentForSender?: boolean;
  queryPending?: boolean;
  recentLimit?: number;
};

const reconcilePayoutRequestsAdmin = async (
  payload: ReconcilePayoutRequestsPayload,
  performedBy: string
) => {
  const results: Array<Record<string, unknown>> = [];
  const payoutIds = [...new Set(
    (payload.payoutRequestIds || [])
      .map((value) => asNonEmptyString(value))
      .filter(Boolean) as string[]
  )];
  const chargeIds = [...new Set(
    (payload.stripeChargeIds || [])
      .map((value) => asNonEmptyString(value))
      .filter(Boolean) as string[]
  )];
  const paymentIntentIds = [...new Set(
    (payload.stripePaymentIntentIds || [])
      .map((value) => asNonEmptyString(value))
      .filter(Boolean) as string[]
  )];
  const senderIdFilter = asNonEmptyString(payload.senderId);
  const recentLimit = Math.min(Math.max(Number(payload.recentLimit || 80), 1), 300);
  if (senderIdFilter && payload.includeRecentForSender === true) {
    const recentSnap = await db.collection("payout_requests")
      .where("senderId", "==", senderIdFilter)
      .limit(recentLimit)
      .get();
    for (const doc of recentSnap.docs) {
      payoutIds.push(doc.id);
    }
  }
  if (payload.queryPending === true) {
    const pendingStatuses = [
      "PENDING",
      "PENDING_PROVIDER",
      "PROCESSING",
      "PROCESSING_PROVIDER",
      "PENDING_BANK_SETTLEMENT",
      "PROCESSING_BANK_SETTLEMENT",
    ];
    const pendingSnap = await db.collection("payout_requests")
      .where("status", "in", pendingStatuses)
      .limit(recentLimit)
      .get();
    for (const doc of pendingSnap.docs) {
      payoutIds.push(doc.id);
    }
  }

  for (const chargeId of chargeIds) {
    try {
      const charge = await getStripe().charges.retrieve(chargeId);
      const result = await tryFinalizePayoutFromStripeCharge(charge);
      results.push({chargeId, ...result, performedBy});
    } catch (error) {
      results.push({
        chargeId,
        handled: false,
        error: parseProviderErrorMessage(error),
        performedBy,
      });
    }
  }

  for (const paymentIntentId of paymentIntentIds) {
    try {
      const paymentIntent = await getStripe().paymentIntents.retrieve(paymentIntentId);
      const payoutRequestId = asNonEmptyString(paymentIntent.metadata?.payoutRequestId);
      if (!payoutRequestId) {
        results.push({
          paymentIntentId,
          handled: false,
          error: "Payment intent is missing payoutRequestId metadata.",
          performedBy,
        });
        continue;
      }
      payoutIds.push(payoutRequestId);
      results.push({
        paymentIntentId,
        payoutRequestId,
        paymentIntentStatus: paymentIntent.status,
        performedBy,
      });
    } catch (error) {
      results.push({
        paymentIntentId,
        handled: false,
        error: parseProviderErrorMessage(error),
        performedBy,
      });
    }
  }

  const uniquePayoutIds = [...new Set(payoutIds)];
  for (const payoutRequestId of uniquePayoutIds) {
    try {
      const payoutRef = db.collection("payout_requests").doc(payoutRequestId);
      const payoutSnap = await payoutRef.get();
      if (!payoutSnap.exists) {
        results.push({payoutRequestId, handled: false, error: "NOT_FOUND", performedBy});
        continue;
      }

      const payoutData = payoutSnap.data() || {};
      const type = String(payoutData.type || "").trim().toUpperCase();
      const status = String(payoutData.status || "").trim().toUpperCase();
      let action = "INSPECTED";

      if (
        type === "BENEFICIARY_TRANSFER" &&
        status === "FAILED" &&
        String(payoutData.fundingSource || "").trim().toUpperCase() === AFRIEX_HOSTED_WALLET_FUNDING_SOURCE
      ) {
        // Repair an older pre-acceptance provider rejection without creating
        // an app balance. The helper refunds only a linked, completed Stripe
        // card collection and remains idempotent by payout request.
        await refundFailedBeneficiaryTransferFunding(payoutRef, payoutData);
        action = "RECONCILED_FAILED_HOSTED_TRANSFER_FUNDING";
      } else if (type === "CASH_IN" && isStripeSettledAfriexHostedWalletTopUp(payoutData)) {
        const paymentIntentId = asNonEmptyString(payoutData.paymentIntentId);
        if (
          paymentIntentId &&
          !["COMPLETED", "FAILED", "CANCELLED", "REVERSED", "REFUNDED"].includes(status)
        ) {
          const paymentIntent = await getStripe().paymentIntents.retrieve(paymentIntentId);
          const piStatus = String(paymentIntent.status || "").trim().toLowerCase();
          if (piStatus === "succeeded") {
            await payoutRef.set({
              paymentIntentId,
              paymentIntentStatus: piStatus,
              stripeCollectionStatus: "SUCCEEDED",
            }, {merge: true});
            await applyMobileMoneyProviderResult(payoutRef, payoutData, {
              status: "COMPLETED",
              providerTransferId: paymentIntentId,
              providerMessage: "Card funding completed through Stripe (admin reconcile).",
              rawStatus: piStatus.toUpperCase(),
            });
            action = "COMPLETED_CARD_CASH_IN";
          }
        } else if (asNonEmptyString(payoutData.fundingBankChargeId)) {
          await settlePendingStripeBankFundedCashInRequest(payoutRef, payoutData);
          action = "RECONCILED_BANK_CASH_IN";
        }
      } else if (
        (type === "BENEFICIARY_TRANSFER" || type === "DIRECT_PAYOUT") &&
        String(payoutData.fundingSource || "").trim().toUpperCase() === "EXTERNAL_BANK"
      ) {
        if (type === "DIRECT_PAYOUT") {
          await settlePendingBankFundedDirectPayoutRequest(payoutRef, payoutData);
        } else {
          await settlePendingBankFundedTransferRequest(payoutRef, payoutData);
        }
        action = "RECONCILED_BANK_FUNDED_TRANSFER";
      }

      const refreshedSnap = await payoutRef.get();
      const refreshedData = refreshedSnap.data() || {};
      const refreshedStatus = String(refreshedData.status || "").trim().toUpperCase();
      if (
        refreshedData.type === "CASH_IN" &&
        refreshedStatus === "COMPLETED" &&
        refreshedData.cashInSettled !== true
      ) {
        await settleMobileMoneyCashInToWallet(payoutRef, refreshedData);
        action = "SETTLED_HOSTED_FUNDED_TRANSFER";
      }

      const linkedTransferId = asNonEmptyString(
        refreshedData.hostedFundedTransferPayoutRequestId,
        refreshedData.transferIntentPayoutRequestId
      );
      if (linkedTransferId) {
        const linkedRef = db.collection("payout_requests").doc(linkedTransferId);
        const linkedSnap = await linkedRef.get();
        if (linkedSnap.exists) {
          const linkedData = linkedSnap.data() || {};
          const linkedStatus = String(linkedData.status || "").trim().toUpperCase();
          if (linkedStatus === "PENDING_PROVIDER" || linkedStatus === "PROCESSING_PROVIDER") {
            await processPendingMobileMoneyProviderPayout(linkedRef, linkedData);
            action = "RETRIED_LINKED_BENEFICIARY_TRANSFER";
          }
          results.push({
            payoutRequestId,
            handled: true,
            action,
            status: refreshedStatus,
            linkedTransferId,
            linkedStatus,
            performedBy,
          });
          continue;
        }
      }

      if (
        type === "BENEFICIARY_TRANSFER" &&
        (status === "PENDING_PROVIDER" || status === "PROCESSING_PROVIDER")
      ) {
        const hadProviderReference = !!asNonEmptyString(
          payoutData.providerTransferId,
          payoutData.afriexTransactionId,
          payoutData.providerTransactionId
        );
        if (!hadProviderReference && status === "PROCESSING_PROVIDER") {
          const requeued = await requeueOrphanedProviderProcessingPayout(payoutRef, payoutData);
          action = requeued ? "RESET_AND_SUBMITTED_TO_AFRIEX" : "RETRIED_BENEFICIARY_TRANSFER";
        } else {
          await processPendingMobileMoneyProviderPayout(payoutRef, payoutData);
          action = "RETRIED_BENEFICIARY_TRANSFER";
        }
      }

      const finalSnap = await payoutRef.get();
      const finalData = finalSnap.data() || {};
      const finalStatus = String(finalData.status || "").trim().toUpperCase();
      const senderId = asNonEmptyString(finalData.senderId);
      if (senderId && finalStatus === "COMPLETED") {
        const updatedSenderTxCount = await finalizeSenderTransactionsForPayout(
          senderId,
          payoutRef,
          finalData,
          "COMPLETED"
        );
        if (updatedSenderTxCount > 0) {
          action = action === "INSPECTED" ? "SYNCED_SENDER_TRANSACTIONS" : `${action}+SYNCED_SENDER_TX`;
        }
      }

      results.push({
        payoutRequestId,
        handled: true,
        action,
        type: finalData.type,
        status: finalData.status,
        providerStatus: finalData.providerStatus,
        providerMessage: finalData.providerMessage,
        errorMessage: finalData.errorMessage,
        transferIntent: finalData.transferIntent ? {
          mode: finalData.transferIntent.mode,
          destinationCountry: finalData.transferIntent.recipientCountry ||
            finalData.transferIntent.recipientInfo?.country,
          payoutRoute: finalData.transferIntent.afriexPayoutRoute,
        } : null,
        recipientCountry: finalData.recipientCountry || finalData.recipientInfo?.country || null,
        recipientLocalCurrency: finalData.recipientLocalCurrency || finalData.localCurrency || null,
        afriexPayoutRoute: finalData.afriexPayoutRoute || null,
        providerTransferId: finalData.providerTransferId || null,
        hostedFundedTransferPayoutRequestId: finalData.hostedFundedTransferPayoutRequestId || null,
        performedBy,
      });
    } catch (error) {
      const errorMessage = error instanceof Error ?
        error.message :
        (typeof error === "string" ? error : JSON.stringify(error));
      results.push({
        payoutRequestId,
        handled: false,
        error: errorMessage || "Unknown reconcile error.",
        performedBy,
      });
    }
  }

  return {results, totals: {requested: uniquePayoutIds.length, chargeIds: chargeIds.length}};
};

export const adminReconcilePayoutRequests = functions.https.onRequest(async (req, res) => {
  if (req.method !== "POST") {
    res.status(405).json({error: "Method not allowed. Use POST."});
    return;
  }

  const expectedSecret = asNonEmptyString(process.env.ADMIN_PAYOUT_REVERSAL_SECRET);
  if (!expectedSecret) {
    res.status(503).json({error: "ADMIN_PAYOUT_REVERSAL_SECRET is not configured."});
    return;
  }

  const providedSecret = req.header("x-admin-reversal-secret") || "";
  if (providedSecret !== expectedSecret) {
    res.status(403).json({error: "Invalid reversal secret."});
    return;
  }

  const body = (req.body || {}) as ReconcilePayoutRequestsPayload;
  const hasTargets =
    (Array.isArray(body.payoutRequestIds) && body.payoutRequestIds.length > 0) ||
    (Array.isArray(body.stripeChargeIds) && body.stripeChargeIds.length > 0) ||
    (Array.isArray(body.stripePaymentIntentIds) && body.stripePaymentIntentIds.length > 0) ||
    (asNonEmptyString(body.senderId) && body.includeRecentForSender === true) ||
    body.queryPending === true;
  if (!hasTargets) {
    res.status(400).json({
      error: "Provide payoutRequestIds, stripeChargeIds, stripePaymentIntentIds, senderId+includeRecentForSender, or queryPending.",
    });
    return;
  }

  const result = await reconcilePayoutRequestsAdmin(body, "adminReconcilePayoutRequests");
  res.status(200).json(result);
});
